window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["已废止法律"] = {"danbaofa":[{"i":1,"n":"第一条","txt":"为促进资金融通和商品流通，保障债权的实现，发展社会主义市场经济，制定本法。"},{"i":2,"n":"第二条","txt":"在借贷、买卖、货物运输、加工承揽等经济活动中，债权人需要以担保方式保障其债权实现的，可以依照本法规定设定担保。"},{"i":3,"n":"第三条","txt":"担保活动应当遵循平等、自愿、公平、诚实信用的原则。"},{"i":4,"n":"第四条","txt":"第三人为债务人向债权人提供担保时，可以要求债务人提供反担保。"},{"i":5,"n":"第五条","txt":"担保合同是主合同的从合同，主合同无效，担保合同无效。担保合同另有约定的，按照约定。"},{"i":6,"n":"第六条","txt":"本法所称保证，是指保证人和债权人约定，当债务人不履行债务时，保证人按照约定履行债务或者承担责任的行为。"},{"i":7,"n":"第七条","txt":"具有代为清偿债务能力的法人、其他组织或者公民，可以作保证人。"},{"i":8,"n":"第八条","txt":"国家机关不得为保证人，但经国务院批准为使用外国政府或者国际经济组织贷款进行转贷的除外。"},{"i":9,"n":"第九条","txt":"学校、幼儿园、医院等以公益为目的的事业单位、社会团体不得为保证人。"},{"i":10,"n":"第十条","txt":"企业法人的分支机构、职能部门不得为保证人。"},{"i":11,"n":"第十一条","txt":"任何单位和个人不得强令银行等金融机构或者企业为他人提供保证；银行等金融机构或者企业对强令其为他人提供保证的行为，有权拒绝。"},{"i":12,"n":"第十二条","txt":"同一债务有两个以上保证人的，保证人应当按照保证合同约定的保证份额，承担保证责任。没有约定保证份额的，保证人承担连带责任，债权人可以要求任何一个保证人承担全部保证责任，保证人都负有担保全部债权实现的义务。已经承担保证责任的保证人，有权向债务人追偿，或者要求承担连带责任的其他保证人清偿其应当承担的份额。"},{"i":13,"n":"第十三条","txt":"保证人与债权人应当以书面形式订立保证合同。"},{"i":14,"n":"第十四条","txt":"保证人与债权人可以就单个主合同分别订立保证合同，也可以协议在最高债权额限度内就一定期间连续发生的借款合同或者某项商品交易合同订立一个保证合同。"},{"i":15,"n":"第十五条","txt":"保证合同应当包括以下内容："},{"i":16,"n":"第十六条","txt":"保证的方式有："},{"i":17,"n":"第十七条","txt":"当事人在保证合同中约定，债务人不能履行债务时，由保证人承担保证责任的，为一般保证。"},{"i":18,"n":"第十八条","txt":"当事人在保证合同中约定保证人与债务人对债务承担连带责任的，为连带责任保证。"},{"i":19,"n":"第十九条","txt":"当事人对保证方式没有约定或者约定不明确的，按照连带责任保证承担保证责任。"},{"i":20,"n":"第二十条","txt":"一般保证和连带责任保证的保证人享有债务人的抗辩权。债务人放弃对债务的抗辩权的，保证人仍有权抗辩。"},{"i":21,"n":"第二十一条","txt":"保证担保的范围包括主债权及利息、违约金、损害赔偿金和实现债权的费用。保证合同另有约定的，按照约定。"},{"i":22,"n":"第二十二条","txt":"保证期间，债权人依法将主债权转让给第三人的，保证人在原保证担保的范围内继续承担保证责任。保证合同另有约定的，按照约定。"},{"i":23,"n":"第二十三条","txt":"保证期间，债权人许可债务人转让债务的，应当取得保证人书面同意，保证人对未经其同意转让的债务，不再承担保证责任。"},{"i":24,"n":"第二十四条","txt":"债权人与债务人协议变更主合同的，应当取得保证人书面同意，未经保证人书面同意的，保证人不再承担保证责任。保证合同另有约定的，按照约定。"},{"i":25,"n":"第二十五条","txt":"一般保证的保证人与债权人未约定保证期间的，保证期间为主债务履行期届满之日起六个月。"},{"i":26,"n":"第二十六条","txt":"连带责任保证的保证人与债权人未约定保证期间的，债权人有权自主债务履行期届满之日起六个月内要求保证人承担保证责任。"},{"i":27,"n":"第二十七条","txt":"保证人依照本法第十四条规定就连续发生的债权作保证，未约定保证期间的，保证人可以随时书面通知债权人终止保证合同，但保证人对于通知到债权人前所发生的债权，承担保证责任。"},{"i":28,"n":"第二十八条","txt":"同一债权既有保证又有物的担保的，保证人对物的担保以外的债权承担保证责任。"},{"i":29,"n":"第二十九条","txt":"企业法人的分支机构未经法人书面授权或者超出授权范围与债权人订立保证合同的，该合同无效或者超出授权范围的部分无效，债权人和企业法人有过错的，应当根据其过错各自承担相应的民事责任；债权人无过错的，由企业法人承担民事责任。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，保证人不承担民事责任："},{"i":31,"n":"第三十一条","txt":"保证人承担保证责任后，有权向债务人追偿。"},{"i":32,"n":"第三十二条","txt":"人民法院受理债务人破产案件后，债权人未申报债权的，保证人可以参加破产财产分配，预先行使追偿权。"},{"i":33,"n":"第三十三条","txt":"本法所称抵押，是指债务人或者第三人不转移对本法第三十四条所列财产的占有，将该财产作为债权的担保。债务人不履行债务时，债权人有权依照本法规定以该财产折价或者以拍卖、变卖该财产的价款优先受偿。"},{"i":34,"n":"第三十四条","txt":"下列财产可以抵押："},{"i":35,"n":"第三十五条","txt":"抵押人所担保的债权不得超出其抵押物的价值。"},{"i":36,"n":"第三十六条","txt":"以依法取得的国有土地上的房屋抵押的，该房屋占用范围内的国有土地使用权同时抵押。"},{"i":37,"n":"第三十七条","txt":"下列财产不得抵押："},{"i":38,"n":"第三十八条","txt":"抵押人和抵押权人应当以书面形式订立抵押合同。"},{"i":39,"n":"第三十九条","txt":"抵押合同应当包括以下内容："},{"i":40,"n":"第四十条","txt":"订立抵押合同时，抵押权人和抵押人在合同中不得约定在债务履行期届满抵押权人未受清偿时，抵押物的所有权转移为债权人所有。"},{"i":41,"n":"第四十一条","txt":"当事人以本法第四十二条规定的财产抵押的，应当办理抵押物登记，抵押合同自登记之日起生效。"},{"i":42,"n":"第四十二条","txt":"办理抵押物登记的部门如下："},{"i":43,"n":"第四十三条","txt":"当事人以其他财产抵押的，可以自愿办理抵押物登记，抵押合同自签订之日起生效。"},{"i":44,"n":"第四十四条","txt":"办理抵押物登记，应当向登记部门提供下列文件或者其复印件："},{"i":45,"n":"第四十五条","txt":"登记部门登记的资料，应当允许查阅、抄录或者复印。"},{"i":46,"n":"第四十六条","txt":"抵押担保的范围包括主债权及利息、违约金、损害赔偿金和实现抵押权的费用。抵押合同另有约定的，按照约定。"},{"i":47,"n":"第四十七条","txt":"债务履行期届满，债务人不履行债务致使抵押物被人民法院依法扣押的，自扣押之日起抵押权人有权收取由抵押物分离的天然孳息以及抵押人就抵押物可以收取的法定孳息。抵押权人未将扣押抵押物的事实通知应当清偿法定孳息的义务人的，抵押权的效力不及于该孳息。"},{"i":48,"n":"第四十八条","txt":"抵押人将已出租的财产抵押的，应当书面告知承租人，原租赁合同继续有效。"},{"i":49,"n":"第四十九条","txt":"抵押期间，抵押人转让已办理登记的抵押物的，应当通知抵押权人并告知受让人转让物已经抵押的情况；抵押人未通知抵押权人或者未告知受让人的，转让行为无效。"},{"i":50,"n":"第五十条","txt":"抵押权不得与债权分离而单独转让或者作为其他债权的担保。"},{"i":51,"n":"第五十一条","txt":"抵押人的行为足以使抵押物价值减少的，抵押权人有权要求抵押人停止其行为。抵押物价值减少时，抵押权人有权要求抵押人恢复抵押物的价值，或者提供与减少的价值相当的担保。"},{"i":52,"n":"第五十二条","txt":"抵押权与其担保的债权同时存在，债权消灭的，抵押权也消灭。"},{"i":53,"n":"第五十三条","txt":"债务履行期届满抵押权人未受清偿的，可以与抵押人协议以抵押物折价或者以拍卖、变卖该抵押物所得的价款受偿；协议不成的，抵押权人可以向人民法院提起诉讼。"},{"i":54,"n":"第五十四条","txt":"同一财产向两个以上债权人抵押的，拍卖、变卖抵押物所得的价款按照以下规定清偿："},{"i":55,"n":"第五十五条","txt":"城市房地产抵押合同签订后，土地上新增的房屋不属于抵押物。需要拍卖该抵押的房地产时，可以依法将该土地上新增的房屋与抵押物一同拍卖，但对拍卖新增房屋所得，抵押权人无权优先受偿。"},{"i":56,"n":"第五十六条","txt":"拍卖划拨的国有土地使用权所得的价款，在依法缴纳相当于应缴纳的土地使用权出让金的款额后，抵押权人有优先受偿权。"},{"i":57,"n":"第五十七条","txt":"为债务人抵押担保的第三人，在抵押权人实现抵押权后，有权向债务人追偿。"},{"i":58,"n":"第五十八条","txt":"抵押权因抵押物灭失而消灭。因灭失所得的赔偿金，应当作为抵押财产。"},{"i":59,"n":"第五十九条","txt":"本法所称最高额抵押，是指抵押人与抵押权人协议，在最高债权额限度内，以抵押物对一定期间内连续发生的债权作担保。"},{"i":60,"n":"第六十条","txt":"借款合同可以附最高额抵押合同。"},{"i":61,"n":"第六十一条","txt":"最高额抵押的主合同债权不得转让。"},{"i":62,"n":"第六十二条","txt":"最高额抵押除适用本节规定外，适用本章其他规定。"},{"i":63,"n":"第六十三条","txt":"本法所称动产质押，是指债务人或者第三人将其动产移交债权人占有，将该动产作为债权的担保。债务人不履行债务时，债权人有权依照本法规定以该动产折价或者以拍卖、变卖该动产的价款优先受偿。"},{"i":64,"n":"第六十四条","txt":"出质人和质权人应当以书面形式订立质押合同。"},{"i":65,"n":"第六十五条","txt":"质押合同应当包括以下内容："},{"i":66,"n":"第六十六条","txt":"出质人和质权人在合同中不得约定在债务履行期届满质权人未受清偿时，质物的所有权转移为质权人所有。"},{"i":67,"n":"第六十七条","txt":"质押担保的范围包括主债权及利息、违约金、损害赔偿金、质物保管费用和实现质权的费用。质押合同另有约定的，按照约定。"},{"i":68,"n":"第六十八条","txt":"质权人有权收取质物所生的孳息。质押合同另有约定的，按照约定。"},{"i":69,"n":"第六十九条","txt":"质权人负有妥善保管质物的义务。因保管不善致使质物灭失或者毁损的，质权人应当承担民事责任。"},{"i":70,"n":"第七十条","txt":"质物有损坏或者价值明显减少的可能，足以危害质权人权利的，质权人可以要求出质人提供相应的担保。出质人不提供的，质权人可以拍卖或者变卖质物，并与出质人协议将拍卖或者变卖所得的价款用于提前清偿所担保的债权或者向与出质人约定的第三人提存。"},{"i":71,"n":"第七十一条","txt":"债务履行期届满债务人履行债务的，或者出质人提前清偿所担保的债权的，质权人应当返还质物。"},{"i":72,"n":"第七十二条","txt":"为债务人质押担保的第三人，在质权人实现质权后，有权向债务人追偿。"},{"i":73,"n":"第七十三条","txt":"质权因质物灭失而消灭。因灭失所得的赔偿金，应当作为出质财产。"},{"i":74,"n":"第七十四条","txt":"质权与其担保的债权同时存在，债权消灭的，质权也消灭。"},{"i":75,"n":"第七十五条","txt":"下列权利可以质押："},{"i":76,"n":"第七十六条","txt":"以汇票、支票、本票、债券、存款单、仓单、提单出质的，应当在合同约定的期限内将权利凭证交付质权人。质押合同自权利凭证交付之日起生效。"},{"i":77,"n":"第七十七条","txt":"以载明兑现或者提货日期的汇票、支票、本票、债券、存款单、仓单、提单出质的，汇票、支票、本票、债券、存款单、仓单、提单兑现或者提货日期先于债务履行期的，质权人可以在债务履行期届满前兑现或者提货，并与出质人协议将兑现的价款或者提取的货物用于提前清偿所担保的债权或者向与出质人约定的第三人提存。"},{"i":78,"n":"第七十八条","txt":"以依法可以转让的股票出质的，出质人与质权人应当订立书面合同，并向证券登记机构办理出质登记。质押合同自登记之日起生效。"},{"i":79,"n":"第七十九条","txt":"以依法可以转让的商标专用权，专利权、著作权中的财产权出质的，出质人与质权人应当订立书面合同，并向其管理部门办理出质登记。质押合同自登记之日起生效。"},{"i":80,"n":"第八十条","txt":"本法第七十九条规定的权利出质后，出质人不得转让或者许可他人使用，但经出质人与质权人协商同意的可以转让或者许可他人使用。出质人所得的转让费、许可费应当向质权人提前清偿所担保的债权或者向与质权人约定的第三人提存。"},{"i":81,"n":"第八十一条","txt":"权利质押除适用本节规定外，适用本章第一节的规定。"},{"i":82,"n":"第八十二条","txt":"本法所称留置，是指依照本法第八十四条的规定，债权人按照合同约定占有债务人的动产，债务人不按照合同约定的期限履行债务的，债权人有权依照本法规定留置该财产，以该财产折价或者以拍卖、变卖该财产的价款优先受偿。"},{"i":83,"n":"第八十三条","txt":"留置担保的范围包括主债权及利息、违约金、损害赔偿金、留置物保管费用和实现留置权的费用。"},{"i":84,"n":"第八十四条","txt":"因保管合同、运输合同、加工承揽合同发生的债权，债务人不履行债务的，债权人有留置权。"},{"i":85,"n":"第八十五条","txt":"留置的财产为可分物的，留置物的价值应当相当于债务的金额。"},{"i":86,"n":"第八十六条","txt":"留置权人负有妥善保管留置物的义务。因保管不善致使留置物灭失或者毁损的，留置权人应当承担民事责任。"},{"i":87,"n":"第八十七条","txt":"债权人与债务人应当在合同中约定，债权人留置财产后，债务人应当在不少于两个月的期限内履行债务。债权人与债务人在合同中未约定的，债权人留置债务人财产后，应当确定两个月以上的期限，通知债务人在该期限内履行债务。"},{"i":88,"n":"第八十八条","txt":"留置权因下列原因消灭："},{"i":89,"n":"第八十九条","txt":"当事人可以约定一方向对方给付定金作为债权的担保。债务人履行债务后，定金应当抵作价款或者收回。给付定金的一方不履行约定的债务的，无权要求返还定金；收受定金的一方不履行约定的债务的，应当双倍返还定金。"},{"i":90,"n":"第九十条","txt":"定金应当以书面形式约定。当事人在定金合同中应当约定交付定金的期限。定金合同从实际交付定金之日起生效。"},{"i":91,"n":"第九十一条","txt":"定金的数额由当事人约定，但不得超过主合同标的额的百分之二十。"},{"i":92,"n":"第九十二条","txt":"本法所称不动产是指土地以及房屋、林木等地上定着物。"},{"i":93,"n":"第九十三条","txt":"本法所称保证合同、抵押合同、质押合同、定金合同可以是单独订立的书面合同，包括当事人之间的具有担保性质的信函、传真等，也可以是主合同中的担保条款。"},{"i":94,"n":"第九十四条","txt":"抵押物、质物、留置物折价或者变卖，应当参照市场价格。"},{"i":95,"n":"第九十五条","txt":"海商法等法律对担保有特别规定的，依照其规定。"},{"i":96,"n":"第九十六条","txt":"本法自1995年10月1日起施行。"}],"daqiwuranfangzhifa-2":[{"i":1,"n":"第一条","txt":"为保护和改善环境，防治大气污染，保障公众健康，推进生态文明建设，促进经济社会可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"防治大气污染，应当以改善大气环境质量为目标，坚持源头治理，规划先行，转变经济发展方式，优化产业结构和布局，调整能源结构。"},{"i":3,"n":"第三条","txt":"县级以上人民政府应当将大气污染防治工作纳入国民经济和社会发展规划，加大对大气污染防治的财政投入。"},{"i":4,"n":"第四条","txt":"国务院生态环境主管部门会同国务院有关部门，按照国务院的规定，对省、自治区、直辖市大气环境质量改善目标、大气污染防治重点任务完成情况进行考核。省、自治区、直辖市人民政府制定考核办法，对本行政区域内地方大气环境质量改善目标、大气污染防治重点任务完成情况实施考核。考核结果应当向社会公开。"},{"i":5,"n":"第五条","txt":"县级以上人民政府生态环境主管部门对大气污染防治实施统一监督管理。"},{"i":6,"n":"第六条","txt":"国家鼓励和支持大气污染防治科学技术研究，开展对大气污染来源及其变化趋势的分析，推广先进适用的大气污染防治技术和装备，促进科技成果转化，发挥科学技术在大气污染防治中的支撑作用。"},{"i":7,"n":"第七条","txt":"企业事业单位和其他生产经营者应当采取有效措施，防止、减少大气污染，对所造成的损害依法承担责任。"},{"i":8,"n":"第八条","txt":"国务院生态环境主管部门或者省、自治区、直辖市人民政府制定大气环境质量标准，应当以保障公众健康和保护生态环境为宗旨，与经济社会发展相适应，做到科学合理。"},{"i":9,"n":"第九条","txt":"国务院生态环境主管部门或者省、自治区、直辖市人民政府制定大气污染物排放标准，应当以大气环境质量标准和国家经济、技术条件为依据。"},{"i":10,"n":"第十条","txt":"制定大气环境质量标准、大气污染物排放标准，应当组织专家进行审查和论证，并征求有关部门、行业协会、企业事业单位和公众等方面的意见。"},{"i":11,"n":"第十一条","txt":"省级以上人民政府生态环境主管部门应当在其网站上公布大气环境质量标准、大气污染物排放标准，供公众免费查阅、下载。"},{"i":12,"n":"第十二条","txt":"大气环境质量标准、大气污染物排放标准的执行情况应当定期进行评估，根据评估结果对标准适时进行修订。"},{"i":13,"n":"第十三条","txt":"制定燃煤、石油焦、生物质燃料、涂料等含挥发性有机物的产品、烟花爆竹以及锅炉等产品的质量标准，应当明确大气环境保护要求。"},{"i":14,"n":"第十四条","txt":"未达到国家大气环境质量标准城市的人民政府应当及时编制大气环境质量限期达标规划，采取措施，按照国务院或者省级人民政府规定的期限达到大气环境质量标准。"},{"i":15,"n":"第十五条","txt":"城市大气环境质量限期达标规划应当向社会公开。直辖市和设区的市的大气环境质量限期达标规划应当报国务院生态环境主管部门备案。"},{"i":16,"n":"第十六条","txt":"城市人民政府每年在向本级人民代表大会或者其常务委员会报告环境状况和环境保护目标完成情况时，应当报告大气环境质量限期达标规划执行情况，并向社会公开。"},{"i":17,"n":"第十七条","txt":"城市大气环境质量限期达标规划应当根据大气污染防治的要求和经济、技术条件适时进行评估、修订。"},{"i":18,"n":"第十八条","txt":"企业事业单位和其他生产经营者建设对大气环境有影响的项目，应当依法进行环境影响评价、公开环境影响评价文件；向大气排放污染物的，应当符合大气污染物排放标准，遵守重点大气污染物排放总量控制要求。"},{"i":19,"n":"第十九条","txt":"排放工业废气或者本法第七十八条规定名录中所列有毒有害大气污染物的企业事业单位、集中供热设施的燃煤热源生产运营单位以及其他依法实行排污许可管理的单位，应当取得排污许可证。排污许可的具体办法和实施步骤由国务院规定。"},{"i":20,"n":"第二十条","txt":"企业事业单位和其他生产经营者向大气排放污染物的，应当依照法律法规和国务院生态环境主管部门的规定设置大气污染物排放口。"},{"i":21,"n":"第二十一条","txt":"国家对重点大气污染物排放实行总量控制。"},{"i":22,"n":"第二十二条","txt":"对超过国家重点大气污染物排放总量控制指标或者未完成国家下达的大气环境质量改善目标的地区，省级以上人民政府生态环境主管部门应当会同有关部门约谈该地区人民政府的主要负责人，并暂停审批该地区新增重点大气污染物排放总量的建设项目环境影响评价文件。约谈情况应当向社会公开。"},{"i":23,"n":"第二十三条","txt":"国务院生态环境主管部门负责制定大气环境质量和大气污染源的监测和评价规范，组织建设与管理全国大气环境质量和大气污染源监测网，组织开展大气环境质量和大气污染源监测，统一发布全国大气环境质量状况信息。"},{"i":24,"n":"第二十四条","txt":"企业事业单位和其他生产经营者应当按照国家有关规定和监测规范，对其排放的工业废气和本法第七十八条规定名录中所列有毒有害大气污染物进行监测，并保存原始监测记录。其中，重点排污单位应当安装、使用大气污染物排放自动监测设备，与生态环境主管部门的监控设备联网，保证监测设备正常运行并依法公开排放信息。监测的具体办法和重点排污单位的条件由国务院生态环境主管部门规定。"},{"i":25,"n":"第二十五条","txt":"重点排污单位应当对自动监测数据的真实性和准确性负责。生态环境主管部门发现重点排污单位的大气污染物排放自动监测设备传输数据异常，应当及时进行调查。"},{"i":26,"n":"第二十六条","txt":"禁止侵占、损毁或者擅自移动、改变大气环境质量监测设施和大气污染物排放自动监测设备。"},{"i":27,"n":"第二十七条","txt":"国家对严重污染大气环境的工艺、设备和产品实行淘汰制度。"},{"i":28,"n":"第二十八条","txt":"国务院生态环境主管部门会同有关部门，建立和完善大气污染损害评估制度。"},{"i":29,"n":"第二十九条","txt":"生态环境主管部门及其环境执法机构和其他负有大气环境保护监督管理职责的部门，有权通过现场检查监测、自动监测、遥感监测、远红外摄像等方式，对排放大气污染物的企业事业单位和其他生产经营者进行监督检查。被检查者应当如实反映情况，提供必要的资料。实施检查的部门、机构及其工作人员应当为被检查者保守商业秘密。"},{"i":30,"n":"第三十条","txt":"企业事业单位和其他生产经营者违反法律法规规定排放大气污染物，造成或者可能造成严重大气污染，或者有关证据可能灭失或者被隐匿的，县级以上人民政府生态环境主管部门和其他负有大气环境保护监督管理职责的部门，可以对有关设施、设备、物品采取查封、扣押等行政强制措施。"},{"i":31,"n":"第三十一条","txt":"生态环境主管部门和其他负有大气环境保护监督管理职责的部门应当公布举报电话、电子邮箱等，方便公众举报。"},{"i":32,"n":"第三十二条","txt":"国务院有关部门和地方各级人民政府应当采取措施，调整能源结构，推广清洁能源的生产和使用；优化煤炭使用方式，推广煤炭清洁高效利用，逐步降低煤炭在一次能源消费中的比重，减少煤炭生产、使用、转化过程中的大气污染物排放。"},{"i":33,"n":"第三十三条","txt":"国家推行煤炭洗选加工，降低煤炭的硫分和灰分，限制高硫分、高灰分煤炭的开采。新建煤矿应当同步建设配套的煤炭洗选设施，使煤炭的硫分、灰分含量达到规定标准；已建成的煤矿除所采煤炭属于低硫分、低灰分或者根据已达标排放的燃煤电厂要求不需要洗选的以外，应当限期建成配套的煤炭洗选设施。"},{"i":34,"n":"第三十四条","txt":"国家采取有利于煤炭清洁高效利用的经济、技术政策和措施，鼓励和支持洁净煤技术的开发和推广。"},{"i":35,"n":"第三十五条","txt":"国家禁止进口、销售和燃用不符合质量标准的煤炭，鼓励燃用优质煤炭。"},{"i":36,"n":"第三十六条","txt":"地方各级人民政府应当采取措施，加强民用散煤的管理，禁止销售不符合民用散煤质量标准的煤炭，鼓励居民燃用优质煤炭和洁净型煤，推广节能环保型炉灶。"},{"i":37,"n":"第三十七条","txt":"石油炼制企业应当按照燃油质量标准生产燃油。"},{"i":38,"n":"第三十八条","txt":"城市人民政府可以划定并公布高污染燃料禁燃区，并根据大气环境质量改善要求，逐步扩大高污染燃料禁燃区范围。高污染燃料的目录由国务院生态环境主管部门确定。"},{"i":39,"n":"第三十九条","txt":"城市建设应当统筹规划，在燃煤供热地区，推进热电联产和集中供热。在集中供热管网覆盖地区，禁止新建、扩建分散燃煤供热锅炉；已建成的不能达标排放的燃煤供热锅炉，应当在城市人民政府规定的期限内拆除。"},{"i":40,"n":"第四十条","txt":"县级以上人民政府市场监督管理部门应当会同生态环境主管部门对锅炉生产、进口、销售和使用环节执行环境保护标准或者要求的情况进行监督检查；不符合环境保护标准或者要求的，不得生产、进口、销售和使用。"},{"i":41,"n":"第四十一条","txt":"燃煤电厂和其他燃煤单位应当采用清洁生产工艺，配套建设除尘、脱硫、脱硝等装置，或者采取技术改造等其他控制大气污染物排放的措施。"},{"i":42,"n":"第四十二条","txt":"电力调度应当优先安排清洁能源发电上网。"},{"i":43,"n":"第四十三条","txt":"钢铁、建材、有色金属、石油、化工等企业生产过程中排放粉尘、硫化物和氮氧化物的，应当采用清洁生产工艺，配套建设除尘、脱硫、脱硝等装置，或者采取技术改造等其他控制大气污染物排放的措施。"},{"i":44,"n":"第四十四条","txt":"生产、进口、销售和使用含挥发性有机物的原材料和产品的，其挥发性有机物含量应当符合质量标准或者要求。"},{"i":45,"n":"第四十五条","txt":"产生含挥发性有机物废气的生产和服务活动，应当在密闭空间或者设备中进行，并按照规定安装、使用污染防治设施；无法密闭的，应当采取措施减少废气排放。"},{"i":46,"n":"第四十六条","txt":"工业涂装企业应当使用低挥发性有机物含量的涂料，并建立台账，记录生产原料、辅料的使用量、废弃量、去向以及挥发性有机物含量。台账保存期限不得少于三年。"},{"i":47,"n":"第四十七条","txt":"石油、化工以及其他生产和使用有机溶剂的企业，应当采取措施对管道、设备进行日常维护、维修，减少物料泄漏，对泄漏的物料应当及时收集处理。"},{"i":48,"n":"第四十八条","txt":"钢铁、建材、有色金属、石油、化工、制药、矿产开采等企业，应当加强精细化管理，采取集中收集处理等措施，严格控制粉尘和气态污染物的排放。"},{"i":49,"n":"第四十九条","txt":"工业生产、垃圾填埋或者其他活动产生的可燃性气体应当回收利用，不具备回收利用条件的，应当进行污染防治处理。"},{"i":50,"n":"第五十条","txt":"国家倡导低碳、环保出行，根据城市规划合理控制燃油机动车保有量，大力发展城市公共交通，提高公共交通出行比例。"},{"i":51,"n":"第五十一条","txt":"机动车船、非道路移动机械不得超过标准排放大气污染物。"},{"i":52,"n":"第五十二条","txt":"机动车、非道路移动机械生产企业应当对新生产的机动车和非道路移动机械进行排放检验。经检验合格的，方可出厂销售。检验信息应当向社会公开。"},{"i":53,"n":"第五十三条","txt":"在用机动车应当按照国家或者地方的有关规定，由机动车排放检验机构定期对其进行排放检验。经检验合格的，方可上道路行驶。未经检验合格的，公安机关交通管理部门不得核发安全技术检验合格标志。"},{"i":54,"n":"第五十四条","txt":"机动车排放检验机构应当依法通过计量认证，使用经依法检定合格的机动车排放检验设备，按照国务院生态环境主管部门制定的规范，对机动车进行排放检验，并与生态环境主管部门联网，实现检验数据实时共享。机动车排放检验机构及其负责人对检验数据的真实性和准确性负责。"},{"i":55,"n":"第五十五条","txt":"机动车生产、进口企业应当向社会公布其生产、进口机动车车型的排放检验信息、污染控制技术信息和有关维修技术信息。"},{"i":56,"n":"第五十六条","txt":"生态环境主管部门应当会同交通运输、住房城乡建设、农业行政、水行政等有关部门对非道路移动机械的大气污染物排放状况进行监督检查，排放不合格的，不得使用。"},{"i":57,"n":"第五十七条","txt":"国家倡导环保驾驶，鼓励燃油机动车驾驶人在不影响道路通行且需停车三分钟以上的情况下熄灭发动机，减少大气污染物的排放。"},{"i":58,"n":"第五十八条","txt":"国家建立机动车和非道路移动机械环境保护召回制度。"},{"i":59,"n":"第五十九条","txt":"在用重型柴油车、非道路移动机械未安装污染控制装置或者污染控制装置不符合要求，不能达标排放的，应当加装或者更换符合要求的污染控制装置。"},{"i":60,"n":"第六十条","txt":"在用机动车排放大气污染物超过标准的，应当进行维修；经维修或者采用污染控制技术后，大气污染物排放仍不符合国家在用机动车排放标准的，应当强制报废。其所有人应当将机动车交售给报废机动车回收拆解企业，由报废机动车回收拆解企业按照国家有关规定进行登记、拆解、销毁等处理。"},{"i":61,"n":"第六十一条","txt":"城市人民政府可以根据大气环境质量状况，划定并公布禁止使用高排放非道路移动机械的区域。"},{"i":62,"n":"第六十二条","txt":"船舶检验机构对船舶发动机及有关设备进行排放检验。经检验符合国家排放标准的，船舶方可运营。"},{"i":63,"n":"第六十三条","txt":"内河和江海直达船舶应当使用符合标准的普通柴油。远洋船舶靠港后应当使用符合大气污染物控制要求的船舶用燃油。"},{"i":64,"n":"第六十四条","txt":"国务院交通运输主管部门可以在沿海海域划定船舶大气污染物排放控制区，进入排放控制区的船舶应当符合船舶相关排放要求。"},{"i":65,"n":"第六十五条","txt":"禁止生产、进口、销售不符合标准的机动车船、非道路移动机械用燃料；禁止向汽车和摩托车销售普通柴油以及其他非机动车用燃料；禁止向非道路移动机械、内河和江海直达船舶销售渣油和重油。"},{"i":66,"n":"第六十六条","txt":"发动机油、氮氧化物还原剂、燃料和润滑油添加剂以及其他添加剂的有害物质含量和其他大气环境保护指标，应当符合有关标准的要求，不得损害机动车船污染控制装置效果和耐久性，不得增加新的大气污染物排放。"},{"i":67,"n":"第六十七条","txt":"国家积极推进民用航空器的大气污染防治，鼓励在设计、生产、使用过程中采取有效措施减少大气污染物排放。"},{"i":68,"n":"第六十八条","txt":"地方各级人民政府应当加强对建设施工和运输的管理，保持道路清洁，控制料堆和渣土堆放，扩大绿地、水面、湿地和地面铺装面积，防治扬尘污染。"},{"i":69,"n":"第六十九条","txt":"建设单位应当将防治扬尘污染的费用列入工程造价，并在施工承包合同中明确施工单位扬尘污染防治责任。施工单位应当制定具体的施工扬尘污染防治实施方案。"},{"i":70,"n":"第七十条","txt":"运输煤炭、垃圾、渣土、砂石、土方、灰浆等散装、流体物料的车辆应当采取密闭或者其他措施防止物料遗撒造成扬尘污染，并按照规定路线行驶。"},{"i":71,"n":"第七十一条","txt":"市政河道以及河道沿线、公共用地的裸露地面以及其他城镇裸露地面，有关部门应当按照规划组织实施绿化或者透水铺装。"},{"i":72,"n":"第七十二条","txt":"贮存煤炭、煤矸石、煤渣、煤灰、水泥、石灰、石膏、砂土等易产生扬尘的物料应当密闭；不能密闭的，应当设置不低于堆放物高度的严密围挡，并采取有效覆盖措施防治扬尘污染。"},{"i":73,"n":"第七十三条","txt":"地方各级人民政府应当推动转变农业生产方式，发展农业循环经济，加大对废弃物综合处理的支持力度，加强对农业生产经营活动排放大气污染物的控制。"},{"i":74,"n":"第七十四条","txt":"农业生产经营者应当改进施肥方式，科学合理施用化肥并按照国家有关规定使用农药，减少氨、挥发性有机物等大气污染物的排放。"},{"i":75,"n":"第七十五条","txt":"畜禽养殖场、养殖小区应当及时对污水、畜禽粪便和尸体等进行收集、贮存、清运和无害化处理，防止排放恶臭气体。"},{"i":76,"n":"第七十六条","txt":"各级人民政府及其农业行政等有关部门应当鼓励和支持采用先进适用技术，对秸秆、落叶等进行肥料化、饲料化、能源化、工业原料化、食用菌基料化等综合利用，加大对秸秆还田、收集一体化农业机械的财政补贴力度。"},{"i":77,"n":"第七十七条","txt":"省、自治区、直辖市人民政府应当划定区域，禁止露天焚烧秸秆、落叶等产生烟尘污染的物质。"},{"i":78,"n":"第七十八条","txt":"国务院生态环境主管部门应当会同国务院卫生行政部门，根据大气污染物对公众健康和生态环境的危害和影响程度，公布有毒有害大气污染物名录，实行风险管理。"},{"i":79,"n":"第七十九条","txt":"向大气排放持久性有机污染物的企业事业单位和其他生产经营者以及废弃物焚烧设施的运营单位，应当按照国家有关规定，采取有利于减少持久性有机污染物排放的技术方法和工艺，配备有效的净化装置，实现达标排放。"},{"i":80,"n":"第八十条","txt":"企业事业单位和其他生产经营者在生产经营活动中产生恶臭气体的，应当科学选址，设置合理的防护距离，并安装净化装置或者采取其他措施，防止排放恶臭气体。"},{"i":81,"n":"第八十一条","txt":"排放油烟的餐饮服务业经营者应当安装油烟净化设施并保持正常使用，或者采取其他油烟净化措施，使油烟达标排放，并防止对附近居民的正常生活环境造成污染。"},{"i":82,"n":"第八十二条","txt":"禁止在人口集中地区和其他依法需要特殊保护的区域内焚烧沥青、油毡、橡胶、塑料、皮革、垃圾以及其他产生有毒有害烟尘和恶臭气体的物质。"},{"i":83,"n":"第八十三条","txt":"国家鼓励和倡导文明、绿色祭祀。"},{"i":84,"n":"第八十四条","txt":"从事服装干洗和机动车维修等服务活动的经营者，应当按照国家有关标准或者要求设置异味和废气处理装置等污染防治设施并保持正常使用，防止影响周边环境。"},{"i":85,"n":"第八十五条","txt":"国家鼓励、支持消耗臭氧层物质替代品的生产和使用，逐步减少直至停止消耗臭氧层物质的生产和使用。"},{"i":86,"n":"第八十六条","txt":"国家建立重点区域大气污染联防联控机制，统筹协调重点区域内大气污染防治工作。国务院生态环境主管部门根据主体功能区划、区域大气环境质量状况和大气污染传输扩散规律，划定国家大气污染防治重点区域，报国务院批准。"},{"i":87,"n":"第八十七条","txt":"国务院生态环境主管部门会同国务院有关部门、国家大气污染防治重点区域内有关省、自治区、直辖市人民政府，根据重点区域经济社会发展和大气环境承载力，制定重点区域大气污染联合防治行动计划，明确控制目标，优化区域经济布局，统筹交通管理，发展清洁能源，提出重点防治任务和措施，促进重点区域大气环境质量改善。"},{"i":88,"n":"第八十八条","txt":"国务院经济综合主管部门会同国务院生态环境主管部门，结合国家大气污染防治重点区域产业发展实际和大气环境质量状况，进一步提高环境保护、能耗、安全、质量等要求。"},{"i":89,"n":"第八十九条","txt":"编制可能对国家大气污染防治重点区域的大气环境造成严重污染的有关工业园区、开发区、区域产业和发展等规划，应当依法进行环境影响评价。规划编制机关应当与重点区域内有关省、自治区、直辖市人民政府或者有关部门会商。"},{"i":90,"n":"第九十条","txt":"国家大气污染防治重点区域内新建、改建、扩建用煤项目的，应当实行煤炭的等量或者减量替代。"},{"i":91,"n":"第九十一条","txt":"国务院生态环境主管部门应当组织建立国家大气污染防治重点区域的大气环境质量监测、大气污染源监测等相关信息共享机制，利用监测、模拟以及卫星、航测、遥感等新技术分析重点区域内大气污染来源及其变化趋势，并向社会公开。"},{"i":92,"n":"第九十二条","txt":"国务院生态环境主管部门和国家大气污染防治重点区域内有关省、自治区、直辖市人民政府可以组织有关部门开展联合执法、跨区域执法、交叉执法。"},{"i":93,"n":"第九十三条","txt":"国家建立重污染天气监测预警体系。"},{"i":94,"n":"第九十四条","txt":"县级以上地方人民政府应当将重污染天气应对纳入突发事件应急管理体系。"},{"i":95,"n":"第九十五条","txt":"省、自治区、直辖市、设区的市人民政府生态环境主管部门应当会同气象主管机构建立会商机制，进行大气环境质量预报。可能发生重污染天气的，应当及时向本级人民政府报告。省、自治区、直辖市、设区的市人民政府依据重污染天气预报信息，进行综合研判，确定预警等级并及时发出预警。预警等级根据情况变化及时调整。任何单位和个人不得擅自向社会发布重污染天气预报预警信息。"},{"i":96,"n":"第九十六条","txt":"县级以上地方人民政府应当依据重污染天气的预警等级，及时启动应急预案，根据应急需要可以采取责令有关企业停产或者限产、限制部分机动车行驶、禁止燃放烟花爆竹、停止工地土石方作业和建筑物拆除施工、停止露天烧烤、停止幼儿园和学校组织的户外活动、组织开展人工影响天气作业等应急措施。"},{"i":97,"n":"第九十七条","txt":"发生造成大气污染的突发环境事件，人民政府及其有关部门和相关企业事业单位，应当依照《中华人民共和国突发事件应对法》、《中华人民共和国环境保护法》的规定，做好应急处置工作。生态环境主管部门应当及时对突发环境事件产生的大气污染物进行监测，并向社会公布监测信息。"},{"i":98,"n":"第九十八条","txt":"违反本法规定，以拒绝进入现场等方式拒不接受生态环境主管部门及其环境执法机构或者其他负有大气环境保护监督管理职责的部门的监督检查，或者在接受监督检查时弄虚作假的，由县级以上人民政府生态环境主管部门或者其他负有大气环境保护监督管理职责的部门责令改正，处二万元以上二十万元以下的罚款；构成违反治安管理行为的，由公安机关依法予以处罚。"},{"i":99,"n":"第九十九条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府生态环境主管部门责令改正或者限制生产、停产整治，并处十万元以上一百万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":100,"n":"第一百条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府生态环境主管部门责令改正，处二万元以上二十万元以下的罚款；拒不改正的，责令停产整治："},{"i":101,"n":"第一百零一条","txt":"违反本法规定，生产、进口、销售或者使用国家综合性产业政策目录中禁止的设备和产品，采用国家综合性产业政策目录中禁止的工艺，或者将淘汰的设备和产品转让给他人使用的，由县级以上人民政府经济综合主管部门、海关按照职责责令改正，没收违法所得，并处货值金额一倍以上三倍以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业、关闭。进口行为构成走私的，由海关依法予以处罚。"},{"i":102,"n":"第一百零二条","txt":"违反本法规定，煤矿未按照规定建设配套煤炭洗选设施的，由县级以上人民政府能源主管部门责令改正，处十万元以上一百万元以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":103,"n":"第一百零三条","txt":"违反本法规定，有下列行为之一的，由县级以上地方人民政府市场监督管理部门责令改正，没收原材料、产品和违法所得，并处货值金额一倍以上三倍以下的罚款："},{"i":104,"n":"第一百零四条","txt":"违反本法规定，有下列行为之一的，由海关责令改正，没收原材料、产品和违法所得，并处货值金额一倍以上三倍以下的罚款；构成走私的，由海关依法予以处罚："},{"i":105,"n":"第一百零五条","txt":"违反本法规定，单位燃用不符合质量标准的煤炭、石油焦的，由县级以上人民政府生态环境主管部门责令改正，处货值金额一倍以上三倍以下的罚款。"},{"i":106,"n":"第一百零六条","txt":"违反本法规定，使用不符合标准或者要求的船舶用燃油的，由海事管理机构、渔业主管部门按照职责处一万元以上十万元以下的罚款。"},{"i":107,"n":"第一百零七条","txt":"违反本法规定，在禁燃区内新建、扩建燃用高污染燃料的设施，或者未按照规定停止燃用高污染燃料，或者在城市集中供热管网覆盖地区新建、扩建分散燃煤供热锅炉，或者未按照规定拆除已建成的不能达标排放的燃煤供热锅炉的，由县级以上地方人民政府生态环境主管部门没收燃用高污染燃料的设施，组织拆除燃煤供热锅炉，并处二万元以上二十万元以下的罚款。"},{"i":108,"n":"第一百零八条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府生态环境主管部门责令改正，处二万元以上二十万元以下的罚款；拒不改正的，责令停产整治："},{"i":109,"n":"第一百零九条","txt":"违反本法规定，生产超过污染物排放标准的机动车、非道路移动机械的，由省级以上人民政府生态环境主管部门责令改正，没收违法所得，并处货值金额一倍以上三倍以下的罚款，没收销毁无法达到污染物排放标准的机动车、非道路移动机械；拒不改正的，责令停产整治，并由国务院机动车生产主管部门责令停止生产该车型。"},{"i":110,"n":"第一百一十条","txt":"违反本法规定，进口、销售超过污染物排放标准的机动车、非道路移动机械的，由县级以上人民政府市场监督管理部门、海关按照职责没收违法所得，并处货值金额一倍以上三倍以下的罚款，没收销毁无法达到污染物排放标准的机动车、非道路移动机械；进口行为构成走私的，由海关依法予以处罚。"},{"i":111,"n":"第一百一十一条","txt":"违反本法规定，机动车生产、进口企业未按照规定向社会公布其生产、进口机动车车型的排放检验信息或者污染控制技术信息的，由省级以上人民政府生态环境主管部门责令改正，处五万元以上五十万元以下的罚款。"},{"i":112,"n":"第一百一十二条","txt":"违反本法规定，伪造机动车、非道路移动机械排放检验结果或者出具虚假排放检验报告的，由县级以上人民政府生态环境主管部门没收违法所得，并处十万元以上五十万元以下的罚款；情节严重的，由负责资质认定的部门取消其检验资格。"},{"i":113,"n":"第一百一十三条","txt":"违反本法规定，机动车驾驶人驾驶排放检验不合格的机动车上道路行驶的，由公安机关交通管理部门依法予以处罚。"},{"i":114,"n":"第一百一十四条","txt":"违反本法规定，使用排放不合格的非道路移动机械，或者在用重型柴油车、非道路移动机械未按照规定加装、更换污染控制装置的，由县级以上人民政府生态环境等主管部门按照职责责令改正，处五千元的罚款。"},{"i":115,"n":"第一百一十五条","txt":"违反本法规定，施工单位有下列行为之一的，由县级以上人民政府住房城乡建设等主管部门按照职责责令改正，处一万元以上十万元以下的罚款；拒不改正的，责令停工整治："},{"i":116,"n":"第一百一十六条","txt":"违反本法规定，运输煤炭、垃圾、渣土、砂石、土方、灰浆等散装、流体物料的车辆，未采取密闭或者其他措施防止物料遗撒的，由县级以上地方人民政府确定的监督管理部门责令改正，处二千元以上二万元以下的罚款；拒不改正的，车辆不得上道路行驶。"},{"i":117,"n":"第一百一十七条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府生态环境等主管部门按照职责责令改正，处一万元以上十万元以下的罚款；拒不改正的，责令停工整治或者停业整治："},{"i":118,"n":"第一百一十八条","txt":"违反本法规定，排放油烟的餐饮服务业经营者未安装油烟净化设施、不正常使用油烟净化设施或者未采取其他油烟净化措施，超过排放标准排放油烟的，由县级以上地方人民政府确定的监督管理部门责令改正，处五千元以上五万元以下的罚款；拒不改正的，责令停业整治。"},{"i":119,"n":"第一百一十九条","txt":"违反本法规定，在人口集中地区对树木、花草喷洒剧毒、高毒农药，或者露天焚烧秸秆、落叶等产生烟尘污染的物质的，由县级以上地方人民政府确定的监督管理部门责令改正，并可以处五百元以上二千元以下的罚款。"},{"i":120,"n":"第一百二十条","txt":"违反本法规定，从事服装干洗和机动车维修等服务活动，未设置异味和废气处理装置等污染防治设施并保持正常使用，影响周边环境的，由县级以上地方人民政府生态环境主管部门责令改正，处二千元以上二万元以下的罚款；拒不改正的，责令停业整治。"},{"i":121,"n":"第一百二十一条","txt":"违反本法规定，擅自向社会发布重污染天气预报预警信息，构成违反治安管理行为的，由公安机关依法予以处罚。"},{"i":122,"n":"第一百二十二条","txt":"违反本法规定，造成大气污染事故的，由县级以上人民政府生态环境主管部门依照本条第二款的规定处以罚款；对直接负责的主管人员和其他直接责任人员可以处上一年度从本企业事业单位取得收入百分之五十以下的罚款。"},{"i":123,"n":"第一百二十三条","txt":"违反本法规定，企业事业单位和其他生产经营者有下列行为之一，受到罚款处罚，被责令改正，拒不改正的，依法作出处罚决定的行政机关可以自责令改正之日的次日起，按照原处罚数额按日连续处罚："},{"i":124,"n":"第一百二十四条","txt":"违反本法规定，对举报人以解除、变更劳动合同或者其他方式打击报复的，应当依照有关法律的规定承担责任。"},{"i":125,"n":"第一百二十五条","txt":"排放大气污染物造成损害的，应当依法承担侵权责任。"},{"i":126,"n":"第一百二十六条","txt":"地方各级人民政府、县级以上人民政府生态环境主管部门和其他负有大气环境保护监督管理职责的部门及其工作人员滥用职权、玩忽职守、徇私舞弊、弄虚作假的，依法给予处分。"},{"i":127,"n":"第一百二十七条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":128,"n":"第一百二十八条","txt":"海洋工程的大气污染防治，依照《中华人民共和国海洋环境保护法》的有关规定执行。"},{"i":129,"n":"第一百二十九条","txt":"本法自2016年1月1日起施行。"}],"daqiwuranfangzhifa":[{"i":1,"n":"第一条","txt":"为保护和改善环境，防治大气污染，保障公众健康，推进生态文明建设，促进经济社会可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"防治大气污染，应当以改善大气环境质量为目标，坚持源头治理，规划先行，转变经济发展方式，优化产业结构和布局，调整能源结构。"},{"i":3,"n":"第三条","txt":"县级以上人民政府应当将大气污染防治工作纳入国民经济和社会发展规划，加大对大气污染防治的财政投入。"},{"i":4,"n":"第四条","txt":"国务院环境保护主管部门会同国务院有关部门，按照国务院的规定，对省、自治区、直辖市大气环境质量改善目标、大气污染防治重点任务完成情况进行考核。省、自治区、直辖市人民政府制定考核办法，对本行政区域内地方大气环境质量改善目标、大气污染防治重点任务完成情况实施考核。考核结果应当向社会公开。"},{"i":5,"n":"第五条","txt":"县级以上人民政府环境保护主管部门对大气污染防治实施统一监督管理。"},{"i":6,"n":"第六条","txt":"国家鼓励和支持大气污染防治科学技术研究，开展对大气污染来源及其变化趋势的分析，推广先进适用的大气污染防治技术和装备，促进科技成果转化，发挥科学技术在大气污染防治中的支撑作用。"},{"i":7,"n":"第七条","txt":"企业事业单位和其他生产经营者应当采取有效措施，防止、减少大气污染，对所造成的损害依法承担责任。"},{"i":8,"n":"第八条","txt":"国务院环境保护主管部门或者省、自治区、直辖市人民政府制定大气环境质量标准，应当以保障公众健康和保护生态环境为宗旨，与经济社会发展相适应，做到科学合理。"},{"i":9,"n":"第九条","txt":"国务院环境保护主管部门或者省、自治区、直辖市人民政府制定大气污染物排放标准，应当以大气环境质量标准和国家经济、技术条件为依据。"},{"i":10,"n":"第十条","txt":"制定大气环境质量标准、大气污染物排放标准，应当组织专家进行审查和论证，并征求有关部门、行业协会、企业事业单位和公众等方面的意见。"},{"i":11,"n":"第十一条","txt":"省级以上人民政府环境保护主管部门应当在其网站上公布大气环境质量标准、大气污染物排放标准，供公众免费查阅、下载。"},{"i":12,"n":"第十二条","txt":"大气环境质量标准、大气污染物排放标准的执行情况应当定期进行评估，根据评估结果对标准适时进行修订。"},{"i":13,"n":"第十三条","txt":"制定燃煤、石油焦、生物质燃料、涂料等含挥发性有机物的产品、烟花爆竹以及锅炉等产品的质量标准，应当明确大气环境保护要求。"},{"i":14,"n":"第十四条","txt":"未达到国家大气环境质量标准城市的人民政府应当及时编制大气环境质量限期达标规划，采取措施，按照国务院或者省级人民政府规定的期限达到大气环境质量标准。"},{"i":15,"n":"第十五条","txt":"城市大气环境质量限期达标规划应当向社会公开。直辖市和设区的市的大气环境质量限期达标规划应当报国务院环境保护主管部门备案。"},{"i":16,"n":"第十六条","txt":"城市人民政府每年在向本级人民代表大会或者其常务委员会报告环境状况和环境保护目标完成情况时，应当报告大气环境质量限期达标规划执行情况，并向社会公开。"},{"i":17,"n":"第十七条","txt":"城市大气环境质量限期达标规划应当根据大气污染防治的要求和经济、技术条件适时进行评估、修订。"},{"i":18,"n":"第十八条","txt":"企业事业单位和其他生产经营者建设对大气环境有影响的项目，应当依法进行环境影响评价、公开环境影响评价文件；向大气排放污染物的，应当符合大气污染物排放标准，遵守重点大气污染物排放总量控制要求。"},{"i":19,"n":"第十九条","txt":"排放工业废气或者本法第七十八条规定名录中所列有毒有害大气污染物的企业事业单位、集中供热设施的燃煤热源生产运营单位以及其他依法实行排污许可管理的单位，应当取得排污许可证。排污许可的具体办法和实施步骤由国务院规定。"},{"i":20,"n":"第二十条","txt":"企业事业单位和其他生产经营者向大气排放污染物的，应当依照法律法规和国务院环境保护主管部门的规定设置大气污染物排放口。"},{"i":21,"n":"第二十一条","txt":"国家对重点大气污染物排放实行总量控制。"},{"i":22,"n":"第二十二条","txt":"对超过国家重点大气污染物排放总量控制指标或者未完成国家下达的大气环境质量改善目标的地区，省级以上人民政府环境保护主管部门应当会同有关部门约谈该地区人民政府的主要负责人，并暂停审批该地区新增重点大气污染物排放总量的建设项目环境影响评价文件。约谈情况应当向社会公开。"},{"i":23,"n":"第二十三条","txt":"国务院环境保护主管部门负责制定大气环境质量和大气污染源的监测和评价规范，组织建设与管理全国大气环境质量和大气污染源监测网，组织开展大气环境质量和大气污染源监测，统一发布全国大气环境质量状况信息。"},{"i":24,"n":"第二十四条","txt":"企业事业单位和其他生产经营者应当按照国家有关规定和监测规范，对其排放的工业废气和本法第七十八条规定名录中所列有毒有害大气污染物进行监测，并保存原始监测记录。其中，重点排污单位应当安装、使用大气污染物排放自动监测设备，与环境保护主管部门的监控设备联网，保证监测设备正常运行并依法公开排放信息。监测的具体办法和重点排污单位的条件由国务院环境保护主管部门规定。"},{"i":25,"n":"第二十五条","txt":"重点排污单位应当对自动监测数据的真实性和准确性负责。环境保护主管部门发现重点排污单位的大气污染物排放自动监测设备传输数据异常，应当及时进行调查。"},{"i":26,"n":"第二十六条","txt":"禁止侵占、损毁或者擅自移动、改变大气环境质量监测设施和大气污染物排放自动监测设备。"},{"i":27,"n":"第二十七条","txt":"国家对严重污染大气环境的工艺、设备和产品实行淘汰制度。"},{"i":28,"n":"第二十八条","txt":"国务院环境保护主管部门会同有关部门，建立和完善大气污染损害评估制度。"},{"i":29,"n":"第二十九条","txt":"环境保护主管部门及其委托的环境监察机构和其他负有大气环境保护监督管理职责的部门，有权通过现场检查监测、自动监测、遥感监测、远红外摄像等方式，对排放大气污染物的企业事业单位和其他生产经营者进行监督检查。被检查者应当如实反映情况，提供必要的资料。实施检查的部门、机构及其工作人员应当为被检查者保守商业秘密。"},{"i":30,"n":"第三十条","txt":"企业事业单位和其他生产经营者违反法律法规规定排放大气污染物，造成或者可能造成严重大气污染，或者有关证据可能灭失或者被隐匿的，县级以上人民政府环境保护主管部门和其他负有大气环境保护监督管理职责的部门，可以对有关设施、设备、物品采取查封、扣押等行政强制措施。"},{"i":31,"n":"第三十一条","txt":"环境保护主管部门和其他负有大气环境保护监督管理职责的部门应当公布举报电话、电子邮箱等，方便公众举报。"},{"i":32,"n":"第三十二条","txt":"国务院有关部门和地方各级人民政府应当采取措施，调整能源结构，推广清洁能源的生产和使用；优化煤炭使用方式，推广煤炭清洁高效利用，逐步降低煤炭在一次能源消费中的比重，减少煤炭生产、使用、转化过程中的大气污染物排放。"},{"i":33,"n":"第三十三条","txt":"国家推行煤炭洗选加工，降低煤炭的硫分和灰分，限制高硫分、高灰分煤炭的开采。新建煤矿应当同步建设配套的煤炭洗选设施，使煤炭的硫分、灰分含量达到规定标准；已建成的煤矿除所采煤炭属于低硫分、低灰分或者根据已达标排放的燃煤电厂要求不需要洗选的以外，应当限期建成配套的煤炭洗选设施。"},{"i":34,"n":"第三十四条","txt":"国家采取有利于煤炭清洁高效利用的经济、技术政策和措施，鼓励和支持洁净煤技术的开发和推广。"},{"i":35,"n":"第三十五条","txt":"国家禁止进口、销售和燃用不符合质量标准的煤炭，鼓励燃用优质煤炭。"},{"i":36,"n":"第三十六条","txt":"地方各级人民政府应当采取措施，加强民用散煤的管理，禁止销售不符合民用散煤质量标准的煤炭，鼓励居民燃用优质煤炭和洁净型煤，推广节能环保型炉灶。"},{"i":37,"n":"第三十七条","txt":"石油炼制企业应当按照燃油质量标准生产燃油。"},{"i":38,"n":"第三十八条","txt":"城市人民政府可以划定并公布高污染燃料禁燃区，并根据大气环境质量改善要求，逐步扩大高污染燃料禁燃区范围。高污染燃料的目录由国务院环境保护主管部门确定。"},{"i":39,"n":"第三十九条","txt":"城市建设应当统筹规划，在燃煤供热地区，推进热电联产和集中供热。在集中供热管网覆盖地区，禁止新建、扩建分散燃煤供热锅炉；已建成的不能达标排放的燃煤供热锅炉，应当在城市人民政府规定的期限内拆除。"},{"i":40,"n":"第四十条","txt":"县级以上人民政府质量监督部门应当会同环境保护主管部门对锅炉生产、进口、销售和使用环节执行环境保护标准或者要求的情况进行监督检查；不符合环境保护标准或者要求的，不得生产、进口、销售和使用。"},{"i":41,"n":"第四十一条","txt":"燃煤电厂和其他燃煤单位应当采用清洁生产工艺，配套建设除尘、脱硫、脱硝等装置，或者采取技术改造等其他控制大气污染物排放的措施。"},{"i":42,"n":"第四十二条","txt":"电力调度应当优先安排清洁能源发电上网。"},{"i":43,"n":"第四十三条","txt":"钢铁、建材、有色金属、石油、化工等企业生产过程中排放粉尘、硫化物和氮氧化物的，应当采用清洁生产工艺，配套建设除尘、脱硫、脱硝等装置，或者采取技术改造等其他控制大气污染物排放的措施。"},{"i":44,"n":"第四十四条","txt":"生产、进口、销售和使用含挥发性有机物的原材料和产品的，其挥发性有机物含量应当符合质量标准或者要求。"},{"i":45,"n":"第四十五条","txt":"产生含挥发性有机物废气的生产和服务活动，应当在密闭空间或者设备中进行，并按照规定安装、使用污染防治设施；无法密闭的，应当采取措施减少废气排放。"},{"i":46,"n":"第四十六条","txt":"工业涂装企业应当使用低挥发性有机物含量的涂料，并建立台账，记录生产原料、辅料的使用量、废弃量、去向以及挥发性有机物含量。台账保存期限不得少于三年。"},{"i":47,"n":"第四十七条","txt":"石油、化工以及其他生产和使用有机溶剂的企业，应当采取措施对管道、设备进行日常维护、维修，减少物料泄漏，对泄漏的物料应当及时收集处理。"},{"i":48,"n":"第四十八条","txt":"钢铁、建材、有色金属、石油、化工、制药、矿产开采等企业，应当加强精细化管理，采取集中收集处理等措施，严格控制粉尘和气态污染物的排放。"},{"i":49,"n":"第四十九条","txt":"工业生产、垃圾填埋或者其他活动产生的可燃性气体应当回收利用，不具备回收利用条件的，应当进行污染防治处理。"},{"i":50,"n":"第五十条","txt":"国家倡导低碳、环保出行，根据城市规划合理控制燃油机动车保有量，大力发展城市公共交通，提高公共交通出行比例。"},{"i":51,"n":"第五十一条","txt":"机动车船、非道路移动机械不得超过标准排放大气污染物。"},{"i":52,"n":"第五十二条","txt":"机动车、非道路移动机械生产企业应当对新生产的机动车和非道路移动机械进行排放检验。经检验合格的，方可出厂销售。检验信息应当向社会公开。"},{"i":53,"n":"第五十三条","txt":"在用机动车应当按照国家或者地方的有关规定，由机动车排放检验机构定期对其进行排放检验。经检验合格的，方可上道路行驶。未经检验合格的，公安机关交通管理部门不得核发安全技术检验合格标志。"},{"i":54,"n":"第五十四条","txt":"机动车排放检验机构应当依法通过计量认证，使用经依法检定合格的机动车排放检验设备，按照国务院环境保护主管部门制定的规范，对机动车进行排放检验，并与环境保护主管部门联网，实现检验数据实时共享。机动车排放检验机构及其负责人对检验数据的真实性和准确性负责。"},{"i":55,"n":"第五十五条","txt":"机动车生产、进口企业应当向社会公布其生产、进口机动车车型的排放检验信息、污染控制技术信息和有关维修技术信息。"},{"i":56,"n":"第五十六条","txt":"环境保护主管部门应当会同交通运输、住房城乡建设、农业行政、水行政等有关部门对非道路移动机械的大气污染物排放状况进行监督检查，排放不合格的，不得使用。"},{"i":57,"n":"第五十七条","txt":"国家倡导环保驾驶，鼓励燃油机动车驾驶人在不影响道路通行且需停车三分钟以上的情况下熄灭发动机，减少大气污染物的排放。"},{"i":58,"n":"第五十八条","txt":"国家建立机动车和非道路移动机械环境保护召回制度。"},{"i":59,"n":"第五十九条","txt":"在用重型柴油车、非道路移动机械未安装污染控制装置或者污染控制装置不符合要求，不能达标排放的，应当加装或者更换符合要求的污染控制装置。"},{"i":60,"n":"第六十条","txt":"在用机动车排放大气污染物超过标准的，应当进行维修；经维修或者采用污染控制技术后，大气污染物排放仍不符合国家在用机动车排放标准的，应当强制报废。其所有人应当将机动车交售给报废机动车回收拆解企业，由报废机动车回收拆解企业按照国家有关规定进行登记、拆解、销毁等处理。"},{"i":61,"n":"第六十一条","txt":"城市人民政府可以根据大气环境质量状况，划定并公布禁止使用高排放非道路移动机械的区域。"},{"i":62,"n":"第六十二条","txt":"船舶检验机构对船舶发动机及有关设备进行排放检验。经检验符合国家排放标准的，船舶方可运营。"},{"i":63,"n":"第六十三条","txt":"内河和江海直达船舶应当使用符合标准的普通柴油。远洋船舶靠港后应当使用符合大气污染物控制要求的船舶用燃油。"},{"i":64,"n":"第六十四条","txt":"国务院交通运输主管部门可以在沿海海域划定船舶大气污染物排放控制区，进入排放控制区的船舶应当符合船舶相关排放要求。"},{"i":65,"n":"第六十五条","txt":"禁止生产、进口、销售不符合标准的机动车船、非道路移动机械用燃料；禁止向汽车和摩托车销售普通柴油以及其他非机动车用燃料；禁止向非道路移动机械、内河和江海直达船舶销售渣油和重油。"},{"i":66,"n":"第六十六条","txt":"发动机油、氮氧化物还原剂、燃料和润滑油添加剂以及其他添加剂的有害物质含量和其他大气环境保护指标，应当符合有关标准的要求，不得损害机动车船污染控制装置效果和耐久性，不得增加新的大气污染物排放。"},{"i":67,"n":"第六十七条","txt":"国家积极推进民用航空器的大气污染防治，鼓励在设计、生产、使用过程中采取有效措施减少大气污染物排放。"},{"i":68,"n":"第六十八条","txt":"地方各级人民政府应当加强对建设施工和运输的管理，保持道路清洁，控制料堆和渣土堆放，扩大绿地、水面、湿地和地面铺装面积，防治扬尘污染。"},{"i":69,"n":"第六十九条","txt":"建设单位应当将防治扬尘污染的费用列入工程造价，并在施工承包合同中明确施工单位扬尘污染防治责任。施工单位应当制定具体的施工扬尘污染防治实施方案。"},{"i":70,"n":"第七十条","txt":"运输煤炭、垃圾、渣土、砂石、土方、灰浆等散装、流体物料的车辆应当采取密闭或者其他措施防止物料遗撒造成扬尘污染，并按照规定路线行驶。"},{"i":71,"n":"第七十一条","txt":"市政河道以及河道沿线、公共用地的裸露地面以及其他城镇裸露地面，有关部门应当按照规划组织实施绿化或者透水铺装。"},{"i":72,"n":"第七十二条","txt":"贮存煤炭、煤矸石、煤渣、煤灰、水泥、石灰、石膏、砂土等易产生扬尘的物料应当密闭；不能密闭的，应当设置不低于堆放物高度的严密围挡，并采取有效覆盖措施防治扬尘污染。"},{"i":73,"n":"第七十三条","txt":"地方各级人民政府应当推动转变农业生产方式，发展农业循环经济，加大对废弃物综合处理的支持力度，加强对农业生产经营活动排放大气污染物的控制。"},{"i":74,"n":"第七十四条","txt":"农业生产经营者应当改进施肥方式，科学合理施用化肥并按照国家有关规定使用农药，减少氨、挥发性有机物等大气污染物的排放。"},{"i":75,"n":"第七十五条","txt":"畜禽养殖场、养殖小区应当及时对污水、畜禽粪便和尸体等进行收集、贮存、清运和无害化处理，防止排放恶臭气体。"},{"i":76,"n":"第七十六条","txt":"各级人民政府及其农业行政等有关部门应当鼓励和支持采用先进适用技术，对秸秆、落叶等进行肥料化、饲料化、能源化、工业原料化、食用菌基料化等综合利用，加大对秸秆还田、收集一体化农业机械的财政补贴力度。"},{"i":77,"n":"第七十七条","txt":"省、自治区、直辖市人民政府应当划定区域，禁止露天焚烧秸秆、落叶等产生烟尘污染的物质。"},{"i":78,"n":"第七十八条","txt":"国务院环境保护主管部门应当会同国务院卫生行政部门，根据大气污染物对公众健康和生态环境的危害和影响程度，公布有毒有害大气污染物名录，实行风险管理。"},{"i":79,"n":"第七十九条","txt":"向大气排放持久性有机污染物的企业事业单位和其他生产经营者以及废弃物焚烧设施的运营单位，应当按照国家有关规定，采取有利于减少持久性有机污染物排放的技术方法和工艺，配备有效的净化装置，实现达标排放。"},{"i":80,"n":"第八十条","txt":"企业事业单位和其他生产经营者在生产经营活动中产生恶臭气体的，应当科学选址，设置合理的防护距离，并安装净化装置或者采取其他措施，防止排放恶臭气体。"},{"i":81,"n":"第八十一条","txt":"排放油烟的餐饮服务业经营者应当安装油烟净化设施并保持正常使用，或者采取其他油烟净化措施，使油烟达标排放，并防止对附近居民的正常生活环境造成污染。"},{"i":82,"n":"第八十二条","txt":"禁止在人口集中地区和其他依法需要特殊保护的区域内焚烧沥青、油毡、橡胶、塑料、皮革、垃圾以及其他产生有毒有害烟尘和恶臭气体的物质。"},{"i":83,"n":"第八十三条","txt":"国家鼓励和倡导文明、绿色祭祀。"},{"i":84,"n":"第八十四条","txt":"从事服装干洗和机动车维修等服务活动的经营者，应当按照国家有关标准或者要求设置异味和废气处理装置等污染防治设施并保持正常使用，防止影响周边环境。"},{"i":85,"n":"第八十五条","txt":"国家鼓励、支持消耗臭氧层物质替代品的生产和使用，逐步减少直至停止消耗臭氧层物质的生产和使用。"},{"i":86,"n":"第八十六条","txt":"国家建立重点区域大气污染联防联控机制，统筹协调重点区域内大气污染防治工作。国务院环境保护主管部门根据主体功能区划、区域大气环境质量状况和大气污染传输扩散规律，划定国家大气污染防治重点区域，报国务院批准。"},{"i":87,"n":"第八十七条","txt":"国务院环境保护主管部门会同国务院有关部门、国家大气污染防治重点区域内有关省、自治区、直辖市人民政府，根据重点区域经济社会发展和大气环境承载力，制定重点区域大气污染联合防治行动计划，明确控制目标，优化区域经济布局，统筹交通管理，发展清洁能源，提出重点防治任务和措施，促进重点区域大气环境质量改善。"},{"i":88,"n":"第八十八条","txt":"国务院经济综合主管部门会同国务院环境保护主管部门，结合国家大气污染防治重点区域产业发展实际和大气环境质量状况，进一步提高环境保护、能耗、安全、质量等要求。"},{"i":89,"n":"第八十九条","txt":"编制可能对国家大气污染防治重点区域的大气环境造成严重污染的有关工业园区、开发区、区域产业和发展等规划，应当依法进行环境影响评价。规划编制机关应当与重点区域内有关省、自治区、直辖市人民政府或者有关部门会商。"},{"i":90,"n":"第九十条","txt":"国家大气污染防治重点区域内新建、改建、扩建用煤项目的，应当实行煤炭的等量或者减量替代。"},{"i":91,"n":"第九十一条","txt":"国务院环境保护主管部门应当组织建立国家大气污染防治重点区域的大气环境质量监测、大气污染源监测等相关信息共享机制，利用监测、模拟以及卫星、航测、遥感等新技术分析重点区域内大气污染来源及其变化趋势，并向社会公开。"},{"i":92,"n":"第九十二条","txt":"国务院环境保护主管部门和国家大气污染防治重点区域内有关省、自治区、直辖市人民政府可以组织有关部门开展联合执法、跨区域执法、交叉执法。"},{"i":93,"n":"第九十三条","txt":"国家建立重污染天气监测预警体系。"},{"i":94,"n":"第九十四条","txt":"县级以上地方人民政府应当将重污染天气应对纳入突发事件应急管理体系。"},{"i":95,"n":"第九十五条","txt":"省、自治区、直辖市、设区的市人民政府环境保护主管部门应当会同气象主管机构建立会商机制，进行大气环境质量预报。可能发生重污染天气的，应当及时向本级人民政府报告。省、自治区、直辖市、设区的市人民政府依据重污染天气预报信息，进行综合研判，确定预警等级并及时发出预警。预警等级根据情况变化及时调整。任何单位和个人不得擅自向社会发布重污染天气预报预警信息。"},{"i":96,"n":"第九十六条","txt":"县级以上地方人民政府应当依据重污染天气的预警等级，及时启动应急预案，根据应急需要可以采取责令有关企业停产或者限产、限制部分机动车行驶、禁止燃放烟花爆竹、停止工地土石方作业和建筑物拆除施工、停止露天烧烤、停止幼儿园和学校组织的户外活动、组织开展人工影响天气作业等应急措施。"},{"i":97,"n":"第九十七条","txt":"发生造成大气污染的突发环境事件，人民政府及其有关部门和相关企业事业单位，应当依照《中华人民共和国突发事件应对法》、《中华人民共和国环境保护法》的规定，做好应急处置工作。环境保护主管部门应当及时对突发环境事件产生的大气污染物进行监测，并向社会公布监测信息。"},{"i":98,"n":"第九十八条","txt":"违反本法规定，以拒绝进入现场等方式拒不接受环境保护主管部门及其委托的环境监察机构或者其他负有大气环境保护监督管理职责的部门的监督检查，或者在接受监督检查时弄虚作假的，由县级以上人民政府环境保护主管部门或者其他负有大气环境保护监督管理职责的部门责令改正，处二万元以上二十万元以下的罚款；构成违反治安管理行为的，由公安机关依法予以处罚。"},{"i":99,"n":"第九十九条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府环境保护主管部门责令改正或者限制生产、停产整治，并处十万元以上一百万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":100,"n":"第一百条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府环境保护主管部门责令改正，处二万元以上二十万元以下的罚款；拒不改正的，责令停产整治："},{"i":101,"n":"第一百零一条","txt":"违反本法规定，生产、进口、销售或者使用国家综合性产业政策目录中禁止的设备和产品，采用国家综合性产业政策目录中禁止的工艺，或者将淘汰的设备和产品转让给他人使用的，由县级以上人民政府经济综合主管部门、出入境检验检疫机构按照职责责令改正，没收违法所得，并处货值金额一倍以上三倍以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业、关闭。进口行为构成走私的，由海关依法予以处罚。"},{"i":102,"n":"第一百零二条","txt":"违反本法规定，煤矿未按照规定建设配套煤炭洗选设施的，由县级以上人民政府能源主管部门责令改正，处十万元以上一百万元以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":103,"n":"第一百零三条","txt":"违反本法规定，有下列行为之一的，由县级以上地方人民政府质量监督、工商行政管理部门按照职责责令改正，没收原材料、产品和违法所得，并处货值金额一倍以上三倍以下的罚款："},{"i":104,"n":"第一百零四条","txt":"违反本法规定，有下列行为之一的，由出入境检验检疫机构责令改正，没收原材料、产品和违法所得，并处货值金额一倍以上三倍以下的罚款；构成走私的，由海关依法予以处罚："},{"i":105,"n":"第一百零五条","txt":"违反本法规定，单位燃用不符合质量标准的煤炭、石油焦的，由县级以上人民政府环境保护主管部门责令改正，处货值金额一倍以上三倍以下的罚款。"},{"i":106,"n":"第一百零六条","txt":"违反本法规定，使用不符合标准或者要求的船舶用燃油的，由海事管理机构、渔业主管部门按照职责处一万元以上十万元以下的罚款。"},{"i":107,"n":"第一百零七条","txt":"违反本法规定，在禁燃区内新建、扩建燃用高污染燃料的设施，或者未按照规定停止燃用高污染燃料，或者在城市集中供热管网覆盖地区新建、扩建分散燃煤供热锅炉，或者未按照规定拆除已建成的不能达标排放的燃煤供热锅炉的，由县级以上地方人民政府环境保护主管部门没收燃用高污染燃料的设施，组织拆除燃煤供热锅炉，并处二万元以上二十万元以下的罚款。"},{"i":108,"n":"第一百零八条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府环境保护主管部门责令改正，处二万元以上二十万元以下的罚款；拒不改正的，责令停产整治："},{"i":109,"n":"第一百零九条","txt":"违反本法规定，生产超过污染物排放标准的机动车、非道路移动机械的，由省级以上人民政府环境保护主管部门责令改正，没收违法所得，并处货值金额一倍以上三倍以下的罚款，没收销毁无法达到污染物排放标准的机动车、非道路移动机械；拒不改正的，责令停产整治，并由国务院机动车生产主管部门责令停止生产该车型。"},{"i":110,"n":"第一百一十条","txt":"违反本法规定，进口、销售超过污染物排放标准的机动车、非道路移动机械的，由县级以上人民政府工商行政管理部门、出入境检验检疫机构按照职责没收违法所得，并处货值金额一倍以上三倍以下的罚款，没收销毁无法达到污染物排放标准的机动车、非道路移动机械；进口行为构成走私的，由海关依法予以处罚。"},{"i":111,"n":"第一百一十一条","txt":"违反本法规定，机动车生产、进口企业未按照规定向社会公布其生产、进口机动车车型的排放检验信息或者污染控制技术信息的，由省级以上人民政府环境保护主管部门责令改正，处五万元以上五十万元以下的罚款。"},{"i":112,"n":"第一百一十二条","txt":"违反本法规定，伪造机动车、非道路移动机械排放检验结果或者出具虚假排放检验报告的，由县级以上人民政府环境保护主管部门没收违法所得，并处十万元以上五十万元以下的罚款；情节严重的，由负责资质认定的部门取消其检验资格。"},{"i":113,"n":"第一百一十三条","txt":"违反本法规定，机动车驾驶人驾驶排放检验不合格的机动车上道路行驶的，由公安机关交通管理部门依法予以处罚。"},{"i":114,"n":"第一百一十四条","txt":"违反本法规定，使用排放不合格的非道路移动机械，或者在用重型柴油车、非道路移动机械未按照规定加装、更换污染控制装置的，由县级以上人民政府环境保护等主管部门按照职责责令改正，处五千元的罚款。"},{"i":115,"n":"第一百一十五条","txt":"违反本法规定，施工单位有下列行为之一的，由县级以上人民政府住房城乡建设等主管部门按照职责责令改正，处一万元以上十万元以下的罚款；拒不改正的，责令停工整治："},{"i":116,"n":"第一百一十六条","txt":"违反本法规定，运输煤炭、垃圾、渣土、砂石、土方、灰浆等散装、流体物料的车辆，未采取密闭或者其他措施防止物料遗撒的，由县级以上地方人民政府确定的监督管理部门责令改正，处二千元以上二万元以下的罚款；拒不改正的，车辆不得上道路行驶。"},{"i":117,"n":"第一百一十七条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府环境保护等主管部门按照职责责令改正，处一万元以上十万元以下的罚款；拒不改正的，责令停工整治或者停业整治："},{"i":118,"n":"第一百一十八条","txt":"违反本法规定，排放油烟的餐饮服务业经营者未安装油烟净化设施、不正常使用油烟净化设施或者未采取其他油烟净化措施，超过排放标准排放油烟的，由县级以上地方人民政府确定的监督管理部门责令改正，处五千元以上五万元以下的罚款；拒不改正的，责令停业整治。"},{"i":119,"n":"第一百一十九条","txt":"违反本法规定，在人口集中地区对树木、花草喷洒剧毒、高毒农药，或者露天焚烧秸秆、落叶等产生烟尘污染的物质的，由县级以上地方人民政府确定的监督管理部门责令改正，并可以处五百元以上二千元以下的罚款。"},{"i":120,"n":"第一百二十条","txt":"违反本法规定，从事服装干洗和机动车维修等服务活动，未设置异味和废气处理装置等污染防治设施并保持正常使用，影响周边环境的，由县级以上地方人民政府环境保护主管部门责令改正，处二千元以上二万元以下的罚款；拒不改正的，责令停业整治。"},{"i":121,"n":"第一百二十一条","txt":"违反本法规定，擅自向社会发布重污染天气预报预警信息，构成违反治安管理行为的，由公安机关依法予以处罚。"},{"i":122,"n":"第一百二十二条","txt":"违反本法规定，造成大气污染事故的，由县级以上人民政府环境保护主管部门依照本条第二款的规定处以罚款；对直接负责的主管人员和其他直接责任人员可以处上一年度从本企业事业单位取得收入百分之五十以下的罚款。"},{"i":123,"n":"第一百二十三条","txt":"违反本法规定，企业事业单位和其他生产经营者有下列行为之一，受到罚款处罚，被责令改正，拒不改正的，依法作出处罚决定的行政机关可以自责令改正之日的次日起，按照原处罚数额按日连续处罚："},{"i":124,"n":"第一百二十四条","txt":"违反本法规定，对举报人以解除、变更劳动合同或者其他方式打击报复的，应当依照有关法律的规定承担责任。"},{"i":125,"n":"第一百二十五条","txt":"排放大气污染物造成损害的，应当依法承担侵权责任。"},{"i":126,"n":"第一百二十六条","txt":"地方各级人民政府、县级以上人民政府环境保护主管部门和其他负有大气环境保护监督管理职责的部门及其工作人员滥用职权、玩忽职守、徇私舞弊、弄虚作假的，依法给予处分。"},{"i":127,"n":"第一百二十七条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":128,"n":"第一百二十八条","txt":"海洋工程的大气污染防治，依照《中华人民共和国海洋环境保护法》的有关规定执行。"},{"i":129,"n":"第一百二十九条","txt":"本法自2016年1月1日起施行。"}],"fangshexingwuranfangzhifa":[{"i":1,"n":"第一条","txt":"为了防治放射性污染，保护环境，保障人体健康，促进核能、核技术的开发与和平利用，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于中华人民共和国领域和管辖的其他海域在核设施选址、建造、运行、退役和核技术、铀（钍）矿、伴生放射性矿开发利用过程中发生的放射性污染的防治活动。"},{"i":3,"n":"第三条","txt":"国家对放射性污染的防治，实行预防为主、防治结合、严格管理、安全第一的方针。"},{"i":4,"n":"第四条","txt":"国家鼓励、支持放射性污染防治的科学研究和技术开发利用，推广先进的放射性污染防治技术。"},{"i":5,"n":"第五条","txt":"县级以上人民政府应当将放射性污染防治工作纳入环境保护规划。"},{"i":6,"n":"第六条","txt":"任何单位和个人有权对造成放射性污染的行为提出检举和控告。"},{"i":7,"n":"第七条","txt":"在放射性污染防治工作中作出显著成绩的单位和个人，由县级以上人民政府给予奖励。"},{"i":8,"n":"第八条","txt":"国务院环境保护行政主管部门对全国放射性污染防治工作依法实施统一监督管理。"},{"i":9,"n":"第九条","txt":"国家放射性污染防治标准由国务院环境保护行政主管部门根据环境安全要求、国家经济技术条件制定。国家放射性污染防治标准由国务院环境保护行政主管部门和国务院标准化行政主管部门联合发布。"},{"i":10,"n":"第十条","txt":"国家建立放射性污染监测制度。国务院环境保护行政主管部门会同国务院其他有关部门组织环境监测网络，对放射性污染实施监测管理。"},{"i":11,"n":"第十一条","txt":"国务院环境保护行政主管部门和国务院其他有关部门，按照职责分工，各负其责，互通信息，密切配合，对核设施、铀（钍）矿开发利用中的放射性污染防治进行监督检查。"},{"i":12,"n":"第十二条","txt":"核设施营运单位、核技术利用单位、铀（钍）矿和伴生放射性矿开发利用单位，负责本单位放射性污染的防治，接受环境保护行政主管部门和其他有关部门的监督管理，并依法对其造成的放射性污染承担责任。"},{"i":13,"n":"第十三条","txt":"核设施营运单位、核技术利用单位、铀（钍）矿和伴生放射性矿开发利用单位，必须采取安全与防护措施，预防发生可能导致放射性污染的各类事故，避免放射性污染危害。"},{"i":14,"n":"第十四条","txt":"国家对从事放射性污染防治的专业人员实行资格管理制度；对从事放射性污染监测工作的机构实行资质管理制度。"},{"i":15,"n":"第十五条","txt":"运输放射性物质和含放射源的射线装置，应当采取有效措施，防止放射性污染。具体办法由国务院规定。"},{"i":16,"n":"第十六条","txt":"放射性物质和射线装置应当设置明显的放射性标识和中文警示说明。生产、销售、使用、贮存、处置放射性物质和射线装置的场所，以及运输放射性物质和含放射源的射线装置的工具，应当设置明显的放射性标志。"},{"i":17,"n":"第十七条","txt":"含有放射性物质的产品，应当符合国家放射性污染防治标准；不符合国家放射性污染防治标准的，不得出厂和销售。"},{"i":18,"n":"第十八条","txt":"核设施选址，应当进行科学论证，并按照国家有关规定办理审批手续。在办理核设施选址审批手续前，应当编制环境影响报告书，报国务院环境保护行政主管部门审查批准；未经批准，有关部门不得办理核设施选址批准文件。"},{"i":19,"n":"第十九条","txt":"核设施营运单位在进行核设施建造、装料、运行、退役等活动前，必须按照国务院有关核设施安全监督管理的规定，申请领取核设施建造、运行许可证和办理装料、退役等审批手续。"},{"i":20,"n":"第二十条","txt":"核设施营运单位应当在申请领取核设施建造、运行许可证和办理退役审批手续前编制环境影响报告书，报国务院环境保护行政主管部门审查批准；未经批准，有关部门不得颁发许可证和办理批准文件。"},{"i":21,"n":"第二十一条","txt":"与核设施相配套的放射性污染防治设施，应当与主体工程同时设计、同时施工、同时投入使用。"},{"i":22,"n":"第二十二条","txt":"进口核设施，应当符合国家放射性污染防治标准；没有相应的国家放射性污染防治标准的，采用国务院环境保护行政主管部门指定的国外有关标准。"},{"i":23,"n":"第二十三条","txt":"核动力厂等重要核设施外围地区应当划定规划限制区。规划限制区的划定和管理办法，由国务院规定。"},{"i":24,"n":"第二十四条","txt":"核设施营运单位应当对核设施周围环境中所含的放射性核素的种类、浓度以及核设施流出物中的放射性核素总量实施监测，并定期向国务院环境保护行政主管部门和所在地省、自治区、直辖市人民政府环境保护行政主管部门报告监测结果。"},{"i":25,"n":"第二十五条","txt":"核设施营运单位应当建立健全安全保卫制度，加强安全保卫工作，并接受公安部门的监督指导。"},{"i":26,"n":"第二十六条","txt":"国家建立健全核事故应急制度。"},{"i":27,"n":"第二十七条","txt":"核设施营运单位应当制定核设施退役计划。"},{"i":28,"n":"第二十八条","txt":"生产、销售、使用放射性同位素和射线装置的单位，应当按照国务院有关放射性同位素与射线装置放射防护的规定申请领取许可证，办理登记手续。"},{"i":29,"n":"第二十九条","txt":"生产、销售、使用放射性同位素和加速器、中子发生器以及含放射源的射线装置的单位，应当在申请领取许可证前编制环境影响评价文件，报省、自治区、直辖市人民政府环境保护行政主管部门审查批准；未经批准，有关部门不得颁发许可证。"},{"i":30,"n":"第三十条","txt":"新建、改建、扩建放射工作场所的放射防护设施，应当与主体工程同时设计、同时施工、同时投入使用。"},{"i":31,"n":"第三十一条","txt":"放射性同位素应当单独存放，不得与易燃、易爆、腐蚀性物品等一起存放，其贮存场所应当采取有效的防火、防盗、防射线泄漏的安全防护措施，并指定专人负责保管。贮存、领取、使用、归还放射性同位素时，应当进行登记、检查，做到账物相符。"},{"i":32,"n":"第三十二条","txt":"生产、使用放射性同位素和射线装置的单位，应当按照国务院环境保护行政主管部门的规定对其产生的放射性废物进行收集、包装、贮存。"},{"i":33,"n":"第三十三条","txt":"生产、销售、使用、贮存放射源的单位，应当建立健全安全保卫制度，指定专人负责，落实安全责任制，制定必要的事故应急措施。发生放射源丢失、被盗和放射性污染事故时，有关单位和个人必须立即采取应急措施，并向公安部门、卫生行政部门和环境保护行政主管部门报告。"},{"i":34,"n":"第三十四条","txt":"开发利用或者关闭铀（钍）矿的单位，应当在申请领取采矿许可证或者办理退役审批手续前编制环境影响报告书，报国务院环境保护行政主管部门审查批准。"},{"i":35,"n":"第三十五条","txt":"与铀（钍）矿和伴生放射性矿开发利用建设项目相配套的放射性污染防治设施，应当与主体工程同时设计、同时施工、同时投入使用。"},{"i":36,"n":"第三十六条","txt":"铀（钍）矿开发利用单位应当对铀（钍）矿的流出物和周围的环境实施监测，并定期向国务院环境保护行政主管部门和所在地省、自治区、直辖市人民政府环境保护行政主管部门报告监测结果。"},{"i":37,"n":"第三十七条","txt":"对铀（钍）矿和伴生放射性矿开发利用过程中产生的尾矿，应当建造尾矿库进行贮存、处置；建造的尾矿库应当符合放射性污染防治的要求。"},{"i":38,"n":"第三十八条","txt":"铀（钍）矿开发利用单位应当制定铀（钍）矿退役计划。铀矿退役费用由国家财政预算安排。"},{"i":39,"n":"第三十九条","txt":"核设施营运单位、核技术利用单位、铀（钍）矿和伴生放射性矿开发利用单位，应当合理选择和利用原材料，采用先进的生产工艺和设备，尽量减少放射性废物的产生量。"},{"i":40,"n":"第四十条","txt":"向环境排放放射性废气、废液，必须符合国家放射性污染防治标准。"},{"i":41,"n":"第四十一条","txt":"产生放射性废气、废液的单位向环境排放符合国家放射性污染防治标准的放射性废气、废液，应当向审批环境影响评价文件的环境保护行政主管部门申请放射性核素排放量，并定期报告排放计量结果。"},{"i":42,"n":"第四十二条","txt":"产生放射性废液的单位，必须按照国家放射性污染防治标准的要求，对不得向环境排放的放射性废液进行处理或者贮存。"},{"i":43,"n":"第四十三条","txt":"低、中水平放射性固体废物在符合国家规定的区域实行近地表处置。"},{"i":44,"n":"第四十四条","txt":"国务院核设施主管部门会同国务院环境保护行政主管部门根据地质条件和放射性固体废物处置的需要，在环境影响评价的基础上编制放射性固体废物处置场所选址规划，报国务院批准后实施。"},{"i":45,"n":"第四十五条","txt":"产生放射性固体废物的单位，应当按照国务院环境保护行政主管部门的规定，对其产生的放射性固体废物进行处理后，送交放射性固体废物处置单位处置，并承担处置费用。"},{"i":46,"n":"第四十六条","txt":"设立专门从事放射性固体废物贮存、处置的单位，必须经国务院环境保护行政主管部门审查批准，取得许可证。具体办法由国务院规定。"},{"i":47,"n":"第四十七条","txt":"禁止将放射性废物和被放射性污染的物品输入中华人民共和国境内或者经中华人民共和国境内转移。"},{"i":48,"n":"第四十八条","txt":"放射性污染防治监督管理人员违反法律规定，利用职务上的便利收受他人财物、谋取其他利益，或者玩忽职守，有下列行为之一的，依法给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":49,"n":"第四十九条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府环境保护行政主管部门或者其他有关部门依据职权责令限期改正，可以处二万元以下罚款："},{"i":50,"n":"第五十条","txt":"违反本法规定，未编制环境影响评价文件，或者环境影响评价文件未经环境保护行政主管部门批准，擅自进行建造、运行、生产和使用等活动的，由审批环境影响评价文件的环境保护行政主管部门责令停止违法行为，限期补办手续或者恢复原状，并处一万元以上二十万元以下罚款。"},{"i":51,"n":"第五十一条","txt":"违反本法规定，未建造放射性污染防治设施、放射防护设施，或者防治防护设施未经验收合格，主体工程即投入生产或者使用的，由审批环境影响评价文件的环境保护行政主管部门责令停止违法行为，限期改正，并处五万元以上二十万元以下罚款。"},{"i":52,"n":"第五十二条","txt":"违反本法规定，未经许可或者批准，核设施营运单位擅自进行核设施的建造、装料、运行、退役等活动的，由国务院环境保护行政主管部门责令停止违法行为，限期改正，并处二十万元以上五十万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"违反本法规定，生产、销售、使用、转让、进口、贮存放射性同位素和射线装置以及装备有放射性同位素的仪表的，由县级以上人民政府环境保护行政主管部门或者其他有关部门依据职权责令停止违法行为，限期改正；逾期不改正的，责令停产停业或者吊销许可证；有违法所得的，没收违法所得；违法所得十万元以上的，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足十万元的，并处一万元以上十万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":54,"n":"第五十四条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府环境保护行政主管部门责令停止违法行为，限期改正，处以罚款；构成犯罪的，依法追究刑事责任："},{"i":55,"n":"第五十五条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府环境保护行政主管部门或者其他有关部门依据职权责令限期改正；逾期不改正的，责令停产停业，并处二万元以上十万元以下罚款；构成犯罪的，依法追究刑事责任："},{"i":56,"n":"第五十六条","txt":"产生放射性固体废物的单位，不按照本法第四十五条的规定对其产生的放射性固体废物进行处置的，由审批该单位立项环境影响评价文件的环境保护行政主管部门责令停止违法行为，限期改正；逾期不改正的，指定有处置能力的单位代为处置，所需费用由产生放射性固体废物的单位承担，可以并处二十万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"违反本法规定，有下列行为之一的，由省级以上人民政府环境保护行政主管部门责令停产停业或者吊销许可证；有违法所得的，没收违法所得；违法所得十万元以上的，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足十万元的，并处五万元以上十万元以下罚款；构成犯罪的，依法追究刑事责任："},{"i":58,"n":"第五十八条","txt":"向中华人民共和国境内输入放射性废物和被放射性污染的物品，或者经中华人民共和国境内转移放射性废物和被放射性污染的物品的，由海关责令退运该放射性废物和被放射性污染的物品，并处五十万元以上一百万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":59,"n":"第五十九条","txt":"因放射性污染造成他人损害的，应当依法承担民事责任。"},{"i":60,"n":"第六十条","txt":"军用设施、装备的放射性污染防治，由国务院和军队的有关主管部门依照本法规定的原则和国务院、中央军事委员会规定的职责实施监督管理。"},{"i":61,"n":"第六十一条","txt":"劳动者在职业活动中接触放射性物质造成的职业病的防治，依照《中华人民共和国职业病防治法》的规定执行。"},{"i":62,"n":"第六十二条","txt":"本法中下列用语的含义："},{"i":63,"n":"第六十三条","txt":"本法自2003年10月1日起施行。"}],"gutifeiwuwuranhuanjingfangzhifa-2":[{"i":1,"n":"第一条","txt":"为了保护和改善生态环境，防治固体废物污染环境，保障公众健康，维护生态安全，推进生态文明建设，促进经济社会可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"固体废物污染环境的防治适用本法。"},{"i":3,"n":"第三条","txt":"国家推行绿色发展方式，促进清洁生产和循环经济发展。"},{"i":4,"n":"第四条","txt":"固体废物污染环境防治坚持减量化、资源化和无害化的原则。"},{"i":5,"n":"第五条","txt":"固体废物污染环境防治坚持污染担责的原则。"},{"i":6,"n":"第六条","txt":"国家推行生活垃圾分类制度。"},{"i":7,"n":"第七条","txt":"地方各级人民政府对本行政区域固体废物污染环境防治负责。"},{"i":8,"n":"第八条","txt":"各级人民政府应当加强对固体废物污染环境防治工作的领导，组织、协调、督促有关部门依法履行固体废物污染环境防治监督管理职责。"},{"i":9,"n":"第九条","txt":"国务院生态环境主管部门对全国固体废物污染环境防治工作实施统一监督管理。国务院发展改革、工业和信息化、自然资源、住房城乡建设、交通运输、农业农村、商务、卫生健康、海关等主管部门在各自职责范围内负责固体废物污染环境防治的监督管理工作。"},{"i":10,"n":"第十条","txt":"国家鼓励、支持固体废物污染环境防治的科学研究、技术开发、先进技术推广和科学普及，加强固体废物污染环境防治科技支撑。"},{"i":11,"n":"第十一条","txt":"国家机关、社会团体、企业事业单位、基层群众性自治组织和新闻媒体应当加强固体废物污染环境防治宣传教育和科学普及，增强公众固体废物污染环境防治意识。"},{"i":12,"n":"第十二条","txt":"各级人民政府对在固体废物污染环境防治工作以及相关的综合利用活动中做出显著成绩的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":13,"n":"第十三条","txt":"县级以上人民政府应当将固体废物污染环境防治工作纳入国民经济和社会发展规划、生态环境保护规划，并采取有效措施减少固体废物的产生量、促进固体废物的综合利用、降低固体废物的危害性，最大限度降低固体废物填埋量。"},{"i":14,"n":"第十四条","txt":"国务院生态环境主管部门应当会同国务院有关部门根据国家环境质量标准和国家经济、技术条件，制定固体废物鉴别标准、鉴别程序和国家固体废物污染环境防治技术标准。"},{"i":15,"n":"第十五条","txt":"国务院标准化主管部门应当会同国务院发展改革、工业和信息化、生态环境、农业农村等主管部门，制定固体废物综合利用标准。"},{"i":16,"n":"第十六条","txt":"国务院生态环境主管部门应当会同国务院有关部门建立全国危险废物等固体废物污染环境防治信息平台，推进固体废物收集、转移、处置等全过程监控和信息化追溯。"},{"i":17,"n":"第十七条","txt":"建设产生、贮存、利用、处置固体废物的项目，应当依法进行环境影响评价，并遵守国家有关建设项目环境保护管理的规定。"},{"i":18,"n":"第十八条","txt":"建设项目的环境影响评价文件确定需要配套建设的固体废物污染环境防治设施，应当与主体工程同时设计、同时施工、同时投入使用。建设项目的初步设计，应当按照环境保护设计规范的要求，将固体废物污染环境防治内容纳入环境影响评价文件，落实防治固体废物污染环境和破坏生态的措施以及固体废物污染环境防治设施投资概算。"},{"i":19,"n":"第十九条","txt":"收集、贮存、运输、利用、处置固体废物的单位和其他生产经营者，应当加强对相关设施、设备和场所的管理和维护，保证其正常运行和使用。"},{"i":20,"n":"第二十条","txt":"产生、收集、贮存、运输、利用、处置固体废物的单位和其他生产经营者，应当采取防扬散、防流失、防渗漏或者其他防止污染环境的措施，不得擅自倾倒、堆放、丢弃、遗撒固体废物。"},{"i":21,"n":"第二十一条","txt":"在生态保护红线区域、永久基本农田集中区域和其他需要特别保护的区域内，禁止建设工业固体废物、危险废物集中贮存、利用、处置的设施、场所和生活垃圾填埋场。"},{"i":22,"n":"第二十二条","txt":"转移固体废物出省、自治区、直辖市行政区域贮存、处置的，应当向固体废物移出地的省、自治区、直辖市人民政府生态环境主管部门提出申请。移出地的省、自治区、直辖市人民政府生态环境主管部门应当及时商经接受地的省、自治区、直辖市人民政府生态环境主管部门同意后，在规定期限内批准转移该固体废物出省、自治区、直辖市行政区域。未经批准的，不得转移。"},{"i":23,"n":"第二十三条","txt":"禁止中华人民共和国境外的固体废物进境倾倒、堆放、处置。"},{"i":24,"n":"第二十四条","txt":"国家逐步实现固体废物零进口，由国务院生态环境主管部门会同国务院商务、发展改革、海关等主管部门组织实施。"},{"i":25,"n":"第二十五条","txt":"海关发现进口货物疑似固体废物的，可以委托专业机构开展属性鉴别，并根据鉴别结论依法管理。"},{"i":26,"n":"第二十六条","txt":"生态环境主管部门及其环境执法机构和其他负有固体废物污染环境防治监督管理职责的部门，在各自职责范围内有权对从事产生、收集、贮存、运输、利用、处置固体废物等活动的单位和其他生产经营者进行现场检查。被检查者应当如实反映情况，并提供必要的资料。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一，生态环境主管部门和其他负有固体废物污染环境防治监督管理职责的部门，可以对违法收集、贮存、运输、利用、处置的固体废物及设施、设备、场所、工具、物品予以查封、扣押："},{"i":28,"n":"第二十八条","txt":"生态环境主管部门应当会同有关部门建立产生、收集、贮存、运输、利用、处置固体废物的单位和其他生产经营者信用记录制度，将相关信用记录纳入全国信用信息共享平台。"},{"i":29,"n":"第二十九条","txt":"设区的市级人民政府生态环境主管部门应当会同住房城乡建设、农业农村、卫生健康等主管部门，定期向社会发布固体废物的种类、产生量、处置能力、利用处置状况等信息。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府应当将工业固体废物、生活垃圾、危险废物等固体废物污染环境防治情况纳入环境状况和环境保护目标完成情况年度报告，向本级人民代表大会或者人民代表大会常务委员会报告。"},{"i":31,"n":"第三十一条","txt":"任何单位和个人都有权对造成固体废物污染环境的单位和个人进行举报。"},{"i":32,"n":"第三十二条","txt":"国务院生态环境主管部门应当会同国务院发展改革、工业和信息化等主管部门对工业固体废物对公众健康、生态环境的危害和影响程度等作出界定，制定防治工业固体废物污染环境的技术政策，组织推广先进的防治工业固体废物污染环境的生产工艺和设备。"},{"i":33,"n":"第三十三条","txt":"国务院工业和信息化主管部门应当会同国务院有关部门组织研究开发、推广减少工业固体废物产生量和降低工业固体废物危害性的生产工艺和设备，公布限期淘汰产生严重污染环境的工业固体废物的落后生产工艺、设备的名录。"},{"i":34,"n":"第三十四条","txt":"国务院工业和信息化主管部门应当会同国务院发展改革、生态环境等主管部门，定期发布工业固体废物综合利用技术、工艺、设备和产品导向目录，组织开展工业固体废物资源综合利用评价，推动工业固体废物综合利用。"},{"i":35,"n":"第三十五条","txt":"县级以上地方人民政府应当制定工业固体废物污染环境防治工作规划，组织建设工业固体废物集中处置等设施，推动工业固体废物污染环境防治工作。"},{"i":36,"n":"第三十六条","txt":"产生工业固体废物的单位应当建立健全工业固体废物产生、收集、贮存、运输、利用、处置全过程的污染环境防治责任制度，建立工业固体废物管理台账，如实记录产生工业固体废物的种类、数量、流向、贮存、利用、处置等信息，实现工业固体废物可追溯、可查询，并采取防治工业固体废物污染环境的措施。"},{"i":37,"n":"第三十七条","txt":"产生工业固体废物的单位委托他人运输、利用、处置工业固体废物的，应当对受托方的主体资格和技术能力进行核实，依法签订书面合同，在合同中约定污染防治要求。"},{"i":38,"n":"第三十八条","txt":"产生工业固体废物的单位应当依法实施清洁生产审核，合理选择和利用原材料、能源和其他资源，采用先进的生产工艺和设备，减少工业固体废物的产生量，降低工业固体废物的危害性。"},{"i":39,"n":"第三十九条","txt":"产生工业固体废物的单位应当取得排污许可证。排污许可的具体办法和实施步骤由国务院规定。"},{"i":40,"n":"第四十条","txt":"产生工业固体废物的单位应当根据经济、技术条件对工业固体废物加以利用；对暂时不利用或者不能利用的，应当按照国务院生态环境等主管部门的规定建设贮存设施、场所，安全分类存放，或者采取无害化处置措施。贮存工业固体废物应当采取符合国家环境保护标准的防护措施。"},{"i":41,"n":"第四十一条","txt":"产生工业固体废物的单位终止的，应当在终止前对工业固体废物的贮存、处置的设施、场所采取污染防治措施，并对未处置的工业固体废物作出妥善处置，防止污染环境。"},{"i":42,"n":"第四十二条","txt":"矿山企业应当采取科学的开采方法和选矿工艺，减少尾矿、煤矸石、废石等矿业固体废物的产生量和贮存量。"},{"i":43,"n":"第四十三条","txt":"县级以上地方人民政府应当加快建立分类投放、分类收集、分类运输、分类处理的生活垃圾管理系统，实现生活垃圾分类制度有效覆盖。"},{"i":44,"n":"第四十四条","txt":"县级以上地方人民政府应当有计划地改进燃料结构，发展清洁能源，减少燃料废渣等固体废物的产生量。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府应当统筹安排建设城乡生活垃圾收集、运输、处理设施，确定设施厂址，提高生活垃圾的综合利用和无害化处置水平，促进生活垃圾收集、处理的产业化发展，逐步建立和完善生活垃圾污染环境防治的社会服务体系。"},{"i":46,"n":"第四十六条","txt":"地方各级人民政府应当加强农村生活垃圾污染环境的防治，保护和改善农村人居环境。"},{"i":47,"n":"第四十七条","txt":"设区的市级以上人民政府环境卫生主管部门应当制定生活垃圾清扫、收集、贮存、运输和处理设施、场所建设运行规范，发布生活垃圾分类指导目录，加强监督管理。"},{"i":48,"n":"第四十八条","txt":"县级以上地方人民政府环境卫生等主管部门应当组织对城乡生活垃圾进行清扫、收集、运输和处理，可以通过招标等方式选择具备条件的单位从事生活垃圾的清扫、收集、运输和处理。"},{"i":49,"n":"第四十九条","txt":"产生生活垃圾的单位、家庭和个人应当依法履行生活垃圾源头减量和分类投放义务，承担生活垃圾产生者责任。"},{"i":50,"n":"第五十条","txt":"清扫、收集、运输、处理城乡生活垃圾，应当遵守国家有关环境保护和环境卫生管理的规定，防止污染环境。"},{"i":51,"n":"第五十一条","txt":"从事公共交通运输的经营单位，应当及时清扫、收集运输过程中产生的生活垃圾。"},{"i":52,"n":"第五十二条","txt":"农贸市场、农产品批发市场等应当加强环境卫生管理，保持环境卫生清洁，对所产生的垃圾及时清扫、分类收集、妥善处理。"},{"i":53,"n":"第五十三条","txt":"从事城市新区开发、旧区改建和住宅小区开发建设、村镇建设的单位，以及机场、码头、车站、公园、商场、体育场馆等公共设施、场所的经营管理单位，应当按照国家有关环境卫生的规定，配套建设生活垃圾收集设施。"},{"i":54,"n":"第五十四条","txt":"从生活垃圾中回收的物质应当按照国家规定的用途、标准使用，不得用于生产可能危害人体健康的产品。"},{"i":55,"n":"第五十五条","txt":"建设生活垃圾处理设施、场所，应当符合国务院生态环境主管部门和国务院住房城乡建设主管部门规定的环境保护和环境卫生标准。"},{"i":56,"n":"第五十六条","txt":"生活垃圾处理单位应当按照国家有关规定，安装使用监测设备，实时监测污染物的排放情况，将污染排放数据实时公开。监测设备应当与所在地生态环境主管部门的监控设备联网。"},{"i":57,"n":"第五十七条","txt":"县级以上地方人民政府环境卫生主管部门负责组织开展厨余垃圾资源化、无害化处理工作。"},{"i":58,"n":"第五十八条","txt":"县级以上地方人民政府应当按照产生者付费原则，建立生活垃圾处理收费制度。"},{"i":59,"n":"第五十九条","txt":"省、自治区、直辖市和设区的市、自治州可以结合实际，制定本地方生活垃圾具体管理办法。"},{"i":60,"n":"第六十条","txt":"县级以上地方人民政府应当加强建筑垃圾污染环境的防治，建立建筑垃圾分类处理制度。"},{"i":61,"n":"第六十一条","txt":"国家鼓励采用先进技术、工艺、设备和管理措施，推进建筑垃圾源头减量，建立建筑垃圾回收利用体系。"},{"i":62,"n":"第六十二条","txt":"县级以上地方人民政府环境卫生主管部门负责建筑垃圾污染环境防治工作，建立建筑垃圾全过程管理制度，规范建筑垃圾产生、收集、贮存、运输、利用、处置行为，推进综合利用，加强建筑垃圾处置设施、场所建设，保障处置安全，防止污染环境。"},{"i":63,"n":"第六十三条","txt":"工程施工单位应当编制建筑垃圾处理方案，采取污染防治措施，并报县级以上地方人民政府环境卫生主管部门备案。"},{"i":64,"n":"第六十四条","txt":"县级以上人民政府农业农村主管部门负责指导农业固体废物回收利用体系建设，鼓励和引导有关单位和其他生产经营者依法收集、贮存、运输、利用、处置农业固体废物，加强监督管理，防止污染环境。"},{"i":65,"n":"第六十五条","txt":"产生秸秆、废弃农用薄膜、农药包装废弃物等农业固体废物的单位和其他生产经营者，应当采取回收利用和其他防止污染环境的措施。"},{"i":66,"n":"第六十六条","txt":"国家建立电器电子、铅蓄电池、车用动力电池等产品的生产者责任延伸制度。"},{"i":67,"n":"第六十七条","txt":"国家对废弃电器电子产品等实行多渠道回收和集中处理制度。"},{"i":68,"n":"第六十八条","txt":"产品和包装物的设计、制造，应当遵守国家有关清洁生产的规定。国务院标准化主管部门应当根据国家经济和技术条件、固体废物污染环境防治状况以及产品的技术要求，组织制定有关标准，防止过度包装造成环境污染。"},{"i":69,"n":"第六十九条","txt":"国家依法禁止、限制生产、销售和使用不可降解塑料袋等一次性塑料制品。"},{"i":70,"n":"第七十条","txt":"旅游、住宿等行业应当按照国家有关规定推行不主动提供一次性用品。"},{"i":71,"n":"第七十一条","txt":"城镇污水处理设施维护运营单位或者污泥处理单位应当安全处理污泥，保证处理后的污泥符合国家有关标准，对污泥的流向、用途、用量等进行跟踪、记录，并报告城镇排水主管部门、生态环境主管部门。"},{"i":72,"n":"第七十二条","txt":"禁止擅自倾倒、堆放、丢弃、遗撒城镇污水处理设施产生的污泥和处理后的污泥。"},{"i":73,"n":"第七十三条","txt":"各级各类实验室及其设立单位应当加强对实验室产生的固体废物的管理，依法收集、贮存、运输、利用、处置实验室固体废物。实验室固体废物属于危险废物的，应当按照危险废物管理。"},{"i":74,"n":"第七十四条","txt":"危险废物污染环境的防治，适用本章规定；本章未作规定的，适用本法其他有关规定。"},{"i":75,"n":"第七十五条","txt":"国务院生态环境主管部门应当会同国务院有关部门制定国家危险废物名录，规定统一的危险废物鉴别标准、鉴别方法、识别标志和鉴别单位管理要求。国家危险废物名录应当动态调整。"},{"i":76,"n":"第七十六条","txt":"省、自治区、直辖市人民政府应当组织有关部门编制危险废物集中处置设施、场所的建设规划，科学评估危险废物处置需求，合理布局危险废物集中处置设施、场所，确保本行政区域的危险废物得到妥善处置。"},{"i":77,"n":"第七十七条","txt":"对危险废物的容器和包装物以及收集、贮存、运输、利用、处置危险废物的设施、场所，应当按照规定设置危险废物识别标志。"},{"i":78,"n":"第七十八条","txt":"产生危险废物的单位，应当按照国家有关规定制定危险废物管理计划；建立危险废物管理台账，如实记录有关信息，并通过国家危险废物信息管理系统向所在地生态环境主管部门申报危险废物的种类、产生量、流向、贮存、处置等有关资料。"},{"i":79,"n":"第七十九条","txt":"产生危险废物的单位，应当按照国家有关规定和环境保护标准要求贮存、利用、处置危险废物，不得擅自倾倒、堆放。"},{"i":80,"n":"第八十条","txt":"从事收集、贮存、利用、处置危险废物经营活动的单位，应当按照国家有关规定申请取得许可证。许可证的具体管理办法由国务院制定。"},{"i":81,"n":"第八十一条","txt":"收集、贮存危险废物，应当按照危险废物特性分类进行。禁止混合收集、贮存、运输、处置性质不相容而未经安全性处置的危险废物。"},{"i":82,"n":"第八十二条","txt":"转移危险废物的，应当按照国家有关规定填写、运行危险废物电子或者纸质转移联单。"},{"i":83,"n":"第八十三条","txt":"运输危险废物，应当采取防止污染环境的措施，并遵守国家有关危险货物运输管理的规定。"},{"i":84,"n":"第八十四条","txt":"收集、贮存、运输、利用、处置危险废物的场所、设施、设备和容器、包装物及其他物品转作他用时，应当按照国家有关规定经过消除污染处理，方可使用。"},{"i":85,"n":"第八十五条","txt":"产生、收集、贮存、运输、利用、处置危险废物的单位，应当依法制定意外事故的防范措施和应急预案，并向所在地生态环境主管部门和其他负有固体废物污染环境防治监督管理职责的部门备案；生态环境主管部门和其他负有固体废物污染环境防治监督管理职责的部门应当进行检查。"},{"i":86,"n":"第八十六条","txt":"因发生事故或者其他突发性事件，造成危险废物严重污染环境的单位，应当立即采取有效措施消除或者减轻对环境的污染危害，及时通报可能受到污染危害的单位和居民，并向所在地生态环境主管部门和有关部门报告，接受调查处理。"},{"i":87,"n":"第八十七条","txt":"在发生或者有证据证明可能发生危险废物严重污染环境、威胁居民生命财产安全时，生态环境主管部门或者其他负有固体废物污染环境防治监督管理职责的部门应当立即向本级人民政府和上一级人民政府有关部门报告，由人民政府采取防止或者减轻危害的有效措施。有关人民政府可以根据需要责令停止导致或者可能导致环境污染事故的作业。"},{"i":88,"n":"第八十八条","txt":"重点危险废物集中处置设施、场所退役前，运营单位应当按照国家有关规定对设施、场所采取污染防治措施。退役的费用应当预提，列入投资概算或者生产成本，专门用于重点危险废物集中处置设施、场所的退役。具体提取和管理办法，由国务院财政部门、价格主管部门会同国务院生态环境主管部门规定。"},{"i":89,"n":"第八十九条","txt":"禁止经中华人民共和国过境转移危险废物。"},{"i":90,"n":"第九十条","txt":"医疗废物按照国家危险废物名录管理。县级以上地方人民政府应当加强医疗废物集中处置能力建设。"},{"i":91,"n":"第九十一条","txt":"重大传染病疫情等突发事件发生时，县级以上人民政府应当统筹协调医疗废物等危险废物收集、贮存、运输、处置等工作，保障所需的车辆、场地、处置设施和防护物资。卫生健康、生态环境、环境卫生、交通运输等主管部门应当协同配合，依法履行应急处置职责。"},{"i":92,"n":"第九十二条","txt":"国务院有关部门、县级以上地方人民政府及其有关部门在编制国土空间规划和相关专项规划时，应当统筹生活垃圾、建筑垃圾、危险废物等固体废物转运、集中处置等设施建设需求，保障转运、集中处置等设施用地。"},{"i":93,"n":"第九十三条","txt":"国家采取有利于固体废物污染环境防治的经济、技术政策和措施，鼓励、支持有关方面采取有利于固体废物污染环境防治的措施，加强对从事固体废物污染环境防治工作人员的培训和指导，促进固体废物污染环境防治产业专业化、规模化发展。"},{"i":94,"n":"第九十四条","txt":"国家鼓励和支持科研单位、固体废物产生单位、固体废物利用单位、固体废物处置单位等联合攻关，研究开发固体废物综合利用、集中处置等的新技术，推动固体废物污染环境防治技术进步。"},{"i":95,"n":"第九十五条","txt":"各级人民政府应当加强固体废物污染环境的防治，按照事权划分的原则安排必要的资金用于下列事项："},{"i":96,"n":"第九十六条","txt":"国家鼓励和支持社会力量参与固体废物污染环境防治工作，并按照国家有关规定给予政策扶持。"},{"i":97,"n":"第九十七条","txt":"国家发展绿色金融，鼓励金融机构加大对固体废物污染环境防治项目的信贷投放。"},{"i":98,"n":"第九十八条","txt":"从事固体废物综合利用等固体废物污染环境防治工作的，依照法律、行政法规的规定，享受税收优惠。"},{"i":99,"n":"第九十九条","txt":"收集、贮存、运输、利用、处置危险废物的单位，应当按照国家有关规定，投保环境污染责任保险。"},{"i":100,"n":"第一百条","txt":"国家鼓励单位和个人购买、使用综合利用产品和可重复使用产品。"},{"i":101,"n":"第一百零一条","txt":"生态环境主管部门或者其他负有固体废物污染环境防治监督管理职责的部门违反本法规定，有下列行为之一，由本级人民政府或者上级人民政府有关部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":102,"n":"第一百零二条","txt":"违反本法规定，有下列行为之一，由生态环境主管部门责令改正，处以罚款，没收违法所得；情节严重的，报经有批准权的人民政府批准，可以责令停业或者关闭："},{"i":103,"n":"第一百零三条","txt":"违反本法规定，以拖延、围堵、滞留执法人员等方式拒绝、阻挠监督检查，或者在接受监督检查时弄虚作假的，由生态环境主管部门或者其他负有固体废物污染环境防治监督管理职责的部门责令改正，处五万元以上二十万元以下的罚款；对直接负责的主管人员和其他直接责任人员，处二万元以上十万元以下的罚款。"},{"i":104,"n":"第一百零四条","txt":"违反本法规定，未依法取得排污许可证产生工业固体废物的，由生态环境主管部门责令改正或者限制生产、停产整治，处十万元以上一百万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业或者关闭。"},{"i":105,"n":"第一百零五条","txt":"违反本法规定，生产经营者未遵守限制商品过度包装的强制性标准的，由县级以上地方人民政府市场监督管理部门或者有关部门责令改正；拒不改正的，处二千元以上二万元以下的罚款；情节严重的，处二万元以上十万元以下的罚款。"},{"i":106,"n":"第一百零六条","txt":"违反本法规定，未遵守国家有关禁止、限制使用不可降解塑料袋等一次性塑料制品的规定，或者未按照国家有关规定报告塑料袋等一次性塑料制品的使用情况的，由县级以上地方人民政府商务、邮政等主管部门责令改正，处一万元以上十万元以下的罚款。"},{"i":107,"n":"第一百零七条","txt":"从事畜禽规模养殖未及时收集、贮存、利用或者处置养殖过程中产生的畜禽粪污等固体废物的，由生态环境主管部门责令改正，可以处十万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业或者关闭。"},{"i":108,"n":"第一百零八条","txt":"违反本法规定，城镇污水处理设施维护运营单位或者污泥处理单位对污泥流向、用途、用量等未进行跟踪、记录，或者处理后的污泥不符合国家有关标准的，由城镇排水主管部门责令改正，给予警告；造成严重后果的，处十万元以上二十万元以下的罚款；拒不改正的，城镇排水主管部门可以指定有治理能力的单位代为治理，所需费用由违法者承担。"},{"i":109,"n":"第一百零九条","txt":"违反本法规定，生产、销售、进口或者使用淘汰的设备，或者采用淘汰的生产工艺的，由县级以上地方人民政府指定的部门责令改正，处十万元以上一百万元以下的罚款，没收违法所得；情节严重的，由县级以上地方人民政府指定的部门提出意见，报经有批准权的人民政府批准，责令停业或者关闭。"},{"i":110,"n":"第一百一十条","txt":"尾矿、煤矸石、废石等矿业固体废物贮存设施停止使用后，未按照国家有关环境保护规定进行封场的，由生态环境主管部门责令改正，处二十万元以上一百万元以下的罚款。"},{"i":111,"n":"第一百一十一条","txt":"违反本法规定，有下列行为之一，由县级以上地方人民政府环境卫生主管部门责令改正，处以罚款，没收违法所得："},{"i":112,"n":"第一百一十二条","txt":"违反本法规定，有下列行为之一，由生态环境主管部门责令改正，处以罚款，没收违法所得；情节严重的，报经有批准权的人民政府批准，可以责令停业或者关闭："},{"i":113,"n":"第一百一十三条","txt":"违反本法规定，危险废物产生者未按照规定处置其产生的危险废物被责令改正后拒不改正的，由生态环境主管部门组织代为处置，处置费用由危险废物产生者承担；拒不承担代为处置费用的，处代为处置费用一倍以上三倍以下的罚款。"},{"i":114,"n":"第一百一十四条","txt":"无许可证从事收集、贮存、利用、处置危险废物经营活动的，由生态环境主管部门责令改正，处一百万元以上五百万元以下的罚款，并报经有批准权的人民政府批准，责令停业或者关闭；对法定代表人、主要负责人、直接负责的主管人员和其他责任人员，处十万元以上一百万元以下的罚款。"},{"i":115,"n":"第一百一十五条","txt":"违反本法规定，将中华人民共和国境外的固体废物输入境内的，由海关责令退运该固体废物，处五十万元以上五百万元以下的罚款。"},{"i":116,"n":"第一百一十六条","txt":"违反本法规定，经中华人民共和国过境转移危险废物的，由海关责令退运该危险废物，处五十万元以上五百万元以下的罚款。"},{"i":117,"n":"第一百一十七条","txt":"对已经非法入境的固体废物，由省级以上人民政府生态环境主管部门依法向海关提出处理意见，海关应当依照本法第一百一十五条的规定作出处罚决定；已经造成环境污染的，由省级以上人民政府生态环境主管部门责令进口者消除污染。"},{"i":118,"n":"第一百一十八条","txt":"违反本法规定，造成固体废物污染环境事故的，除依法承担赔偿责任外，由生态环境主管部门依照本条第二款的规定处以罚款，责令限期采取治理措施；造成重大或者特大固体废物污染环境事故的，还可以报经有批准权的人民政府批准，责令关闭。"},{"i":119,"n":"第一百一十九条","txt":"单位和其他生产经营者违反本法规定排放固体废物，受到罚款处罚，被责令改正的，依法作出处罚决定的行政机关应当组织复查，发现其继续实施该违法行为的，依照《中华人民共和国环境保护法》的规定按日连续处罚。"},{"i":120,"n":"第一百二十条","txt":"违反本法规定，有下列行为之一，尚不构成犯罪的，由公安机关对法定代表人、主要负责人、直接负责的主管人员和其他责任人员处十日以上十五日以下的拘留；情节较轻的，处五日以上十日以下的拘留："},{"i":121,"n":"第一百二十一条","txt":"固体废物污染环境、破坏生态，损害国家利益、社会公共利益的，有关机关和组织可以依照《中华人民共和国环境保护法》、《中华人民共和国民事诉讼法》、《中华人民共和国行政诉讼法》等法律的规定向人民法院提起诉讼。"},{"i":122,"n":"第一百二十二条","txt":"固体废物污染环境、破坏生态给国家造成重大损失的，由设区的市级以上地方人民政府或者其指定的部门、机构组织与造成环境污染和生态破坏的单位和其他生产经营者进行磋商，要求其承担损害赔偿责任；磋商未达成一致的，可以向人民法院提起诉讼。"},{"i":123,"n":"第一百二十三条","txt":"违反本法规定，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任；造成人身、财产损害的，依法承担民事责任。"},{"i":124,"n":"第一百二十四条","txt":"本法下列用语的含义："},{"i":125,"n":"第一百二十五条","txt":"液态废物的污染防治，适用本法；但是，排入水体的废水的污染防治适用有关法律，不适用本法。"},{"i":126,"n":"第一百二十六条","txt":"本法自2020年9月1日起施行。"}],"gutifeiwuwuranhuanjingfangzhifa":[{"i":1,"n":"第一条","txt":"为了防治固体废物污染环境，保障人体健康，维护生态安全，促进经济社会可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于中华人民共和国境内固体废物污染环境的防治。"},{"i":3,"n":"第三条","txt":"国家对固体废物污染环境的防治，实行减少固体废物的产生量和危害性、充分合理利用固体废物和无害化处置固体废物的原则，促进清洁生产和循环经济发展。"},{"i":4,"n":"第四条","txt":"县级以上人民政府应当将固体废物污染环境防治工作纳入国民经济和社会发展计划，并采取有利于固体废物污染环境防治的经济、技术政策和措施。"},{"i":5,"n":"第五条","txt":"国家对固体废物污染环境防治实行污染者依法负责的原则。"},{"i":6,"n":"第六条","txt":"国家鼓励、支持固体废物污染环境防治的科学研究、技术开发、推广先进的防治技术和普及固体废物污染环境防治的科学知识。"},{"i":7,"n":"第七条","txt":"国家鼓励单位和个人购买、使用再生产品和可重复利用产品。"},{"i":8,"n":"第八条","txt":"各级人民政府对在固体废物污染环境防治工作以及相关的综合利用活动中作出显著成绩的单位和个人给予奖励。"},{"i":9,"n":"第九条","txt":"任何单位和个人都有保护环境的义务，并有权对造成固体废物污染环境的单位和个人进行检举和控告。"},{"i":10,"n":"第十条","txt":"国务院环境保护行政主管部门对全国固体废物污染环境的防治工作实施统一监督管理。国务院有关部门在各自的职责范围内负责固体废物污染环境防治的监督管理工作。"},{"i":11,"n":"第十一条","txt":"国务院环境保护行政主管部门会同国务院有关行政主管部门根据国家环境质量标准和国家经济、技术条件，制定国家固体废物污染环境防治技术标准。"},{"i":12,"n":"第十二条","txt":"国务院环境保护行政主管部门建立固体废物污染环境监测制度，制定统一的监测规范，并会同有关部门组织监测网络。"},{"i":13,"n":"第十三条","txt":"建设产生固体废物的项目以及建设贮存、利用、处置固体废物的项目，必须依法进行环境影响评价，并遵守国家有关建设项目环境保护管理的规定。"},{"i":14,"n":"第十四条","txt":"建设项目的环境影响评价文件确定需要配套建设的固体废物污染环境防治设施，必须与主体工程同时设计、同时施工、同时投入使用。固体废物污染环境防治设施必须经原审批环境影响评价文件的环境保护行政主管部门验收合格后，该建设项目方可投入生产或者使用。对固体废物污染环境防治设施的验收应当与对主体工程的验收同时进行。"},{"i":15,"n":"第十五条","txt":"县级以上人民政府环境保护行政主管部门和其他固体废物污染环境防治工作的监督管理部门，有权依据各自的职责对管辖范围内与固体废物污染环境防治有关的单位进行现场检查。被检查的单位应当如实反映情况，提供必要的资料。检查机关应当为被检查的单位保守技术秘密和业务秘密。"},{"i":16,"n":"第十六条","txt":"产生固体废物的单位和个人，应当采取措施，防止或者减少固体废物对环境的污染。"},{"i":17,"n":"第十七条","txt":"收集、贮存、运输、利用、处置固体废物的单位和个人，必须采取防扬散、防流失、防渗漏或者其他防止污染环境的措施；不得擅自倾倒、堆放、丢弃、遗撒固体废物。"},{"i":18,"n":"第十八条","txt":"产品和包装物的设计、制造，应当遵守国家有关清洁生产的规定。国务院标准化行政主管部门应当根据国家经济和技术条件、固体废物污染环境防治状况以及产品的技术要求，组织制定有关标准，防止过度包装造成环境污染。"},{"i":19,"n":"第十九条","txt":"国家鼓励科研、生产单位研究、生产易回收利用、易处置或者在环境中可降解的薄膜覆盖物和商品包装物。"},{"i":20,"n":"第二十条","txt":"从事畜禽规模养殖应当按照国家有关规定收集、贮存、利用或者处置养殖过程中产生的畜禽粪便，防止污染环境。"},{"i":21,"n":"第二十一条","txt":"对收集、贮存、运输、处置固体废物的设施、设备和场所，应当加强管理和维护，保证其正常运行和使用。"},{"i":22,"n":"第二十二条","txt":"在国务院和国务院有关主管部门及省、自治区、直辖市人民政府划定的自然保护区、风景名胜区、饮用水水源保护区、基本农田保护区和其他需要特别保护的区域内，禁止建设工业固体废物集中贮存、处置的设施、场所和生活垃圾填埋场。"},{"i":23,"n":"第二十三条","txt":"转移固体废物出省、自治区、直辖市行政区域贮存、处置的，应当向固体废物移出地的省、自治区、直辖市人民政府环境保护行政主管部门提出申请。移出地的省、自治区、直辖市人民政府环境保护行政主管部门应当商经接受地的省、自治区、直辖市人民政府环境保护行政主管部门同意后，方可批准转移该固体废物出省、自治区、直辖市行政区域。未经批准的，不得转移。"},{"i":24,"n":"第二十四条","txt":"禁止中华人民共和国境外的固体废物进境倾倒、堆放、处置。"},{"i":25,"n":"第二十五条","txt":"禁止进口不能用作原料或者不能以无害化方式利用的固体废物；对可以用作原料的固体废物实行限制进口和非限制进口分类管理。"},{"i":26,"n":"第二十六条","txt":"进口者对海关将其所进口的货物纳入固体废物管理范围不服的，可以依法申请行政复议，也可以向人民法院提起行政诉讼。"},{"i":27,"n":"第二十七条","txt":"国务院环境保护行政主管部门应当会同国务院经济综合宏观调控部门和其他有关部门对工业固体废物对环境的污染作出界定，制定防治工业固体废物污染环境的技术政策，组织推广先进的防治工业固体废物污染环境的生产工艺和设备。"},{"i":28,"n":"第二十八条","txt":"国务院经济综合宏观调控部门应当会同国务院有关部门组织研究、开发和推广减少工业固体废物产生量和危害性的生产工艺和设备，公布限期淘汰产生严重污染环境的工业固体废物的落后生产工艺、落后设备的名录。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府有关部门应当制定工业固体废物污染环境防治工作规划，推广能够减少工业固体废物产生量和危害性的先进生产工艺和设备，推动工业固体废物污染环境防治工作。"},{"i":30,"n":"第三十条","txt":"产生工业固体废物的单位应当建立、健全污染环境防治责任制度，采取防治工业固体废物污染环境的措施。"},{"i":31,"n":"第三十一条","txt":"企业事业单位应当合理选择和利用原材料、能源和其他资源，采用先进的生产工艺和设备，减少工业固体废物产生量，降低工业固体废物的危害性。"},{"i":32,"n":"第三十二条","txt":"国家实行工业固体废物申报登记制度。"},{"i":33,"n":"第三十三条","txt":"企业事业单位应当根据经济、技术条件对其产生的工业固体废物加以利用；对暂时不利用或者不能利用的，必须按照国务院环境保护行政主管部门的规定建设贮存设施、场所，安全分类存放，或者采取无害化处置措施。"},{"i":34,"n":"第三十四条","txt":"禁止擅自关闭、闲置或者拆除工业固体废物污染环境防治设施、场所；确有必要关闭、闲置或者拆除的，必须经所在地县级以上地方人民政府环境保护行政主管部门核准，并采取措施，防止污染环境。"},{"i":35,"n":"第三十五条","txt":"产生工业固体废物的单位需要终止的，应当事先对工业固体废物的贮存、处置的设施、场所采取污染防治措施，并对未处置的工业固体废物作出妥善处置，防止污染环境。"},{"i":36,"n":"第三十六条","txt":"矿山企业应当采取科学的开采方法和选矿工艺，减少尾矿、矸石、废石等矿业固体废物的产生量和贮存量。"},{"i":37,"n":"第三十七条","txt":"拆解、利用、处置废弃电器产品和废弃机动车船，应当遵守有关法律、法规的规定，采取措施，防止污染环境。"},{"i":38,"n":"第三十八条","txt":"县级以上人民政府应当统筹安排建设城乡生活垃圾收集、运输、处置设施，提高生活垃圾的利用率和无害化处置率，促进生活垃圾收集、处置的产业化发展，逐步建立和完善生活垃圾污染环境防治的社会服务体系。"},{"i":39,"n":"第三十九条","txt":"县级以上地方人民政府环境卫生行政主管部门应当组织对城市生活垃圾进行清扫、收集、运输和处置，可以通过招标等方式选择具备条件的单位从事生活垃圾的清扫、收集、运输和处置。"},{"i":40,"n":"第四十条","txt":"对城市生活垃圾应当按照环境卫生行政主管部门的规定，在指定的地点放置，不得随意倾倒、抛撒或者堆放。"},{"i":41,"n":"第四十一条","txt":"清扫、收集、运输、处置城市生活垃圾，应当遵守国家有关环境保护和环境卫生管理的规定，防止污染环境。"},{"i":42,"n":"第四十二条","txt":"对城市生活垃圾应当及时清运，逐步做到分类收集和运输，并积极开展合理利用和实施无害化处置。"},{"i":43,"n":"第四十三条","txt":"城市人民政府应当有计划地改进燃料结构，发展城市煤气、天然气、液化气和其他清洁能源。"},{"i":44,"n":"第四十四条","txt":"建设生活垃圾处置的设施、场所，必须符合国务院环境保护行政主管部门和国务院建设行政主管部门规定的环境保护和环境卫生标准。"},{"i":45,"n":"第四十五条","txt":"从生活垃圾中回收的物质必须按照国家规定的用途或者标准使用，不得用于生产可能危害人体健康的产品。"},{"i":46,"n":"第四十六条","txt":"工程施工单位应当及时清运工程施工过程中产生的固体废物，并按照环境卫生行政主管部门的规定进行利用或者处置。"},{"i":47,"n":"第四十七条","txt":"从事公共交通运输的经营单位，应当按照国家有关规定，清扫、收集运输过程中产生的生活垃圾。"},{"i":48,"n":"第四十八条","txt":"从事城市新区开发、旧区改建和住宅小区开发建设的单位，以及机场、码头、车站、公园、商店等公共设施、场所的经营管理单位，应当按照国家有关环境卫生的规定，配套建设生活垃圾收集设施。"},{"i":49,"n":"第四十九条","txt":"农村生活垃圾污染环境防治的具体办法，由地方性法规规定。"},{"i":50,"n":"第五十条","txt":"危险废物污染环境的防治，适用本章规定；本章未作规定的，适用本法其他有关规定。"},{"i":51,"n":"第五十一条","txt":"国务院环境保护行政主管部门应当会同国务院有关部门制定国家危险废物名录，规定统一的危险废物鉴别标准、鉴别方法和识别标志。"},{"i":52,"n":"第五十二条","txt":"对危险废物的容器和包装物以及收集、贮存、运输、处置危险废物的设施、场所，必须设置危险废物识别标志。"},{"i":53,"n":"第五十三条","txt":"产生危险废物的单位，必须按照国家有关规定制定危险废物管理计划，并向所在地县级以上地方人民政府环境保护行政主管部门申报危险废物的种类、产生量、流向、贮存、处置等有关资料。"},{"i":54,"n":"第五十四条","txt":"国务院环境保护行政主管部门会同国务院经济综合宏观调控部门组织编制危险废物集中处置设施、场所的建设规划，报国务院批准后实施。"},{"i":55,"n":"第五十五条","txt":"产生危险废物的单位，必须按照国家有关规定处置危险废物，不得擅自倾倒、堆放；不处置的，由所在地县级以上地方人民政府环境保护行政主管部门责令限期改正；逾期不处置或者处置不符合国家有关规定的，由所在地县级以上地方人民政府环境保护行政主管部门指定单位按照国家有关规定代为处置，处置费用由产生危险废物的单位承担。"},{"i":56,"n":"第五十六条","txt":"以填埋方式处置危险废物不符合国务院环境保护行政主管部门规定的，应当缴纳危险废物排污费。危险废物排污费征收的具体办法由国务院规定。"},{"i":57,"n":"第五十七条","txt":"从事收集、贮存、处置危险废物经营活动的单位，必须向县级以上人民政府环境保护行政主管部门申请领取经营许可证；从事利用危险废物经营活动的单位，必须向国务院环境保护行政主管部门或者省、自治区、直辖市人民政府环境保护行政主管部门申请领取经营许可证。具体管理办法由国务院规定。"},{"i":58,"n":"第五十八条","txt":"收集、贮存危险废物，必须按照危险废物特性分类进行。禁止混合收集、贮存、运输、处置性质不相容而未经安全性处置的危险废物。"},{"i":59,"n":"第五十九条","txt":"转移危险废物的，必须按照国家有关规定填写危险废物转移联单。跨省、自治区、直辖市转移危险废物的，应当向危险废物移出地省、自治区、直辖市人民政府环境保护行政主管部门申请。移出地省、自治区、直辖市人民政府环境保护行政主管部门应当商经接受地省、自治区、直辖市人民政府环境保护行政主管部门同意后，方可批准转移该危险废物。未经批准的，不得转移。"},{"i":60,"n":"第六十条","txt":"运输危险废物，必须采取防止污染环境的措施，并遵守国家有关危险货物运输管理的规定。"},{"i":61,"n":"第六十一条","txt":"收集、贮存、运输、处置危险废物的场所、设施、设备和容器、包装物及其他物品转作他用时，必须经过消除污染的处理，方可使用。"},{"i":62,"n":"第六十二条","txt":"产生、收集、贮存、运输、利用、处置危险废物的单位，应当制定意外事故的防范措施和应急预案，并向所在地县级以上地方人民政府环境保护行政主管部门备案；环境保护行政主管部门应当进行检查。"},{"i":63,"n":"第六十三条","txt":"因发生事故或者其他突发性事件，造成危险废物严重污染环境的单位，必须立即采取措施消除或者减轻对环境的污染危害，及时通报可能受到污染危害的单位和居民，并向所在地县级以上地方人民政府环境保护行政主管部门和有关部门报告，接受调查处理。"},{"i":64,"n":"第六十四条","txt":"在发生或者有证据证明可能发生危险废物严重污染环境、威胁居民生命财产安全时，县级以上地方人民政府环境保护行政主管部门或者其他固体废物污染环境防治工作的监督管理部门必须立即向本级人民政府和上一级人民政府有关行政主管部门报告，由人民政府采取防止或者减轻危害的有效措施。有关人民政府可以根据需要责令停止导致或者可能导致环境污染事故的作业。"},{"i":65,"n":"第六十五条","txt":"重点危险废物集中处置设施、场所的退役费用应当预提，列入投资概算或者经营成本。具体提取和管理办法，由国务院财政部门、价格主管部门会同国务院环境保护行政主管部门规定。"},{"i":66,"n":"第六十六条","txt":"禁止经中华人民共和国过境转移危险废物。"},{"i":67,"n":"第六十七条","txt":"县级以上人民政府环境保护行政主管部门或者其他固体废物污染环境防治工作的监督管理部门违反本法规定，有下列行为之一的，由本级人民政府或者上级人民政府有关行政主管部门责令改正，对负有责任的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":68,"n":"第六十八条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府环境保护行政主管部门责令停止违法行为，限期改正，处以罚款："},{"i":69,"n":"第六十九条","txt":"违反本法规定，建设项目需要配套建设的固体废物污染环境防治设施未建成、未经验收或者验收不合格，主体工程即投入生产或者使用的，由审批该建设项目环境影响评价文件的环境保护行政主管部门责令停止生产或者使用，可以并处十万元以下的罚款。"},{"i":70,"n":"第七十条","txt":"违反本法规定，拒绝县级以上人民政府环境保护行政主管部门或者其他固体废物污染环境防治工作的监督管理部门现场检查的，由执行现场检查的部门责令限期改正；拒不改正或者在检查时弄虚作假的，处二千元以上二万元以下的罚款。"},{"i":71,"n":"第七十一条","txt":"从事畜禽规模养殖未按照国家有关规定收集、贮存、处置畜禽粪便，造成环境污染的，由县级以上地方人民政府环境保护行政主管部门责令限期改正，可以处五万元以下的罚款。"},{"i":72,"n":"第七十二条","txt":"违反本法规定，生产、销售、进口或者使用淘汰的设备，或者采用淘汰的生产工艺的，由县级以上人民政府经济综合宏观调控部门责令改正；情节严重的，由县级以上人民政府经济综合宏观调控部门提出意见，报请同级人民政府按照国务院规定的权限决定停业或者关闭。"},{"i":73,"n":"第七十三条","txt":"尾矿、矸石、废石等矿业固体废物贮存设施停止使用后，未按照国家有关环境保护规定进行封场的，由县级以上地方人民政府环境保护行政主管部门责令限期改正，可以处五万元以上二十万元以下的罚款。"},{"i":74,"n":"第七十四条","txt":"违反本法有关城市生活垃圾污染环境防治的规定，有下列行为之一的，由县级以上地方人民政府环境卫生行政主管部门责令停止违法行为，限期改正，处以罚款："},{"i":75,"n":"第七十五条","txt":"违反本法有关危险废物污染环境防治的规定，有下列行为之一的，由县级以上人民政府环境保护行政主管部门责令停止违法行为，限期改正，处以罚款："},{"i":76,"n":"第七十六条","txt":"违反本法规定，危险废物产生者不处置其产生的危险废物又不承担依法应当承担的处置费用的，由县级以上地方人民政府环境保护行政主管部门责令限期改正，处代为处置费用一倍以上三倍以下的罚款。"},{"i":77,"n":"第七十七条","txt":"无经营许可证或者不按照经营许可证规定从事收集、贮存、利用、处置危险废物经营活动的，由县级以上人民政府环境保护行政主管部门责令停止违法行为，没收违法所得，可以并处违法所得三倍以下的罚款。"},{"i":78,"n":"第七十八条","txt":"违反本法规定，将中华人民共和国境外的固体废物进境倾倒、堆放、处置的，进口属于禁止进口的固体废物或者未经许可擅自进口属于限制进口的固体废物用作原料的，由海关责令退运该固体废物，可以并处十万元以上一百万元以下的罚款；构成犯罪的，依法追究刑事责任。进口者不明的，由承运人承担退运该固体废物的责任，或者承担该固体废物的处置费用。"},{"i":79,"n":"第七十九条","txt":"违反本法规定，经中华人民共和国过境转移危险废物的，由海关责令退运该危险废物，可以并处五万元以上五十万元以下的罚款。"},{"i":80,"n":"第八十条","txt":"对已经非法入境的固体废物，由省级以上人民政府环境保护行政主管部门依法向海关提出处理意见，海关应当依照本法第七十八条的规定作出处罚决定；已经造成环境污染的，由省级以上人民政府环境保护行政主管部门责令进口者消除污染。"},{"i":81,"n":"第八十一条","txt":"违反本法规定，造成固体废物严重污染环境的，由县级以上人民政府环境保护行政主管部门按照国务院规定的权限决定限期治理；逾期未完成治理任务的，由本级人民政府决定停业或者关闭。"},{"i":82,"n":"第八十二条","txt":"违反本法规定，造成固体废物污染环境事故的，由县级以上人民政府环境保护行政主管部门处二万元以上二十万元以下的罚款；造成重大损失的，按照直接损失的百分之三十计算罚款，但是最高不超过一百万元，对负有责任的主管人员和其他直接责任人员，依法给予行政处分；造成固体废物污染环境重大事故的，并由县级以上人民政府按照国务院规定的权限决定停业或者关闭。"},{"i":83,"n":"第八十三条","txt":"违反本法规定，收集、贮存、利用、处置危险废物，造成重大环境污染事故，构成犯罪的，依法追究刑事责任。"},{"i":84,"n":"第八十四条","txt":"受到固体废物污染损害的单位和个人，有权要求依法赔偿损失。"},{"i":85,"n":"第八十五条","txt":"造成固体废物污染环境的，应当排除危害，依法赔偿损失，并采取措施恢复环境原状。"},{"i":86,"n":"第八十六条","txt":"因固体废物污染环境引起的损害赔偿诉讼，由加害人就法律规定的免责事由及其行为与损害结果之间不存在因果关系承担举证责任。"},{"i":87,"n":"第八十七条","txt":"固体废物污染环境的损害赔偿责任和赔偿金额的纠纷，当事人可以委托环境监测机构提供监测数据。环境监测机构应当接受委托，如实提供有关监测数据。"},{"i":88,"n":"第八十八条","txt":"本法下列用语的含义："},{"i":89,"n":"第八十九条","txt":"液态废物的污染防治，适用本法；但是，排入水体的废水的污染防治适用有关法律，不适用本法。"},{"i":90,"n":"第九十条","txt":"中华人民共和国缔结或者参加的与固体废物污染环境防治有关的国际条约与本法有不同规定的，适用国际条约的规定；但是，中华人民共和国声明保留的条款除外。"},{"i":91,"n":"第九十一条","txt":"本法自2005年4月1日起施行。"}],"haiyanghuanjingbaohufa-2":[{"i":1,"n":"第一条","txt":"为了保护和改善海洋环境，保护海洋资源，防治污染损害，保障生态安全和公众健康，维护国家海洋权益，建设海洋强国，推进生态文明建设，促进经济社会可持续发展，实现人与自然和谐共生，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于中华人民共和国管辖海域。"},{"i":3,"n":"第三条","txt":"海洋环境保护应当坚持保护优先、预防为主、源头防控、陆海统筹、综合治理、公众参与、损害担责的原则。"},{"i":4,"n":"第四条","txt":"国务院生态环境主管部门负责全国海洋环境的监督管理，负责全国防治陆源污染物、海岸工程和海洋工程建设项目（以下称工程建设项目）、海洋倾倒废弃物对海洋环境污染损害的环境保护工作，指导、协调和监督全国海洋生态保护修复工作。"},{"i":5,"n":"第五条","txt":"沿海县级以上地方人民政府对其管理海域的海洋环境质量负责。"},{"i":6,"n":"第六条","txt":"沿海县级以上地方人民政府可以建立海洋环境保护区域协作机制，组织协调其管理海域的环境保护工作。"},{"i":7,"n":"第七条","txt":"国务院和沿海县级以上地方人民政府应当将海洋环境保护工作纳入国民经济和社会发展规划，按照事权和支出责任划分原则，将海洋环境保护工作所需经费纳入本级政府预算。"},{"i":8,"n":"第八条","txt":"各级人民政府及其有关部门应当加强海洋环境保护的宣传教育和知识普及工作，增强公众海洋环境保护意识，引导公众依法参与海洋环境保护工作；鼓励基层群众性自治组织、社会组织、志愿者等开展海洋环境保护法律法规和知识的宣传活动；按照职责分工依法公开海洋环境相关信息。"},{"i":9,"n":"第九条","txt":"任何单位和个人都有保护海洋环境的义务，并有权对污染海洋环境、破坏海洋生态的单位和个人，以及海洋环境监督管理人员的违法行为进行监督和检举。"},{"i":10,"n":"第十条","txt":"国家鼓励、支持海洋环境保护科学技术研究、开发和应用，促进海洋环境保护信息化建设，加强海洋环境保护专业技术人才培养，提高海洋环境保护科学技术水平。"},{"i":11,"n":"第十一条","txt":"对在海洋环境保护工作中做出显著成绩的单位和个人，按照国家有关规定给予表彰和奖励。"},{"i":12,"n":"第十二条","txt":"国家实施陆海统筹、区域联动的海洋环境监督管理制度，加强规划、标准、监测等监督管理制度的衔接协调。"},{"i":13,"n":"第十三条","txt":"国家优先将生态功能极重要、生态极敏感脆弱的海域划入生态保护红线，实行严格保护。"},{"i":14,"n":"第十四条","txt":"国务院生态环境主管部门会同有关部门、机构和沿海省、自治区、直辖市人民政府制定全国海洋生态环境保护规划，报国务院批准后实施。全国海洋生态环境保护规划应当与全国国土空间规划相衔接。"},{"i":15,"n":"第十五条","txt":"沿海省、自治区、直辖市人民政府应当根据其管理海域的生态环境和资源利用状况，将其管理海域纳入生态环境分区管控方案和生态环境准入清单，报国务院生态环境主管部门备案后实施。生态环境分区管控方案和生态环境准入清单应当与国土空间规划相衔接。"},{"i":16,"n":"第十六条","txt":"国务院生态环境主管部门根据海洋环境质量状况和国家经济、技术条件，制定国家海洋环境质量标准。"},{"i":17,"n":"第十七条","txt":"制定海洋环境质量标准，应当征求有关部门、行业协会、企业事业单位、专家和公众等的意见，提高海洋环境质量标准的科学性。"},{"i":18,"n":"第十八条","txt":"国家和有关地方水污染物排放标准的制定，应当将海洋环境质量标准作为重要依据之一。"},{"i":19,"n":"第十九条","txt":"国家加强海洋环境质量管控，推进海域综合治理，严格海域排污许可管理，提升重点海域海洋环境质量。"},{"i":20,"n":"第二十条","txt":"国务院生态环境主管部门根据海洋环境状况和质量改善要求，会同国务院发展改革、自然资源、住房和城乡建设、交通运输、水行政、渔业等部门和海警机构，划定国家环境治理重点海域及其控制区域，制定综合治理行动方案，报国务院批准后实施。"},{"i":21,"n":"第二十一条","txt":"直接向海洋排放应税污染物的企业事业单位和其他生产经营者，应当依照法律规定缴纳环境保护税。"},{"i":22,"n":"第二十二条","txt":"国家加强防治海洋环境污染损害的科学技术的研究和开发，对严重污染海洋环境的落后生产工艺和落后设备，实行淘汰制度。"},{"i":23,"n":"第二十三条","txt":"国务院生态环境主管部门负责海洋生态环境监测工作，制定海洋生态环境监测规范和标准并监督实施，组织实施海洋生态环境质量监测，统一发布国家海洋生态环境状况公报，定期组织对海洋生态环境质量状况进行调查评价。"},{"i":24,"n":"第二十四条","txt":"国务院有关部门和海警机构应当向国务院生态环境主管部门提供编制国家海洋生态环境状况公报所必需的入海河口和海洋环境监测、调查、监视等方面的资料。"},{"i":25,"n":"第二十五条","txt":"国务院生态环境主管部门会同有关部门和机构通过智能化的综合信息系统，为海洋环境保护监督管理、信息共享提供服务。"},{"i":26,"n":"第二十六条","txt":"国家加强海洋辐射环境监测，国务院生态环境主管部门负责制定海洋辐射环境应急监测方案并组织实施。"},{"i":27,"n":"第二十七条","txt":"因发生事故或者其他突发性事件，造成或者可能造成海洋环境污染、生态破坏事件的单位和个人，应当立即采取有效措施解除或者减轻危害，及时向可能受到危害者通报，并向依照本法规定行使海洋环境监督管理权的部门和机构报告，接受调查处理。"},{"i":28,"n":"第二十八条","txt":"国家根据防止海洋环境污染的需要，制定国家重大海上污染事件应急预案，建立健全海上溢油污染等应急机制，保障应对工作的必要经费。"},{"i":29,"n":"第二十九条","txt":"依照本法规定行使海洋环境监督管理权的部门和机构，有权对从事影响海洋环境活动的单位和个人进行现场检查；在巡航监视中发现违反本法规定的行为时，应当予以制止并调查取证，必要时有权采取有效措施，防止事态扩大，并报告有关部门或者机构处理。"},{"i":30,"n":"第三十条","txt":"造成或者可能造成严重海洋环境污染、生态破坏的，或者有关证据可能灭失或者被隐匿的，依照本法规定行使海洋环境监督管理权的部门和机构可以查封、扣押有关船舶、设施、设备、物品。"},{"i":31,"n":"第三十一条","txt":"在中华人民共和国管辖海域以外，造成或者可能造成中华人民共和国管辖海域环境污染、生态破坏的，有关部门和机构有权采取必要的措施。"},{"i":32,"n":"第三十二条","txt":"国务院生态环境主管部门会同有关部门和机构建立向海洋排放污染物、从事废弃物海洋倾倒、从事海洋生态环境治理和服务的企业事业单位和其他生产经营者信用记录与评价应用制度，将相关信用记录纳入全国公共信用信息共享平台。"},{"i":33,"n":"第三十三条","txt":"国家加强海洋生态保护，提升海洋生态系统质量和多样性、稳定性、持续性。"},{"i":34,"n":"第三十四条","txt":"国务院和沿海省、自治区、直辖市人民政府及其有关部门根据保护海洋的需要，依法将重要的海洋生态系统、珍稀濒危海洋生物的天然集中分布区、海洋自然遗迹和自然景观集中分布区等区域纳入国家公园、自然保护区或者自然公园等自然保护地。"},{"i":35,"n":"第三十五条","txt":"国家建立健全海洋生态保护补偿制度。"},{"i":36,"n":"第三十六条","txt":"国家加强海洋生物多样性保护，健全海洋生物多样性调查、监测、评估和保护体系，维护和修复重要海洋生态廊道，防止对海洋生物多样性的破坏。"},{"i":37,"n":"第三十七条","txt":"国家鼓励科学开展水生生物增殖放流，支持科学规划，因地制宜采取投放人工鱼礁和种植海藻场、海草床、珊瑚等措施，恢复海洋生物多样性，修复改善海洋生态。"},{"i":38,"n":"第三十八条","txt":"开发海岛及周围海域的资源，应当采取严格的生态保护措施，不得造成海岛地形、岸滩、植被和海岛周围海域生态环境的损害。"},{"i":39,"n":"第三十九条","txt":"国家严格保护自然岸线，建立健全自然岸线控制制度。沿海省、自治区、直辖市人民政府负责划定严格保护岸线的范围并发布。"},{"i":40,"n":"第四十条","txt":"国务院水行政主管部门确定重要入海河流的生态流量管控指标，应当征求并研究国务院生态环境、自然资源等部门的意见。确定生态流量管控指标，应当进行科学论证，综合考虑水资源条件、气候状况、生态环境保护要求、生活生产用水状况等因素。"},{"i":41,"n":"第四十一条","txt":"沿海地方各级人民政府应当结合当地自然环境的特点，建设海岸防护设施、沿海防护林、沿海城镇园林和绿地，对海岸侵蚀和海水入侵地区进行综合治理。"},{"i":42,"n":"第四十二条","txt":"对遭到破坏的具有重要生态、经济、社会价值的海洋生态系统，应当进行修复。海洋生态修复应当以改善生境、恢复生物多样性和生态系统基本功能为重点，以自然恢复为主、人工修复为辅，并优先修复具有典型性、代表性的海洋生态系统。"},{"i":43,"n":"第四十三条","txt":"国务院自然资源主管部门负责开展全国海洋生态灾害预防、风险评估和隐患排查治理。"},{"i":44,"n":"第四十四条","txt":"国家鼓励发展生态渔业，推广多种生态渔业生产方式，改善海洋生态状况，保护海洋环境。"},{"i":45,"n":"第四十五条","txt":"从事海水养殖活动应当保护海域环境，科学确定养殖规模和养殖密度，合理投饵、投肥，正确使用药物，及时规范收集处理固体废物，防止造成海洋生态环境的损害。"},{"i":46,"n":"第四十六条","txt":"向海域排放陆源污染物，应当严格执行国家或者地方规定的标准和有关规定。"},{"i":47,"n":"第四十七条","txt":"入海排污口位置的选择，应当符合国土空间用途管制要求，根据海水动力条件和有关规定，经科学论证后，报设区的市级以上人民政府生态环境主管部门备案。排污口的责任主体应当加强排污口监测，按照规定开展监控和自动监测。"},{"i":48,"n":"第四十八条","txt":"禁止在自然保护地、重要渔业水域、海水浴场、生态保护红线区域及其他需要特别保护的区域，新设工业排污口和城镇污水处理厂排污口；法律、行政法规另有规定的除外。"},{"i":49,"n":"第四十九条","txt":"经开放式沟（渠）向海洋排放污染物的，对开放式沟（渠）按照国家和地方的有关规定、标准实施水环境质量管理。"},{"i":50,"n":"第五十条","txt":"国务院有关部门和县级以上地方人民政府及其有关部门应当依照水污染防治有关法律、行政法规的规定，加强入海河流管理，协同推进入海河流污染防治，使入海河口的水质符合入海河口环境质量相关要求。"},{"i":51,"n":"第五十一条","txt":"禁止向海域排放油类、酸液、碱液、剧毒废液。"},{"i":52,"n":"第五十二条","txt":"含病原体的医疗污水、生活污水和工业废水应当经过处理，符合国家和地方有关排放标准后，方可排入海域。"},{"i":53,"n":"第五十三条","txt":"含有机物和营养物质的工业废水、生活污水，应当严格控制向海湾、半封闭海及其他自净能力较差的海域排放。"},{"i":54,"n":"第五十四条","txt":"向海域排放含热废水，应当采取有效措施，保证邻近自然保护地、渔业水域的水温符合国家和地方海洋环境质量标准，避免热污染对珍稀濒危海洋生物、海洋水产资源造成危害。"},{"i":55,"n":"第五十五条","txt":"沿海地方各级人民政府应当加强农业面源污染防治。沿海农田、林场施用化学农药，应当执行国家农药安全使用的规定和标准。沿海农田、林场应当合理使用化肥和植物生长调节剂。"},{"i":56,"n":"第五十六条","txt":"在沿海陆域弃置、堆放和处理尾矿、矿渣、煤灰渣、垃圾和其他固体废物的，依照《中华人民共和国固体废物污染环境防治法》的有关规定执行，并采取有效措施防止固体废物进入海洋。"},{"i":57,"n":"第五十七条","txt":"沿海县级以上地方人民政府负责其管理海域的海洋垃圾污染防治，建立海洋垃圾监测、清理制度，统筹规划建设陆域接收、转运、处理海洋垃圾的设施，明确有关部门、乡镇、街道、企业事业单位等的海洋垃圾管控区域，建立海洋垃圾监测、拦截、收集、打捞、运输、处理体系并组织实施，采取有效措施鼓励、支持公众参与上述活动。国务院生态环境、住房和城乡建设、发展改革等部门应当按照职责分工加强海洋垃圾污染防治的监督指导和保障。"},{"i":58,"n":"第五十八条","txt":"禁止经中华人民共和国内水、领海过境转移危险废物。"},{"i":59,"n":"第五十九条","txt":"沿海县级以上地方人民政府应当建设和完善排水管网，根据改善海洋环境质量的需要建设城镇污水处理厂和其他污水处理设施，加强城乡污水处理。"},{"i":60,"n":"第六十条","txt":"国家采取必要措施，防止、减少和控制来自大气层或者通过大气层造成的海洋环境污染损害。"},{"i":61,"n":"第六十一条","txt":"新建、改建、扩建工程建设项目，应当遵守国家有关建设项目环境保护管理的规定，并把污染防治和生态保护所需资金纳入建设项目投资计划。"},{"i":62,"n":"第六十二条","txt":"工程建设项目应当按照国家有关建设项目环境影响评价的规定进行环境影响评价。未依法进行并通过环境影响评价的建设项目，不得开工建设。"},{"i":63,"n":"第六十三条","txt":"禁止在沿海陆域新建不符合国家产业政策的化学制浆造纸、化工、印染、制革、电镀、酿造、炼油、岸边冲滩拆船及其他严重污染海洋环境的生产项目。"},{"i":64,"n":"第六十四条","txt":"新建、改建、扩建工程建设项目，应当采取有效措施，保护国家和地方重点保护的野生动植物及其生存环境，保护海洋水产资源，避免或者减轻对海洋生物的影响。"},{"i":65,"n":"第六十五条","txt":"工程建设项目不得使用含超标准放射性物质或者易溶出有毒有害物质的材料；不得造成领海基点及其周围环境的侵蚀、淤积和损害，不得危及领海基点的稳定。"},{"i":66,"n":"第六十六条","txt":"工程建设项目需要爆破作业时，应当采取有效措施，保护海洋环境。"},{"i":67,"n":"第六十七条","txt":"工程建设项目不得违法向海洋排放污染物、废弃物及其他有害物质。"},{"i":68,"n":"第六十八条","txt":"海洋油气钻井平台（船）、生产生活平台、生产储卸装置等海洋油气装备及其有关海上设施，不得向海域处置含油的工业固体废物。处置其他固体废物，不得造成海洋环境污染。"},{"i":69,"n":"第六十九条","txt":"海上试油时，应当确保油气充分燃烧，油和油性混合物不得排放入海。"},{"i":70,"n":"第七十条","txt":"勘探开发海洋油气资源，应当按照有关规定编制油气污染应急预案，报国务院生态环境主管部门海域派出机构备案。"},{"i":71,"n":"第七十一条","txt":"任何个人和未经批准的单位，不得向中华人民共和国管辖海域倾倒任何废弃物。"},{"i":72,"n":"第七十二条","txt":"国务院生态环境主管部门根据废弃物的毒性、有毒物质含量和对海洋环境影响程度，制定海洋倾倒废弃物评价程序和标准。"},{"i":73,"n":"第七十三条","txt":"国务院生态环境主管部门会同国务院自然资源主管部门编制全国海洋倾倒区规划，并征求国务院交通运输、渔业等部门和海警机构的意见，报国务院批准。"},{"i":74,"n":"第七十四条","txt":"国务院生态环境主管部门组织开展海洋倾倒区使用状况评估，根据评估结果予以调整、暂停使用或者封闭海洋倾倒区。"},{"i":75,"n":"第七十五条","txt":"获准和实施倾倒废弃物的单位，应当按照许可证注明的期限及条件，到指定的区域进行倾倒。倾倒作业船舶等载运工具应当安装使用符合要求的海洋倾倒在线监控设备，并与国务院生态环境主管部门监管系统联网。"},{"i":76,"n":"第七十六条","txt":"获准和实施倾倒废弃物的单位，应当按照规定向颁发许可证的国务院生态环境主管部门海域派出机构报告倾倒情况。倾倒废弃物的船舶应当向驶出港的海事管理机构、海警机构作出报告。"},{"i":77,"n":"第七十七条","txt":"禁止在海上焚烧废弃物。"},{"i":78,"n":"第七十八条","txt":"获准倾倒废弃物的单位委托实施废弃物海洋倾倒作业的，应当对受托单位的主体资格、技术能力和信用状况进行核实，依法签订书面合同，在合同中约定污染防治与生态保护要求，并监督实施。"},{"i":79,"n":"第七十九条","txt":"在中华人民共和国管辖海域，任何船舶及相关作业不得违法向海洋排放船舶垃圾、生活污水、含油污水、含有毒有害物质污水、废气等污染物，废弃物，压载水和沉积物及其他有害物质。"},{"i":80,"n":"第八十条","txt":"船舶应当配备相应的防污设备和器材。"},{"i":81,"n":"第八十一条","txt":"船舶应当遵守海上交通安全法律、法规的规定，防止因碰撞、触礁、搁浅、火灾或者爆炸等引起的海难事故，造成海洋环境的污染。"},{"i":82,"n":"第八十二条","txt":"国家完善并实施船舶油污损害民事赔偿责任制度；按照船舶油污损害赔偿责任由船东和货主共同承担风险的原则，完善并实施船舶油污保险、油污损害赔偿基金制度，具体办法由国务院规定。"},{"i":83,"n":"第八十三条","txt":"载运具有污染危害性货物进出港口的船舶，其承运人、货物所有人或者代理人，应当事先向海事管理机构申报。经批准后，方可进出港口或者装卸作业。"},{"i":84,"n":"第八十四条","txt":"交付船舶载运污染危害性货物的，托运人应当将货物的正式名称、污染危害性以及应当采取的防护措施如实告知承运人。污染危害性货物的单证、包装、标志、数量限制等，应当符合对所交付货物的有关规定。"},{"i":85,"n":"第八十五条","txt":"港口、码头、装卸站和船舶修造拆解单位所在地县级以上地方人民政府应当统筹规划建设船舶污染物等的接收、转运、处理处置设施，建立相应的接收、转运、处理处置多部门联合监管制度。"},{"i":86,"n":"第八十六条","txt":"国家海事管理机构组织制定中国籍船舶禁止或者限制安装和使用的有害材料名录。"},{"i":87,"n":"第八十七条","txt":"从事船舶拆解的单位，应当采取有效的污染防治措施，在船舶拆解前将船舶污染物减至最小量，对拆解产生的船舶污染物、废弃物和其他有害物质进行安全与环境无害化处置。拆解的船舶部件不得进入水体。"},{"i":88,"n":"第八十八条","txt":"国家倡导绿色低碳智能航运，鼓励船舶使用新能源或者清洁能源，淘汰高耗能高排放老旧船舶，减少温室气体和大气污染物的排放。沿海县级以上地方人民政府应当制定港口岸电、船舶受电等设施建设和改造计划，并组织实施。港口岸电设施的供电能力应当与靠港船舶的用电需求相适应。"},{"i":89,"n":"第八十九条","txt":"船舶及有关作业活动应当遵守有关法律法规和标准，采取有效措施，防止造成海洋环境污染。海事管理机构等应当加强对船舶及有关作业活动的监督管理。"},{"i":90,"n":"第九十条","txt":"船舶发生海难事故，造成或者可能造成海洋环境重大污染损害的，国家海事管理机构有权强制采取避免或者减少污染损害的措施。"},{"i":91,"n":"第九十一条","txt":"所有船舶均有监视海上污染的义务，在发现海上污染事件或者违反本法规定的行为时，应当立即向就近的依照本法规定行使海洋环境监督管理权的部门或者机构报告。"},{"i":92,"n":"第九十二条","txt":"国务院交通运输主管部门可以划定船舶污染物排放控制区。进入控制区的船舶应当符合船舶污染物排放相关控制要求。"},{"i":93,"n":"第九十三条","txt":"违反本法规定，有下列行为之一，由依照本法规定行使海洋环境监督管理权的部门或者机构责令改正或者责令采取限制生产、停产整治等措施，并处以罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":94,"n":"第九十四条","txt":"违反本法规定，有下列行为之一，由依照本法规定行使海洋环境监督管理权的部门或者机构责令改正，处以罚款："},{"i":95,"n":"第九十五条","txt":"违反本法规定，拒绝、阻挠调查和现场检查，或者在被检查时弄虚作假的，由依照本法规定行使海洋环境监督管理权的部门或者机构责令改正，处五万元以上二十万元以下的罚款；对直接负责的主管人员和其他直接责任人员处二万元以上十万元以下的罚款。"},{"i":96,"n":"第九十六条","txt":"违反本法规定，造成珊瑚礁等海洋生态系统或者自然保护地破坏的，由依照本法规定行使海洋环境监督管理权的部门或者机构责令改正、采取补救措施，处每平方米一千元以上一万元以下的罚款。"},{"i":97,"n":"第九十七条","txt":"违反本法规定，有下列行为之一，由依照本法规定行使海洋环境监督管理权的部门或者机构责令改正，处以罚款："},{"i":98,"n":"第九十八条","txt":"违反本法规定，从事海水养殖活动有下列行为之一，由依照本法规定行使海洋环境监督管理权的部门或者机构责令改正，处二万元以上二十万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":99,"n":"第九十九条","txt":"违反本法规定设置入海排污口的，由生态环境主管部门责令关闭或者拆除，处二万元以上十万元以下的罚款；拒不关闭或者拆除的，强制关闭、拆除，所需费用由违法者承担，处十万元以上五十万元以下的罚款；情节严重的，可以责令停产整治。"},{"i":100,"n":"第一百条","txt":"违反本法规定，经中华人民共和国管辖海域，转移危险废物的，由国家海事管理机构责令非法运输该危险废物的船舶退出中华人民共和国管辖海域，处五十万元以上五百万元以下的罚款。"},{"i":101,"n":"第一百零一条","txt":"违反本法规定，建设单位未落实建设项目投资计划有关要求的，由生态环境主管部门责令改正，处五万元以上二十万元以下的罚款；拒不改正的，处二十万元以上一百万元以下的罚款。"},{"i":102,"n":"第一百零二条","txt":"违反本法规定，在依法划定的自然保护地、重要渔业水域及其他需要特别保护的区域建设污染环境、破坏生态的工程建设项目或者从事其他活动，或者在沿海陆域新建不符合国家产业政策的生产项目的，由县级以上人民政府按照管理权限责令关闭。"},{"i":103,"n":"第一百零三条","txt":"违反本法规定，环境保护设施未与主体工程同时设计、同时施工、同时投产使用的，或者环境保护设施未建成、未达到规定要求、未经验收或者经验收不合格即投入生产、使用的，由生态环境主管部门或者海警机构责令改正，处二十万元以上一百万元以下的罚款；拒不改正的，处一百万元以上二百万元以下的罚款；对直接负责的主管人员和其他责任人员处五万元以上二十万元以下的罚款；造成重大环境污染、生态破坏的，责令其停止生产、使用，或者报经有批准权的人民政府批准，责令关闭。"},{"i":104,"n":"第一百零四条","txt":"违反本法规定，工程建设项目有下列行为之一，由依照本法规定行使海洋环境监督管理权的部门或者机构责令其停止违法行为、消除危害，处二十万元以上一百万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":105,"n":"第一百零五条","txt":"违反本法规定进行海洋油气勘探开发活动，造成海洋环境污染的，由海警机构责令改正，给予警告，并处二十万元以上一百万元以下的罚款。"},{"i":106,"n":"第一百零六条","txt":"违反本法规定，有下列行为之一，由国务院生态环境主管部门及其海域派出机构、海事管理机构或者海警机构责令改正，处以罚款，必要时可以扣押船舶；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":107,"n":"第一百零七条","txt":"违反本法规定，有下列行为之一，由国务院生态环境主管部门及其海域派出机构、海事管理机构或者海警机构责令改正，处以罚款，暂扣或者吊销倾倒许可证，必要时可以扣押船舶；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":108,"n":"第一百零八条","txt":"违反本法规定，将中华人民共和国境外废弃物运进中华人民共和国管辖海域倾倒的，由海警机构责令改正，根据造成或者可能造成的危害后果，处五十万元以上五百万元以下的罚款。"},{"i":109,"n":"第一百零九条","txt":"违反本法规定，有下列行为之一，由依照本法规定行使海洋环境监督管理权的部门或者机构责令改正，处以罚款："},{"i":110,"n":"第一百一十条","txt":"违反本法规定，有下列行为之一，由依照本法规定行使海洋环境监督管理权的部门或者机构责令改正，处以罚款："},{"i":111,"n":"第一百一十一条","txt":"违反本法规定，有下列行为之一，由依照本法规定行使海洋环境监督管理权的部门或者机构责令改正，处以罚款："},{"i":112,"n":"第一百一十二条","txt":"违反本法规定，有下列行为之一，由依照本法规定行使海洋环境监督管理权的部门或者机构责令改正，处一万元以上五万元以下的罚款："},{"i":113,"n":"第一百一十三条","txt":"企业事业单位和其他生产经营者违反本法规定向海域排放、倾倒、处置污染物、废弃物或者其他物质，受到罚款处罚，被责令改正的，依法作出处罚决定的部门或者机构应当组织复查，发现其继续实施该违法行为或者拒绝、阻挠复查的，依照《中华人民共和国环境保护法》的规定按日连续处罚。"},{"i":114,"n":"第一百一十四条","txt":"对污染海洋环境、破坏海洋生态，造成他人损害的，依照《中华人民共和国民法典》等法律的规定承担民事责任。"},{"i":115,"n":"第一百一十五条","txt":"对违反本法规定，造成海洋环境污染、生态破坏事故的单位，除依法承担赔偿责任外，由依照本法规定行使海洋环境监督管理权的部门或者机构处以罚款；对直接负责的主管人员和其他直接责任人员可以处上一年度从本单位取得收入百分之五十以下的罚款；直接负责的主管人员和其他直接责任人员属于公职人员的，依法给予处分。"},{"i":116,"n":"第一百一十六条","txt":"完全属于下列情形之一，经过及时采取合理措施，仍然不能避免对海洋环境造成污染损害的，造成污染损害的有关责任者免予承担责任："},{"i":117,"n":"第一百一十七条","txt":"未依照本法规定缴纳倾倒费的，由国务院生态环境主管部门及其海域派出机构责令限期缴纳；逾期拒不缴纳的，处应缴纳倾倒费数额一倍以上三倍以下的罚款，并可以报经有批准权的人民政府批准，责令停业、关闭。"},{"i":118,"n":"第一百一十八条","txt":"海洋环境监督管理人员滥用职权、玩忽职守、徇私舞弊，造成海洋环境污染损害、生态破坏的，依法给予处分。"},{"i":119,"n":"第一百一十九条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":120,"n":"第一百二十条","txt":"本法中下列用语的含义是："},{"i":121,"n":"第一百二十一条","txt":"涉及海洋环境监督管理的有关部门的具体职权划分，本法未作规定的，由国务院规定。"},{"i":122,"n":"第一百二十二条","txt":"军事船舶和军事用海环境保护管理办法，由国务院、中央军事委员会依照本法制定。"},{"i":123,"n":"第一百二十三条","txt":"中华人民共和国缔结或者参加的与海洋环境保护有关的国际条约与本法有不同规定的，适用国际条约的规定；但是，中华人民共和国声明保留的条款除外。"},{"i":124,"n":"第一百二十四条","txt":"本法自2024年1月1日起施行。"}],"haiyanghuanjingbaohufa":[{"i":1,"n":"第一条","txt":"为了保护和改善海洋环境，保护海洋资源，防治污染损害，维护生态平衡，保障人体健康，促进经济和社会的可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于中华人民共和国内水、领海、毗连区、专属经济区、大陆架以及中华人民共和国管辖的其他海域。"},{"i":3,"n":"第三条","txt":"国家在重点海洋生态功能区、生态环境敏感区和脆弱区等海域划定生态保护红线，实行严格保护。"},{"i":4,"n":"第四条","txt":"一切单位和个人都有保护海洋环境的义务，并有权对污染损害海洋环境的单位和个人，以及海洋环境监督管理人员的违法失职行为进行监督和检举。"},{"i":5,"n":"第五条","txt":"国务院环境保护行政主管部门作为对全国环境保护工作统一监督管理的部门，对全国海洋环境保护工作实施指导、协调和监督，并负责全国防治陆源污染物和海岸工程建设项目对海洋污染损害的环境保护工作。"},{"i":6,"n":"第六条","txt":"环境保护行政主管部门、海洋行政主管部门和其他行使海洋环境监督管理权的部门，根据职责分工依法公开海洋环境相关信息；相关排污单位应当依法公开排污信息。"},{"i":7,"n":"第七条","txt":"国家海洋行政主管部门会同国务院有关部门和沿海省、自治区、直辖市人民政府根据全国海洋主体功能区规划，拟定全国海洋功能区划，报国务院批准。"},{"i":8,"n":"第八条","txt":"国家根据海洋功能区划制定全国海洋环境保护规划和重点海域区域性海洋环境保护规划。"},{"i":9,"n":"第九条","txt":"跨区域的海洋环境保护工作，由有关沿海地方人民政府协商解决，或者由上级人民政府协调解决。"},{"i":10,"n":"第十条","txt":"国家根据海洋环境质量状况和国家经济、技术条件，制定国家海洋环境质量标准。"},{"i":11,"n":"第十一条","txt":"国家和地方水污染物排放标准的制定，应当将国家和地方海洋环境质量标准作为重要依据之一。在国家建立并实施排污总量控制制度的重点海域，水污染物排放标准的制定，还应当将主要污染物排海总量控制指标作为重要依据。"},{"i":12,"n":"第十二条","txt":"直接向海洋排放污染物的单位和个人，必须按照国家规定缴纳排污费。依照法律规定缴纳环境保护税的，不再缴纳排污费。"},{"i":13,"n":"第十三条","txt":"国家加强防治海洋环境污染损害的科学技术的研究和开发，对严重污染海洋环境的落后生产工艺和落后设备，实行淘汰制度。"},{"i":14,"n":"第十四条","txt":"国家海洋行政主管部门按照国家环境监测、监视规范和标准，管理全国海洋环境的调查、监测、监视，制定具体的实施办法，会同有关部门组织全国海洋环境监测、监视网络，定期评价海洋环境质量，发布海洋巡航监视通报。"},{"i":15,"n":"第十五条","txt":"国务院有关部门应当向国务院环境保护行政主管部门提供编制全国环境质量公报所必需的海洋环境监测资料。"},{"i":16,"n":"第十六条","txt":"国家海洋行政主管部门按照国家制定的环境监测、监视信息管理制度，负责管理海洋综合信息系统，为海洋环境保护监督管理提供服务。"},{"i":17,"n":"第十七条","txt":"因发生事故或者其他突发性事件，造成或者可能造成海洋环境污染事故的单位和个人，必须立即采取有效措施，及时向可能受到危害者通报，并向依照本法规定行使海洋环境监督管理权的部门报告，接受调查处理。"},{"i":18,"n":"第十八条","txt":"国家根据防止海洋环境污染的需要，制定国家重大海上污染事故应急计划。"},{"i":19,"n":"第十九条","txt":"依照本法规定行使海洋环境监督管理权的部门可以在海上实行联合执法，在巡航监视中发现海上污染事故或者违反本法规定的行为时，应当予以制止并调查取证，必要时有权采取有效措施，防止污染事态的扩大，并报告有关主管部门处理。"},{"i":20,"n":"第二十条","txt":"国务院和沿海地方各级人民政府应当采取有效措施，保护红树林、珊瑚礁、滨海湿地、海岛、海湾、入海河口、重要渔业水域等具有典型性、代表性的海洋生态系统，珍稀、濒危海洋生物的天然集中分布区，具有重要经济价值的海洋生物生存区域及有重大科学文化价值的海洋自然历史遗迹和自然景观。"},{"i":21,"n":"第二十一条","txt":"国务院有关部门和沿海省级人民政府应当根据保护海洋生态的需要，选划、建立海洋自然保护区。"},{"i":22,"n":"第二十二条","txt":"凡具有下列条件之一的，应当建立海洋自然保护区："},{"i":23,"n":"第二十三条","txt":"凡具有特殊地理条件、生态系统、生物与非生物资源及海洋开发利用特殊需要的区域，可以建立海洋特别保护区，采取有效的保护措施和科学的开发方式进行特殊管理。"},{"i":24,"n":"第二十四条","txt":"国家建立健全海洋生态保护补偿制度。"},{"i":25,"n":"第二十五条","txt":"引进海洋动植物物种，应当进行科学论证，避免对海洋生态系统造成危害。"},{"i":26,"n":"第二十六条","txt":"开发海岛及周围海域的资源，应当采取严格的生态保护措施，不得造成海岛地形、岸滩、植被以及海岛周围海域生态环境的破坏。"},{"i":27,"n":"第二十七条","txt":"沿海地方各级人民政府应当结合当地自然环境的特点，建设海岸防护设施、沿海防护林、沿海城镇园林和绿地，对海岸侵蚀和海水入侵地区进行综合治理。"},{"i":28,"n":"第二十八条","txt":"国家鼓励发展生态渔业建设，推广多种生态渔业生产方式，改善海洋生态状况。"},{"i":29,"n":"第二十九条","txt":"向海域排放陆源污染物，必须严格执行国家或者地方规定的标准和有关规定。"},{"i":30,"n":"第三十条","txt":"入海排污口位置的选择，应当根据海洋功能区划、海水动力条件和有关规定，经科学论证后，报设区的市级以上人民政府环境保护行政主管部门备案。"},{"i":31,"n":"第三十一条","txt":"省、自治区、直辖市人民政府环境保护行政主管部门和水行政主管部门应当按照水污染防治有关法律的规定，加强入海河流管理，防治污染，使入海河口的水质处于良好状态。"},{"i":32,"n":"第三十二条","txt":"排放陆源污染物的单位，必须向环境保护行政主管部门申报拥有的陆源污染物排放设施、处理设施和在正常作业条件下排放陆源污染物的种类、数量和浓度，并提供防治海洋环境污染方面的有关技术和资料。"},{"i":33,"n":"第三十三条","txt":"禁止向海域排放油类、酸液、碱液、剧毒废液和高、中水平放射性废水。"},{"i":34,"n":"第三十四条","txt":"含病原体的医疗污水、生活污水和工业废水必须经过处理，符合国家有关排放标准后，方能排入海域。"},{"i":35,"n":"第三十五条","txt":"含有机物和营养物质的工业废水、生活污水，应当严格控制向海湾、半封闭海及其他自净能力较差的海域排放。"},{"i":36,"n":"第三十六条","txt":"向海域排放含热废水，必须采取有效措施，保证邻近渔业水域的水温符合国家海洋环境质量标准，避免热污染对水产资源的危害。"},{"i":37,"n":"第三十七条","txt":"沿海农田、林场施用化学农药，必须执行国家农药安全使用的规定和标准。"},{"i":38,"n":"第三十八条","txt":"在岸滩弃置、堆放和处理尾矿、矿渣、煤灰渣、垃圾和其他固体废物的，依照《中华人民共和国固体废物污染环境防治法》的有关规定执行。"},{"i":39,"n":"第三十九条","txt":"禁止经中华人民共和国内水、领海转移危险废物。"},{"i":40,"n":"第四十条","txt":"沿海城市人民政府应当建设和完善城市排水管网，有计划地建设城市污水处理厂或者其他污水集中处理设施，加强城市污水的综合整治。"},{"i":41,"n":"第四十一条","txt":"国家采取必要措施，防止、减少和控制来自大气层或者通过大气层造成的海洋环境污染损害。"},{"i":42,"n":"第四十二条","txt":"新建、改建、扩建海岸工程建设项目，必须遵守国家有关建设项目环境保护管理的规定，并把防治污染所需资金纳入建设项目投资计划。"},{"i":43,"n":"第四十三条","txt":"海岸工程建设项目单位，必须对海洋环境进行科学调查，根据自然条件和社会条件，合理选址，编制环境影响报告书（表）。在建设项目开工前，将环境影响报告书（表）报环境保护行政主管部门审查批准。"},{"i":44,"n":"第四十四条","txt":"海岸工程建设项目的环境保护设施，必须与主体工程同时设计、同时施工、同时投产使用。环境保护设施应当符合经批准的环境影响评价报告书（表）的要求。"},{"i":45,"n":"第四十五条","txt":"禁止在沿海陆域内新建不具备有效治理措施的化学制浆造纸、化工、印染、制革、电镀、酿造、炼油、岸边冲滩拆船以及其他严重污染海洋环境的工业生产项目。"},{"i":46,"n":"第四十六条","txt":"兴建海岸工程建设项目，必须采取有效措施，保护国家和地方重点保护的野生动植物及其生存环境和海洋水产资源。"},{"i":47,"n":"第四十七条","txt":"海洋工程建设项目必须符合全国海洋主体功能区规划、海洋功能区划、海洋环境保护规划和国家有关环境保护标准。海洋工程建设项目单位应当对海洋环境进行科学调查，编制海洋环境影响报告书（表），并在建设项目开工前，报海洋行政主管部门审查批准。"},{"i":48,"n":"第四十八条","txt":"海洋工程建设项目的环境保护设施，必须与主体工程同时设计、同时施工、同时投产使用。环境保护设施未经海洋行政主管部门验收，或者经验收不合格的，建设项目不得投入生产或者使用。"},{"i":49,"n":"第四十九条","txt":"海洋工程建设项目，不得使用含超标准放射性物质或者易溶出有毒有害物质的材料。"},{"i":50,"n":"第五十条","txt":"海洋工程建设项目需要爆破作业时，必须采取有效措施，保护海洋资源。"},{"i":51,"n":"第五十一条","txt":"海洋石油钻井船、钻井平台和采油平台的含油污水和油性混合物，必须经过处理达标后排放；残油、废油必须予以回收，不得排放入海。经回收处理后排放的，其含油量不得超过国家规定的标准。"},{"i":52,"n":"第五十二条","txt":"海洋石油钻井船、钻井平台和采油平台及其有关海上设施，不得向海域处置含油的工业垃圾。处置其他工业垃圾，不得造成海洋环境污染。"},{"i":53,"n":"第五十三条","txt":"海上试油时，应当确保油气充分燃烧，油和油性混合物不得排放入海。"},{"i":54,"n":"第五十四条","txt":"勘探开发海洋石油，必须按有关规定编制溢油应急计划，报国家海洋行政主管部门的海区派出机构备案。"},{"i":55,"n":"第五十五条","txt":"任何单位未经国家海洋行政主管部门批准，不得向中华人民共和国管辖海域倾倒任何废弃物。"},{"i":56,"n":"第五十六条","txt":"国家海洋行政主管部门根据废弃物的毒性、有毒物质含量和对海洋环境影响程度，制定海洋倾倒废弃物评价程序和标准。"},{"i":57,"n":"第五十七条","txt":"国家海洋行政主管部门按照科学、合理、经济、安全的原则选划海洋倾倒区，经国务院环境保护行政主管部门提出审核意见后，报国务院批准。"},{"i":58,"n":"第五十八条","txt":"国家海洋行政主管部门监督管理倾倒区的使用，组织倾倒区的环境监测。对经确认不宜继续使用的倾倒区，国家海洋行政主管部门应当予以封闭，终止在该倾倒区的一切倾倒活动，并报国务院备案。"},{"i":59,"n":"第五十九条","txt":"获准倾倒废弃物的单位，必须按照许可证注明的期限及条件，到指定的区域进行倾倒。废弃物装载之后，批准部门应当予以核实。"},{"i":60,"n":"第六十条","txt":"获准倾倒废弃物的单位，应当详细记录倾倒的情况，并在倾倒后向批准部门作出书面报告。倾倒废弃物的船舶必须向驶出港的海事行政主管部门作出书面报告。"},{"i":61,"n":"第六十一条","txt":"禁止在海上焚烧废弃物。"},{"i":62,"n":"第六十二条","txt":"在中华人民共和国管辖海域，任何船舶及相关作业不得违反本法规定向海洋排放污染物、废弃物和压载水、船舶垃圾及其他有害物质。"},{"i":63,"n":"第六十三条","txt":"船舶必须按照有关规定持有防止海洋环境污染的证书与文书，在进行涉及污染物排放及操作时，应当如实记录。"},{"i":64,"n":"第六十四条","txt":"船舶必须配置相应的防污设备和器材。"},{"i":65,"n":"第六十五条","txt":"船舶应当遵守海上交通安全法律、法规的规定，防止因碰撞、触礁、搁浅、火灾或者爆炸等引起的海难事故，造成海洋环境的污染。"},{"i":66,"n":"第六十六条","txt":"国家完善并实施船舶油污损害民事赔偿责任制度；按照船舶油污损害赔偿责任由船东和货主共同承担风险的原则，建立船舶油污保险、油污损害赔偿基金制度。"},{"i":67,"n":"第六十七条","txt":"载运具有污染危害性货物进出港口的船舶，其承运人、货物所有人或者代理人，必须事先向海事行政主管部门申报。经批准后，方可进出港口、过境停留或者装卸作业。"},{"i":68,"n":"第六十八条","txt":"交付船舶装运污染危害性货物的单证、包装、标志、数量限制等，必须符合对所装货物的有关规定。"},{"i":69,"n":"第六十九条","txt":"港口、码头、装卸站和船舶修造厂必须按照有关规定备有足够的用于处理船舶污染物、废弃物的接收设施，并使该设施处于良好状态。"},{"i":70,"n":"第七十条","txt":"船舶及有关作业活动应当遵守有关法律法规和标准，采取有效措施，防止造成海洋环境污染。海事行政主管部门等有关部门应当加强对船舶及有关作业活动的监督管理。"},{"i":71,"n":"第七十一条","txt":"船舶发生海难事故，造成或者可能造成海洋环境重大污染损害的，国家海事行政主管部门有权强制采取避免或者减少污染损害的措施。"},{"i":72,"n":"第七十二条","txt":"所有船舶均有监视海上污染的义务，在发现海上污染事故或者违反本法规定的行为时，必须立即向就近的依照本法规定行使海洋环境监督管理权的部门报告。"},{"i":73,"n":"第七十三条","txt":"违反本法有关规定，有下列行为之一的，由依照本法规定行使海洋环境监督管理权的部门责令停止违法行为、限期改正或者责令采取限制生产、停产整治等措施，并处以罚款；拒不改正的，依法作出处罚决定的部门可以自责令改正之日的次日起，按照原罚款数额按日连续处罚；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":74,"n":"第七十四条","txt":"违反本法有关规定，有下列行为之一的，由依照本法规定行使海洋环境监督管理权的部门予以警告，或者处以罚款："},{"i":75,"n":"第七十五条","txt":"违反本法第十九条第二款的规定，拒绝现场检查，或者在被检查时弄虚作假的，由依照本法规定行使海洋环境监督管理权的部门予以警告，并处二万元以下的罚款。"},{"i":76,"n":"第七十六条","txt":"违反本法规定，造成珊瑚礁、红树林等海洋生态系统及海洋水产资源、海洋保护区破坏的，由依照本法规定行使海洋环境监督管理权的部门责令限期改正和采取补救措施，并处一万元以上十万元以下的罚款；有违法所得的，没收其违法所得。"},{"i":77,"n":"第七十七条","txt":"违反本法第三十条第一款、第三款规定设置入海排污口的，由县级以上地方人民政府环境保护行政主管部门责令其关闭，并处二万元以上十万元以下的罚款。"},{"i":78,"n":"第七十八条","txt":"违反本法第三十九条第二款的规定，经中华人民共和国管辖海域，转移危险废物的，由国家海事行政主管部门责令非法运输该危险废物的船舶退出中华人民共和国管辖海域，并处五万元以上五十万元以下的罚款。"},{"i":79,"n":"第七十九条","txt":"海岸工程建设项目未依法进行环境影响评价的，依照《中华人民共和国环境影响评价法》的规定处理。"},{"i":80,"n":"第八十条","txt":"违反本法第四十四条的规定，海岸工程建设项目未建成环境保护设施，或者环境保护设施未达到规定要求即投入生产、使用的，由环境保护行政主管部门责令其停止生产或者使用，并处二万元以上十万元以下的罚款。"},{"i":81,"n":"第八十一条","txt":"违反本法第四十五条的规定，新建严重污染海洋环境的工业生产建设项目的，按照管理权限，由县级以上人民政府责令关闭。"},{"i":82,"n":"第八十二条","txt":"违反本法第四十七条第一款的规定，进行海洋工程建设项目的，由海洋行政主管部门责令其停止施工，根据违法情节和危害后果，处建设项目总投资额百分之一以上百分之五以下的罚款，并可以责令恢复原状。"},{"i":83,"n":"第八十三条","txt":"违反本法第四十九条的规定，使用含超标准放射性物质或者易溶出有毒有害物质材料的，由海洋行政主管部门处五万元以下的罚款，并责令其停止该建设项目的运行，直到消除污染危害。"},{"i":84,"n":"第八十四条","txt":"违反本法规定进行海洋石油勘探开发活动，造成海洋环境污染的，由国家海洋行政主管部门予以警告，并处二万元以上二十万元以下的罚款。"},{"i":85,"n":"第八十五条","txt":"违反本法规定，不按照许可证的规定倾倒，或者向已经封闭的倾倒区倾倒废弃物的，由海洋行政主管部门予以警告，并处三万元以上二十万元以下的罚款；对情节严重的，可以暂扣或者吊销许可证。"},{"i":86,"n":"第八十六条","txt":"违反本法第五十五条第三款的规定，将中华人民共和国境外废弃物运进中华人民共和国管辖海域倾倒的，由国家海洋行政主管部门予以警告，并根据造成或者可能造成的危害后果，处十万元以上一百万元以下的罚款。"},{"i":87,"n":"第八十七条","txt":"违反本法规定，有下列行为之一的，由依照本法规定行使海洋环境监督管理权的部门予以警告，或者处以罚款："},{"i":88,"n":"第八十八条","txt":"违反本法规定，船舶、石油平台和装卸油类的港口、码头、装卸站不编制溢油应急计划的，由依照本法规定行使海洋环境监督管理权的部门予以警告，或者责令限期改正。"},{"i":89,"n":"第八十九条","txt":"造成海洋环境污染损害的责任者，应当排除危害，并赔偿损失；完全由于第三者的故意或者过失，造成海洋环境污染损害的，由第三者排除危害，并承担赔偿责任。"},{"i":90,"n":"第九十条","txt":"对违反本法规定，造成海洋环境污染事故的单位，除依法承担赔偿责任外，由依照本法规定行使海洋环境监督管理权的部门依照本条第二款的规定处以罚款；对直接负责的主管人员和其他直接责任人员可以处上一年度从本单位取得收入百分之五十以下的罚款；直接负责的主管人员和其他直接责任人员属于国家工作人员的，依法给予处分。"},{"i":91,"n":"第九十一条","txt":"完全属于下列情形之一，经过及时采取合理措施，仍然不能避免对海洋环境造成污染损害的，造成污染损害的有关责任者免予承担责任："},{"i":92,"n":"第九十二条","txt":"对违反本法第十二条有关缴纳排污费、倾倒费规定的行政处罚，由国务院规定。"},{"i":93,"n":"第九十三条","txt":"海洋环境监督管理人员滥用职权、玩忽职守、徇私舞弊，造成海洋环境污染损害的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":94,"n":"第九十四条","txt":"本法中下列用语的含义是："},{"i":95,"n":"第九十五条","txt":"涉及海洋环境监督管理的有关部门的具体职权划分，本法未作规定的，由国务院规定。"},{"i":96,"n":"第九十六条","txt":"中华人民共和国缔结或者参加的与海洋环境保护有关的国际条约与本法有不同规定的，适用国际条约的规定；但是，中华人民共和国声明保留的条款除外。"},{"i":97,"n":"第九十七条","txt":"本法自2000年4月1日起施行。"}],"hetongfa":[{"i":1,"n":"第一条","txt":"为了保护合同当事人的合法权益，维护社会经济秩序，促进社会主义现代化建设，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称合同是平等主体的自然人、法人、其他组织之间设立、变更、终止民事权利义务关系的协议。"},{"i":3,"n":"第三条","txt":"合同当事人的法律地位平等，一方不得将自己的意志强加给另一方。"},{"i":4,"n":"第四条","txt":"当事人依法享有自愿订立合同的权利，任何单位和个人不得非法干预。"},{"i":5,"n":"第五条","txt":"当事人应当遵循公平原则确定各方的权利和义务。"},{"i":6,"n":"第六条","txt":"当事人行使权利、履行义务应当遵循诚实信用原则。"},{"i":7,"n":"第七条","txt":"当事人订立、履行合同，应当遵守法律、行政法规，尊重社会公德，不得扰乱社会经济秩序，损害社会公共利益。"},{"i":8,"n":"第八条","txt":"依法成立的合同，对当事人具有法律约束力。当事人应当按照约定履行自己的义务，不得擅自变更或者解除合同。"},{"i":9,"n":"第九条","txt":"当事人订立合同，应当具有相应的民事权利能力和民事行为能力。"},{"i":10,"n":"第十条","txt":"当事人订立合同，有书面形式、口头形式和其他形式。"},{"i":11,"n":"第十一条","txt":"书面形式是指合同书、信件和数据电文（包括电报、电传、传真、电子数据交换和电子邮件）等可以有形地表现所载内容的形式。"},{"i":12,"n":"第十二条","txt":"合同的内容由当事人约定，一般包括以下条款："},{"i":13,"n":"第十三条","txt":"当事人订立合同，采取要约、承诺方式。"},{"i":14,"n":"第十四条","txt":"要约是希望和他人订立合同的意思表示，该意思表示应当符合下列规定："},{"i":15,"n":"第十五条","txt":"要约邀请是希望他人向自己发出要约的意思表示。寄送的价目表、拍卖公告、招标公告、招股说明书、商业广告等为要约邀请。"},{"i":16,"n":"第十六条","txt":"要约到达受要约人时生效。"},{"i":17,"n":"第十七条","txt":"要约可以撤回。撤回要约的通知应当在要约到达受要约人之前或者与要约同时到达受要约人。"},{"i":18,"n":"第十八条","txt":"要约可以撤销。撤销要约的通知应当在受要约人发出承诺通知之前到达受要约人。"},{"i":19,"n":"第十九条","txt":"有下列情形之一的，要约不得撤销："},{"i":20,"n":"第二十条","txt":"有下列情形之一的，要约失效："},{"i":21,"n":"第二十一条","txt":"承诺是受要约人同意要约的意思表示。"},{"i":22,"n":"第二十二条","txt":"承诺应当以通知的方式作出，但根据交易习惯或者要约表明可以通过行为作出承诺的除外。"},{"i":23,"n":"第二十三条","txt":"承诺应当在要约确定的期限内到达要约人。"},{"i":24,"n":"第二十四条","txt":"要约以信件或者电报作出的，承诺期限自信件载明的日期或者电报交发之日开始计算。信件未载明日期的，自投寄该信件的邮戳日期开始计算。要约以电话、传真等快速通讯方式作出的，承诺期限自要约到达受要约人时开始计算。"},{"i":25,"n":"第二十五条","txt":"承诺生效时合同成立。"},{"i":26,"n":"第二十六条","txt":"承诺通知到达要约人时生效。承诺不需要通知的，根据交易习惯或者要约的要求作出承诺的行为时生效。"},{"i":27,"n":"第二十七条","txt":"承诺可以撤回。撤回承诺的通知应当在承诺通知到达要约人之前或者与承诺通知同时到达要约人。"},{"i":28,"n":"第二十八条","txt":"受要约人超过承诺期限发出承诺的，除要约人及时通知受要约人该承诺有效的以外，为新要约。"},{"i":29,"n":"第二十九条","txt":"受要约人在承诺期限内发出承诺，按照通常情形能够及时到达要约人，但因其他原因承诺到达要约人时超过承诺期限的，除要约人及时通知受要约人因承诺超过期限不接受该承诺的以外，该承诺有效。"},{"i":30,"n":"第三十条","txt":"承诺的内容应当与要约的内容一致。受要约人对要约的内容作出实质性变更的，为新要约。有关合同标的、数量、质量、价款或者报酬、履行期限、履行地点和方式、违约责任和解决争议方法等的变更，是对要约内容的实质性变更。"},{"i":31,"n":"第三十一条","txt":"承诺对要约的内容作出非实质性变更的，除要约人及时表示反对或者要约表明承诺不得对要约的内容作出任何变更的以外，该承诺有效，合同的内容以承诺的内容为准。"},{"i":32,"n":"第三十二条","txt":"当事人采用合同书形式订立合同的，自双方当事人签字或者盖章时合同成立。"},{"i":33,"n":"第三十三条","txt":"当事人采用信件、数据电文等形式订立合同的，可以在合同成立之前要求签订确认书。签订确认书时合同成立。"},{"i":34,"n":"第三十四条","txt":"承诺生效的地点为合同成立的地点。"},{"i":35,"n":"第三十五条","txt":"当事人采用合同书形式订立合同的，双方当事人签字或者盖章的地点为合同成立的地点。"},{"i":36,"n":"第三十六条","txt":"法律、行政法规规定或者当事人约定采用书面形式订立合同，当事人未采用书面形式但一方已经履行主要义务，对方接受的，该合同成立。"},{"i":37,"n":"第三十七条","txt":"采用合同书形式订立合同，在签字或者盖章之前，当事人一方已经履行主要义务，对方接受的，该合同成立。"},{"i":38,"n":"第三十八条","txt":"国家根据需要下达指令性任务或者国家订货任务的，有关法人、其他组织之间应当依照有关法律、行政法规规定的权利和义务订立合同。"},{"i":39,"n":"第三十九条","txt":"采用格式条款订立合同的，提供格式条款的一方应当遵循公平原则确定当事人之间的权利和义务，并采取合理的方式提请对方注意免除或者限制其责任的条款，按照对方的要求，对该条款予以说明。"},{"i":40,"n":"第四十条","txt":"格式条款具有本法第五十二条和第五十三条规定情形的，或者提供格式条款一方免除其责任、加重对方责任、排除对方主要权利的，该条款无效。"},{"i":41,"n":"第四十一条","txt":"对格式条款的理解发生争议的，应当按照通常理解予以解释。对格式条款有两种以上解释的，应当作出不利于提供格式条款一方的解释。格式条款和非格式条款不一致的，应当采用非格式条款。"},{"i":42,"n":"第四十二条","txt":"当事人在订立合同过程中有下列情形之一，给对方造成损失的，应当承担损害赔偿责任："},{"i":43,"n":"第四十三条","txt":"当事人在订立合同过程中知悉的商业秘密，无论合同是否成立，不得泄露或者不正当地使用。泄露或者不正当地使用该商业秘密给对方造成损失的，应当承担损害赔偿责任。"},{"i":44,"n":"第四十四条","txt":"依法成立的合同，自成立时生效。"},{"i":45,"n":"第四十五条","txt":"当事人对合同的效力可以约定附条件。附生效条件的合同，自条件成就时生效。附解除条件的合同，自条件成就时失效。"},{"i":46,"n":"第四十六条","txt":"当事人对合同的效力可以约定附期限。附生效期限的合同，自期限届至时生效。附终止期限的合同，自期限届满时失效。"},{"i":47,"n":"第四十七条","txt":"限制民事行为能力人订立的合同，经法定代理人追认后，该合同有效，但纯获利益的合同或者与其年龄、智力、精神健康状况相适应而订立的合同，不必经法定代理人追认。"},{"i":48,"n":"第四十八条","txt":"行为人没有代理权、超越代理权或者代理权终止后以被代理人名义订立的合同，未经被代理人追认，对被代理人不发生效力，由行为人承担责任。"},{"i":49,"n":"第四十九条","txt":"行为人没有代理权、超越代理权或者代理权终止后以被代理人名义订立合同，相对人有理由相信行为人有代理权的，该代理行为有效。"},{"i":50,"n":"第五十条","txt":"法人或者其他组织的法定代表人、负责人超越权限订立的合同，除相对人知道或者应当知道其超越权限的以外，该代表行为有效。"},{"i":51,"n":"第五十一条","txt":"无处分权的人处分他人财产，经权利人追认或者无处分权的人订立合同后取得处分权的，该合同有效。"},{"i":52,"n":"第五十二条","txt":"有下列情形之一的，合同无效："},{"i":53,"n":"第五十三条","txt":"合同中的下列免责条款无效："},{"i":54,"n":"第五十四条","txt":"下列合同，当事人一方有权请求人民法院或者仲裁机构变更或者撤销："},{"i":55,"n":"第五十五条","txt":"有下列情形之一的，撤销权消灭："},{"i":56,"n":"第五十六条","txt":"无效的合同或者被撤销的合同自始没有法律约束力。合同部分无效，不影响其他部分效力的，其他部分仍然有效。"},{"i":57,"n":"第五十七条","txt":"合同无效、被撤销或者终止的，不影响合同中独立存在的有关解决争议方法的条款的效力。"},{"i":58,"n":"第五十八条","txt":"合同无效或者被撤销后，因该合同取得的财产，应当予以返还；不能返还或者没有必要返还的，应当折价补偿。有过错的一方应当赔偿对方因此所受到的损失，双方都有过错的，应当各自承担相应的责任。"},{"i":59,"n":"第五十九条","txt":"当事人恶意串通，损害国家、集体或者第三人利益的，因此取得的财产收归国家所有或者返还集体、第三人。"},{"i":60,"n":"第六十条","txt":"当事人应当按照约定全面履行自己的义务。"},{"i":61,"n":"第六十一条","txt":"合同生效后，当事人就质量、价款或者报酬、履行地点等内容没有约定或者约定不明确的，可以协议补充；不能达成补充协议的，按照合同有关条款或者交易习惯确定。"},{"i":62,"n":"第六十二条","txt":"当事人就有关合同内容约定不明确，依照本法第六十一条的规定仍不能确定的，适用下列规定："},{"i":63,"n":"第六十三条","txt":"执行政府定价或者政府指导价的，在合同约定的交付期限内政府价格调整时，按照交付时的价格计价。逾期交付标的物的，遇价格上涨时，按照原价格执行；价格下降时，按照新价格执行。逾期提取标的物或者逾期付款的，遇价格上涨时，按照新价格执行；价格下降时，按照原价格执行。"},{"i":64,"n":"第六十四条","txt":"当事人约定由债务人向第三人履行债务的，债务人未向第三人履行债务或者履行债务不符合约定，应当向债权人承担违约责任。"},{"i":65,"n":"第六十五条","txt":"当事人约定由第三人向债权人履行债务的，第三人不履行债务或者履行债务不符合约定，债务人应当向债权人承担违约责任。"},{"i":66,"n":"第六十六条","txt":"当事人互负债务，没有先后履行顺序的，应当同时履行。一方在对方履行之前有权拒绝其履行要求。一方在对方履行债务不符合约定时，有权拒绝其相应的履行要求。"},{"i":67,"n":"第六十七条","txt":"当事人互负债务，有先后履行顺序，先履行一方未履行的，后履行一方有权拒绝其履行要求。先履行一方履行债务不符合约定的，后履行一方有权拒绝其相应的履行要求。"},{"i":68,"n":"第六十八条","txt":"应当先履行债务的当事人，有确切证据证明对方有下列情形之一的，可以中止履行："},{"i":69,"n":"第六十九条","txt":"当事人依照本法第六十八条的规定中止履行的，应当及时通知对方。对方提供适当担保时，应当恢复履行。中止履行后，对方在合理期限内未恢复履行能力并且未提供适当担保的，中止履行的一方可以解除合同。"},{"i":70,"n":"第七十条","txt":"债权人分立、合并或者变更住所没有通知债务人，致使履行债务发生困难的，债务人可以中止履行或者将标的物提存。"},{"i":71,"n":"第七十一条","txt":"债权人可以拒绝债务人提前履行债务，但提前履行不损害债权人利益的除外。"},{"i":72,"n":"第七十二条","txt":"债权人可以拒绝债务人部分履行债务，但部分履行不损害债权人利益的除外。"},{"i":73,"n":"第七十三条","txt":"因债务人怠于行使其到期债权，对债权人造成损害的，债权人可以向人民法院请求以自己的名义代位行使债务人的债权，但该债权专属于债务人自身的除外。"},{"i":74,"n":"第七十四条","txt":"因债务人放弃其到期债权或者无偿转让财产，对债权人造成损害的，债权人可以请求人民法院撤销债务人的行为。债务人以明显不合理的低价转让财产，对债权人造成损害，并且受让人知道该情形的，债权人也可以请求人民法院撤销债务人的行为。"},{"i":75,"n":"第七十五条","txt":"撤销权自债权人知道或者应当知道撤销事由之日起一年内行使。自债务人的行为发生之日起五年内没有行使撤销权的，该撤销权消灭。"},{"i":76,"n":"第七十六条","txt":"合同生效后，当事人不得因姓名、名称的变更或者法定代表人、负责人、承办人的变动而不履行合同义务。"},{"i":77,"n":"第七十七条","txt":"当事人协商一致，可以变更合同。"},{"i":78,"n":"第七十八条","txt":"当事人对合同变更的内容约定不明确的，推定为未变更。"},{"i":79,"n":"第七十九条","txt":"债权人可以将合同的权利全部或者部分转让给第三人，但有下列情形之一的除外："},{"i":80,"n":"第八十条","txt":"债权人转让权利的，应当通知债务人。未经通知，该转让对债务人不发生效力。"},{"i":81,"n":"第八十一条","txt":"债权人转让权利的，受让人取得与债权有关的从权利，但该从权利专属于债权人自身的除外。"},{"i":82,"n":"第八十二条","txt":"债务人接到债权转让通知后，债务人对让与人的抗辩，可以向受让人主张。"},{"i":83,"n":"第八十三条","txt":"债务人接到债权转让通知时，债务人对让与人享有债权，并且债务人的债权先于转让的债权到期或者同时到期的，债务人可以向受让人主张抵销。"},{"i":84,"n":"第八十四条","txt":"债务人将合同的义务全部或者部分转移给第三人的，应当经债权人同意。"},{"i":85,"n":"第八十五条","txt":"债务人转移义务的，新债务人可以主张原债务人对债权人的抗辩。"},{"i":86,"n":"第八十六条","txt":"债务人转移义务的，新债务人应当承担与主债务有关的从债务，但该从债务专属于原债务人自身的除外。"},{"i":87,"n":"第八十七条","txt":"法律、行政法规规定转让权利或者转移义务应当办理批准、登记等手续的，依照其规定。"},{"i":88,"n":"第八十八条","txt":"当事人一方经对方同意，可以将自己在合同中的权利和义务一并转让给第三人。"},{"i":89,"n":"第八十九条","txt":"权利和义务一并转让的，适用本法第七十九条、第八十一条至第八十三条、第八十五条至第八十七条的规定。"},{"i":90,"n":"第九十条","txt":"当事人订立合同后合并的，由合并后的法人或者其他组织行使合同权利，履行合同义务。当事人订立合同后分立的，除债权人和债务人另有约定的以外，由分立的法人或者其他组织对合同的权利和义务享有连带债权，承担连带债务。"},{"i":91,"n":"第九十一条","txt":"有下列情形之一的，合同的权利义务终止："},{"i":92,"n":"第九十二条","txt":"合同的权利义务终止后，当事人应当遵循诚实信用原则，根据交易习惯履行通知、协助、保密等义务。"},{"i":93,"n":"第九十三条","txt":"当事人协商一致，可以解除合同。"},{"i":94,"n":"第九十四条","txt":"有下列情形之一的，当事人可以解除合同："},{"i":95,"n":"第九十五条","txt":"法律规定或者当事人约定解除权行使期限，期限届满当事人不行使的，该权利消灭。"},{"i":96,"n":"第九十六条","txt":"当事人一方依照本法第九十三条第二款、第九十四条的规定主张解除合同的，应当通知对方。合同自通知到达对方时解除。对方有异议的，可以请求人民法院或者仲裁机构确认解除合同的效力。"},{"i":97,"n":"第九十七条","txt":"合同解除后，尚未履行的，终止履行；已经履行的，根据履行情况和合同性质，当事人可以要求恢复原状、采取其他补救措施，并有权要求赔偿损失。"},{"i":98,"n":"第九十八条","txt":"合同的权利义务终止，不影响合同中结算和清理条款的效力。"},{"i":99,"n":"第九十九条","txt":"当事人互负到期债务，该债务的标的物种类、品质相同的，任何一方可以将自己的债务与对方的债务抵销，但依照法律规定或者按照合同性质不得抵销的除外。"},{"i":100,"n":"第一百条","txt":"当事人互负债务，标的物种类、品质不相同的，经双方协商一致，也可以抵销。"},{"i":101,"n":"第一百零一条","txt":"有下列情形之一，难以履行债务的，债务人可以将标的物提存："},{"i":102,"n":"第一百零二条","txt":"标的物提存后，除债权人下落不明的以外，债务人应当及时通知债权人或者债权人的继承人、监护人。"},{"i":103,"n":"第一百零三条","txt":"标的物提存后，毁损、灭失的风险由债权人承担。提存期间，标的物的孳息归债权人所有。提存费用由债权人负担。"},{"i":104,"n":"第一百零四条","txt":"债权人可以随时领取提存物，但债权人对债务人负有到期债务的，在债权人未履行债务或者提供担保之前，提存部门根据债务人的要求应当拒绝其领取提存物。"},{"i":105,"n":"第一百零五条","txt":"债权人免除债务人部分或者全部债务的，合同的权利义务部分或者全部终止。"},{"i":106,"n":"第一百零六条","txt":"债权和债务同归于一人的，合同的权利义务终止，但涉及第三人利益的除外。"},{"i":107,"n":"第一百零七条","txt":"当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。"},{"i":108,"n":"第一百零八条","txt":"当事人一方明确表示或者以自己的行为表明不履行合同义务的，对方可以在履行期限届满之前要求其承担违约责任。"},{"i":109,"n":"第一百零九条","txt":"当事人一方未支付价款或者报酬的，对方可以要求其支付价款或者报酬。"},{"i":110,"n":"第一百一十条","txt":"当事人一方不履行非金钱债务或者履行非金钱债务不符合约定的，对方可以要求履行，但有下列情形之一的除外："},{"i":111,"n":"第一百一十一条","txt":"质量不符合约定的，应当按照当事人的约定承担违约责任。对违约责任没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，受损害方根据标的的性质以及损失的大小，可以合理选择要求对方承担修理、更换、重作、退货、减少价款或者报酬等违约责任。"},{"i":112,"n":"第一百一十二条","txt":"当事人一方不履行合同义务或者履行合同义务不符合约定的，在履行义务或者采取补救措施后，对方还有其他损失的，应当赔偿损失。"},{"i":113,"n":"第一百一十三条","txt":"当事人一方不履行合同义务或者履行合同义务不符合约定，给对方造成损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益，但不得超过违反合同一方订立合同时预见到或者应当预见到的因违反合同可能造成的损失。"},{"i":114,"n":"第一百一十四条","txt":"当事人可以约定一方违约时应当根据违约情况向对方支付一定数额的违约金，也可以约定因违约产生的损失赔偿额的计算方法。"},{"i":115,"n":"第一百一十五条","txt":"当事人可以依照《中华人民共和国担保法》约定一方向对方给付定金作为债权的担保。债务人履行债务后，定金应当抵作价款或者收回。给付定金的一方不履行约定的债务的，无权要求返还定金；收受定金的一方不履行约定的债务的，应当双倍返还定金。"},{"i":116,"n":"第一百一十六条","txt":"当事人既约定违约金，又约定定金的，一方违约时，对方可以选择适用违约金或者定金条款。"},{"i":117,"n":"第一百一十七条","txt":"因不可抗力不能履行合同的，根据不可抗力的影响，部分或者全部免除责任，但法律另有规定的除外。当事人迟延履行后发生不可抗力的，不能免除责任。"},{"i":118,"n":"第一百一十八条","txt":"当事人一方因不可抗力不能履行合同的，应当及时通知对方，以减轻可能给对方造成的损失，并应当在合理期限内提供证明。"},{"i":119,"n":"第一百一十九条","txt":"当事人一方违约后，对方应当采取适当措施防止损失的扩大；没有采取适当措施致使损失扩大的，不得就扩大的损失要求赔偿。"},{"i":120,"n":"第一百二十条","txt":"当事人双方都违反合同的，应当各自承担相应的责任。"},{"i":121,"n":"第一百二十一条","txt":"当事人一方因第三人的原因造成违约的，应当向对方承担违约责任。当事人一方和第三人之间的纠纷，依照法律规定或者按照约定解决。"},{"i":122,"n":"第一百二十二条","txt":"因当事人一方的违约行为，侵害对方人身、财产权益的，受损害方有权选择依照本法要求其承担违约责任或者依照其他法律要求其承担侵权责任。"},{"i":123,"n":"第一百二十三条","txt":"其他法律对合同另有规定的，依照其规定。"},{"i":124,"n":"第一百二十四条","txt":"本法分则或者其他法律没有明文规定的合同，适用本法总则的规定，并可以参照本法分则或者其他法律最相类似的规定。"},{"i":125,"n":"第一百二十五条","txt":"当事人对合同条款的理解有争议的，应当按照合同所使用的词句、合同的有关条款、合同的目的、交易习惯以及诚实信用原则，确定该条款的真实意思。"},{"i":126,"n":"第一百二十六条","txt":"涉外合同的当事人可以选择处理合同争议所适用的法律，但法律另有规定的除外。涉外合同的当事人没有选择的，适用与合同有最密切联系的国家的法律。"},{"i":127,"n":"第一百二十七条","txt":"工商行政管理部门和其他有关行政主管部门在各自的职权范围内，依照法律、行政法规的规定，对利用合同危害国家利益、社会公共利益的违法行为，负责监督处理；构成犯罪的，依法追究刑事责任。"},{"i":128,"n":"第一百二十八条","txt":"当事人可以通过和解或者调解解决合同争议。"},{"i":129,"n":"第一百二十九条","txt":"因国际货物买卖合同和技术进出口合同争议提起诉讼或者申请仲裁的期限为四年，自当事人知道或者应当知道其权利受到侵害之日起计算。因其他合同争议提起诉讼或者申请仲裁的期限，依照有关法律的规定。"},{"i":130,"n":"第一百三十条","txt":"买卖合同是出卖人转移标的物的所有权于买受人，买受人支付价款的合同。"},{"i":131,"n":"第一百三十一条","txt":"买卖合同的内容除依照本法第十二条的规定以外，还可以包括包装方式、检验标准和方法、结算方式、合同使用的文字及其效力等条款。"},{"i":132,"n":"第一百三十二条","txt":"出卖的标的物，应当属于出卖人所有或者出卖人有权处分。"},{"i":133,"n":"第一百三十三条","txt":"标的物的所有权自标的物交付时起转移，但法律另有规定或者当事人另有约定的除外。"},{"i":134,"n":"第一百三十四条","txt":"当事人可以在买卖合同中约定买受人未履行支付价款或者其他义务的，标的物的所有权属于出卖人。"},{"i":135,"n":"第一百三十五条","txt":"出卖人应当履行向买受人交付标的物或者交付提取标的物的单证，并转移标的物所有权的义务。"},{"i":136,"n":"第一百三十六条","txt":"出卖人应当按照约定或者交易习惯向买受人交付提取标的物单证以外的有关单证和资料。"},{"i":137,"n":"第一百三十七条","txt":"出卖具有知识产权的计算机软件等标的物的，除法律另有规定或者当事人另有约定的以外，该标的物的知识产权不属于买受人。"},{"i":138,"n":"第一百三十八条","txt":"出卖人应当按照约定的期限交付标的物。约定交付期间的，出卖人可以在该交付期间内的任何时间交付。"},{"i":139,"n":"第一百三十九条","txt":"当事人没有约定标的物的交付期限或者约定不明确的，适用本法第六十一条、第六十二条第四项的规定。"},{"i":140,"n":"第一百四十条","txt":"标的物在订立合同之前已为买受人占有的，合同生效的时间为交付时间。"},{"i":141,"n":"第一百四十一条","txt":"出卖人应当按照约定的地点交付标的物。"},{"i":142,"n":"第一百四十二条","txt":"标的物毁损、灭失的风险，在标的物交付之前由出卖人承担，交付之后由买受人承担，但法律另有规定或者当事人另有约定的除外。"},{"i":143,"n":"第一百四十三条","txt":"因买受人的原因致使标的物不能按照约定的期限交付的，买受人应当自违反约定之日起承担标的物毁损、灭失的风险。"},{"i":144,"n":"第一百四十四条","txt":"出卖人出卖交由承运人运输的在途标的物，除当事人另有约定的以外，毁损、灭失的风险自合同成立时起由买受人承担。"},{"i":145,"n":"第一百四十五条","txt":"当事人没有约定交付地点或者约定不明确，依照本法第一百四十一条第二款第一项的规定标的物需要运输的，出卖人将标的物交付给第一承运人后，标的物毁损、灭失的风险由买受人承担。"},{"i":146,"n":"第一百四十六条","txt":"出卖人按照约定或者依照本法第一百四十一条第二款第二项的规定将标的物置于交付地点，买受人违反约定没有收取的，标的物毁损、灭失的风险自违反约定之日起由买受人承担。"},{"i":147,"n":"第一百四十七条","txt":"出卖人按照约定未交付有关标的物的单证和资料的，不影响标的物毁损、灭失风险的转移。"},{"i":148,"n":"第一百四十八条","txt":"因标的物质量不符合质量要求，致使不能实现合同目的的，买受人可以拒绝接受标的物或者解除合同。买受人拒绝接受标的物或者解除合同的，标的物毁损、灭失的风险由出卖人承担。"},{"i":149,"n":"第一百四十九条","txt":"标的物毁损、灭失的风险由买受人承担的，不影响因出卖人履行债务不符合约定，买受人要求其承担违约责任的权利。"},{"i":150,"n":"第一百五十条","txt":"出卖人就交付的标的物，负有保证第三人不得向买受人主张任何权利的义务，但法律另有规定的除外。"},{"i":151,"n":"第一百五十一条","txt":"买受人订立合同时知道或者应当知道第三人对买卖的标的物享有权利的，出卖人不承担本法第一百五十条规定的义务。"},{"i":152,"n":"第一百五十二条","txt":"买受人有确切证据证明第三人可能就标的物主张权利的，可以中止支付相应的价款，但出卖人提供适当担保的除外。"},{"i":153,"n":"第一百五十三条","txt":"出卖人应当按照约定的质量要求交付标的物。出卖人提供有关标的物质量说明的，交付的标的物应当符合该说明的质量要求。"},{"i":154,"n":"第一百五十四条","txt":"当事人对标的物的质量要求没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，适用本法第六十二条第一项的规定。"},{"i":155,"n":"第一百五十五条","txt":"出卖人交付的标的物不符合质量要求的，买受人可以依照本法第一百一十一条的规定要求承担违约责任。"},{"i":156,"n":"第一百五十六条","txt":"出卖人应当按照约定的包装方式交付标的物。对包装方式没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，应当按照通用的方式包装，没有通用方式的，应当采取足以保护标的物的包装方式。"},{"i":157,"n":"第一百五十七条","txt":"买受人收到标的物时应当在约定的检验期间内检验。没有约定检验期间的，应当及时检验。"},{"i":158,"n":"第一百五十八条","txt":"当事人约定检验期间的，买受人应当在检验期间内将标的物的数量或者质量不符合约定的情形通知出卖人。买受人怠于通知的，视为标的物的数量或者质量符合约定。"},{"i":159,"n":"第一百五十九条","txt":"买受人应当按照约定的数额支付价款。对价款没有约定或者约定不明确的，适用本法第六十一条、第六十二条第二项的规定。"},{"i":160,"n":"第一百六十条","txt":"买受人应当按照约定的地点支付价款。对支付地点没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，买受人应当在出卖人的营业地支付，但约定支付价款以交付标的物或者交付提取标的物单证为条件的，在交付标的物或者交付提取标的物单证的所在地支付。"},{"i":161,"n":"第一百六十一条","txt":"买受人应当按照约定的时间支付价款。对支付时间没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，买受人应当在收到标的物或者提取标的物单证的同时支付。"},{"i":162,"n":"第一百六十二条","txt":"出卖人多交标的物的，买受人可以接收或者拒绝接收多交的部分。买受人接收多交部分的，按照合同的价格支付价款；买受人拒绝接收多交部分的，应当及时通知出卖人。"},{"i":163,"n":"第一百六十三条","txt":"标的物在交付之前产生的孳息，归出卖人所有，交付之后产生的孳息，归买受人所有。"},{"i":164,"n":"第一百六十四条","txt":"因标的物的主物不符合约定而解除合同的，解除合同的效力及于从物。因标的物的从物不符合约定被解除的，解除的效力不及于主物。"},{"i":165,"n":"第一百六十五条","txt":"标的物为数物，其中一物不符合约定的，买受人可以就该物解除，但该物与他物分离使标的物的价值显受损害的，当事人可以就数物解除合同。"},{"i":166,"n":"第一百六十六条","txt":"出卖人分批交付标的物的，出卖人对其中一批标的物不交付或者交付不符合约定，致使该批标的物不能实现合同目的的，买受人可以就该批标的物解除。"},{"i":167,"n":"第一百六十七条","txt":"分期付款的买受人未支付到期价款的金额达到全部价款的五分之一的，出卖人可以要求买受人支付全部价款或者解除合同。"},{"i":168,"n":"第一百六十八条","txt":"凭样品买卖的当事人应当封存样品，并可以对样品质量予以说明。出卖人交付的标的物应当与样品及其说明的质量相同。"},{"i":169,"n":"第一百六十九条","txt":"凭样品买卖的买受人不知道样品有隐蔽瑕疵的，即使交付的标的物与样品相同，出卖人交付的标的物的质量仍然应当符合同种物的通常标准。"},{"i":170,"n":"第一百七十条","txt":"试用买卖的当事人可以约定标的物的试用期间。对试用期间没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，由出卖人确定。"},{"i":171,"n":"第一百七十一条","txt":"试用买卖的买受人在试用期内可以购买标的物，也可以拒绝购买。试用期间届满，买受人对是否购买标的物未作表示的，视为购买。"},{"i":172,"n":"第一百七十二条","txt":"招标投标买卖的当事人的权利和义务以及招标投标程序等，依照有关法律、行政法规的规定。"},{"i":173,"n":"第一百七十三条","txt":"拍卖的当事人的权利和义务以及拍卖程序等，依照有关法律、行政法规的规定。"},{"i":174,"n":"第一百七十四条","txt":"法律对其他有偿合同有规定的，依照其规定；没有规定的，参照买卖合同的有关规定。"},{"i":175,"n":"第一百七十五条","txt":"当事人约定易货交易，转移标的物的所有权的，参照买卖合同的有关规定。"},{"i":176,"n":"第一百七十六条","txt":"供用电合同是供电人向用电人供电，用电人支付电费的合同。"},{"i":177,"n":"第一百七十七条","txt":"供用电合同的内容包括供电的方式、质量、时间，用电容量、地址、性质，计量方式，电价、电费的结算方式，供用电设施的维护责任等条款。"},{"i":178,"n":"第一百七十八条","txt":"供用电合同的履行地点，按照当事人约定；当事人没有约定或者约定不明确的，供电设施的产权分界处为履行地点。"},{"i":179,"n":"第一百七十九条","txt":"供电人应当按照国家规定的供电质量标准和约定安全供电。供电人未按照国家规定的供电质量标准和约定安全供电，造成用电人损失的，应当承担损害赔偿责任。"},{"i":180,"n":"第一百八十条","txt":"供电人因供电设施计划检修、临时检修、依法限电或者用电人违法用电等原因，需要中断供电时，应当按照国家有关规定事先通知用电人。未事先通知用电人中断供电，造成用电人损失的，应当承担损害赔偿责任。"},{"i":181,"n":"第一百八十一条","txt":"因自然灾害等原因断电，供电人应当按照国家有关规定及时抢修。未及时抢修，造成用电人损失的，应当承担损害赔偿责任。"},{"i":182,"n":"第一百八十二条","txt":"用电人应当按照国家有关规定和当事人的约定及时交付电费。用电人逾期不交付电费的，应当按照约定支付违约金。经催告用电人在合理期限内仍不交付电费和违约金的，供电人可以按照国家规定的程序中止供电。"},{"i":183,"n":"第一百八十三条","txt":"用电人应当按照国家有关规定和当事人的约定安全用电。用电人未按照国家有关规定和当事人的约定安全用电，造成供电人损失的，应当承担损害赔偿责任。"},{"i":184,"n":"第一百八十四条","txt":"供用水、供用气、供用热力合同，参照供用电合同的有关规定。"},{"i":185,"n":"第一百八十五条","txt":"赠与合同是赠与人将自己的财产无偿给予受赠人，受赠人表示接受赠与的合同。"},{"i":186,"n":"第一百八十六条","txt":"赠与人在赠与财产的权利转移之前可以撤销赠与。"},{"i":187,"n":"第一百八十七条","txt":"赠与的财产依法需要办理登记等手续的，应当办理有关手续。"},{"i":188,"n":"第一百八十八条","txt":"具有救灾、扶贫等社会公益、道德义务性质的赠与合同或者经过公证的赠与合同，赠与人不交付赠与的财产的，受赠人可以要求交付。"},{"i":189,"n":"第一百八十九条","txt":"因赠与人故意或者重大过失致使赠与的财产毁损、灭失的，赠与人应当承担损害赔偿责任。"},{"i":190,"n":"第一百九十条","txt":"赠与可以附义务。"},{"i":191,"n":"第一百九十一条","txt":"赠与的财产有瑕疵的，赠与人不承担责任。附义务的赠与，赠与的财产有瑕疵的，赠与人在附义务的限度内承担与出卖人相同的责任。"},{"i":192,"n":"第一百九十二条","txt":"受赠人有下列情形之一的，赠与人可以撤销赠与："},{"i":193,"n":"第一百九十三条","txt":"因受赠人的违法行为致使赠与人死亡或者丧失民事行为能力的，赠与人的继承人或者法定代理人可以撤销赠与。"},{"i":194,"n":"第一百九十四条","txt":"撤销权人撤销赠与的，可以向受赠人要求返还赠与的财产。"},{"i":195,"n":"第一百九十五条","txt":"赠与人的经济状况显著恶化，严重影响其生产经营或者家庭生活的，可以不再履行赠与义务。"},{"i":196,"n":"第一百九十六条","txt":"借款合同是借款人向贷款人借款，到期返还借款并支付利息的合同。"},{"i":197,"n":"第一百九十七条","txt":"借款合同采用书面形式，但自然人之间借款另有约定的除外。"},{"i":198,"n":"第一百九十八条","txt":"订立借款合同，贷款人可以要求借款人提供担保。担保依照《中华人民共和国担保法》的规定。"},{"i":199,"n":"第一百九十九条","txt":"订立借款合同，借款人应当按照贷款人的要求提供与借款有关的业务活动和财务状况的真实情况。"},{"i":200,"n":"第二百条","txt":"借款的利息不得预先在本金中扣除。利息预先在本金中扣除的，应当按照实际借款数额返还借款并计算利息。"},{"i":201,"n":"第二百零一条","txt":"贷款人未按照约定的日期、数额提供借款，造成借款人损失的，应当赔偿损失。"},{"i":202,"n":"第二百零二条","txt":"贷款人按照约定可以检查、监督借款的使用情况。借款人应当按照约定向贷款人定期提供有关财务会计报表等资料。"},{"i":203,"n":"第二百零三条","txt":"借款人未按照约定的借款用途使用借款的，贷款人可以停止发放借款、提前收回借款或者解除合同。"},{"i":204,"n":"第二百零四条","txt":"办理贷款业务的金融机构贷款的利率，应当按照中国人民银行规定的贷款利率的上下限确定。"},{"i":205,"n":"第二百零五条","txt":"借款人应当按照约定的期限支付利息。对支付利息的期限没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定，借款期间不满一年的，应当在返还借款时一并支付；借款期间一年以上的，应当在每届满一年时支付，剩余期间不满一年的，应当在返还借款时一并支付。"},{"i":206,"n":"第二百零六条","txt":"借款人应当按照约定的期限返还借款。对借款期限没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，借款人可以随时返还；贷款人可以催告借款人在合理期限内返还。"},{"i":207,"n":"第二百零七条","txt":"借款人未按照约定的期限返还借款的，应当按照约定或者国家有关规定支付逾期利息。"},{"i":208,"n":"第二百零八条","txt":"借款人提前偿还借款的，除当事人另有约定的以外，应当按照实际借款的期间计算利息。"},{"i":209,"n":"第二百零九条","txt":"借款人可以在还款期限届满之前向贷款人申请展期。贷款人同意的，可以展期。"},{"i":210,"n":"第二百一十条","txt":"自然人之间的借款合同，自贷款人提供借款时生效。"},{"i":211,"n":"第二百一十一条","txt":"自然人之间的借款合同对支付利息没有约定或者约定不明确的，视为不支付利息。"},{"i":212,"n":"第二百一十二条","txt":"租赁合同是出租人将租赁物交付承租人使用、收益，承租人支付租金的合同。"},{"i":213,"n":"第二百一十三条","txt":"租赁合同的内容包括租赁物的名称、数量、用途、租赁期限、租金及其支付期限和方式、租赁物维修等条款。"},{"i":214,"n":"第二百一十四条","txt":"租赁期限不得超过二十年。超过二十年的，超过部分无效。"},{"i":215,"n":"第二百一十五条","txt":"租赁期限六个月以上的，应当采用书面形式。当事人未采用书面形式的，视为不定期租赁。"},{"i":216,"n":"第二百一十六条","txt":"出租人应当按照约定将租赁物交付承租人，并在租赁期间保持租赁物符合约定的用途。"},{"i":217,"n":"第二百一十七条","txt":"承租人应当按照约定的方法使用租赁物。对租赁物的使用方法没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，应当按照租赁物的性质使用。"},{"i":218,"n":"第二百一十八条","txt":"承租人按照约定的方法或者租赁物的性质使用租赁物，致使租赁物受到损耗的，不承担损害赔偿责任。"},{"i":219,"n":"第二百一十九条","txt":"承租人未按照约定的方法或者租赁物的性质使用租赁物，致使租赁物受到损失的，出租人可以解除合同并要求赔偿损失。"},{"i":220,"n":"第二百二十条","txt":"出租人应当履行租赁物的维修义务，但当事人另有约定的除外。"},{"i":221,"n":"第二百二十一条","txt":"承租人在租赁物需要维修时可以要求出租人在合理期限内维修。出租人未履行维修义务的，承租人可以自行维修，维修费用由出租人负担。因维修租赁物影响承租人使用的，应当相应减少租金或者延长租期。"},{"i":222,"n":"第二百二十二条","txt":"承租人应当妥善保管租赁物，因保管不善造成租赁物毁损、灭失的，应当承担损害赔偿责任。"},{"i":223,"n":"第二百二十三条","txt":"承租人经出租人同意，可以对租赁物进行改善或者增设他物。"},{"i":224,"n":"第二百二十四条","txt":"承租人经出租人同意，可以将租赁物转租给第三人。承租人转租的，承租人与出租人之间的租赁合同继续有效，第三人对租赁物造成损失的，承租人应当赔偿损失。"},{"i":225,"n":"第二百二十五条","txt":"在租赁期间因占有、使用租赁物获得的收益，归承租人所有，但当事人另有约定的除外。"},{"i":226,"n":"第二百二十六条","txt":"承租人应当按照约定的期限支付租金。对支付期限没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定，租赁期间不满一年的，应当在租赁期间届满时支付；租赁期间一年以上的，应当在每届满一年时支付，剩余期间不满一年的，应当在租赁期间届满时支付。"},{"i":227,"n":"第二百二十七条","txt":"承租人无正当理由未支付或者迟延支付租金的，出租人可以要求承租人在合理期限内支付。承租人逾期不支付的，出租人可以解除合同。"},{"i":228,"n":"第二百二十八条","txt":"因第三人主张权利，致使承租人不能对租赁物使用、收益的，承租人可以要求减少租金或者不支付租金。"},{"i":229,"n":"第二百二十九条","txt":"租赁物在租赁期间发生所有权变动的，不影响租赁合同的效力。"},{"i":230,"n":"第二百三十条","txt":"出租人出卖租赁房屋的，应当在出卖之前的合理期限内通知承租人，承租人享有以同等条件优先购买的权利。"},{"i":231,"n":"第二百三十一条","txt":"因不可归责于承租人的事由，致使租赁物部分或者全部毁损、灭失的，承租人可以要求减少租金或者不支付租金；因租赁物部分或者全部毁损、灭失，致使不能实现合同目的的，承租人可以解除合同。"},{"i":232,"n":"第二百三十二条","txt":"当事人对租赁期限没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，视为不定期租赁。当事人可以随时解除合同，但出租人解除合同应当在合理期限之前通知承租人。"},{"i":233,"n":"第二百三十三条","txt":"租赁物危及承租人的安全或者健康的，即使承租人订立合同时明知该租赁物质量不合格，承租人仍然可以随时解除合同。"},{"i":234,"n":"第二百三十四条","txt":"承租人在房屋租赁期间死亡的，与其生前共同居住的人可以按照原租赁合同租赁该房屋。"},{"i":235,"n":"第二百三十五条","txt":"租赁期间届满，承租人应当返还租赁物。返还的租赁物应当符合按照约定或者租赁物的性质使用后的状态。"},{"i":236,"n":"第二百三十六条","txt":"租赁期间届满，承租人继续使用租赁物，出租人没有提出异议的，原租赁合同继续有效，但租赁期限为不定期。"},{"i":237,"n":"第二百三十七条","txt":"融资租赁合同是出租人根据承租人对出卖人、租赁物的选择，向出卖人购买租赁物，提供给承租人使用，承租人支付租金的合同。"},{"i":238,"n":"第二百三十八条","txt":"融资租赁合同的内容包括租赁物名称、数量、规格、技术性能、检验方法、租赁期限、租金构成及其支付期限和方式、币种、租赁期间届满租赁物的归属等条款。"},{"i":239,"n":"第二百三十九条","txt":"出租人根据承租人对出卖人、租赁物的选择订立的买卖合同，出卖人应当按照约定向承租人交付标的物，承租人享有与受领标的物有关的买受人的权利。"},{"i":240,"n":"第二百四十条","txt":"出租人、出卖人、承租人可以约定，出卖人不履行买卖合同义务的，由承租人行使索赔的权利。承租人行使索赔权利的，出租人应当协助。"},{"i":241,"n":"第二百四十一条","txt":"出租人根据承租人对出卖人、租赁物的选择订立的买卖合同，未经承租人同意，出租人不得变更与承租人有关的合同内容。"},{"i":242,"n":"第二百四十二条","txt":"出租人享有租赁物的所有权。承租人破产的，租赁物不属于破产财产。"},{"i":243,"n":"第二百四十三条","txt":"融资租赁合同的租金，除当事人另有约定的以外，应当根据购买租赁物的大部分或者全部成本以及出租人的合理利润确定。"},{"i":244,"n":"第二百四十四条","txt":"租赁物不符合约定或者不符合使用目的的，出租人不承担责任，但承租人依赖出租人的技能确定租赁物或者出租人干预选择租赁物的除外。"},{"i":245,"n":"第二百四十五条","txt":"出租人应当保证承租人对租赁物的占有和使用。"},{"i":246,"n":"第二百四十六条","txt":"承租人占有租赁物期间，租赁物造成第三人的人身伤害或者财产损害的，出租人不承担责任。"},{"i":247,"n":"第二百四十七条","txt":"承租人应当妥善保管、使用租赁物。"},{"i":248,"n":"第二百四十八条","txt":"承租人应当按照约定支付租金。承租人经催告后在合理期限内仍不支付租金的，出租人可以要求支付全部租金；也可以解除合同，收回租赁物。"},{"i":249,"n":"第二百四十九条","txt":"当事人约定租赁期间届满租赁物归承租人所有，承租人已经支付大部分租金，但无力支付剩余租金，出租人因此解除合同收回租赁物的，收回的租赁物的价值超过承租人欠付的租金以及其他费用的，承租人可以要求部分返还。"},{"i":250,"n":"第二百五十条","txt":"出租人和承租人可以约定租赁期间届满租赁物的归属。对租赁物的归属没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，租赁物的所有权归出租人。"},{"i":251,"n":"第二百五十一条","txt":"承揽合同是承揽人按照定作人的要求完成工作，交付工作成果，定作人给付报酬的合同。"},{"i":252,"n":"第二百五十二条","txt":"承揽合同的内容包括承揽的标的、数量、质量、报酬、承揽方式、材料的提供、履行期限、验收标准和方法等条款。"},{"i":253,"n":"第二百五十三条","txt":"承揽人应当以自己的设备、技术和劳力，完成主要工作，但当事人另有约定的除外。"},{"i":254,"n":"第二百五十四条","txt":"承揽人可以将其承揽的辅助工作交由第三人完成。承揽人将其承揽的辅助工作交由第三人完成的，应当就该第三人完成的工作成果向定作人负责。"},{"i":255,"n":"第二百五十五条","txt":"承揽人提供材料的，承揽人应当按照约定选用材料，并接受定作人检验。"},{"i":256,"n":"第二百五十六条","txt":"定作人提供材料的，定作人应当按照约定提供材料。承揽人对定作人提供的材料，应当及时检验，发现不符合约定时，应当及时通知定作人更换、补齐或者采取其他补救措施。"},{"i":257,"n":"第二百五十七条","txt":"承揽人发现定作人提供的图纸或者技术要求不合理的，应当及时通知定作人。因定作人怠于答复等原因造成承揽人损失的，应当赔偿损失。"},{"i":258,"n":"第二百五十八条","txt":"定作人中途变更承揽工作的要求，造成承揽人损失的，应当赔偿损失。"},{"i":259,"n":"第二百五十九条","txt":"承揽工作需要定作人协助的，定作人有协助的义务。"},{"i":260,"n":"第二百六十条","txt":"承揽人在工作期间，应当接受定作人必要的监督检验。定作人不得因监督检验妨碍承揽人的正常工作。"},{"i":261,"n":"第二百六十一条","txt":"承揽人完成工作的，应当向定作人交付工作成果，并提交必要的技术资料和有关质量证明。定作人应当验收该工作成果。"},{"i":262,"n":"第二百六十二条","txt":"承揽人交付的工作成果不符合质量要求的，定作人可以要求承揽人承担修理、重作、减少报酬、赔偿损失等违约责任。"},{"i":263,"n":"第二百六十三条","txt":"定作人应当按照约定的期限支付报酬。对支付报酬的期限没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，定作人应当在承揽人交付工作成果时支付；工作成果部分交付的，定作人应当相应支付。"},{"i":264,"n":"第二百六十四条","txt":"定作人未向承揽人支付报酬或者材料费等价款的，承揽人对完成的工作成果享有留置权，但当事人另有约定的除外。"},{"i":265,"n":"第二百六十五条","txt":"承揽人应当妥善保管定作人提供的材料以及完成的工作成果，因保管不善造成毁损、灭失的，应当承担损害赔偿责任。"},{"i":266,"n":"第二百六十六条","txt":"承揽人应当按照定作人的要求保守秘密，未经定作人许可，不得留存复制品或者技术资料。"},{"i":267,"n":"第二百六十七条","txt":"共同承揽人对定作人承担连带责任，但当事人另有约定的除外。"},{"i":268,"n":"第二百六十八条","txt":"定作人可以随时解除承揽合同，造成承揽人损失的，应当赔偿损失。"},{"i":269,"n":"第二百六十九条","txt":"建设工程合同是承包人进行工程建设，发包人支付价款的合同。"},{"i":270,"n":"第二百七十条","txt":"建设工程合同应当采用书面形式。"},{"i":271,"n":"第二百七十一条","txt":"建设工程的招标投标活动，应当依照有关法律的规定公开、公平、公正进行。"},{"i":272,"n":"第二百七十二条","txt":"发包人可以与总承包人订立建设工程合同，也可以分别与勘察人、设计人、施工人订立勘察、设计、施工承包合同。发包人不得将应当由一个承包人完成的建设工程肢解成若干部分发包给几个承包人。"},{"i":273,"n":"第二百七十三条","txt":"国家重大建设工程合同，应当按照国家规定的程序和国家批准的投资计划、可行性研究报告等文件订立。"},{"i":274,"n":"第二百七十四条","txt":"勘察、设计合同的内容包括提交有关基础资料和文件（包括概预算）的期限、质量要求、费用以及其他协作条件等条款。"},{"i":275,"n":"第二百七十五条","txt":"施工合同的内容包括工程范围、建设工期、中间交工工程的开工和竣工时间、工程质量、工程造价、技术资料交付时间、材料和设备供应责任、拨款和结算、竣工验收、质量保修范围和质量保证期、双方相互协作等条款。"},{"i":276,"n":"第二百七十六条","txt":"建设工程实行监理的，发包人应当与监理人采用书面形式订立委托监理合同。发包人与监理人的权利和义务以及法律责任，应当依照本法委托合同以及其他有关法律、行政法规的规定。"},{"i":277,"n":"第二百七十七条","txt":"发包人在不妨碍承包人正常作业的情况下，可以随时对作业进度、质量进行检查。"},{"i":278,"n":"第二百七十八条","txt":"隐蔽工程在隐蔽以前，承包人应当通知发包人检查。发包人没有及时检查的，承包人可以顺延工程日期，并有权要求赔偿停工、窝工等损失。"},{"i":279,"n":"第二百七十九条","txt":"建设工程竣工后，发包人应当根据施工图纸及说明书、国家颁发的施工验收规范和质量检验标准及时进行验收。验收合格的，发包人应当按照约定支付价款，并接收该建设工程。"},{"i":280,"n":"第二百八十条","txt":"勘察、设计的质量不符合要求或者未按照期限提交勘察、设计文件拖延工期，造成发包人损失的，勘察人、设计人应当继续完善勘察、设计，减收或者免收勘察、设计费并赔偿损失。"},{"i":281,"n":"第二百八十一条","txt":"因施工人的原因致使建设工程质量不符合约定的，发包人有权要求施工人在合理期限内无偿修理或者返工、改建。经过修理或者返工、改建后，造成逾期交付的，施工人应当承担违约责任。"},{"i":282,"n":"第二百八十二条","txt":"因承包人的原因致使建设工程在合理使用期限内造成人身和财产损害的，承包人应当承担损害赔偿责任。"},{"i":283,"n":"第二百八十三条","txt":"发包人未按照约定的时间和要求提供原材料、设备、场地、资金、技术资料的，承包人可以顺延工程日期，并有权要求赔偿停工、窝工等损失。"},{"i":284,"n":"第二百八十四条","txt":"因发包人的原因致使工程中途停建、缓建的，发包人应当采取措施弥补或者减少损失，赔偿承包人因此造成的停工、窝工、倒运、机械设备调迁、材料和构件积压等损失和实际费用。"},{"i":285,"n":"第二百八十五条","txt":"因发包人变更计划，提供的资料不准确，或者未按照期限提供必需的勘察、设计工作条件而造成勘察、设计的返工、停工或者修改设计，发包人应当按照勘察人、设计人实际消耗的工作量增付费用。"},{"i":286,"n":"第二百八十六条","txt":"发包人未按照约定支付价款的，承包人可以催告发包人在合理期限内支付价款。发包人逾期不支付的，除按照建设工程的性质不宜折价、拍卖的以外，承包人可以与发包人协议将该工程折价，也可以申请人民法院将该工程依法拍卖。建设工程的价款就该工程折价或者拍卖的价款优先受偿。"},{"i":287,"n":"第二百八十七条","txt":"本章没有规定的，适用承揽合同的有关规定。"},{"i":288,"n":"第二百八十八条","txt":"运输合同是承运人将旅客或者货物从起运地点运输到约定地点，旅客、托运人或者收货人支付票款或者运输费用的合同。"},{"i":289,"n":"第二百八十九条","txt":"从事公共运输的承运人不得拒绝旅客、托运人通常、合理的运输要求。"},{"i":290,"n":"第二百九十条","txt":"承运人应当在约定期间或者合理期间内将旅客、货物安全运输到约定地点。"},{"i":291,"n":"第二百九十一条","txt":"承运人应当按照约定的或者通常的运输路线将旅客、货物运输到约定地点。"},{"i":292,"n":"第二百九十二条","txt":"旅客、托运人或者收货人应当支付票款或者运输费用。承运人未按照约定路线或者通常路线运输增加票款或者运输费用的，旅客、托运人或者收货人可以拒绝支付增加部分的票款或者运输费用。"},{"i":293,"n":"第二百九十三条","txt":"客运合同自承运人向旅客交付客票时成立，但当事人另有约定或者另有交易习惯的除外。"},{"i":294,"n":"第二百九十四条","txt":"旅客应当持有效客票乘运。旅客无票乘运、超程乘运、越级乘运或者持失效客票乘运的，应当补交票款，承运人可以按照规定加收票款。旅客不交付票款的，承运人可以拒绝运输。"},{"i":295,"n":"第二百九十五条","txt":"旅客因自己的原因不能按照客票记载的时间乘坐的，应当在约定的时间内办理退票或者变更手续。逾期办理的，承运人可以不退票款，并不再承担运输义务。"},{"i":296,"n":"第二百九十六条","txt":"旅客在运输中应当按照约定的限量携带行李。超过限量携带行李的，应当办理托运手续。"},{"i":297,"n":"第二百九十七条","txt":"旅客不得随身携带或者在行李中夹带易燃、易爆、有毒、有腐蚀性、有放射性以及有可能危及运输工具上人身和财产安全的危险物品或者其他违禁物品。"},{"i":298,"n":"第二百九十八条","txt":"承运人应当向旅客及时告知有关不能正常运输的重要事由和安全运输应当注意的事项。"},{"i":299,"n":"第二百九十九条","txt":"承运人应当按照客票载明的时间和班次运输旅客。承运人迟延运输的，应当根据旅客的要求安排改乘其他班次或者退票。"},{"i":300,"n":"第三百条","txt":"承运人擅自变更运输工具而降低服务标准的，应当根据旅客的要求退票或者减收票款；提高服务标准的，不应当加收票款。"},{"i":301,"n":"第三百零一条","txt":"承运人在运输过程中，应当尽力救助患有急病、分娩、遇险的旅客。"},{"i":302,"n":"第三百零二条","txt":"承运人应当对运输过程中旅客的伤亡承担损害赔偿责任，但伤亡是旅客自身健康原因造成的或者承运人证明伤亡是旅客故意、重大过失造成的除外。"},{"i":303,"n":"第三百零三条","txt":"在运输过程中旅客自带物品毁损、灭失，承运人有过错的，应当承担损害赔偿责任。"},{"i":304,"n":"第三百零四条","txt":"托运人办理货物运输，应当向承运人准确表明收货人的名称或者姓名或者凭指示的收货人，货物的名称、性质、重量、数量，收货地点等有关货物运输的必要情况。"},{"i":305,"n":"第三百零五条","txt":"货物运输需要办理审批、检验等手续的，托运人应当将办理完有关手续的文件提交承运人。"},{"i":306,"n":"第三百零六条","txt":"托运人应当按照约定的方式包装货物。对包装方式没有约定或者约定不明确的，适用本法第一百五十六条的规定。"},{"i":307,"n":"第三百零七条","txt":"托运人托运易燃、易爆、有毒、有腐蚀性、有放射性等危险物品的，应当按照国家有关危险物品运输的规定对危险物品妥善包装，作出危险物标志和标签，并将有关危险物品的名称、性质和防范措施的书面材料提交承运人。"},{"i":308,"n":"第三百零八条","txt":"在承运人将货物交付收货人之前，托运人可以要求承运人中止运输、返还货物、变更到达地或者将货物交给其他收货人，但应当赔偿承运人因此受到的损失。"},{"i":309,"n":"第三百零九条","txt":"货物运输到达后，承运人知道收货人的，应当及时通知收货人，收货人应当及时提货。收货人逾期提货的，应当向承运人支付保管费等费用。"},{"i":310,"n":"第三百一十条","txt":"收货人提货时应当按照约定的期限检验货物。对检验货物的期限没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，应当在合理期限内检验货物。收货人在约定的期限或者合理期限内对货物的数量、毁损等未提出异议的，视为承运人已经按照运输单证的记载交付的初步证据。"},{"i":311,"n":"第三百一十一条","txt":"承运人对运输过程中货物的毁损、灭失承担损害赔偿责任，但承运人证明货物的毁损、灭失是因不可抗力、货物本身的自然性质或者合理损耗以及托运人、收货人的过错造成的，不承担损害赔偿责任。"},{"i":312,"n":"第三百一十二条","txt":"货物的毁损、灭失的赔偿额，当事人有约定的，按照其约定；没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，按照交付或者应当交付时货物到达地的市场价格计算。法律、行政法规对赔偿额的计算方法和赔偿限额另有规定的，依照其规定。"},{"i":313,"n":"第三百一十三条","txt":"两个以上承运人以同一运输方式联运的，与托运人订立合同的承运人应当对全程运输承担责任。损失发生在某一运输区段的，与托运人订立合同的承运人和该区段的承运人承担连带责任。"},{"i":314,"n":"第三百一十四条","txt":"货物在运输过程中因不可抗力灭失，未收取运费的，承运人不得要求支付运费；已收取运费的，托运人可以要求返还。"},{"i":315,"n":"第三百一十五条","txt":"托运人或者收货人不支付运费、保管费以及其他运输费用的，承运人对相应的运输货物享有留置权，但当事人另有约定的除外。"},{"i":316,"n":"第三百一十六条","txt":"收货人不明或者收货人无正当理由拒绝受领货物的，依照本法第一百零一条的规定，承运人可以提存货物。"},{"i":317,"n":"第三百一十七条","txt":"多式联运经营人负责履行或者组织履行多式联运合同，对全程运输享有承运人的权利，承担承运人的义务。"},{"i":318,"n":"第三百一十八条","txt":"多式联运经营人可以与参加多式联运的各区段承运人就多式联运合同的各区段运输约定相互之间的责任，但该约定不影响多式联运经营人对全程运输承担的义务。"},{"i":319,"n":"第三百一十九条","txt":"多式联运经营人收到托运人交付的货物时，应当签发多式联运单据。按照托运人的要求，多式联运单据可以是可转让单据，也可以是不可转让单据。"},{"i":320,"n":"第三百二十条","txt":"因托运人托运货物时的过错造成多式联运经营人损失的，即使托运人已经转让多式联运单据，托运人仍然应当承担损害赔偿责任。"},{"i":321,"n":"第三百二十一条","txt":"货物的毁损、灭失发生于多式联运的某一运输区段的，多式联运经营人的赔偿责任和责任限额，适用调整该区段运输方式的有关法律规定。货物毁损、灭失发生的运输区段不能确定的，依照本章规定承担损害赔偿责任。"},{"i":322,"n":"第三百二十二条","txt":"技术合同是当事人就技术开发、转让、咨询或者服务订立的确立相互之间权利和义务的合同。"},{"i":323,"n":"第三百二十三条","txt":"订立技术合同，应当有利于科学技术的进步，加速科学技术成果的转化、应用和推广。"},{"i":324,"n":"第三百二十四条","txt":"技术合同的内容由当事人约定，一般包括以下条款："},{"i":325,"n":"第三百二十五条","txt":"技术合同价款、报酬或者使用费的支付方式由当事人约定，可以采取一次总算、一次总付或者一次总算、分期支付，也可以采取提成支付或者提成支付附加预付入门费的方式。"},{"i":326,"n":"第三百二十六条","txt":"职务技术成果的使用权、转让权属于法人或者其他组织的，法人或者其他组织可以就该项职务技术成果订立技术合同。法人或者其他组织应当从使用和转让该项职务技术成果所取得的收益中提取一定比例，对完成该项职务技术成果的个人给予奖励或者报酬。法人或者其他组织订立技术合同转让职务技术成果时，职务技术成果的完成人享有以同等条件优先受让的权利。"},{"i":327,"n":"第三百二十七条","txt":"非职务技术成果的使用权、转让权属于完成技术成果的个人，完成技术成果的个人可以就该项非职务技术成果订立技术合同。"},{"i":328,"n":"第三百二十八条","txt":"完成技术成果的个人有在有关技术成果文件上写明自己是技术成果完成者的权利和取得荣誉证书、奖励的权利。"},{"i":329,"n":"第三百二十九条","txt":"非法垄断技术、妨碍技术进步或者侵害他人技术成果的技术合同无效。"},{"i":330,"n":"第三百三十条","txt":"技术开发合同是指当事人之间就新技术、新产品、新工艺或者新材料及其系统的研究开发所订立的合同。"},{"i":331,"n":"第三百三十一条","txt":"委托开发合同的委托人应当按照约定支付研究开发经费和报酬；提供技术资料、原始数据；完成协作事项；接受研究开发成果。"},{"i":332,"n":"第三百三十二条","txt":"委托开发合同的研究开发人应当按照约定制定和实施研究开发计划；合理使用研究开发经费；按期完成研究开发工作，交付研究开发成果，提供有关的技术资料和必要的技术指导，帮助委托人掌握研究开发成果。"},{"i":333,"n":"第三百三十三条","txt":"委托人违反约定造成研究开发工作停滞、延误或者失败的，应当承担违约责任。"},{"i":334,"n":"第三百三十四条","txt":"研究开发人违反约定造成研究开发工作停滞、延误或者失败的，应当承担违约责任。"},{"i":335,"n":"第三百三十五条","txt":"合作开发合同的当事人应当按照约定进行投资，包括以技术进行投资；分工参与研究开发工作；协作配合研究开发工作。"},{"i":336,"n":"第三百三十六条","txt":"合作开发合同的当事人违反约定造成研究开发工作停滞、延误或者失败的，应当承担违约责任。"},{"i":337,"n":"第三百三十七条","txt":"因作为技术开发合同标的的技术已经由他人公开，致使技术开发合同的履行没有意义的，当事人可以解除合同。"},{"i":338,"n":"第三百三十八条","txt":"在技术开发合同履行过程中，因出现无法克服的技术困难，致使研究开发失败或者部分失败的，该风险责任由当事人约定。没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，风险责任由当事人合理分担。"},{"i":339,"n":"第三百三十九条","txt":"委托开发完成的发明创造，除当事人另有约定的以外，申请专利的权利属于研究开发人。研究开发人取得专利权的，委托人可以免费实施该专利。"},{"i":340,"n":"第三百四十条","txt":"合作开发完成的发明创造，除当事人另有约定的以外，申请专利的权利属于合作开发的当事人共有。当事人一方转让其共有的专利申请权的，其他各方享有以同等条件优先受让的权利。"},{"i":341,"n":"第三百四十一条","txt":"委托开发或者合作开发完成的技术秘密成果的使用权、转让权以及利益的分配办法，由当事人约定。没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，当事人均有使用和转让的权利，但委托开发的研究开发人不得在向委托人交付研究开发成果之前，将研究开发成果转让给第三人。"},{"i":342,"n":"第三百四十二条","txt":"技术转让合同包括专利权转让、专利申请权转让、技术秘密转让、专利实施许可合同。"},{"i":343,"n":"第三百四十三条","txt":"技术转让合同可以约定让与人和受让人实施专利或者使用技术秘密的范围，但不得限制技术竞争和技术发展。"},{"i":344,"n":"第三百四十四条","txt":"专利实施许可合同只在该专利权的存续期间内有效。专利权有效期限届满或者专利权被宣布无效的，专利权人不得就该专利与他人订立专利实施许可合同。"},{"i":345,"n":"第三百四十五条","txt":"专利实施许可合同的让与人应当按照约定许可受让人实施专利，交付实施专利有关的技术资料，提供必要的技术指导。"},{"i":346,"n":"第三百四十六条","txt":"专利实施许可合同的受让人应当按照约定实施专利，不得许可约定以外的第三人实施该专利；并按照约定支付使用费。"},{"i":347,"n":"第三百四十七条","txt":"技术秘密转让合同的让与人应当按照约定提供技术资料，进行技术指导，保证技术的实用性、可靠性，承担保密义务。"},{"i":348,"n":"第三百四十八条","txt":"技术秘密转让合同的受让人应当按照约定使用技术，支付使用费，承担保密义务。"},{"i":349,"n":"第三百四十九条","txt":"技术转让合同的让与人应当保证自己是所提供的技术的合法拥有者，并保证所提供的技术完整、无误、有效，能够达到约定的目标。"},{"i":350,"n":"第三百五十条","txt":"技术转让合同的受让人应当按照约定的范围和期限，对让与人提供的技术中尚未公开的秘密部分，承担保密义务。"},{"i":351,"n":"第三百五十一条","txt":"让与人未按照约定转让技术的，应当返还部分或者全部使用费，并应当承担违约责任；实施专利或者使用技术秘密超越约定的范围的，违反约定擅自许可第三人实施该项专利或者使用该项技术秘密的，应当停止违约行为，承担违约责任；违反约定的保密义务的，应当承担违约责任。"},{"i":352,"n":"第三百五十二条","txt":"受让人未按照约定支付使用费的，应当补交使用费并按照约定支付违约金；不补交使用费或者支付违约金的，应当停止实施专利或者使用技术秘密，交还技术资料，承担违约责任；实施专利或者使用技术秘密超越约定的范围的，未经让与人同意擅自许可第三人实施该专利或者使用该技术秘密的，应当停止违约行为，承担违约责任；违反约定的保密义务的，应当承担违约责任。"},{"i":353,"n":"第三百五十三条","txt":"受让人按照约定实施专利、使用技术秘密侵害他人合法权益的，由让与人承担责任，但当事人另有约定的除外。"},{"i":354,"n":"第三百五十四条","txt":"当事人可以按照互利的原则，在技术转让合同中约定实施专利、使用技术秘密后续改进的技术成果的分享办法。没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，一方后续改进的技术成果，其他各方无权分享。"},{"i":355,"n":"第三百五十五条","txt":"法律、行政法规对技术进出口合同或者专利、专利申请合同另有规定的，依照其规定。"},{"i":356,"n":"第三百五十六条","txt":"技术咨询合同包括就特定技术项目提供可行性论证、技术预测、专题技术调查、分析评价报告等合同。"},{"i":357,"n":"第三百五十七条","txt":"技术咨询合同的委托人应当按照约定阐明咨询的问题，提供技术背景材料及有关技术资料、数据；接受受托人的工作成果，支付报酬。"},{"i":358,"n":"第三百五十八条","txt":"技术咨询合同的受托人应当按照约定的期限完成咨询报告或者解答问题；提出的咨询报告应当达到约定的要求。"},{"i":359,"n":"第三百五十九条","txt":"技术咨询合同的委托人未按照约定提供必要的资料和数据，影响工作进度和质量，不接受或者逾期接受工作成果的，支付的报酬不得追回，未支付的报酬应当支付。"},{"i":360,"n":"第三百六十条","txt":"技术服务合同的委托人应当按照约定提供工作条件，完成配合事项；接受工作成果并支付报酬。"},{"i":361,"n":"第三百六十一条","txt":"技术服务合同的受托人应当按照约定完成服务项目，解决技术问题，保证工作质量，并传授解决技术问题的知识。"},{"i":362,"n":"第三百六十二条","txt":"技术服务合同的委托人不履行合同义务或者履行合同义务不符合约定，影响工作进度和质量，不接受或者逾期接受工作成果的，支付的报酬不得追回，未支付的报酬应当支付。"},{"i":363,"n":"第三百六十三条","txt":"在技术咨询合同、技术服务合同履行过程中，受托人利用委托人提供的技术资料和工作条件完成的新的技术成果，属于受托人。委托人利用受托人的工作成果完成的新的技术成果，属于委托人。当事人另有约定的，按照其约定。"},{"i":364,"n":"第三百六十四条","txt":"法律、行政法规对技术中介合同、技术培训合同另有规定的，依照其规定。"},{"i":365,"n":"第三百六十五条","txt":"保管合同是保管人保管寄存人交付的保管物，并返还该物的合同。"},{"i":366,"n":"第三百六十六条","txt":"寄存人应当按照约定向保管人支付保管费。"},{"i":367,"n":"第三百六十七条","txt":"保管合同自保管物交付时成立，但当事人另有约定的除外。"},{"i":368,"n":"第三百六十八条","txt":"寄存人向保管人交付保管物的，保管人应当给付保管凭证，但另有交易习惯的除外。"},{"i":369,"n":"第三百六十九条","txt":"保管人应当妥善保管保管物。"},{"i":370,"n":"第三百七十条","txt":"寄存人交付的保管物有瑕疵或者按照保管物的性质需要采取特殊保管措施的，寄存人应当将有关情况告知保管人。寄存人未告知，致使保管物受损失的，保管人不承担损害赔偿责任；保管人因此受损失的，除保管人知道或者应当知道并且未采取补救措施的以外，寄存人应当承担损害赔偿责任。"},{"i":371,"n":"第三百七十一条","txt":"保管人不得将保管物转交第三人保管，但当事人另有约定的除外。"},{"i":372,"n":"第三百七十二条","txt":"保管人不得使用或者许可第三人使用保管物，但当事人另有约定的除外。"},{"i":373,"n":"第三百七十三条","txt":"第三人对保管物主张权利的，除依法对保管物采取保全或者执行的以外，保管人应当履行向寄存人返还保管物的义务。"},{"i":374,"n":"第三百七十四条","txt":"保管期间，因保管人保管不善造成保管物毁损、灭失的，保管人应当承担损害赔偿责任，但保管是无偿的，保管人证明自己没有重大过失的，不承担损害赔偿责任。"},{"i":375,"n":"第三百七十五条","txt":"寄存人寄存货币、有价证券或者其他贵重物品的，应当向保管人声明，由保管人验收或者封存。寄存人未声明的，该物品毁损、灭失后，保管人可以按照一般物品予以赔偿。"},{"i":376,"n":"第三百七十六条","txt":"寄存人可以随时领取保管物。"},{"i":377,"n":"第三百七十七条","txt":"保管期间届满或者寄存人提前领取保管物的，保管人应当将原物及其孳息归还寄存人。"},{"i":378,"n":"第三百七十八条","txt":"保管人保管货币的，可以返还相同种类、数量的货币。保管其他可替代物的，可以按照约定返还相同种类、品质、数量的物品。"},{"i":379,"n":"第三百七十九条","txt":"有偿的保管合同，寄存人应当按照约定的期限向保管人支付保管费。"},{"i":380,"n":"第三百八十条","txt":"寄存人未按照约定支付保管费以及其他费用的，保管人对保管物享有留置权，但当事人另有约定的除外。"},{"i":381,"n":"第三百八十一条","txt":"仓储合同是保管人储存存货人交付的仓储物，存货人支付仓储费的合同。"},{"i":382,"n":"第三百八十二条","txt":"仓储合同自成立时生效。"},{"i":383,"n":"第三百八十三条","txt":"储存易燃、易爆、有毒、有腐蚀性、有放射性等危险物品或者易变质物品，存货人应当说明该物品的性质，提供有关资料。"},{"i":384,"n":"第三百八十四条","txt":"保管人应当按照约定对入库仓储物进行验收。保管人验收时发现入库仓储物与约定不符合的，应当及时通知存货人。保管人验收后，发生仓储物的品种、数量、质量不符合约定的，保管人应当承担损害赔偿责任。"},{"i":385,"n":"第三百八十五条","txt":"存货人交付仓储物的，保管人应当给付仓单。"},{"i":386,"n":"第三百八十六条","txt":"保管人应当在仓单上签字或者盖章。仓单包括下列事项："},{"i":387,"n":"第三百八十七条","txt":"仓单是提取仓储物的凭证。存货人或者仓单持有人在仓单上背书并经保管人签字或者盖章的，可以转让提取仓储物的权利。"},{"i":388,"n":"第三百八十八条","txt":"保管人根据存货人或者仓单持有人的要求，应当同意其检查仓储物或者提取样品。"},{"i":389,"n":"第三百八十九条","txt":"保管人对入库仓储物发现有变质或者其他损坏的，应当及时通知存货人或者仓单持有人。"},{"i":390,"n":"第三百九十条","txt":"保管人对入库仓储物发现有变质或者其他损坏，危及其他仓储物的安全和正常保管的，应当催告存货人或者仓单持有人作出必要的处置。因情况紧急，保管人可以作出必要的处置，但事后应当将该情况及时通知存货人或者仓单持有人。"},{"i":391,"n":"第三百九十一条","txt":"当事人对储存期间没有约定或者约定不明确的，存货人或者仓单持有人可以随时提取仓储物，保管人也可以随时要求存货人或者仓单持有人提取仓储物，但应当给予必要的准备时间。"},{"i":392,"n":"第三百九十二条","txt":"储存期间届满，存货人或者仓单持有人应当凭仓单提取仓储物。存货人或者仓单持有人逾期提取的，应当加收仓储费；提前提取的，不减收仓储费。"},{"i":393,"n":"第三百九十三条","txt":"储存期间届满，存货人或者仓单持有人不提取仓储物的，保管人可以催告其在合理期限内提取，逾期不提取的，保管人可以提存仓储物。"},{"i":394,"n":"第三百九十四条","txt":"储存期间，因保管人保管不善造成仓储物毁损、灭失的，保管人应当承担损害赔偿责任。"},{"i":395,"n":"第三百九十五条","txt":"本章没有规定的，适用保管合同的有关规定。"},{"i":396,"n":"第三百九十六条","txt":"委托合同是委托人和受托人约定，由受托人处理委托人事务的合同。"},{"i":397,"n":"第三百九十七条","txt":"委托人可以特别委托受托人处理一项或者数项事务，也可以概括委托受托人处理一切事务。"},{"i":398,"n":"第三百九十八条","txt":"委托人应当预付处理委托事务的费用。受托人为处理委托事务垫付的必要费用，委托人应当偿还该费用及其利息。"},{"i":399,"n":"第三百九十九条","txt":"受托人应当按照委托人的指示处理委托事务。需要变更委托人指示的，应当经委托人同意；因情况紧急，难以和委托人取得联系的，受托人应当妥善处理委托事务，但事后应当将该情况及时报告委托人。"},{"i":400,"n":"第四百条","txt":"受托人应当亲自处理委托事务。经委托人同意，受托人可以转委托。转委托经同意的，委托人可以就委托事务直接指示转委托的第三人，受托人仅就第三人的选任及其对第三人的指示承担责任。转委托未经同意的，受托人应当对转委托的第三人的行为承担责任，但在紧急情况下受托人为维护委托人的利益需要转委托的除外。"},{"i":401,"n":"第四百零一条","txt":"受托人应当按照委托人的要求，报告委托事务的处理情况。委托合同终止时，受托人应当报告委托事务的结果。"},{"i":402,"n":"第四百零二条","txt":"受托人以自己的名义，在委托人的授权范围内与第三人订立的合同，第三人在订立合同时知道受托人与委托人之间的代理关系的，该合同直接约束委托人和第三人，但有确切证据证明该合同只约束受托人和第三人的除外。"},{"i":403,"n":"第四百零三条","txt":"受托人以自己的名义与第三人订立合同时，第三人不知道受托人与委托人之间的代理关系的，受托人因第三人的原因对委托人不履行义务，受托人应当向委托人披露第三人，委托人因此可以行使受托人对第三人的权利，但第三人与受托人订立合同时如果知道该委托人就不会订立合同的除外。"},{"i":404,"n":"第四百零四条","txt":"受托人处理委托事务取得的财产，应当转交给委托人。"},{"i":405,"n":"第四百零五条","txt":"受托人完成委托事务的，委托人应当向其支付报酬。因不可归责于受托人的事由，委托合同解除或者委托事务不能完成的，委托人应当向受托人支付相应的报酬。当事人另有约定的，按照其约定。"},{"i":406,"n":"第四百零六条","txt":"有偿的委托合同，因受托人的过错给委托人造成损失的，委托人可以要求赔偿损失。无偿的委托合同，因受托人的故意或者重大过失给委托人造成损失的，委托人可以要求赔偿损失。"},{"i":407,"n":"第四百零七条","txt":"受托人处理委托事务时，因不可归责于自己的事由受到损失的，可以向委托人要求赔偿损失。"},{"i":408,"n":"第四百零八条","txt":"委托人经受托人同意，可以在受托人之外委托第三人处理委托事务。因此给受托人造成损失的，受托人可以向委托人要求赔偿损失。"},{"i":409,"n":"第四百零九条","txt":"两个以上的受托人共同处理委托事务的，对委托人承担连带责任。"},{"i":410,"n":"第四百一十条","txt":"委托人或者受托人可以随时解除委托合同。因解除合同给对方造成损失的，除不可归责于该当事人的事由以外，应当赔偿损失。"},{"i":411,"n":"第四百一十一条","txt":"委托人或者受托人死亡、丧失民事行为能力或者破产的，委托合同终止，但当事人另有约定或者根据委托事务的性质不宜终止的除外。"},{"i":412,"n":"第四百一十二条","txt":"因委托人死亡、丧失民事行为能力或者破产，致使委托合同终止将损害委托人利益的，在委托人的继承人、法定代理人或者清算组织承受委托事务之前，受托人应当继续处理委托事务。"},{"i":413,"n":"第四百一十三条","txt":"因受托人死亡、丧失民事行为能力或者破产，致使委托合同终止的，受托人的继承人、法定代理人或者清算组织应当及时通知委托人。因委托合同终止将损害委托人利益的，在委托人作出善后处理之前，受托人的继承人、法定代理人或者清算组织应当采取必要措施。"},{"i":414,"n":"第四百一十四条","txt":"行纪合同是行纪人以自己的名义为委托人从事贸易活动，委托人支付报酬的合同。"},{"i":415,"n":"第四百一十五条","txt":"行纪人处理委托事务支出的费用，由行纪人负担，但当事人另有约定的除外。"},{"i":416,"n":"第四百一十六条","txt":"行纪人占有委托物的，应当妥善保管委托物。"},{"i":417,"n":"第四百一十七条","txt":"委托物交付给行纪人时有瑕疵或者容易腐烂、变质的，经委托人同意，行纪人可以处分该物；和委托人不能及时取得联系的，行纪人可以合理处分。"},{"i":418,"n":"第四百一十八条","txt":"行纪人低于委托人指定的价格卖出或者高于委托人指定的价格买入的，应当经委托人同意。未经委托人同意，行纪人补偿其差额的，该买卖对委托人发生效力。"},{"i":419,"n":"第四百一十九条","txt":"行纪人卖出或者买入具有市场定价的商品，除委托人有相反的意思表示的以外，行纪人自己可以作为买受人或者出卖人。"},{"i":420,"n":"第四百二十条","txt":"行纪人按照约定买入委托物，委托人应当及时受领。经行纪人催告，委托人无正当理由拒绝受领的，行纪人依照本法第一百零一条的规定可以提存委托物。"},{"i":421,"n":"第四百二十一条","txt":"行纪人与第三人订立合同的，行纪人对该合同直接享有权利、承担义务。"},{"i":422,"n":"第四百二十二条","txt":"行纪人完成或者部分完成委托事务的，委托人应当向其支付相应的报酬。委托人逾期不支付报酬的，行纪人对委托物享有留置权，但当事人另有约定的除外。"},{"i":423,"n":"第四百二十三条","txt":"本章没有规定的，适用委托合同的有关规定。"},{"i":424,"n":"第四百二十四条","txt":"居间合同是居间人向委托人报告订立合同的机会或者提供订立合同的媒介服务，委托人支付报酬的合同。"},{"i":425,"n":"第四百二十五条","txt":"居间人应当就有关订立合同的事项向委托人如实报告。"},{"i":426,"n":"第四百二十六条","txt":"居间人促成合同成立的，委托人应当按照约定支付报酬。对居间人的报酬没有约定或者约定不明确，依照本法第六十一条的规定仍不能确定的，根据居间人的劳务合理确定。因居间人提供订立合同的媒介服务而促成合同成立的，由该合同的当事人平均负担居间人的报酬。"},{"i":427,"n":"第四百二十七条","txt":"居间人未促成合同成立的，不得要求支付报酬，但可以要求委托人支付从事居间活动支出的必要费用。"},{"i":428,"n":"第四百二十八条","txt":"本法自1999年10月1日起施行，《中华人民共和国经济合同法》、《中华人民共和国涉外经济合同法》、《中华人民共和国技术合同法》同时废止。"}],"huanjingbaohufa":[{"i":1,"n":"第一条","txt":"为保护和改善环境，防治污染和其他公害，保障公众健康，推进生态文明建设，促进经济社会可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称环境，是指影响人类生存和发展的各种天然的和经过人工改造的自然因素的总体，包括大气、水、海洋、土地、矿藏、森林、草原、湿地、野生生物、自然遗迹、人文遗迹、自然保护区、风景名胜区、城市和乡村等。"},{"i":3,"n":"第三条","txt":"本法适用于中华人民共和国领域和中华人民共和国管辖的其他海域。"},{"i":4,"n":"第四条","txt":"保护环境是国家的基本国策。"},{"i":5,"n":"第五条","txt":"环境保护坚持保护优先、预防为主、综合治理、公众参与、损害担责的原则。"},{"i":6,"n":"第六条","txt":"一切单位和个人都有保护环境的义务。"},{"i":7,"n":"第七条","txt":"国家支持环境保护科学技术研究、开发和应用，鼓励环境保护产业发展，促进环境保护信息化建设，提高环境保护科学技术水平。"},{"i":8,"n":"第八条","txt":"各级人民政府应当加大保护和改善环境、防治污染和其他公害的财政投入，提高财政资金的使用效益。"},{"i":9,"n":"第九条","txt":"各级人民政府应当加强环境保护宣传和普及工作，鼓励基层群众性自治组织、社会组织、环境保护志愿者开展环境保护法律法规和环境保护知识的宣传，营造保护环境的良好风气。"},{"i":10,"n":"第十条","txt":"国务院环境保护主管部门，对全国环境保护工作实施统一监督管理；县级以上地方人民政府环境保护主管部门，对本行政区域环境保护工作实施统一监督管理。"},{"i":11,"n":"第十一条","txt":"对保护和改善环境有显著成绩的单位和个人，由人民政府给予奖励。"},{"i":12,"n":"第十二条","txt":"每年6月5日为环境日。"},{"i":13,"n":"第十三条","txt":"县级以上人民政府应当将环境保护工作纳入国民经济和社会发展规划。"},{"i":14,"n":"第十四条","txt":"国务院有关部门和省、自治区、直辖市人民政府组织制定经济、技术政策，应当充分考虑对环境的影响，听取有关方面和专家的意见。"},{"i":15,"n":"第十五条","txt":"国务院环境保护主管部门制定国家环境质量标准。"},{"i":16,"n":"第十六条","txt":"国务院环境保护主管部门根据国家环境质量标准和国家经济、技术条件，制定国家污染物排放标准。"},{"i":17,"n":"第十七条","txt":"国家建立、健全环境监测制度。国务院环境保护主管部门制定监测规范，会同有关部门组织监测网络，统一规划国家环境质量监测站（点）的设置，建立监测数据共享机制，加强对环境监测的管理。"},{"i":18,"n":"第十八条","txt":"省级以上人民政府应当组织有关部门或者委托专业机构，对环境状况进行调查、评价，建立环境资源承载能力监测预警机制。"},{"i":19,"n":"第十九条","txt":"编制有关开发利用规划，建设对环境有影响的项目，应当依法进行环境影响评价。"},{"i":20,"n":"第二十条","txt":"国家建立跨行政区域的重点区域、流域环境污染和生态破坏联合防治协调机制，实行统一规划、统一标准、统一监测、统一的防治措施。"},{"i":21,"n":"第二十一条","txt":"国家采取财政、税收、价格、政府采购等方面的政策和措施，鼓励和支持环境保护技术装备、资源综合利用和环境服务等环境保护产业的发展。"},{"i":22,"n":"第二十二条","txt":"企业事业单位和其他生产经营者，在污染物排放符合法定要求的基础上，进一步减少污染物排放的，人民政府应当依法采取财政、税收、价格、政府采购等方面的政策和措施予以鼓励和支持。"},{"i":23,"n":"第二十三条","txt":"企业事业单位和其他生产经营者，为改善环境，依照有关规定转产、搬迁、关闭的，人民政府应当予以支持。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府环境保护主管部门及其委托的环境监察机构和其他负有环境保护监督管理职责的部门，有权对排放污染物的企业事业单位和其他生产经营者进行现场检查。被检查者应当如实反映情况，提供必要的资料。实施现场检查的部门、机构及其工作人员应当为被检查者保守商业秘密。"},{"i":25,"n":"第二十五条","txt":"企业事业单位和其他生产经营者违反法律法规规定排放污染物，造成或者可能造成严重污染的，县级以上人民政府环境保护主管部门和其他负有环境保护监督管理职责的部门，可以查封、扣押造成污染物排放的设施、设备。"},{"i":26,"n":"第二十六条","txt":"国家实行环境保护目标责任制和考核评价制度。县级以上人民政府应当将环境保护目标完成情况纳入对本级人民政府负有环境保护监督管理职责的部门及其负责人和下级人民政府及其负责人的考核内容，作为对其考核评价的重要依据。考核结果应当向社会公开。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府应当每年向本级人民代表大会或者人民代表大会常务委员会报告环境状况和环境保护目标完成情况，对发生的重大环境事件应当及时向本级人民代表大会常务委员会报告，依法接受监督。"},{"i":28,"n":"第二十八条","txt":"地方各级人民政府应当根据环境保护目标和治理任务，采取有效措施，改善环境质量。"},{"i":29,"n":"第二十九条","txt":"国家在重点生态功能区、生态环境敏感区和脆弱区等区域划定生态保护红线，实行严格保护。"},{"i":30,"n":"第三十条","txt":"开发利用自然资源，应当合理开发，保护生物多样性，保障生态安全，依法制定有关生态保护和恢复治理方案并予以实施。"},{"i":31,"n":"第三十一条","txt":"国家建立、健全生态保护补偿制度。"},{"i":32,"n":"第三十二条","txt":"国家加强对大气、水、土壤等的保护，建立和完善相应的调查、监测、评估和修复制度。"},{"i":33,"n":"第三十三条","txt":"各级人民政府应当加强对农业环境的保护，促进农业环境保护新技术的使用，加强对农业污染源的监测预警，统筹有关部门采取措施，防治土壤污染和土地沙化、盐渍化、贫瘠化、石漠化、地面沉降以及防治植被破坏、水土流失、水体富营养化、水源枯竭、种源灭绝等生态失调现象，推广植物病虫害的综合防治。"},{"i":34,"n":"第三十四条","txt":"国务院和沿海地方各级人民政府应当加强对海洋环境的保护。向海洋排放污染物、倾倒废弃物，进行海岸工程和海洋工程建设，应当符合法律法规规定和有关标准，防止和减少对海洋环境的污染损害。"},{"i":35,"n":"第三十五条","txt":"城乡建设应当结合当地自然环境的特点，保护植被、水域和自然景观，加强城市园林、绿地和风景名胜区的建设与管理。"},{"i":36,"n":"第三十六条","txt":"国家鼓励和引导公民、法人和其他组织使用有利于保护环境的产品和再生产品，减少废弃物的产生。"},{"i":37,"n":"第三十七条","txt":"地方各级人民政府应当采取措施，组织对生活废弃物的分类处置、回收利用。"},{"i":38,"n":"第三十八条","txt":"公民应当遵守环境保护法律法规，配合实施环境保护措施，按照规定对生活废弃物进行分类放置，减少日常生活对环境造成的损害。"},{"i":39,"n":"第三十九条","txt":"国家建立、健全环境与健康监测、调查和风险评估制度；鼓励和组织开展环境质量对公众健康影响的研究，采取措施预防和控制与环境污染有关的疾病。"},{"i":40,"n":"第四十条","txt":"国家促进清洁生产和资源循环利用。"},{"i":41,"n":"第四十一条","txt":"建设项目中防治污染的设施，应当与主体工程同时设计、同时施工、同时投产使用。防治污染的设施应当符合经批准的环境影响评价文件的要求，不得擅自拆除或者闲置。"},{"i":42,"n":"第四十二条","txt":"排放污染物的企业事业单位和其他生产经营者，应当采取措施，防治在生产建设或者其他活动中产生的废气、废水、废渣、医疗废物、粉尘、恶臭气体、放射性物质以及噪声、振动、光辐射、电磁辐射等对环境的污染和危害。"},{"i":43,"n":"第四十三条","txt":"排放污染物的企业事业单位和其他生产经营者，应当按照国家有关规定缴纳排污费。排污费应当全部专项用于环境污染防治，任何单位和个人不得截留、挤占或者挪作他用。"},{"i":44,"n":"第四十四条","txt":"国家实行重点污染物排放总量控制制度。重点污染物排放总量控制指标由国务院下达，省、自治区、直辖市人民政府分解落实。企业事业单位在执行国家和地方污染物排放标准的同时，应当遵守分解落实到本单位的重点污染物排放总量控制指标。"},{"i":45,"n":"第四十五条","txt":"国家依照法律规定实行排污许可管理制度。"},{"i":46,"n":"第四十六条","txt":"国家对严重污染环境的工艺、设备和产品实行淘汰制度。任何单位和个人不得生产、销售或者转移、使用严重污染环境的工艺、设备和产品。"},{"i":47,"n":"第四十七条","txt":"各级人民政府及其有关部门和企业事业单位，应当依照《中华人民共和国突发事件应对法》的规定，做好突发环境事件的风险控制、应急准备、应急处置和事后恢复等工作。"},{"i":48,"n":"第四十八条","txt":"生产、储存、运输、销售、使用、处置化学物品和含有放射性物质的物品，应当遵守国家有关规定，防止污染环境。"},{"i":49,"n":"第四十九条","txt":"各级人民政府及其农业等有关部门和机构应当指导农业生产经营者科学种植和养殖，科学合理施用农药、化肥等农业投入品，科学处置农用薄膜、农作物秸秆等农业废弃物，防止农业面源污染。"},{"i":50,"n":"第五十条","txt":"各级人民政府应当在财政预算中安排资金，支持农村饮用水水源地保护、生活污水和其他废弃物处理、畜禽养殖和屠宰污染防治、土壤污染防治和农村工矿污染治理等环境保护工作。"},{"i":51,"n":"第五十一条","txt":"各级人民政府应当统筹城乡建设污水处理设施及配套管网，固体废物的收集、运输和处置等环境卫生设施，危险废物集中处置设施、场所以及其他环境保护公共设施，并保障其正常运行。"},{"i":52,"n":"第五十二条","txt":"国家鼓励投保环境污染责任保险。"},{"i":53,"n":"第五十三条","txt":"公民、法人和其他组织依法享有获取环境信息、参与和监督环境保护的权利。"},{"i":54,"n":"第五十四条","txt":"国务院环境保护主管部门统一发布国家环境质量、重点污染源监测信息及其他重大环境信息。省级以上人民政府环境保护主管部门定期发布环境状况公报。"},{"i":55,"n":"第五十五条","txt":"重点排污单位应当如实向社会公开其主要污染物的名称、排放方式、排放浓度和总量、超标排放情况，以及防治污染设施的建设和运行情况，接受社会监督。"},{"i":56,"n":"第五十六条","txt":"对依法应当编制环境影响报告书的建设项目，建设单位应当在编制时向可能受影响的公众说明情况，充分征求意见。"},{"i":57,"n":"第五十七条","txt":"公民、法人和其他组织发现任何单位和个人有污染环境和破坏生态行为的，有权向环境保护主管部门或者其他负有环境保护监督管理职责的部门举报。"},{"i":58,"n":"第五十八条","txt":"对污染环境、破坏生态，损害社会公共利益的行为，符合下列条件的社会组织可以向人民法院提起诉讼："},{"i":59,"n":"第五十九条","txt":"企业事业单位和其他生产经营者违法排放污染物，受到罚款处罚，被责令改正，拒不改正的，依法作出处罚决定的行政机关可以自责令改正之日的次日起，按照原处罚数额按日连续处罚。"},{"i":60,"n":"第六十条","txt":"企业事业单位和其他生产经营者超过污染物排放标准或者超过重点污染物排放总量控制指标排放污染物的，县级以上人民政府环境保护主管部门可以责令其采取限制生产、停产整治等措施；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":61,"n":"第六十一条","txt":"建设单位未依法提交建设项目环境影响评价文件或者环境影响评价文件未经批准，擅自开工建设的，由负有环境保护监督管理职责的部门责令停止建设，处以罚款，并可以责令恢复原状。"},{"i":62,"n":"第六十二条","txt":"违反本法规定，重点排污单位不公开或者不如实公开环境信息的，由县级以上地方人民政府环境保护主管部门责令公开，处以罚款，并予以公告。"},{"i":63,"n":"第六十三条","txt":"企业事业单位和其他生产经营者有下列行为之一，尚不构成犯罪的，除依照有关法律法规规定予以处罚外，由县级以上人民政府环境保护主管部门或者其他有关部门将案件移送公安机关，对其直接负责的主管人员和其他直接责任人员，处十日以上十五日以下拘留；情节较轻的，处五日以上十日以下拘留："},{"i":64,"n":"第六十四条","txt":"因污染环境和破坏生态造成损害的，应当依照《中华人民共和国侵权责任法》的有关规定承担侵权责任。"},{"i":65,"n":"第六十五条","txt":"环境影响评价机构、环境监测机构以及从事环境监测设备和防治污染设施维护、运营的机构，在有关环境服务活动中弄虚作假，对造成的环境污染和生态破坏负有责任的，除依照有关法律法规规定予以处罚外，还应当与造成环境污染和生态破坏的其他责任者承担连带责任。"},{"i":66,"n":"第六十六条","txt":"提起环境损害赔偿诉讼的时效期间为三年，从当事人知道或者应当知道其受到损害时起计算。"},{"i":67,"n":"第六十七条","txt":"上级人民政府及其环境保护主管部门应当加强对下级人民政府及其有关部门环境保护工作的监督。发现有关工作人员有违法行为，依法应当给予处分的，应当向其任免机关或者监察机关提出处分建议。"},{"i":68,"n":"第六十八条","txt":"地方各级人民政府、县级以上人民政府环境保护主管部门和其他负有环境保护监督管理职责的部门有下列行为之一的，对直接负责的主管人员和其他直接责任人员给予记过、记大过或者降级处分；造成严重后果的，给予撤职或者开除处分，其主要负责人应当引咎辞职："},{"i":69,"n":"第六十九条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":70,"n":"第七十条","txt":"本法自2015年1月1日起施行。"}],"huanjingyingxiangpingjiafa-2":[{"i":1,"n":"第一条","txt":"为了实施可持续发展战略，预防因规划和建设项目实施后对环境造成不良影响，促进经济、社会和环境的协调发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称环境影响评价，是指对规划和建设项目实施后可能造成的环境影响进行分析、预测和评估，提出预防或者减轻不良环境影响的对策和措施，进行跟踪监测的方法与制度。"},{"i":3,"n":"第三条","txt":"编制本法第九条所规定的范围内的规划，在中华人民共和国领域和中华人民共和国管辖的其他海域内建设对环境有影响的项目，应当依照本法进行环境影响评价。"},{"i":4,"n":"第四条","txt":"环境影响评价必须客观、公开、公正，综合考虑规划或者建设项目实施后对各种环境因素及其所构成的生态系统可能造成的影响，为决策提供科学依据。"},{"i":5,"n":"第五条","txt":"国家鼓励有关单位、专家和公众以适当方式参与环境影响评价。"},{"i":6,"n":"第六条","txt":"国家加强环境影响评价的基础数据库和评价指标体系建设，鼓励和支持对环境影响评价的方法、技术规范进行科学研究，建立必要的环境影响评价信息共享制度，提高环境影响评价的科学性。"},{"i":7,"n":"第七条","txt":"国务院有关部门、设区的市级以上地方人民政府及其有关部门，对其组织编制的土地利用的有关规划，区域、流域、海域的建设、开发利用规划，应当在规划编制过程中组织进行环境影响评价，编写该规划有关环境影响的篇章或者说明。"},{"i":8,"n":"第八条","txt":"国务院有关部门、设区的市级以上地方人民政府及其有关部门，对其组织编制的工业、农业、畜牧业、林业、能源、水利、交通、城市建设、旅游、自然资源开发的有关专项规划（以下简称专项规划），应当在该专项规划草案上报审批前，组织进行环境影响评价，并向审批该专项规划的机关提出环境影响报告书。"},{"i":9,"n":"第九条","txt":"依照本法第七条、第八条的规定进行环境影响评价的规划的具体范围，由国务院生态环境主管部门会同国务院有关部门规定，报国务院批准。"},{"i":10,"n":"第十条","txt":"专项规划的环境影响报告书应当包括下列内容："},{"i":11,"n":"第十一条","txt":"专项规划的编制机关对可能造成不良环境影响并直接涉及公众环境权益的规划，应当在该规划草案报送审批前，举行论证会、听证会，或者采取其他形式，征求有关单位、专家和公众对环境影响报告书草案的意见。但是，国家规定需要保密的情形除外。"},{"i":12,"n":"第十二条","txt":"专项规划的编制机关在报批规划草案时，应当将环境影响报告书一并附送审批机关审查；未附送环境影响报告书的，审批机关不予审批。"},{"i":13,"n":"第十三条","txt":"设区的市级以上人民政府在审批专项规划草案，作出决策前，应当先由人民政府指定的生态环境主管部门或者其他部门召集有关部门代表和专家组成审查小组，对环境影响报告书进行审查。审查小组应当提出书面审查意见。"},{"i":14,"n":"第十四条","txt":"审查小组提出修改意见的，专项规划的编制机关应当根据环境影响报告书结论和审查意见对规划草案进行修改完善，并对环境影响报告书结论和审查意见的采纳情况作出说明；不采纳的，应当说明理由。"},{"i":15,"n":"第十五条","txt":"对环境有重大影响的规划实施后，编制机关应当及时组织环境影响的跟踪评价，并将评价结果报告审批机关；发现有明显不良环境影响的，应当及时提出改进措施。"},{"i":16,"n":"第十六条","txt":"国家根据建设项目对环境的影响程度，对建设项目的环境影响评价实行分类管理。"},{"i":17,"n":"第十七条","txt":"建设项目的环境影响报告书应当包括下列内容："},{"i":18,"n":"第十八条","txt":"建设项目的环境影响评价，应当避免与规划的环境影响评价相重复。"},{"i":19,"n":"第十九条","txt":"建设单位可以委托技术单位对其建设项目开展环境影响评价，编制建设项目环境影响报告书、环境影响报告表；建设单位具备环境影响评价技术能力的，可以自行对其建设项目开展环境影响评价，编制建设项目环境影响报告书、环境影响报告表。"},{"i":20,"n":"第二十条","txt":"建设单位应当对建设项目环境影响报告书、环境影响报告表的内容和结论负责，接受委托编制建设项目环境影响报告书、环境影响报告表的技术单位对其编制的建设项目环境影响报告书、环境影响报告表承担相应责任。"},{"i":21,"n":"第二十一条","txt":"除国家规定需要保密的情形外，对环境可能造成重大影响、应当编制环境影响报告书的建设项目，建设单位应当在报批建设项目环境影响报告书前，举行论证会、听证会，或者采取其他形式，征求有关单位、专家和公众的意见。"},{"i":22,"n":"第二十二条","txt":"建设项目的环境影响报告书、报告表，由建设单位按照国务院的规定报有审批权的生态环境主管部门审批。"},{"i":23,"n":"第二十三条","txt":"国务院生态环境主管部门负责审批下列建设项目的环境影响评价文件："},{"i":24,"n":"第二十四条","txt":"建设项目的环境影响评价文件经批准后，建设项目的性质、规模、地点、采用的生产工艺或者防治污染、防止生态破坏的措施发生重大变动的，建设单位应当重新报批建设项目的环境影响评价文件。"},{"i":25,"n":"第二十五条","txt":"建设项目的环境影响评价文件未依法经审批部门审查或者审查后未予批准的，建设单位不得开工建设。"},{"i":26,"n":"第二十六条","txt":"建设项目建设过程中，建设单位应当同时实施环境影响报告书、环境影响报告表以及环境影响评价文件审批部门审批意见中提出的环境保护对策措施。"},{"i":27,"n":"第二十七条","txt":"在项目建设、运行过程中产生不符合经审批的环境影响评价文件的情形的，建设单位应当组织环境影响的后评价，采取改进措施，并报原环境影响评价文件审批部门和建设项目审批部门备案；原环境影响评价文件审批部门也可以责成建设单位进行环境影响的后评价，采取改进措施。"},{"i":28,"n":"第二十八条","txt":"生态环境主管部门应当对建设项目投入生产或者使用后所产生的环境影响进行跟踪检查，对造成严重环境污染或者生态破坏的，应当查清原因、查明责任。对属于建设项目环境影响报告书、环境影响报告表存在基础资料明显不实，内容存在重大缺陷、遗漏或者虚假，环境影响评价结论不正确或者不合理等严重质量问题的，依照本法第三十二条的规定追究建设单位及其相关责任人员和接受委托编制建设项目环境影响报告书、环境影响报告表的技术单位及其相关人员的法律责任；属于审批部门工作人员失职、渎职，对依法不应批准的建设项目环境影响报告书、环境影响报告表予以批准的，依照本法第三十四条的规定追究其法律责任。"},{"i":29,"n":"第二十九条","txt":"规划编制机关违反本法规定，未组织环境影响评价，或者组织环境影响评价时弄虚作假或者有失职行为，造成环境影响评价严重失实的，对直接负责的主管人员和其他直接责任人员，由上级机关或者监察机关依法给予行政处分。"},{"i":30,"n":"第三十条","txt":"规划审批机关对依法应当编写有关环境影响的篇章或者说明而未编写的规划草案，依法应当附送环境影响报告书而未附送的专项规划草案，违法予以批准的，对直接负责的主管人员和其他直接责任人员，由上级机关或者监察机关依法给予行政处分。"},{"i":31,"n":"第三十一条","txt":"建设单位未依法报批建设项目环境影响报告书、报告表，或者未依照本法第二十四条的规定重新报批或者报请重新审核环境影响报告书、报告表，擅自开工建设的，由县级以上生态环境主管部门责令停止建设，根据违法情节和危害后果，处建设项目总投资额百分之一以上百分之五以下的罚款，并可以责令恢复原状；对建设单位直接负责的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":32,"n":"第三十二条","txt":"建设项目环境影响报告书、环境影响报告表存在基础资料明显不实，内容存在重大缺陷、遗漏或者虚假，环境影响评价结论不正确或者不合理等严重质量问题的，由设区的市级以上人民政府生态环境主管部门对建设单位处五十万元以上二百万元以下的罚款，并对建设单位的法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员，处五万元以上二十万元以下的罚款。"},{"i":33,"n":"第三十三条","txt":"负责审核、审批、备案建设项目环境影响评价文件的部门在审批、备案中收取费用的，由其上级机关或者监察机关责令退还；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":34,"n":"第三十四条","txt":"生态环境主管部门或者其他部门的工作人员徇私舞弊，滥用职权，玩忽职守，违法批准建设项目环境影响评价文件的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"省、自治区、直辖市人民政府可以根据本地的实际情况，要求对本辖区的县级人民政府编制的规划进行环境影响评价。具体办法由省、自治区、直辖市参照本法第二章的规定制定。"},{"i":36,"n":"第三十六条","txt":"军事设施建设项目的环境影响评价办法，由中央军事委员会依照本法的原则制定。"},{"i":37,"n":"第三十七条","txt":"本法自2003年9月1日起施行。"}],"huanjingyingxiangpingjiafa":[{"i":1,"n":"第一条","txt":"为了实施可持续发展战略，预防因规划和建设项目实施后对环境造成不良影响，促进经济、社会和环境的协调发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称环境影响评价，是指对规划和建设项目实施后可能造成的环境影响进行分析、预测和评估，提出预防或者减轻不良环境影响的对策和措施，进行跟踪监测的方法与制度。"},{"i":3,"n":"第三条","txt":"编制本法第九条所规定的范围内的规划，在中华人民共和国领域和中华人民共和国管辖的其他海域内建设对环境有影响的项目，应当依照本法进行环境影响评价。"},{"i":4,"n":"第四条","txt":"环境影响评价必须客观、公开、公正，综合考虑规划或者建设项目实施后对各种环境因素及其所构成的生态系统可能造成的影响，为决策提供科学依据。"},{"i":5,"n":"第五条","txt":"国家鼓励有关单位、专家和公众以适当方式参与环境影响评价。"},{"i":6,"n":"第六条","txt":"国家加强环境影响评价的基础数据库和评价指标体系建设，鼓励和支持对环境影响评价的方法、技术规范进行科学研究，建立必要的环境影响评价信息共享制度，提高环境影响评价的科学性。"},{"i":7,"n":"第七条","txt":"国务院有关部门、设区的市级以上地方人民政府及其有关部门，对其组织编制的土地利用的有关规划，区域、流域、海域的建设、开发利用规划，应当在规划编制过程中组织进行环境影响评价，编写该规划有关环境影响的篇章或者说明。"},{"i":8,"n":"第八条","txt":"国务院有关部门、设区的市级以上地方人民政府及其有关部门，对其组织编制的工业、农业、畜牧业、林业、能源、水利、交通、城市建设、旅游、自然资源开发的有关专项规划（以下简称专项规划），应当在该专项规划草案上报审批前，组织进行环境影响评价，并向审批该专项规划的机关提出环境影响报告书。"},{"i":9,"n":"第九条","txt":"依照本法第七条、第八条的规定进行环境影响评价的规划的具体范围，由国务院环境保护行政主管部门会同国务院有关部门规定，报国务院批准。"},{"i":10,"n":"第十条","txt":"专项规划的环境影响报告书应当包括下列内容："},{"i":11,"n":"第十一条","txt":"专项规划的编制机关对可能造成不良环境影响并直接涉及公众环境权益的规划，应当在该规划草案报送审批前，举行论证会、听证会，或者采取其他形式，征求有关单位、专家和公众对环境影响报告书草案的意见。但是，国家规定需要保密的情形除外。"},{"i":12,"n":"第十二条","txt":"专项规划的编制机关在报批规划草案时，应当将环境影响报告书一并附送审批机关审查；未附送环境影响报告书的，审批机关不予审批。"},{"i":13,"n":"第十三条","txt":"设区的市级以上人民政府在审批专项规划草案，作出决策前，应当先由人民政府指定的环境保护行政主管部门或者其他部门召集有关部门代表和专家组成审查小组，对环境影响报告书进行审查。审查小组应当提出书面审查意见。"},{"i":14,"n":"第十四条","txt":"审查小组提出修改意见的，专项规划的编制机关应当根据环境影响报告书结论和审查意见对规划草案进行修改完善，并对环境影响报告书结论和审查意见的采纳情况作出说明；不采纳的，应当说明理由。"},{"i":15,"n":"第十五条","txt":"对环境有重大影响的规划实施后，编制机关应当及时组织环境影响的跟踪评价，并将评价结果报告审批机关；发现有明显不良环境影响的，应当及时提出改进措施。"},{"i":16,"n":"第十六条","txt":"国家根据建设项目对环境的影响程度，对建设项目的环境影响评价实行分类管理。"},{"i":17,"n":"第十七条","txt":"建设项目的环境影响报告书应当包括下列内容："},{"i":18,"n":"第十八条","txt":"建设项目的环境影响评价，应当避免与规划的环境影响评价相重复。"},{"i":19,"n":"第十九条","txt":"接受委托为建设项目环境影响评价提供技术服务的机构，应当经国务院环境保护行政主管部门考核审查合格后，颁发资质证书，按照资质证书规定的等级和评价范围，从事环境影响评价服务，并对评价结论负责。为建设项目环境影响评价提供技术服务的机构的资质条件和管理办法，由国务院环境保护行政主管部门制定。"},{"i":20,"n":"第二十条","txt":"环境影响评价文件中的环境影响报告书或者环境影响报告表，应当由具有相应环境影响评价资质的机构编制。"},{"i":21,"n":"第二十一条","txt":"除国家规定需要保密的情形外，对环境可能造成重大影响、应当编制环境影响报告书的建设项目，建设单位应当在报批建设项目环境影响报告书前，举行论证会、听证会，或者采取其他形式，征求有关单位、专家和公众的意见。"},{"i":22,"n":"第二十二条","txt":"建设项目的环境影响报告书、报告表，由建设单位按照国务院的规定报有审批权的环境保护行政主管部门审批。"},{"i":23,"n":"第二十三条","txt":"国务院环境保护行政主管部门负责审批下列建设项目的环境影响评价文件："},{"i":24,"n":"第二十四条","txt":"建设项目的环境影响评价文件经批准后，建设项目的性质、规模、地点、采用的生产工艺或者防治污染、防止生态破坏的措施发生重大变动的，建设单位应当重新报批建设项目的环境影响评价文件。"},{"i":25,"n":"第二十五条","txt":"建设项目的环境影响评价文件未依法经审批部门审查或者审查后未予批准的，建设单位不得开工建设。"},{"i":26,"n":"第二十六条","txt":"建设项目建设过程中，建设单位应当同时实施环境影响报告书、环境影响报告表以及环境影响评价文件审批部门审批意见中提出的环境保护对策措施。"},{"i":27,"n":"第二十七条","txt":"在项目建设、运行过程中产生不符合经审批的环境影响评价文件的情形的，建设单位应当组织环境影响的后评价，采取改进措施，并报原环境影响评价文件审批部门和建设项目审批部门备案；原环境影响评价文件审批部门也可以责成建设单位进行环境影响的后评价，采取改进措施。"},{"i":28,"n":"第二十八条","txt":"环境保护行政主管部门应当对建设项目投入生产或者使用后所产生的环境影响进行跟踪检查，对造成严重环境污染或者生态破坏的，应当查清原因、查明责任。对属于为建设项目环境影响评价提供技术服务的机构编制不实的环境影响评价文件的，依照本法第三十二条的规定追究其法律责任；属于审批部门工作人员失职、渎职，对依法不应批准的建设项目环境影响评价文件予以批准的，依照本法第三十四条的规定追究其法律责任。"},{"i":29,"n":"第二十九条","txt":"规划编制机关违反本法规定，未组织环境影响评价，或者组织环境影响评价时弄虚作假或者有失职行为，造成环境影响评价严重失实的，对直接负责的主管人员和其他直接责任人员，由上级机关或者监察机关依法给予行政处分。"},{"i":30,"n":"第三十条","txt":"规划审批机关对依法应当编写有关环境影响的篇章或者说明而未编写的规划草案，依法应当附送环境影响报告书而未附送的专项规划草案，违法予以批准的，对直接负责的主管人员和其他直接责任人员，由上级机关或者监察机关依法给予行政处分。"},{"i":31,"n":"第三十一条","txt":"建设单位未依法报批建设项目环境影响报告书、报告表，或者未依照本法第二十四条的规定重新报批或者报请重新审核环境影响报告书、报告表，擅自开工建设的，由县级以上环境保护行政主管部门责令停止建设，根据违法情节和危害后果，处建设项目总投资额百分之一以上百分之五以下的罚款，并可以责令恢复原状；对建设单位直接负责的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":32,"n":"第三十二条","txt":"接受委托为建设项目环境影响评价提供技术服务的机构在环境影响评价工作中不负责任或者弄虚作假，致使环境影响评价文件失实的，由授予环境影响评价资质的环境保护行政主管部门降低其资质等级或者吊销其资质证书，并处所收费用一倍以上三倍以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"负责审核、审批、备案建设项目环境影响评价文件的部门在审批、备案中收取费用的，由其上级机关或者监察机关责令退还；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":34,"n":"第三十四条","txt":"环境保护行政主管部门或者其他部门的工作人员徇私舞弊，滥用职权，玩忽职守，违法批准建设项目环境影响评价文件的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"省、自治区、直辖市人民政府可以根据本地的实际情况，要求对本辖区的县级人民政府编制的规划进行环境影响评价。具体办法由省、自治区、直辖市参照本法第二章的规定制定。"},{"i":36,"n":"第三十六条","txt":"军事设施建设项目的环境影响评价办法，由中央军事委员会依照本法的原则制定。"},{"i":37,"n":"第三十七条","txt":"本法自2003年9月1日起施行。"}],"huanjingzaoshengwuranfangzhifa-2":[{"i":1,"n":"第一条","txt":"为防治环境噪声污染，保护和改善生活环境，保障人体健康，促进经济和社会发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称环境噪声，是指在工业生产、建筑施工、交通运输和社会生活中所产生的干扰周围生活环境的声音。"},{"i":3,"n":"第三条","txt":"本法适用于中华人民共和国领域内环境噪声污染的防治。"},{"i":4,"n":"第四条","txt":"国务院和地方各级人民政府应当将环境噪声污染防治工作纳入环境保护规划，并采取有利于声环境保护的经济、技术政策和措施。"},{"i":5,"n":"第五条","txt":"地方各级人民政府在制定城乡建设规划时，应当充分考虑建设项目和区域开发、改造所产生的噪声对周围生活环境的影响，统筹规划，合理安排功能区和建设布局，防止或者减轻环境噪声污染。"},{"i":6,"n":"第六条","txt":"国务院生态环境主管部门对全国环境噪声污染防治实施统一监督管理。"},{"i":7,"n":"第七条","txt":"任何单位和个人都有保护声环境的义务，并有权对造成环境噪声污染的单位和个人进行检举和控告。"},{"i":8,"n":"第八条","txt":"国家鼓励、支持环境噪声污染防治的科学研究、技术开发，推广先进的防治技术和普及防治环境噪声污染的科学知识。"},{"i":9,"n":"第九条","txt":"对在环境噪声污染防治方面成绩显著的单位和个人，由人民政府给予奖励。"},{"i":10,"n":"第十条","txt":"国务院生态环境主管部门分别不同的功能区制定国家声环境质量标准。"},{"i":11,"n":"第十一条","txt":"国务院生态环境主管部门根据国家声环境质量标准和国家经济、技术条件，制定国家环境噪声排放标准。"},{"i":12,"n":"第十二条","txt":"城市规划部门在确定建设布局时，应当依据国家声环境质量标准和民用建筑隔声设计规范，合理划定建筑物与交通干线的防噪声距离，并提出相应的规划设计要求。"},{"i":13,"n":"第十三条","txt":"新建、改建、扩建的建设项目，必须遵守国家有关建设项目环境保护管理的规定。"},{"i":14,"n":"第十四条","txt":"建设项目的环境噪声污染防治设施必须与主体工程同时设计、同时施工、同时投产使用。"},{"i":15,"n":"第十五条","txt":"产生环境噪声污染的企业事业单位，必须保持防治环境噪声污染的设施的正常使用；拆除或者闲置环境噪声污染防治设施的，必须事先报经所在地的县级以上地方人民政府生态环境主管部门批准。"},{"i":16,"n":"第十六条","txt":"产生环境噪声污染的单位，应当采取措施进行治理，并按照国家规定缴纳超标准排污费。"},{"i":17,"n":"第十七条","txt":"对于在噪声敏感建筑物集中区域内造成严重环境噪声污染的企业事业单位，限期治理。"},{"i":18,"n":"第十八条","txt":"国家对环境噪声污染严重的落后设备实行淘汰制度。"},{"i":19,"n":"第十九条","txt":"在城市范围内从事生产活动确需排放偶发性强烈噪声的，必须事先向当地公安机关提出申请，经批准后方可进行。当地公安机关应当向社会公告。"},{"i":20,"n":"第二十条","txt":"国务院生态环境主管部门应当建立环境噪声监测制度，制定监测规范，并会同有关部门组织监测网络。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府生态环境主管部门和其他环境噪声污染防治工作的监督管理部门、机构，有权依据各自的职责对管辖范围内排放环境噪声的单位进行现场检查。被检查的单位必须如实反映情况，并提供必要的资料。检查部门、机构应当为被检查的单位保守技术秘密和业务秘密。"},{"i":22,"n":"第二十二条","txt":"本法所称工业噪声，是指在工业生产活动中使用固定的设备时产生的干扰周围生活环境的声音。"},{"i":23,"n":"第二十三条","txt":"在城市范围内向周围生活环境排放工业噪声的，应当符合国家规定的工业企业厂界环境噪声排放标准。"},{"i":24,"n":"第二十四条","txt":"在工业生产中因使用固定的设备造成环境噪声污染的工业企业，必须按照国务院生态环境主管部门的规定，向所在地的县级以上地方人民政府生态环境主管部门申报拥有的造成环境噪声污染的设备的种类、数量以及在正常作业条件下所发出的噪声值和防治环境噪声污染的设施情况，并提供防治噪声污染的技术资料。"},{"i":25,"n":"第二十五条","txt":"产生环境噪声污染的工业企业，应当采取有效措施，减轻噪声对周围生活环境的影响。"},{"i":26,"n":"第二十六条","txt":"国务院有关主管部门对可能产生环境噪声污染的工业设备，应当根据声环境保护的要求和国家的经济、技术条件，逐步在依法制定的产品的国家标准、行业标准中规定噪声限值。"},{"i":27,"n":"第二十七条","txt":"本法所称建筑施工噪声，是指在建筑施工过程中产生的干扰周围生活环境的声音。"},{"i":28,"n":"第二十八条","txt":"在城市市区范围内向周围生活环境排放建筑施工噪声的，应当符合国家规定的建筑施工场界环境噪声排放标准。"},{"i":29,"n":"第二十九条","txt":"在城市市区范围内，建筑施工过程中使用机械设备，可能产生环境噪声污染的，施工单位必须在工程开工十五日以前向工程所在地县级以上地方人民政府生态环境主管部门申报该工程的项目名称、施工场所和期限、可能产生的环境噪声值以及所采取的环境噪声污染防治措施的情况。"},{"i":30,"n":"第三十条","txt":"在城市市区噪声敏感建筑物集中区域内，禁止夜间进行产生环境噪声污染的建筑施工作业，但抢修、抢险作业和因生产工艺上要求或者特殊需要必须连续作业的除外。"},{"i":31,"n":"第三十一条","txt":"本法所称交通运输噪声，是指机动车辆、铁路机车、机动船舶、航空器等交通运输工具在运行时所产生的干扰周围生活环境的声音。"},{"i":32,"n":"第三十二条","txt":"禁止制造、销售或者进口超过规定的噪声限值的汽车。"},{"i":33,"n":"第三十三条","txt":"在城市市区范围内行驶的机动车辆的消声器和喇叭必须符合国家规定的要求。机动车辆必须加强维修和保养，保持技术性能良好，防治环境噪声污染。"},{"i":34,"n":"第三十四条","txt":"机动车辆在城市市区范围内行驶，机动船舶在城市市区的内河航道航行，铁路机车驶经或者进入城市市区、疗养区时，必须按照规定使用声响装置。"},{"i":35,"n":"第三十五条","txt":"城市人民政府公安机关可以根据本地城市市区区域声环境保护的需要，划定禁止机动车辆行驶和禁止其使用声响装置的路段和时间，并向社会公告。"},{"i":36,"n":"第三十六条","txt":"建设经过已有的噪声敏感建筑物集中区域的高速公路和城市高架、轻轨道路，有可能造成环境噪声污染的，应当设置声屏障或者采取其他有效的控制环境噪声污染的措施。"},{"i":37,"n":"第三十七条","txt":"在已有的城市交通干线的两侧建设噪声敏感建筑物的，建设单位应当按照国家规定间隔一定距离，并采取减轻、避免交通噪声影响的措施。"},{"i":38,"n":"第三十八条","txt":"在车站、铁路编组站、港口、码头、航空港等地指挥作业时使用广播喇叭的，应当控制音量，减轻噪声对周围生活环境的影响。"},{"i":39,"n":"第三十九条","txt":"穿越城市居民区、文教区的铁路，因铁路机车运行造成环境噪声污染的，当地城市人民政府应当组织铁路部门和其他有关部门，制定减轻环境噪声污染的规划。铁路部门和其他有关部门应当按照规划的要求，采取有效措施，减轻环境噪声污染。"},{"i":40,"n":"第四十条","txt":"除起飞、降落或者依法规定的情形以外，民用航空器不得飞越城市市区上空。城市人民政府应当在航空器起飞、降落的净空周围划定限制建设噪声敏感建筑物的区域；在该区域内建设噪声敏感建筑物的，建设单位应当采取减轻、避免航空器运行时产生的噪声影响的措施。民航部门应当采取有效措施，减轻环境噪声污染。"},{"i":41,"n":"第四十一条","txt":"本法所称社会生活噪声，是指人为活动所产生的除工业噪声、建筑施工噪声和交通运输噪声之外的干扰周围生活环境的声音。"},{"i":42,"n":"第四十二条","txt":"在城市市区噪声敏感建筑物集中区域内，因商业经营活动中使用固定设备造成环境噪声污染的商业企业，必须按照国务院生态环境主管部门的规定，向所在地的县级以上地方人民政府生态环境主管部门申报拥有的造成环境噪声污染的设备的状况和防治环境噪声污染的设施的情况。"},{"i":43,"n":"第四十三条","txt":"新建营业性文化娱乐场所的边界噪声必须符合国家规定的环境噪声排放标准；不符合国家规定的环境噪声排放标准的，文化行政主管部门不得核发文化经营许可证，市场监督管理部门不得核发营业执照。"},{"i":44,"n":"第四十四条","txt":"禁止在商业经营活动中使用高音广播喇叭或者采用其他发出高噪声的方法招揽顾客。"},{"i":45,"n":"第四十五条","txt":"禁止任何单位、个人在城市市区噪声敏感建筑物集中区域内使用高音广播喇叭。"},{"i":46,"n":"第四十六条","txt":"使用家用电器、乐器或者进行其他家庭室内娱乐活动时，应当控制音量或者采取其他有效措施，避免对周围居民造成环境噪声污染。"},{"i":47,"n":"第四十七条","txt":"在已竣工交付使用的住宅楼进行室内装修活动，应当限制作业时间，并采取其他有效措施，以减轻、避免对周围居民造成环境噪声污染。"},{"i":48,"n":"第四十八条","txt":"违反本法第十四条的规定，建设项目中需要配套建设的环境噪声污染防治设施没有建成或者没有达到国家规定的要求，擅自投入生产或者使用的，由县级以上生态环境主管部门责令限期改正，并对单位和个人处以罚款；造成重大环境污染或者生态破坏的，责令停止生产或者使用，或者报经有批准权的人民政府批准，责令关闭。"},{"i":49,"n":"第四十九条","txt":"违反本法规定，拒报或者谎报规定的环境噪声排放申报事项的，县级以上地方人民政府生态环境主管部门可以根据不同情节，给予警告或者处以罚款。"},{"i":50,"n":"第五十条","txt":"违反本法第十五条的规定，未经生态环境主管部门批准，擅自拆除或者闲置环境噪声污染防治设施，致使环境噪声排放超过规定标准的，由县级以上地方人民政府生态环境主管部门责令改正，并处罚款。"},{"i":51,"n":"第五十一条","txt":"违反本法第十六条的规定，不按照国家规定缴纳超标准排污费的，县级以上地方人民政府生态环境主管部门可以根据不同情节，给予警告或者处以罚款。"},{"i":52,"n":"第五十二条","txt":"违反本法第十七条的规定，对经限期治理逾期未完成治理任务的企业事业单位，除依照国家规定加收超标准排污费外，可以根据所造成的危害后果处以罚款，或者责令停业、搬迁、关闭。"},{"i":53,"n":"第五十三条","txt":"违反本法第十八条的规定，生产、销售、进口禁止生产、销售、进口的设备的，由县级以上人民政府经济综合主管部门责令改正；情节严重的，由县级以上人民政府经济综合主管部门提出意见，报请同级人民政府按照国务院规定的权限责令停业、关闭。"},{"i":54,"n":"第五十四条","txt":"违反本法第十九条的规定，未经当地公安机关批准，进行产生偶发性强烈噪声活动的，由公安机关根据不同情节给予警告或者处以罚款。"},{"i":55,"n":"第五十五条","txt":"排放环境噪声的单位违反本法第二十一条的规定，拒绝生态环境主管部门或者其他依照本法规定行使环境噪声监督管理权的部门、机构现场检查或者在被检查时弄虚作假的，生态环境主管部门或者其他依照本法规定行使环境噪声监督管理权的监督管理部门、机构可以根据不同情节，给予警告或者处以罚款。"},{"i":56,"n":"第五十六条","txt":"建筑施工单位违反本法第三十条第一款的规定，在城市市区噪声敏感建筑物集中区域内，夜间进行禁止进行的产生环境噪声污染的建筑施工作业的，由工程所在地县级以上地方人民政府生态环境主管部门责令改正，可以并处罚款。"},{"i":57,"n":"第五十七条","txt":"违反本法第三十四条的规定，机动车辆不按照规定使用声响装置的，由当地公安机关根据不同情节给予警告或者处以罚款。"},{"i":58,"n":"第五十八条","txt":"违反本法规定，有下列行为之一的，由公安机关给予警告，可以并处罚款："},{"i":59,"n":"第五十九条","txt":"违反本法第四十三条第二款、第四十四条第二款的规定，造成环境噪声污染的，由县级以上地方人民政府生态环境主管部门责令改正，可以并处罚款。"},{"i":60,"n":"第六十条","txt":"违反本法第四十四条第一款的规定，造成环境噪声污染的，由公安机关责令改正，可以并处罚款。"},{"i":61,"n":"第六十一条","txt":"受到环境噪声污染危害的单位和个人，有权要求加害人排除危害；造成损失的，依法赔偿损失。"},{"i":62,"n":"第六十二条","txt":"环境噪声污染防治监督管理人员滥用职权、玩忽职守、徇私舞弊的，由其所在单位或者上级主管机关给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"本法中下列用语的含义是："},{"i":64,"n":"第六十四条","txt":"本法自1997年3月1日起施行。1989年9月26日国务院发布的《中华人民共和国环境噪声污染防治条例》同时废止。"}],"huanjingzaoshengwuranfangzhifa":[{"i":1,"n":"第一条","txt":"为防治环境噪声污染，保护和改善生活环境，保障人体健康，促进经济和社会发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称环境噪声，是指在工业生产、建筑施工、交通运输和社会生活中所产生的干扰周围生活环境的声音。"},{"i":3,"n":"第三条","txt":"本法适用于中华人民共和国领域内环境噪声污染的防治。"},{"i":4,"n":"第四条","txt":"国务院和地方各级人民政府应当将环境噪声污染防治工作纳入环境保护规划，并采取有利于声环境保护的经济、技术政策和措施。"},{"i":5,"n":"第五条","txt":"地方各级人民政府在制定城乡建设规划时，应当充分考虑建设项目和区域开发、改造所产生的噪声对周围生活环境的影响，统筹规划，合理安排功能区和建设布局，防止或者减轻环境噪声污染。"},{"i":6,"n":"第六条","txt":"国务院环境保护行政主管部门对全国环境噪声污染防治实施统一监督管理。"},{"i":7,"n":"第七条","txt":"任何单位和个人都有保护声环境的义务，并有权对造成环境噪声污染的单位和个人进行检举和控告。"},{"i":8,"n":"第八条","txt":"国家鼓励、支持环境噪声污染防治的科学研究、技术开发，推广先进的防治技术和普及防治环境噪声污染的科学知识。"},{"i":9,"n":"第九条","txt":"对在环境噪声污染防治方面成绩显著的单位和个人，由人民政府给予奖励。"},{"i":10,"n":"第十条","txt":"国务院环境保护行政主管部门分别不同的功能区制定国家声环境质量标准。"},{"i":11,"n":"第十一条","txt":"国务院环境保护行政主管部门根据国家声环境质量标准和国家经济、技术条件，制定国家环境噪声排放标准。"},{"i":12,"n":"第十二条","txt":"城市规划部门在确定建设布局时，应当依据国家声环境质量标准和民用建筑隔声设计规范，合理划定建筑物与交通干线的防噪声距离，并提出相应的规划设计要求。"},{"i":13,"n":"第十三条","txt":"新建、改建、扩建的建设项目，必须遵守国家有关建设项目环境保护管理的规定。"},{"i":14,"n":"第十四条","txt":"建设项目的环境噪声污染防治设施必须与主体工程同时设计、同时施工、同时投产使用。"},{"i":15,"n":"第十五条","txt":"产生环境噪声污染的企业事业单位，必须保持防治环境噪声污染的设施的正常使用；拆除或者闲置环境噪声污染防治设施的，必须事先报经所在地的县级以上地方人民政府环境保护行政主管部门批准。"},{"i":16,"n":"第十六条","txt":"产生环境噪声污染的单位，应当采取措施进行治理，并按照国家规定缴纳超标准排污费。"},{"i":17,"n":"第十七条","txt":"对于在噪声敏感建筑物集中区域内造成严重环境噪声污染的企业事业单位，限期治理。"},{"i":18,"n":"第十八条","txt":"国家对环境噪声污染严重的落后设备实行淘汰制度。"},{"i":19,"n":"第十九条","txt":"在城市范围内从事生产活动确需排放偶发性强烈噪声的，必须事先向当地公安机关提出申请，经批准后方可进行。当地公安机关应当向社会公告。"},{"i":20,"n":"第二十条","txt":"国务院环境保护行政主管部门应当建立环境噪声监测制度，制定监测规范，并会同有关部门组织监测网络。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府环境保护行政主管部门和其他环境噪声污染防治工作的监督管理部门、机构，有权依据各自的职责对管辖范围内排放环境噪声的单位进行现场检查。被检查的单位必须如实反映情况，并提供必要的资料。检查部门、机构应当为被检查的单位保守技术秘密和业务秘密。"},{"i":22,"n":"第二十二条","txt":"本法所称工业噪声，是指在工业生产活动中使用固定的设备时产生的干扰周围生活环境的声音。"},{"i":23,"n":"第二十三条","txt":"在城市范围内向周围生活环境排放工业噪声的，应当符合国家规定的工业企业厂界环境噪声排放标准。"},{"i":24,"n":"第二十四条","txt":"在工业生产中因使用固定的设备造成环境噪声污染的工业企业，必须按照国务院环境保护行政主管部门的规定，向所在地的县级以上地方人民政府环境保护行政主管部门申报拥有的造成环境噪声污染的设备的种类、数量以及在正常作业条件下所发出的噪声值和防治环境噪声污染的设施情况，并提供防治噪声污染的技术资料。"},{"i":25,"n":"第二十五条","txt":"产生环境噪声污染的工业企业，应当采取有效措施，减轻噪声对周围生活环境的影响。"},{"i":26,"n":"第二十六条","txt":"国务院有关主管部门对可能产生环境噪声污染的工业设备，应当根据声环境保护的要求和国家的经济、技术条件，逐步在依法制定的产品的国家标准、行业标准中规定噪声限值。"},{"i":27,"n":"第二十七条","txt":"本法所称建筑施工噪声，是指在建筑施工过程中产生的干扰周围生活环境的声音。"},{"i":28,"n":"第二十八条","txt":"在城市市区范围内向周围生活环境排放建筑施工噪声的，应当符合国家规定的建筑施工场界环境噪声排放标准。"},{"i":29,"n":"第二十九条","txt":"在城市市区范围内，建筑施工过程中使用机械设备，可能产生环境噪声污染的，施工单位必须在工程开工十五日以前向工程所在地县级以上地方人民政府环境保护行政主管部门申报该工程的项目名称、施工场所和期限、可能产生的环境噪声值以及所采取的环境噪声污染防治措施的情况。"},{"i":30,"n":"第三十条","txt":"在城市市区噪声敏感建筑物集中区域内，禁止夜间进行产生环境噪声污染的建筑施工作业，但抢修、抢险作业和因生产工艺上要求或者特殊需要必须连续作业的除外。"},{"i":31,"n":"第三十一条","txt":"本法所称交通运输噪声，是指机动车辆、铁路机车、机动船舶、航空器等交通运输工具在运行时所产生的干扰周围生活环境的声音。"},{"i":32,"n":"第三十二条","txt":"禁止制造、销售或者进口超过规定的噪声限值的汽车。"},{"i":33,"n":"第三十三条","txt":"在城市市区范围内行驶的机动车辆的消声器和喇叭必须符合国家规定的要求。机动车辆必须加强维修和保养，保持技术性能良好，防治环境噪声污染。"},{"i":34,"n":"第三十四条","txt":"机动车辆在城市市区范围内行驶，机动船舶在城市市区的内河航道航行，铁路机车驶经或者进入城市市区、疗养区时，必须按照规定使用声响装置。"},{"i":35,"n":"第三十五条","txt":"城市人民政府公安机关可以根据本地城市市区区域声环境保护的需要，划定禁止机动车辆行驶和禁止其使用声响装置的路段和时间，并向社会公告。"},{"i":36,"n":"第三十六条","txt":"建设经过已有的噪声敏感建筑物集中区域的高速公路和城市高架、轻轨道路，有可能造成环境噪声污染的，应当设置声屏障或者采取其他有效的控制环境噪声污染的措施。"},{"i":37,"n":"第三十七条","txt":"在已有的城市交通干线的两侧建设噪声敏感建筑物的，建设单位应当按照国家规定间隔一定距离，并采取减轻、避免交通噪声影响的措施。"},{"i":38,"n":"第三十八条","txt":"在车站、铁路编组站、港口、码头、航空港等地指挥作业时使用广播喇叭的，应当控制音量，减轻噪声对周围生活环境的影响。"},{"i":39,"n":"第三十九条","txt":"穿越城市居民区、文教区的铁路，因铁路机车运行造成环境噪声污染的，当地城市人民政府应当组织铁路部门和其他有关部门，制定减轻环境噪声污染的规划。铁路部门和其他有关部门应当按照规划的要求，采取有效措施，减轻环境噪声污染。"},{"i":40,"n":"第四十条","txt":"除起飞、降落或者依法规定的情形以外，民用航空器不得飞越城市市区上空。城市人民政府应当在航空器起飞、降落的净空周围划定限制建设噪声敏感建筑物的区域；在该区域内建设噪声敏感建筑物的，建设单位应当采取减轻、避免航空器运行时产生的噪声影响的措施。民航部门应当采取有效措施，减轻环境噪声污染。"},{"i":41,"n":"第四十一条","txt":"本法所称社会生活噪声，是指人为活动所产生的除工业噪声、建筑施工噪声和交通运输噪声之外的干扰周围生活环境的声音。"},{"i":42,"n":"第四十二条","txt":"在城市市区噪声敏感建筑物集中区域内，因商业经营活动中使用固定设备造成环境噪声污染的商业企业，必须按照国务院环境保护行政主管部门的规定，向所在地的县级以上地方人民政府环境保护行政主管部门申报拥有的造成环境噪声污染的设备的状况和防治环境噪声污染的设施的情况。"},{"i":43,"n":"第四十三条","txt":"新建营业性文化娱乐场所的边界噪声必须符合国家规定的环境噪声排放标准；不符合国家规定的环境噪声排放标准的，文化行政主管部门不得核发文化经营许可证，工商行政管理部门不得核发营业执照。"},{"i":44,"n":"第四十四条","txt":"禁止在商业经营活动中使用高音广播喇叭或者采用其他发出高噪声的方法招揽顾客。"},{"i":45,"n":"第四十五条","txt":"禁止任何单位、个人在城市市区噪声敏感建筑物集中区域内使用高音广播喇叭。"},{"i":46,"n":"第四十六条","txt":"使用家用电器、乐器或者进行其他家庭室内娱乐活动时，应当控制音量或者采取其他有效措施，避免对周围居民造成环境噪声污染。"},{"i":47,"n":"第四十七条","txt":"在已竣工交付使用的住宅楼进行室内装修活动，应当限制作业时间，并采取其他有效措施，以减轻、避免对周围居民造成环境噪声污染。"},{"i":48,"n":"第四十八条","txt":"违反本法第十四条的规定，建设项目中需要配套建设的环境噪声污染防治设施没有建成或者没有达到国家规定的要求，擅自投入生产或者使用的，由批准该建设项目的环境影响报告书的环境保护行政主管部门责令停止生产或者使用，可以并处罚款。"},{"i":49,"n":"第四十九条","txt":"违反本法规定，拒报或者谎报规定的环境噪声排放申报事项的，县级以上地方人民政府环境保护行政主管部门可以根据不同情节，给予警告或者处以罚款。"},{"i":50,"n":"第五十条","txt":"违反本法第十五条的规定，未经环境保护行政主管部门批准，擅自拆除或者闲置环境噪声污染防治设施，致使环境噪声排放超过规定标准的，由县级以上地方人民政府环境保护行政主管部门责令改正，并处罚款。"},{"i":51,"n":"第五十一条","txt":"违反本法第十六条的规定，不按照国家规定缴纳超标准排污费的，县级以上地方人民政府环境保护行政主管部门可以根据不同情节，给予警告或者处以罚款。"},{"i":52,"n":"第五十二条","txt":"违反本法第十七条的规定，对经限期治理逾期未完成治理任务的企业事业单位，除依照国家规定加收超标准排污费外，可以根据所造成的危害后果处以罚款，或者责令停业、搬迁、关闭。"},{"i":53,"n":"第五十三条","txt":"违反本法第十八条的规定，生产、销售、进口禁止生产、销售、进口的设备的，由县级以上人民政府经济综合主管部门责令改正；情节严重的，由县级以上人民政府经济综合主管部门提出意见，报请同级人民政府按照国务院规定的权限责令停业、关闭。"},{"i":54,"n":"第五十四条","txt":"违反本法第十九条的规定，未经当地公安机关批准，进行产生偶发性强烈噪声活动的，由公安机关根据不同情节给予警告或者处以罚款。"},{"i":55,"n":"第五十五条","txt":"排放环境噪声的单位违反本法第二十一条的规定，拒绝环境保护行政主管部门或者其他依照本法规定行使环境噪声监督管理权的部门、机构现场检查或者在被检查时弄虚作假的，环境保护行政主管部门或者其他依照本法规定行使环境噪声监督管理权的监督管理部门、机构可以根据不同情节，给予警告或者处以罚款。"},{"i":56,"n":"第五十六条","txt":"建筑施工单位违反本法第三十条第一款的规定，在城市市区噪声敏感建筑物集中区域内，夜间进行禁止进行的产生环境噪声污染的建筑施工作业的，由工程所在地县级以上地方人民政府环境保护行政主管部门责令改正，可以并处罚款。"},{"i":57,"n":"第五十七条","txt":"违反本法第三十四条的规定，机动车辆不按照规定使用声响装置的，由当地公安机关根据不同情节给予警告或者处以罚款。"},{"i":58,"n":"第五十八条","txt":"违反本法规定，有下列行为之一的，由公安机关给予警告，可以并处罚款："},{"i":59,"n":"第五十九条","txt":"违反本法第四十三条第二款、第四十四条第二款的规定，造成环境噪声污染的，由县级以上地方人民政府环境保护行政主管部门责令改正，可以并处罚款。"},{"i":60,"n":"第六十条","txt":"违反本法第四十四条第一款的规定，造成环境噪声污染的，由公安机关责令改正，可以并处罚款。"},{"i":61,"n":"第六十一条","txt":"受到环境噪声污染危害的单位和个人，有权要求加害人排除危害；造成损失的，依法赔偿损失。"},{"i":62,"n":"第六十二条","txt":"环境噪声污染防治监督管理人员滥用职权、玩忽职守、徇私舞弊的，由其所在单位或者上级主管机关给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"本法中下列用语的含义是："},{"i":64,"n":"第六十四条","txt":"本法自1997年3月1日起施行。1989年9月26日国务院发布的《中华人民共和国环境噪声污染防治条例》同时废止。"}],"hunyinfa":[{"i":1,"n":"第一条","txt":"本法是婚姻家庭关系的基本准则。"},{"i":2,"n":"第二条","txt":"实行婚姻自由、一夫一妻、男女平等的婚姻制度。"},{"i":3,"n":"第三条","txt":"禁止包办、买卖婚姻和其他干涉婚姻自由的行为。禁止借婚姻索取财物。"},{"i":4,"n":"第四条","txt":"夫妻应当互相忠实，互相尊重；家庭成员间应当敬老爱幼，互相帮助，维护平等、和睦、文明的婚姻家庭关系。"},{"i":5,"n":"第五条","txt":"结婚必须男女双方完全自愿，不许任何一方对他方加以强迫或任何第三者加以干涉。"},{"i":6,"n":"第六条","txt":"结婚年龄，男不得早于二十二周岁，女不得早于二十周岁。晚婚晚育应予鼓励。"},{"i":7,"n":"第七条","txt":"有下列情形之一的，禁止结婚："},{"i":8,"n":"第八条","txt":"要求结婚的男女双方必须亲自到婚姻登记机关进行结婚登记。符合本法规定的，予以登记，发给结婚证。取得结婚证，即确立夫妻关系。未办理结婚登记的，应当补办登记。"},{"i":9,"n":"第九条","txt":"登记结婚后，根据男女双方约定，女方可以成为男方家庭的成员，男方可以成为女方家庭的成员。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，婚姻无效："},{"i":11,"n":"第十一条","txt":"因胁迫结婚的，受胁迫的一方可以向婚姻登记机关或人民法院请求撤销该婚姻。受胁迫的一方撤销婚姻的请求，应当自结婚登记之日起一年内提出。被非法限制人身自由的当事人请求撤销婚姻的，应当自恢复人身自由之日起一年内提出。"},{"i":12,"n":"第十二条","txt":"无效或被撤销的婚姻，自始无效。当事人不具有夫妻的权利和义务。同居期间所得的财产，由当事人协议处理；协议不成时，由人民法院根据照顾无过错方的原则判决。对重婚导致的婚姻无效的财产处理，不得侵害合法婚姻当事人的财产权益。当事人所生的子女，适用本法有关父母子女的规定。"},{"i":13,"n":"第十三条","txt":"夫妻在家庭中地位平等。"},{"i":14,"n":"第十四条","txt":"夫妻双方都有各用自己姓名的权利。"},{"i":15,"n":"第十五条","txt":"夫妻双方都有参加生产、工作、学习和社会活动的自由，一方不得对他方加以限制或干涉。"},{"i":16,"n":"第十六条","txt":"夫妻双方都有实行计划生育的义务。"},{"i":17,"n":"第十七条","txt":"夫妻在婚姻关系存续期间所得的下列财产，归夫妻共同所有："},{"i":18,"n":"第十八条","txt":"有下列情形之一的，为夫妻一方的财产："},{"i":19,"n":"第十九条","txt":"夫妻可以约定婚姻关系存续期间所得的财产以及婚前财产归各自所有、共同所有或部分各自所有、部分共同所有。约定应当采用书面形式。没有约定或约定不明确的，适用本法第十七条、第十八条的规定。"},{"i":20,"n":"第二十条","txt":"夫妻有互相扶养的义务。"},{"i":21,"n":"第二十一条","txt":"父母对子女有抚养教育的义务；子女对父母有赡养扶助的义务。"},{"i":22,"n":"第二十二条","txt":"子女可以随父姓，可以随母姓。"},{"i":23,"n":"第二十三条","txt":"父母有保护和教育未成年子女的权利和义务。在未成年子女对国家、集体或他人造成损害时，父母有承担民事责任的义务。"},{"i":24,"n":"第二十四条","txt":"夫妻有相互继承遗产的权利。"},{"i":25,"n":"第二十五条","txt":"非婚生子女享有与婚生子女同等的权利，任何人不得加以危害和歧视。"},{"i":26,"n":"第二十六条","txt":"国家保护合法的收养关系。养父母和养子女间的权利和义务，适用本法对父母子女关系的有关规定。"},{"i":27,"n":"第二十七条","txt":"继父母与继子女间，不得虐待或歧视。"},{"i":28,"n":"第二十八条","txt":"有负担能力的祖父母、外祖父母，对于父母已经死亡或父母无力抚养的未成年的孙子女、外孙子女，有抚养的义务。有负担能力的孙子女、外孙子女，对于子女已经死亡或子女无力赡养的祖父母、外祖父母，有赡养的义务。"},{"i":29,"n":"第二十九条","txt":"有负担能力的兄、姐，对于父母已经死亡或父母无力抚养的未成年的弟、妹，有扶养的义务。由兄、姐扶养长大的有负担能力的弟、妹，对于缺乏劳动能力又缺乏生活来源的兄、姐，有扶养的义务。"},{"i":30,"n":"第三十条","txt":"子女应当尊重父母的婚姻权利，不得干涉父母再婚以及婚后的生活。子女对父母的赡养义务，不因父母的婚姻关系变化而终止。"},{"i":31,"n":"第三十一条","txt":"男女双方自愿离婚的，准予离婚。双方必须到婚姻登记机关申请离婚。婚姻登记机关查明双方确实是自愿并对子女和财产问题已有适当处理时，发给离婚证。"},{"i":32,"n":"第三十二条","txt":"男女一方要求离婚的，可由有关部门进行调解或直接向人民法院提出离婚诉讼。"},{"i":33,"n":"第三十三条","txt":"现役军人的配偶要求离婚，须得军人同意，但军人一方有重大过错的除外。"},{"i":34,"n":"第三十四条","txt":"女方在怀孕期间、分娩后一年内或中止妊娠后六个月内，男方不得提出离婚。女方提出离婚的，或人民法院认为确有必要受理男方离婚请求的，不在此限。"},{"i":35,"n":"第三十五条","txt":"离婚后，男女双方自愿恢复夫妻关系的，必须到婚姻登记机关进行复婚登记。"},{"i":36,"n":"第三十六条","txt":"父母与子女间的关系，不因父母离婚而消除。离婚后，子女无论由父或母直接抚养，仍是父母双方的子女。"},{"i":37,"n":"第三十七条","txt":"离婚后，一方抚养的子女，另一方应负担必要的生活费和教育费的一部或全部，负担费用的多少和期限的长短，由双方协议；协议不成时，由人民法院判决。"},{"i":38,"n":"第三十八条","txt":"离婚后，不直接抚养子女的父或母，有探望子女的权利，另一方有协助的义务。"},{"i":39,"n":"第三十九条","txt":"离婚时，夫妻的共同财产由双方协议处理；协议不成时，由人民法院根据财产的具体情况，照顾子女和女方权益的原则判决。"},{"i":40,"n":"第四十条","txt":"夫妻书面约定婚姻关系存续期间所得的财产归各自所有，一方因抚育子女、照料老人、协助另一方工作等付出较多义务的，离婚时有权向另一方请求补偿，另一方应当予以补偿。"},{"i":41,"n":"第四十一条","txt":"离婚时，原为夫妻共同生活所负的债务，应当共同偿还。共同财产不足清偿的，或财产归各自所有的，由双方协议清偿；协议不成时，由人民法院判决。"},{"i":42,"n":"第四十二条","txt":"离婚时，如一方生活困难，另一方应从其住房等个人财产中给予适当帮助。具体办法由双方协议；协议不成时，由人民法院判决。"},{"i":43,"n":"第四十三条","txt":"实施家庭暴力或虐待家庭成员，受害人有权提出请求，居民委员会、村民委员会以及所在单位应当予以劝阻、调解。"},{"i":44,"n":"第四十四条","txt":"对遗弃家庭成员，受害人有权提出请求，居民委员会、村民委员会以及所在单位应当予以劝阻、调解。"},{"i":45,"n":"第四十五条","txt":"对重婚的，对实施家庭暴力或虐待、遗弃家庭成员构成犯罪的，依法追究刑事责任。受害人可以依照刑事诉讼法的有关规定，向人民法院自诉；公安机关应当依法侦查，人民检察院应当依法提起公诉。"},{"i":46,"n":"第四十六条","txt":"有下列情形之一，导致离婚的，无过错方有权请求损害赔偿："},{"i":47,"n":"第四十七条","txt":"离婚时，一方隐藏、转移、变卖、毁损夫妻共同财产，或伪造债务企图侵占另一方财产的，分割夫妻共同财产时，对隐藏、转移、变卖、毁损夫妻共同财产或伪造债务的一方，可以少分或不分。离婚后，另一方发现有上述行为的，可以向人民法院提起诉讼，请求再次分割夫妻共同财产。"},{"i":48,"n":"第四十八条","txt":"对拒不执行有关扶养费、抚养费、赡养费、财产分割、遗产继承、探望子女等判决或裁定的，由人民法院依法强制执行。有关个人和单位应负协助执行的责任。"},{"i":49,"n":"第四十九条","txt":"其他法律对有关婚姻家庭的违法行为和法律责任另有规定的，依照其规定。"},{"i":50,"n":"第五十条","txt":"民族自治地方的人民代表大会有权结合当地民族婚姻家庭的具体情况，制定变通规定。自治州、自治县制定的变通规定，报省、自治区、直辖市人民代表大会常务委员会批准后生效。自治区制定的变通规定，报全国人民代表大会常务委员会批准后生效。"},{"i":51,"n":"第五十一条","txt":"本法自1981年1月1日起施行。"}],"jichengfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国宪法》规定，为保护公民的私有财产的继承权，制定本法。"},{"i":2,"n":"第二条","txt":"继承从被继承人死亡时开始。"},{"i":3,"n":"第三条","txt":"遗产是公民死亡时遗留的个人合法财产，包括："},{"i":4,"n":"第四条","txt":"个人承包应得的个人收益，依照本法规定继承。个人承包，依照法律允许由继承人继续承包的，按照承包合同办理。"},{"i":5,"n":"第五条","txt":"继承开始后，按照法定继承办理；有遗嘱的，按照遗嘱继承或者遗赠办理；有遗赠扶养协议的，按照协议办理。"},{"i":6,"n":"第六条","txt":"无行为能力人的继承权、受遗赠权，由他的法定代理人代为行使。"},{"i":7,"n":"第七条","txt":"继承人有下列行为之一的，丧失继承权："},{"i":8,"n":"第八条","txt":"继承权纠纷提起诉讼的期限为二年，自继承人知道或者应当知道其权利被侵犯之日起计算。但是，自继承开始之日起超过二十年的，不得再提起诉讼。"},{"i":9,"n":"第九条","txt":"继承权男女平等。"},{"i":10,"n":"第十条","txt":"遗产按照下列顺序继承："},{"i":11,"n":"第十一条","txt":"被继承人的子女先于被继承人死亡的，由被继承人的子女的晚辈直系血亲代位继承。代位继承人一般只能继承他的父亲或者母亲有权继承的遗产份额。"},{"i":12,"n":"第十二条","txt":"丧偶儿媳对公、婆，丧偶女婿对岳父、岳母，尽了主要赡养义务的，作为第一顺序继承人。"},{"i":13,"n":"第十三条","txt":"同一顺序继承人继承遗产的份额，一般应当均等。"},{"i":14,"n":"第十四条","txt":"对继承人以外的依靠被继承人扶养的缺乏劳动能力又没有生活来源的人，或者继承人以外的对被继承人扶养较多的人，可以分给他们适当的遗产。"},{"i":15,"n":"第十五条","txt":"继承人应当本着互谅互让、和睦团结的精神，协商处理继承问题。遗产分割的时间、办法和份额，由继承人协商确定。协商不成的，可以由人民调解委员会调解或者向人民法院提起诉讼。"},{"i":16,"n":"第十六条","txt":"公民可以依照本法规定立遗嘱处分个人财产，并可以指定遗嘱执行人。"},{"i":17,"n":"第十七条","txt":"公证遗嘱由遗嘱人经公证机关办理。"},{"i":18,"n":"第十八条","txt":"下列人员不能作为遗嘱见证人："},{"i":19,"n":"第十九条","txt":"遗嘱应当对缺乏劳动能力又没有生活来源的继承人保留必要的遗产份额。"},{"i":20,"n":"第二十条","txt":"遗嘱人可以撤销、变更自己所立的遗嘱。"},{"i":21,"n":"第二十一条","txt":"遗嘱继承或者遗赠附有义务的，继承人或者受遗赠人应当履行义务。没有正当理由不履行义务的，经有关单位或者个人请求，人民法院可以取消他接受遗产的权利。"},{"i":22,"n":"第二十二条","txt":"无行为能力人或者限制行为能力人所立的遗嘱无效。"},{"i":23,"n":"第二十三条","txt":"继承开始后，知道被继承人死亡的继承人应当及时通知其他继承人和遗嘱执行人。继承人中无人知道被继承人死亡或者知道被继承人死亡而不能通知的，由被继承人生前所在单位或者住所地的居民委员会、村民委员会负责通知。"},{"i":24,"n":"第二十四条","txt":"存有遗产的人，应当妥善保管遗产，任何人不得侵吞或者争抢。"},{"i":25,"n":"第二十五条","txt":"继承开始后，继承人放弃继承的，应当在遗产处理前，作出放弃继承的表示。没有表示的，视为接受继承。"},{"i":26,"n":"第二十六条","txt":"夫妻在婚姻关系存续期间所得的共同所有的财产，除有约定的以外，如果分割遗产，应当先将共同所有的财产的一半分出为配偶所有，其余的为被继承人的遗产。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，遗产中的有关部分按照法定继承办理："},{"i":28,"n":"第二十八条","txt":"遗产分割时，应当保留胎儿的继承份额。胎儿出生时是死体的，保留的份额按照法定继承办理。"},{"i":29,"n":"第二十九条","txt":"遗产分割应当有利于生产和生活需要，不损害遗产的效用。"},{"i":30,"n":"第三十条","txt":"夫妻一方死亡后另一方再婚的，有权处分所继承的财产，任何人不得干涉。"},{"i":31,"n":"第三十一条","txt":"公民可以与扶养人签订遗赠扶养协议。按照协议，扶养人承担该公民生养死葬的义务，享有受遗赠的权利。"},{"i":32,"n":"第三十二条","txt":"无人继承又无人受遗赠的遗产，归国家所有；死者生前是集体所有制组织成员的，归所在集体所有制组织所有。"},{"i":33,"n":"第三十三条","txt":"继承遗产应当清偿被继承人依法应当缴纳的税款和债务，缴纳税款和清偿债务以他的遗产实际价值为限。超过遗产实际价值部分，继承人自愿偿还的不在此限。"},{"i":34,"n":"第三十四条","txt":"执行遗赠不得妨碍清偿遗赠人依法应当缴纳的税款和债务。"},{"i":35,"n":"第三十五条","txt":"民族自治地方的人民代表大会可以根据本法的原则，结合当地民族财产继承的具体情况，制定变通的或者补充的规定。自治区的规定，报全国人民代表大会常务委员会备案。自治州、自治县的规定，报省或者自治区的人民代表大会常务委员会批准后生效，并报全国人民代表大会常务委员会备案。"},{"i":36,"n":"第三十六条","txt":"中国公民继承在中华人民共和国境外的遗产或者继承在中华人民共和国境内的外国人的遗产，动产适用被继承人住所地法律，不动产适用不动产所在地法律。"},{"i":37,"n":"第三十七条","txt":"本法自一九八五年十月一日起施行。"}],"minfatongze":[{"i":1,"n":"第一条","txt":"为了保障公民、法人的合法的民事权益，正确调整民事关系，适应社会主义现代化建设事业发展的需要，根据宪法和我国实际情况，总结民事活动的实践经验，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国民法调整平等主体的公民之间、法人之间、公民和法人之间的财产关系和人身关系。"},{"i":3,"n":"第三条","txt":"当事人在民事活动中的地位平等。"},{"i":4,"n":"第四条","txt":"民事活动应当遵循自愿、公平、等价有偿、诚实信用的原则。"},{"i":5,"n":"第五条","txt":"公民、法人的合法的民事权益受法律保护，任何组织和个人不得侵犯。"},{"i":6,"n":"第六条","txt":"民事活动必须遵守法律，法律没有规定的，应当遵守国家政策。"},{"i":7,"n":"第七条","txt":"民事活动应当尊重社会公德，不得损害社会公共利益，扰乱社会经济秩序。"},{"i":8,"n":"第八条","txt":"在中华人民共和国领域内的民事活动，适用中华人民共和国法律，法律另有规定的除外。"},{"i":9,"n":"第九条","txt":"公民从出生时起到死亡时止，具有民事权利能力，依法享有民事权利，承担民事义务。"},{"i":10,"n":"第十条","txt":"公民的民事权利能力一律平等。"},{"i":11,"n":"第十一条","txt":"十八周岁以上的公民是成年人，具有完全民事行为能力，可以独立进行民事活动，是完全民事行为能力人。"},{"i":12,"n":"第十二条","txt":"十周岁以上的未成年人是限制民事行为能力人，可以进行与他的年龄、智力相适应的民事活动；其他民事活动由他的法定代理人代理，或者征得他的法定代理人的同意。"},{"i":13,"n":"第十三条","txt":"不能辨认自己行为的精神病人是无民事行为能力人，由他的法定代理人代理民事活动。"},{"i":14,"n":"第十四条","txt":"无民事行为能力人、限制民事行为能力人的监护人是他的法定代理人。"},{"i":15,"n":"第十五条","txt":"公民以他的户籍所在地的居住地为住所，经常居住地与住所不一致的，经常居住地视为住所。"},{"i":16,"n":"第十六条","txt":"未成年人的父母是未成年人的监护人。"},{"i":17,"n":"第十七条","txt":"无民事行为能力或者限制民事行为能力的精神病人，由下列人员担任监护人："},{"i":18,"n":"第十八条","txt":"监护人应当履行监护职责，保护被监护人的人身、财产及其他合法权益，除为被监护人的利益外，不得处理被监护人的财产。"},{"i":19,"n":"第十九条","txt":"精神病人的利害关系人，可以向人民法院申请宣告精神病人为无民事行为能力人或者限制民事行为能力人。"},{"i":20,"n":"第二十条","txt":"公民下落不明满二年的，利害关系人可以向人民法院申请宣告他为失踪人。"},{"i":21,"n":"第二十一条","txt":"失踪人的财产由他的配偶、父母、成年子女或者关系密切的其他亲属、朋友代管。代管有争议的，没有以上规定的人或者以上规定的人无能力代管的，由人民法院指定的人代管。"},{"i":22,"n":"第二十二条","txt":"被宣告失踪的人重新出现或者确知他的下落，经本人或者利害关系人申请，人民法院应当撤销对他的失踪宣告。"},{"i":23,"n":"第二十三条","txt":"公民有下列情形之一的，利害关系人可以向人民法院申请宣告他死亡："},{"i":24,"n":"第二十四条","txt":"被宣告死亡的人重新出现或者确知他没有死亡，经本人或者利害关系人申请，人民法院应当撤销对他的死亡宣告。"},{"i":25,"n":"第二十五条","txt":"被撤销死亡宣告的人有权请求返还财产。依照继承法取得他的财产的公民或者组织，应当返还原物；原物不存在的，给予适当补偿。"},{"i":26,"n":"第二十六条","txt":"公民在法律允许的范围内，依法经核准登记，从事工商业经营的，为个体工商户。个体工商户可以起字号。"},{"i":27,"n":"第二十七条","txt":"农村集体经济组织的成员，在法律允许的范围内，按照承包合同规定从事商品经营的，为农村承包经营户。"},{"i":28,"n":"第二十八条","txt":"个体工商户、农村承包经营户的合法权益，受法律保护。"},{"i":29,"n":"第二十九条","txt":"个体工商户、农村承包经营户的债务，个人经营的，以个人财产承担；家庭经营的，以家庭财产承担。"},{"i":30,"n":"第三十条","txt":"个人合伙是指两个以上公民按照协议，各自提供资金、实物、技术等，合伙经营、共同劳动。"},{"i":31,"n":"第三十一条","txt":"合伙人应当对出资数额、盈余分配、债务承担、入伙、退伙、合伙终止等事项，订立书面协议。"},{"i":32,"n":"第三十二条","txt":"合伙人投入的财产，由合伙人统一管理和使用。"},{"i":33,"n":"第三十三条","txt":"个人合伙可以起字号，依法经核准登记，在核准登记的经营范围内从事经营。"},{"i":34,"n":"第三十四条","txt":"个人合伙的经营活动，由合伙人共同决定，合伙人有执行和监督的权利。"},{"i":35,"n":"第三十五条","txt":"合伙的债务，由合伙人按照出资比例或者协议的约定，以各自的财产承担清偿责任。"},{"i":36,"n":"第三十六条","txt":"法人是具有民事权利能力和民事行为能力，依法独立享有民事权利和承担民事义务的组织。"},{"i":37,"n":"第三十七条","txt":"法人应当具备下列条件："},{"i":38,"n":"第三十八条","txt":"依照法律或者法人组织章程规定，代表法人行使职权的负责人，是法人的法定代表人。"},{"i":39,"n":"第三十九条","txt":"法人以它的主要办事机构所在地为住所。"},{"i":40,"n":"第四十条","txt":"法人终止，应当依法进行清算，停止清算范围外的活动。"},{"i":41,"n":"第四十一条","txt":"全民所有制企业、集体所有制企业有符合国家规定的资金数额，有组织章程、组织机构和场所，能够独立承担民事责任，经主管机关核准登记，取得法人资格。"},{"i":42,"n":"第四十二条","txt":"企业法人应当在核准登记的经营范围内从事经营。"},{"i":43,"n":"第四十三条","txt":"企业法人对它的法定代表人和其他工作人员的经营活动，承担民事责任。"},{"i":44,"n":"第四十四条","txt":"企业法人分立、合并或者有其他重要事项变更，应当向登记机关办理登记并公告。"},{"i":45,"n":"第四十五条","txt":"企业法人由于下列原因之一终止："},{"i":46,"n":"第四十六条","txt":"企业法人终止，应当向登记机关办理注销登记并公告。"},{"i":47,"n":"第四十七条","txt":"企业法人解散，应当成立清算组织，进行清算。企业法人被撤销、被宣告破产的，应当由主管机关或者人民法院组织有关机关和有关人员成立清算组织，进行清算。"},{"i":48,"n":"第四十八条","txt":"全民所有制企业法人以国家授予它经营管理的财产承担民事责任。集体所有制企业法人以企业所有的财产承担民事责任。中外合资经营企业法人、中外合作经营企业法人和外资企业法人以企业所有的财产承担民事责任，法律另有规定的除外。"},{"i":49,"n":"第四十九条","txt":"企业法人有下列情形之一的，除法人承担责任外，对法定代表人可以给予行政处分、罚款，构成犯罪的，依法追究刑事责任："},{"i":50,"n":"第五十条","txt":"有独立经费的机关从成立之日起，具有法人资格。"},{"i":51,"n":"第五十一条","txt":"企业之间或者企业、事业单位之间联营，组成新的经济实体，独立承担民事责任、具备法人条件的，经主管机关核准登记，取得法人资格。"},{"i":52,"n":"第五十二条","txt":"企业之间或者企业、事业单位之间联营，共同经营、不具备法人条件的，由联营各方按照出资比例或者协议的约定，以各自所有的或者经营管理的财产承担民事责任。依照法律的规定或者协议的约定负连带责任的，承担连带责任。"},{"i":53,"n":"第五十三条","txt":"企业之间或者企业、事业单位之间联营，按照合同的约定各自独立经营的，它的权利和义务由合同约定，各自承担民事责任。"},{"i":54,"n":"第五十四条","txt":"民事法律行为是公民或者法人设立、变更、终止民事权利和民事义务的合法行为。"},{"i":55,"n":"第五十五条","txt":"民事法律行为应当具备下列条件："},{"i":56,"n":"第五十六条","txt":"民事法律行为可以采取书面形式、口头形式或者其他形式。法律规定用特定形式的，应当依照法律规定。"},{"i":57,"n":"第五十七条","txt":"民事法律行为从成立时起具有法律约束力。行为人非依法律规定或者取得对方同意，不得擅自变更或者解除。"},{"i":58,"n":"第五十八条","txt":"下列民事行为无效："},{"i":59,"n":"第五十九条","txt":"下列民事行为，一方有权请求人民法院或者仲裁机关予以变更或者撤销："},{"i":60,"n":"第六十条","txt":"民事行为部分无效，不影响其他部分的效力的，其他部分仍然有效。"},{"i":61,"n":"第六十一条","txt":"民事行为被确认为无效或者被撤销后，当事人因该行为取得的财产，应当返还给受损失的一方。有过错的一方应当赔偿对方因此所受的损失，双方都有过错的，应当各自承担相应的责任。"},{"i":62,"n":"第六十二条","txt":"民事法律行为可以附条件，附条件的民事法律行为在符合所附条件时生效。"},{"i":63,"n":"第六十三条","txt":"公民、法人可以通过代理人实施民事法律行为。"},{"i":64,"n":"第六十四条","txt":"代理包括委托代理、法定代理和指定代理。"},{"i":65,"n":"第六十五条","txt":"民事法律行为的委托代理，可以用书面形式，也可以用口头形式。法律规定用书面形式的，应当用书面形式。"},{"i":66,"n":"第六十六条","txt":"没有代理权、超越代理权或者代理权终止后的行为，只有经过被代理人的追认，被代理人才承担民事责任。未经追认的行为，由行为人承担民事责任。本人知道他人以本人名义实施民事行为而不作否认表示的，视为同意。"},{"i":67,"n":"第六十七条","txt":"代理人知道被委托代理的事项违法仍然进行代理活动的，或者被代理人知道代理人的代理行为违法不表示反对的，由被代理人和代理人负连带责任。"},{"i":68,"n":"第六十八条","txt":"委托代理人为被代理人的利益需要转托他人代理的，应当事先取得被代理人的同意。事先没有取得被代理人同意的，应当在事后及时告诉被代理人，如果被代理人不同意，由代理人对自己所转托的人的行为负民事责任，但在紧急情况下，为了保护被代理人的利益而转托他人代理的除外。"},{"i":69,"n":"第六十九条","txt":"有下列情形之一的，委托代理终止："},{"i":70,"n":"第七十条","txt":"有下列情形之一的，法定代理或者指定代理终止。"},{"i":71,"n":"第七十一条","txt":"财产所有权是指所有人依法对自己的财产享有占有、使用、收益和处分的权利。"},{"i":72,"n":"第七十二条","txt":"财产所有权的取得，不得违反法律规定。"},{"i":73,"n":"第七十三条","txt":"国家财产属于全民所有。"},{"i":74,"n":"第七十四条","txt":"劳动群众集体组织的财产属于劳动群众集体所有，包括："},{"i":75,"n":"第七十五条","txt":"公民的个人财产，包括公民的合法收入、房屋、储蓄、生活用品、文物、图书资料、林木、牲畜和法律允许公民所有的生产资料以及其他合法财产。"},{"i":76,"n":"第七十六条","txt":"公民依法享有财产继承权。"},{"i":77,"n":"第七十七条","txt":"社会团体包括宗教团体的合法财产受法律保护。"},{"i":78,"n":"第七十八条","txt":"财产可以由两个以上的公民、法人共有。"},{"i":79,"n":"第七十九条","txt":"所有人不明的埋藏物、隐藏物，归国家所有。接收单位应当对上缴的单位或者个人，给予表扬或者物质奖励。"},{"i":80,"n":"第八十条","txt":"国家所有的土地，可以依法由全民所有制单位使用，也可以依法确定由集体所有制单位使用，国家保护它的使用、收益的权利；使用单位有管理、保护、合理利用的义务。"},{"i":81,"n":"第八十一条","txt":"国家所有的森林、山岭、草原、荒地、滩涂、水面等自然资源，可以依法由全民所有制单位使用，也可以依法确定由集体所有制单位使用，国家保护它的使用、收益的权利；使用单位有管理、保护、合理利用的义务。"},{"i":82,"n":"第八十二条","txt":"全民所有制企业对国家授予它经营管理的财产依法享有经营权，受法律保护。"},{"i":83,"n":"第八十三条","txt":"不动产的相邻各方，应当按照有利生产、方便生活、团结互助、公平合理的精神，正确处理截水、排水、通行、通风、采光等方面的相邻关系。给相邻方造成妨碍或者损失的，应当停止侵害，排除妨碍，赔偿损失。"},{"i":84,"n":"第八十四条","txt":"债是按照合同的约定或者依照法律的规定，在当事人之间产生的特定的权利和义务关系，享有权利的人是债权人，负有义务的人是债务人。"},{"i":85,"n":"第八十五条","txt":"合同是当事人之间设立、变更、终止民事关系的协议。依法成立的合同，受法律保护。"},{"i":86,"n":"第八十六条","txt":"债权人为二人以上的，按照确定的份额分享权利。债务人为二人以上的，按照确定的份额分担义务。"},{"i":87,"n":"第八十七条","txt":"债权人或者债务人一方人数为二人以上的，依照法律的规定或者当事人的约定，享有连带权利的每个债权人，都有权要求债务人履行义务；负有连带义务的每个债务人，都负有清偿全部债务的义务，履行了义务的人，有权要求其他负有连带义务的人偿付他应当承担的份额。"},{"i":88,"n":"第八十八条","txt":"合同的当事人应当按照合同的约定，全部履行自己的义务。"},{"i":89,"n":"第八十九条","txt":"依照法律的规定或者按照当事人的约定，可以采用下列方式担保债务的履行："},{"i":90,"n":"第九十条","txt":"合法的借贷关系受法律保护。"},{"i":91,"n":"第九十一条","txt":"合同一方将合同的权利、义务全部或者部分转让给第三人的，应当取得合同另一方的同意，并不得牟利。依照法律规定应当由国家批准的合同，需经原批准机关批准。但是，法律另有规定或者原合同另有约定的除外。"},{"i":92,"n":"第九十二条","txt":"没有合法根据，取得不当利益，造成他人损失的，应当将取得的不当利益返还受损失的人。"},{"i":93,"n":"第九十三条","txt":"没有法定的或者约定的义务，为避免他人利益受损失进行管理或者服务的，有权要求受益人偿付由此而支付的必要费用。"},{"i":94,"n":"第九十四条","txt":"公民、法人享有著作权（版权），依法有署名、发表、出版、获得报酬等权利。"},{"i":95,"n":"第九十五条","txt":"公民、法人依法取得的专利权受法律保护。"},{"i":96,"n":"第九十六条","txt":"法人、个体工商户、个人合伙依法取得的商标专用权受法律保护。"},{"i":97,"n":"第九十七条","txt":"公民对自己的发现享有发现权。发现人有权申请领取发现证书、奖金或者其他奖励。"},{"i":98,"n":"第九十八条","txt":"公民享有生命健康权。"},{"i":99,"n":"第九十九条","txt":"公民享有姓名权，有权决定、使用和依照规定改变自己的姓名，禁止他人干涉、盗用、假冒。"},{"i":100,"n":"第一百条","txt":"公民享有肖像权，未经本人同意，不得以营利为目的使用公民的肖像。"},{"i":101,"n":"第一百零一条","txt":"公民、法人享有名誉权，公民的人格尊严受法律保护，禁止用侮辱、诽谤等方式损害公民、法人的名誉。"},{"i":102,"n":"第一百零二条","txt":"公民、法人享有荣誉权，禁止非法剥夺公民、法人的荣誉称号。"},{"i":103,"n":"第一百零三条","txt":"公民享有婚姻自主权，禁止买卖、包办婚姻和其他干涉婚姻自由的行为。"},{"i":104,"n":"第一百零四条","txt":"婚姻、家庭、老人、母亲和儿童受法律保护。"},{"i":105,"n":"第一百零五条","txt":"妇女享有同男子平等的民事权利。"},{"i":106,"n":"第一百零六条","txt":"公民、法人违反合同或者不履行其他义务的，应当承担民事责任。"},{"i":107,"n":"第一百零七条","txt":"因不可抗力不能履行合同或者造成他人损害的，不承担民事责任，法律另有规定的除外。"},{"i":108,"n":"第一百零八条","txt":"债务应当清偿。暂时无力偿还的，经债权人同意或者人民法院裁决，可以由债务人分期偿还。有能力偿还拒不偿还的，由人民法院判决强制偿还。"},{"i":109,"n":"第一百零九条","txt":"因防止、制止国家的、集体的财产或者他人的财产、人身遭受侵害而使自己受到损害的，由侵害人承担赔偿责任，受益人也可以给予适当的补偿。"},{"i":110,"n":"第一百一十条","txt":"对承担民事责任的公民、法人需要追究行政责任的，应当追究行政责任；构成犯罪的，对公民、法人的法定代表人应当依法追究刑事责任。"},{"i":111,"n":"第一百一十一条","txt":"当事人一方不履行合同义务或者履行合同义务不符合约定条件的，另一方有权要求履行或者采取补救措施，并有权要求赔偿损失。"},{"i":112,"n":"第一百一十二条","txt":"当事人一方违反合同的赔偿责任，应当相当于另一方因此所受到的损失。"},{"i":113,"n":"第一百一十三条","txt":"当事人双方都违反合同的，应当分别承担各自应负的民事责任。"},{"i":114,"n":"第一百一十四条","txt":"当事人一方因另一方违反合同受到损失的，应当及时采取措施防止损失的扩大；没有及时采取措施致使损失扩大的，无权就扩大的损失要求赔偿。"},{"i":115,"n":"第一百一十五条","txt":"合同的变更或者解除，不影响当事人要求赔偿损失的权利。"},{"i":116,"n":"第一百一十六条","txt":"当事人一方由于上级机关的原因，不能履行合同义务的，应当按照合同约定向另一方赔偿损失或者采取其他补救措施，再由上级机关对它因此受到的损失负责处理。"},{"i":117,"n":"第一百一十七条","txt":"侵占国家的、集体的财产或者他人财产的，应当返还财产，不能返还财产的，应当折价赔偿。"},{"i":118,"n":"第一百一十八条","txt":"公民、法人的著作权（版权）、专利权、商标专用权、发现权、发明权和其他科技成果权受到剽窃、篡改、假冒等侵害的，有权要求停止侵害，消除影响，赔偿损失。"},{"i":119,"n":"第一百一十九条","txt":"侵害公民身体造成伤害的，应当赔偿医疗费、因误工减少的收入、残废者生活补助费等费用；造成死亡的，并应当支付丧葬费、死者生前扶养的人必要的生活费等费用。"},{"i":120,"n":"第一百二十条","txt":"公民的姓名权、肖像权、名誉权、荣誉权受到侵害的，有权要求停止侵害，恢复名誉，消除影响，赔礼道歉，并可以要求赔偿损失。"},{"i":121,"n":"第一百二十一条","txt":"国家机关或者国家机关工作人员在执行职务中，侵犯公民、法人的合法权益造成损害的，应当承担民事责任。"},{"i":122,"n":"第一百二十二条","txt":"因产品质量不合格造成他人财产、人身损害的，产品制造者、销售者应当依法承担民事责任。运输者、仓储者对此负有责任的，产品制造者、销售者有权要求赔偿损失。"},{"i":123,"n":"第一百二十三条","txt":"从事高空、高压、易燃、易爆、剧毒、放射性、高速运输工具等对周围环境有高度危险的作业造成他人损害的，应当承担民事责任；如果能够证明损害是由受害人故意造成的，不承担民事责任。"},{"i":124,"n":"第一百二十四条","txt":"违反国家保护环境防止污染的规定，污染环境造成他人损害的，应当依法承担民事责任。"},{"i":125,"n":"第一百二十五条","txt":"在公共场所、道旁或者通道上挖坑、修缮安装地下设施等，没有设置明显标志和采取安全措施造成他人损害的，施工人应当承担民事责任。"},{"i":126,"n":"第一百二十六条","txt":"建筑物或者其他设施以及建筑物上的搁置物、悬挂物发生倒塌、脱落、坠落造成他人损害的，它的所有人或者管理人应当承担民事责任，但能够证明自己没有过错的除外。"},{"i":127,"n":"第一百二十七条","txt":"饲养的动物造成他人损害的，动物饲养人或者管理人应当承担民事责任；由于受害人的过错造成损害的，动物饲养人或者管理人不承担民事责任；由于第三人的过错造成损害的，第三人应当承担民事责任。"},{"i":128,"n":"第一百二十八条","txt":"因正当防卫造成损害的，不承担民事责任。正当防卫超过必要的限度，造成不应有的损害的，应当承担适当的民事责任。"},{"i":129,"n":"第一百二十九条","txt":"因紧急避险造成损害的，由引起险情发生的人承担民事责任。如果危险是由自然原因引起的，紧急避险人不承担民事责任或者承担适当的民事责任。因紧急避险采取措施不当或者超过必要的限度，造成不应有的损害的，紧急避险人应当承担适当的民事责任。"},{"i":130,"n":"第一百三十条","txt":"二人以上共同侵权造成他人损害的，应当承担连带责任。"},{"i":131,"n":"第一百三十一条","txt":"受害人对于损害的发生也有过错的，可以减轻侵害人的民事责任。"},{"i":132,"n":"第一百三十二条","txt":"当事人对造成损害都没有过错的，可以根据实际情况，由当事人分担民事责任。"},{"i":133,"n":"第一百三十三条","txt":"无民事行为能力人、限制民事行为能力人造成他人损害的，由监护人承担民事责任。监护人尽了监护责任的，可以适当减轻他的民事责任。"},{"i":134,"n":"第一百三十四条","txt":"承担民事责任的方式主要有："},{"i":135,"n":"第一百三十五条","txt":"向人民法院请求保护民事权利的诉讼时效期间为二年，法律另有规定的除外。"},{"i":136,"n":"第一百三十六条","txt":"下列的诉讼时效期间为一年："},{"i":137,"n":"第一百三十七条","txt":"诉讼时效期间从知道或者应当知道权利被侵害时起计算。但是，从权利被侵害之日起超过二十年的，人民法院不予保护。有特殊情况的，人民法院可以延长诉讼时效期间。"},{"i":138,"n":"第一百三十八条","txt":"超过诉讼时效期间，当事人自愿履行的，不受诉讼时效限制。"},{"i":139,"n":"第一百三十九条","txt":"在诉讼时效期间的最后六个月内，因不可抗力或者其他障碍不能行使请求权的，诉讼时效中止。从中止时效的原因消除之日起，诉讼时效期间继续计算。"},{"i":140,"n":"第一百四十条","txt":"诉讼时效因提起诉讼、当事人一方提出要求或者同意履行义务而中断。从中断时起，诉讼时效期间重新计算。"},{"i":141,"n":"第一百四十一条","txt":"法律对诉讼时效另有规定的，依照法律规定。"},{"i":142,"n":"第一百四十二条","txt":"涉外民事关系的法律适用，依照本章的规定确定。"},{"i":143,"n":"第一百四十三条","txt":"中华人民共和国公民定居国外的，他的民事行为能力可以适用定居国法律。"},{"i":144,"n":"第一百四十四条","txt":"不动产的所有权，适用不动产所在地法律。"},{"i":145,"n":"第一百四十五条","txt":"涉外合同的当事人可以选择处理合同争议所适用的法律，法律另有规定的除外。"},{"i":146,"n":"第一百四十六条","txt":"侵权行为的损害赔偿，适用侵权行为地法律。当事人双方国籍相同或者在同一国家有住所的，也可以适用当事人本国法律或者住所地法律。"},{"i":147,"n":"第一百四十七条","txt":"中华人民共和国公民和外国人结婚适用婚姻缔结地法律，离婚适用受理案件的法院所在地法律。"},{"i":148,"n":"第一百四十八条","txt":"扶养适用与被扶养人有最密切联系的国家的法律。"},{"i":149,"n":"第一百四十九条","txt":"遗产的法定继承，动产适用被继承人死亡时住所地法律，不动产适用不动产所在地法律。"},{"i":150,"n":"第一百五十条","txt":"依照本章规定适用外国法律或者国际惯例的，不得违背中华人民共和国的社会公共利益。"},{"i":151,"n":"第一百五十一条","txt":"民族自治地方的人民代表大会可以根据本法规定的原则，结合当地民族的特点，制定变通的或者补充的单行条例或者规定。自治区人民代表大会制定的，依照法律规定报全国人民代表大会常务委员会批准或者备案；自治州、自治县人民代表大会制定的，报省、自治区人民代表大会常务委员会批准。"},{"i":152,"n":"第一百五十二条","txt":"本法生效以前，经省、自治区、直辖市以上主管机关批准开办的全民所有制企业，已经向工商行政管理机关登记的，可以不再办理法人登记，即具有法人资格。"},{"i":153,"n":"第一百五十三条","txt":"本法所称的“不可抗力”，是指不能预见、不能避免并不能克服的客观情况。"},{"i":154,"n":"第一百五十四条","txt":"民法所称的期间按照公历年、月、日、小时计算。"},{"i":155,"n":"第一百五十五条","txt":"民法所称的“以上”、“以下”、“以内”、“届满”，包括本数；所称的“不满”、“以外”，不包括本数。"},{"i":156,"n":"第一百五十六条","txt":"本法自1987年1月1日起施行。"}],"minfazongze":[{"i":1,"n":"第一条","txt":"为了保护民事主体的合法权益，调整民事关系，维护社会和经济秩序，适应中国特色社会主义发展要求，弘扬社会主义核心价值观，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"民法调整平等主体的自然人、法人和非法人组织之间的人身关系和财产关系。"},{"i":3,"n":"第三条","txt":"民事主体的人身权利、财产权利以及其他合法权益受法律保护，任何组织或者个人不得侵犯。"},{"i":4,"n":"第四条","txt":"民事主体在民事活动中的法律地位一律平等。"},{"i":5,"n":"第五条","txt":"民事主体从事民事活动，应当遵循自愿原则，按照自己的意思设立、变更、终止民事法律关系。"},{"i":6,"n":"第六条","txt":"民事主体从事民事活动，应当遵循公平原则，合理确定各方的权利和义务。"},{"i":7,"n":"第七条","txt":"民事主体从事民事活动，应当遵循诚信原则，秉持诚实，恪守承诺。"},{"i":8,"n":"第八条","txt":"民事主体从事民事活动，不得违反法律，不得违背公序良俗。"},{"i":9,"n":"第九条","txt":"民事主体从事民事活动，应当有利于节约资源、保护生态环境。"},{"i":10,"n":"第十条","txt":"处理民事纠纷，应当依照法律；法律没有规定的，可以适用习惯，但是不得违背公序良俗。"},{"i":11,"n":"第十一条","txt":"其他法律对民事关系有特别规定的，依照其规定。"},{"i":12,"n":"第十二条","txt":"中华人民共和国领域内的民事活动，适用中华人民共和国法律。法律另有规定的，依照其规定。"},{"i":13,"n":"第十三条","txt":"自然人从出生时起到死亡时止，具有民事权利能力，依法享有民事权利，承担民事义务。"},{"i":14,"n":"第十四条","txt":"自然人的民事权利能力一律平等。"},{"i":15,"n":"第十五条","txt":"自然人的出生时间和死亡时间，以出生证明、死亡证明记载的时间为准；没有出生证明、死亡证明的，以户籍登记或者其他有效身份登记记载的时间为准。有其他证据足以推翻以上记载时间的，以该证据证明的时间为准。"},{"i":16,"n":"第十六条","txt":"涉及遗产继承、接受赠与等胎儿利益保护的，胎儿视为具有民事权利能力。但是胎儿娩出时为死体的，其民事权利能力自始不存在。"},{"i":17,"n":"第十七条","txt":"十八周岁以上的自然人为成年人。不满十八周岁的自然人为未成年人。"},{"i":18,"n":"第十八条","txt":"成年人为完全民事行为能力人，可以独立实施民事法律行为。"},{"i":19,"n":"第十九条","txt":"八周岁以上的未成年人为限制民事行为能力人，实施民事法律行为由其法定代理人代理或者经其法定代理人同意、追认，但是可以独立实施纯获利益的民事法律行为或者与其年龄、智力相适应的民事法律行为。"},{"i":20,"n":"第二十条","txt":"不满八周岁的未成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。"},{"i":21,"n":"第二十一条","txt":"不能辨认自己行为的成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。"},{"i":22,"n":"第二十二条","txt":"不能完全辨认自己行为的成年人为限制民事行为能力人，实施民事法律行为由其法定代理人代理或者经其法定代理人同意、追认，但是可以独立实施纯获利益的民事法律行为或者与其智力、精神健康状况相适应的民事法律行为。"},{"i":23,"n":"第二十三条","txt":"无民事行为能力人、限制民事行为能力人的监护人是其法定代理人。"},{"i":24,"n":"第二十四条","txt":"不能辨认或者不能完全辨认自己行为的成年人，其利害关系人或者有关组织，可以向人民法院申请认定该成年人为无民事行为能力人或者限制民事行为能力人。"},{"i":25,"n":"第二十五条","txt":"自然人以户籍登记或者其他有效身份登记记载的居所为住所；经常居所与住所不一致的，经常居所视为住所。"},{"i":26,"n":"第二十六条","txt":"父母对未成年子女负有抚养、教育和保护的义务。"},{"i":27,"n":"第二十七条","txt":"父母是未成年子女的监护人。"},{"i":28,"n":"第二十八条","txt":"无民事行为能力或者限制民事行为能力的成年人，由下列有监护能力的人按顺序担任监护人："},{"i":29,"n":"第二十九条","txt":"被监护人的父母担任监护人的，可以通过遗嘱指定监护人。"},{"i":30,"n":"第三十条","txt":"依法具有监护资格的人之间可以协议确定监护人。协议确定监护人应当尊重被监护人的真实意愿。"},{"i":31,"n":"第三十一条","txt":"对监护人的确定有争议的，由被监护人住所地的居民委员会、村民委员会或者民政部门指定监护人，有关当事人对指定不服的，可以向人民法院申请指定监护人；有关当事人也可以直接向人民法院申请指定监护人。"},{"i":32,"n":"第三十二条","txt":"没有依法具有监护资格的人的，监护人由民政部门担任，也可以由具备履行监护职责条件的被监护人住所地的居民委员会、村民委员会担任。"},{"i":33,"n":"第三十三条","txt":"具有完全民事行为能力的成年人，可以与其近亲属、其他愿意担任监护人的个人或者组织事先协商，以书面形式确定自己的监护人。协商确定的监护人在该成年人丧失或者部分丧失民事行为能力时，履行监护职责。"},{"i":34,"n":"第三十四条","txt":"监护人的职责是代理被监护人实施民事法律行为，保护被监护人的人身权利、财产权利以及其他合法权益等。"},{"i":35,"n":"第三十五条","txt":"监护人应当按照最有利于被监护人的原则履行监护职责。监护人除为维护被监护人利益外，不得处分被监护人的财产。"},{"i":36,"n":"第三十六条","txt":"监护人有下列情形之一的，人民法院根据有关个人或者组织的申请，撤销其监护人资格，安排必要的临时监护措施，并按照最有利于被监护人的原则依法指定监护人："},{"i":37,"n":"第三十七条","txt":"依法负担被监护人抚养费、赡养费、扶养费的父母、子女、配偶等，被人民法院撤销监护人资格后，应当继续履行负担的义务。"},{"i":38,"n":"第三十八条","txt":"被监护人的父母或者子女被人民法院撤销监护人资格后，除对被监护人实施故意犯罪的外，确有悔改表现的，经其申请，人民法院可以在尊重被监护人真实意愿的前提下，视情况恢复其监护人资格，人民法院指定的监护人与被监护人的监护关系同时终止。"},{"i":39,"n":"第三十九条","txt":"有下列情形之一的，监护关系终止："},{"i":40,"n":"第四十条","txt":"自然人下落不明满二年的，利害关系人可以向人民法院申请宣告该自然人为失踪人。"},{"i":41,"n":"第四十一条","txt":"自然人下落不明的时间从其失去音讯之日起计算。战争期间下落不明的，下落不明的时间自战争结束之日或者有关机关确定的下落不明之日起计算。"},{"i":42,"n":"第四十二条","txt":"失踪人的财产由其配偶、成年子女、父母或者其他愿意担任财产代管人的人代管。"},{"i":43,"n":"第四十三条","txt":"财产代管人应当妥善管理失踪人的财产，维护其财产权益。"},{"i":44,"n":"第四十四条","txt":"财产代管人不履行代管职责、侵害失踪人财产权益或者丧失代管能力的，失踪人的利害关系人可以向人民法院申请变更财产代管人。"},{"i":45,"n":"第四十五条","txt":"失踪人重新出现，经本人或者利害关系人申请，人民法院应当撤销失踪宣告。"},{"i":46,"n":"第四十六条","txt":"自然人有下列情形之一的，利害关系人可以向人民法院申请宣告该自然人死亡："},{"i":47,"n":"第四十七条","txt":"对同一自然人，有的利害关系人申请宣告死亡，有的利害关系人申请宣告失踪，符合本法规定的宣告死亡条件的，人民法院应当宣告死亡。"},{"i":48,"n":"第四十八条","txt":"被宣告死亡的人，人民法院宣告死亡的判决作出之日视为其死亡的日期；因意外事件下落不明宣告死亡的，意外事件发生之日视为其死亡的日期。"},{"i":49,"n":"第四十九条","txt":"自然人被宣告死亡但是并未死亡的，不影响该自然人在被宣告死亡期间实施的民事法律行为的效力。"},{"i":50,"n":"第五十条","txt":"被宣告死亡的人重新出现，经本人或者利害关系人申请，人民法院应当撤销死亡宣告。"},{"i":51,"n":"第五十一条","txt":"被宣告死亡的人的婚姻关系，自死亡宣告之日起消灭。死亡宣告被撤销的，婚姻关系自撤销死亡宣告之日起自行恢复，但是其配偶再婚或者向婚姻登记机关书面声明不愿意恢复的除外。"},{"i":52,"n":"第五十二条","txt":"被宣告死亡的人在被宣告死亡期间，其子女被他人依法收养的，在死亡宣告被撤销后，不得以未经本人同意为由主张收养关系无效。"},{"i":53,"n":"第五十三条","txt":"被撤销死亡宣告的人有权请求依照继承法取得其财产的民事主体返还财产。无法返还的，应当给予适当补偿。"},{"i":54,"n":"第五十四条","txt":"自然人从事工商业经营，经依法登记，为个体工商户。个体工商户可以起字号。"},{"i":55,"n":"第五十五条","txt":"农村集体经济组织的成员，依法取得农村土地承包经营权，从事家庭承包经营的，为农村承包经营户。"},{"i":56,"n":"第五十六条","txt":"个体工商户的债务，个人经营的，以个人财产承担；家庭经营的，以家庭财产承担；无法区分的，以家庭财产承担。"},{"i":57,"n":"第五十七条","txt":"法人是具有民事权利能力和民事行为能力，依法独立享有民事权利和承担民事义务的组织。"},{"i":58,"n":"第五十八条","txt":"法人应当依法成立。"},{"i":59,"n":"第五十九条","txt":"法人的民事权利能力和民事行为能力，从法人成立时产生，到法人终止时消灭。"},{"i":60,"n":"第六十条","txt":"法人以其全部财产独立承担民事责任。"},{"i":61,"n":"第六十一条","txt":"依照法律或者法人章程的规定，代表法人从事民事活动的负责人，为法人的法定代表人。"},{"i":62,"n":"第六十二条","txt":"法定代表人因执行职务造成他人损害的，由法人承担民事责任。"},{"i":63,"n":"第六十三条","txt":"法人以其主要办事机构所在地为住所。依法需要办理法人登记的，应当将主要办事机构所在地登记为住所。"},{"i":64,"n":"第六十四条","txt":"法人存续期间登记事项发生变化的，应当依法向登记机关申请变更登记。"},{"i":65,"n":"第六十五条","txt":"法人的实际情况与登记的事项不一致的，不得对抗善意相对人。"},{"i":66,"n":"第六十六条","txt":"登记机关应当依法及时公示法人登记的有关信息。"},{"i":67,"n":"第六十七条","txt":"法人合并的，其权利和义务由合并后的法人享有和承担。"},{"i":68,"n":"第六十八条","txt":"有下列原因之一并依法完成清算、注销登记的，法人终止："},{"i":69,"n":"第六十九条","txt":"有下列情形之一的，法人解散："},{"i":70,"n":"第七十条","txt":"法人解散的，除合并或者分立的情形外，清算义务人应当及时组成清算组进行清算。"},{"i":71,"n":"第七十一条","txt":"法人的清算程序和清算组职权，依照有关法律的规定；没有规定的，参照适用公司法的有关规定。"},{"i":72,"n":"第七十二条","txt":"清算期间法人存续，但是不得从事与清算无关的活动。"},{"i":73,"n":"第七十三条","txt":"法人被宣告破产的，依法进行破产清算并完成法人注销登记时，法人终止。"},{"i":74,"n":"第七十四条","txt":"法人可以依法设立分支机构。法律、行政法规规定分支机构应当登记的，依照其规定。"},{"i":75,"n":"第七十五条","txt":"设立人为设立法人从事的民事活动，其法律后果由法人承受；法人未成立的，其法律后果由设立人承受，设立人为二人以上的，享有连带债权，承担连带债务。"},{"i":76,"n":"第七十六条","txt":"以取得利润并分配给股东等出资人为目的成立的法人，为营利法人。"},{"i":77,"n":"第七十七条","txt":"营利法人经依法登记成立。"},{"i":78,"n":"第七十八条","txt":"依法设立的营利法人，由登记机关发给营利法人营业执照。营业执照签发日期为营利法人的成立日期。"},{"i":79,"n":"第七十九条","txt":"设立营利法人应当依法制定法人章程。"},{"i":80,"n":"第八十条","txt":"营利法人应当设权力机构。"},{"i":81,"n":"第八十一条","txt":"营利法人应当设执行机构。"},{"i":82,"n":"第八十二条","txt":"营利法人设监事会或者监事等监督机构的，监督机构依法行使检查法人财务，监督执行机构成员、高级管理人员执行法人职务的行为，以及法人章程规定的其他职权。"},{"i":83,"n":"第八十三条","txt":"营利法人的出资人不得滥用出资人权利损害法人或者其他出资人的利益。滥用出资人权利给法人或者其他出资人造成损失的，应当依法承担民事责任。"},{"i":84,"n":"第八十四条","txt":"营利法人的控股出资人、实际控制人、董事、监事、高级管理人员不得利用其关联关系损害法人的利益。利用关联关系给法人造成损失的，应当承担赔偿责任。"},{"i":85,"n":"第八十五条","txt":"营利法人的权力机构、执行机构作出决议的会议召集程序、表决方式违反法律、行政法规、法人章程，或者决议内容违反法人章程的，营利法人的出资人可以请求人民法院撤销该决议，但是营利法人依据该决议与善意相对人形成的民事法律关系不受影响。"},{"i":86,"n":"第八十六条","txt":"营利法人从事经营活动，应当遵守商业道德，维护交易安全，接受政府和社会的监督，承担社会责任。"},{"i":87,"n":"第八十七条","txt":"为公益目的或者其他非营利目的成立，不向出资人、设立人或者会员分配所取得利润的法人，为非营利法人。"},{"i":88,"n":"第八十八条","txt":"具备法人条件，为适应经济社会发展需要，提供公益服务设立的事业单位，经依法登记成立，取得事业单位法人资格；依法不需要办理法人登记的，从成立之日起，具有事业单位法人资格。"},{"i":89,"n":"第八十九条","txt":"事业单位法人设理事会的，除法律另有规定外，理事会为其决策机构。事业单位法人的法定代表人依照法律、行政法规或者法人章程的规定产生。"},{"i":90,"n":"第九十条","txt":"具备法人条件，基于会员共同意愿，为公益目的或者会员共同利益等非营利目的设立的社会团体，经依法登记成立，取得社会团体法人资格；依法不需要办理法人登记的，从成立之日起，具有社会团体法人资格。"},{"i":91,"n":"第九十一条","txt":"设立社会团体法人应当依法制定法人章程。"},{"i":92,"n":"第九十二条","txt":"具备法人条件，为公益目的以捐助财产设立的基金会、社会服务机构等，经依法登记成立，取得捐助法人资格。"},{"i":93,"n":"第九十三条","txt":"设立捐助法人应当依法制定法人章程。"},{"i":94,"n":"第九十四条","txt":"捐助人有权向捐助法人查询捐助财产的使用、管理情况，并提出意见和建议，捐助法人应当及时、如实答复。"},{"i":95,"n":"第九十五条","txt":"为公益目的成立的非营利法人终止时，不得向出资人、设立人或者会员分配剩余财产。剩余财产应当按照法人章程的规定或者权力机构的决议用于公益目的；无法按照法人章程的规定或者权力机构的决议处理的，由主管机关主持转给宗旨相同或者相近的法人，并向社会公告。"},{"i":96,"n":"第九十六条","txt":"本节规定的机关法人、农村集体经济组织法人、城镇农村的合作经济组织法人、基层群众性自治组织法人，为特别法人。"},{"i":97,"n":"第九十七条","txt":"有独立经费的机关和承担行政职能的法定机构从成立之日起，具有机关法人资格，可以从事为履行职能所需要的民事活动。"},{"i":98,"n":"第九十八条","txt":"机关法人被撤销的，法人终止，其民事权利和义务由继任的机关法人享有和承担；没有继任的机关法人的，由作出撤销决定的机关法人享有和承担。"},{"i":99,"n":"第九十九条","txt":"农村集体经济组织依法取得法人资格。"},{"i":100,"n":"第一百条","txt":"城镇农村的合作经济组织依法取得法人资格。"},{"i":101,"n":"第一百零一条","txt":"居民委员会、村民委员会具有基层群众性自治组织法人资格，可以从事为履行职能所需要的民事活动。"},{"i":102,"n":"第一百零二条","txt":"非法人组织是不具有法人资格，但是能够依法以自己的名义从事民事活动的组织。"},{"i":103,"n":"第一百零三条","txt":"非法人组织应当依照法律的规定登记。"},{"i":104,"n":"第一百零四条","txt":"非法人组织的财产不足以清偿债务的，其出资人或者设立人承担无限责任。法律另有规定的，依照其规定。"},{"i":105,"n":"第一百零五条","txt":"非法人组织可以确定一人或者数人代表该组织从事民事活动。"},{"i":106,"n":"第一百零六条","txt":"有下列情形之一的，非法人组织解散："},{"i":107,"n":"第一百零七条","txt":"非法人组织解散的，应当依法进行清算。"},{"i":108,"n":"第一百零八条","txt":"非法人组织除适用本章规定外，参照适用本法第三章第一节的有关规定。"},{"i":109,"n":"第一百零九条","txt":"自然人的人身自由、人格尊严受法律保护。"},{"i":110,"n":"第一百一十条","txt":"自然人享有生命权、身体权、健康权、姓名权、肖像权、名誉权、荣誉权、隐私权、婚姻自主权等权利。"},{"i":111,"n":"第一百一十一条","txt":"自然人的个人信息受法律保护。任何组织和个人需要获取他人个人信息的，应当依法取得并确保信息安全，不得非法收集、使用、加工、传输他人个人信息，不得非法买卖、提供或者公开他人个人信息。"},{"i":112,"n":"第一百一十二条","txt":"自然人因婚姻、家庭关系等产生的人身权利受法律保护。"},{"i":113,"n":"第一百一十三条","txt":"民事主体的财产权利受法律平等保护。"},{"i":114,"n":"第一百一十四条","txt":"民事主体依法享有物权。"},{"i":115,"n":"第一百一十五条","txt":"物包括不动产和动产。法律规定权利作为物权客体的，依照其规定。"},{"i":116,"n":"第一百一十六条","txt":"物权的种类和内容，由法律规定。"},{"i":117,"n":"第一百一十七条","txt":"为了公共利益的需要，依照法律规定的权限和程序征收、征用不动产或者动产的，应当给予公平、合理的补偿。"},{"i":118,"n":"第一百一十八条","txt":"民事主体依法享有债权。"},{"i":119,"n":"第一百一十九条","txt":"依法成立的合同，对当事人具有法律约束力。"},{"i":120,"n":"第一百二十条","txt":"民事权益受到侵害的，被侵权人有权请求侵权人承担侵权责任。"},{"i":121,"n":"第一百二十一条","txt":"没有法定的或者约定的义务，为避免他人利益受损失而进行管理的人，有权请求受益人偿还由此支出的必要费用。"},{"i":122,"n":"第一百二十二条","txt":"因他人没有法律根据，取得不当利益，受损失的人有权请求其返还不当利益。"},{"i":123,"n":"第一百二十三条","txt":"民事主体依法享有知识产权。"},{"i":124,"n":"第一百二十四条","txt":"自然人依法享有继承权。"},{"i":125,"n":"第一百二十五条","txt":"民事主体依法享有股权和其他投资性权利。"},{"i":126,"n":"第一百二十六条","txt":"民事主体享有法律规定的其他民事权利和利益。"},{"i":127,"n":"第一百二十七条","txt":"法律对数据、网络虚拟财产的保护有规定的，依照其规定。"},{"i":128,"n":"第一百二十八条","txt":"法律对未成年人、老年人、残疾人、妇女、消费者等的民事权利保护有特别规定的，依照其规定。"},{"i":129,"n":"第一百二十九条","txt":"民事权利可以依据民事法律行为、事实行为、法律规定的事件或者法律规定的其他方式取得。"},{"i":130,"n":"第一百三十条","txt":"民事主体按照自己的意愿依法行使民事权利，不受干涉。"},{"i":131,"n":"第一百三十一条","txt":"民事主体行使权利时，应当履行法律规定的和当事人约定的义务。"},{"i":132,"n":"第一百三十二条","txt":"民事主体不得滥用民事权利损害国家利益、社会公共利益或者他人合法权益。"},{"i":133,"n":"第一百三十三条","txt":"民事法律行为是民事主体通过意思表示设立、变更、终止民事法律关系的行为。"},{"i":134,"n":"第一百三十四条","txt":"民事法律行为可以基于双方或者多方的意思表示一致成立，也可以基于单方的意思表示成立。"},{"i":135,"n":"第一百三十五条","txt":"民事法律行为可以采用书面形式、口头形式或者其他形式；法律、行政法规规定或者当事人约定采用特定形式的，应当采用特定形式。"},{"i":136,"n":"第一百三十六条","txt":"民事法律行为自成立时生效，但是法律另有规定或者当事人另有约定的除外。"},{"i":137,"n":"第一百三十七条","txt":"以对话方式作出的意思表示，相对人知道其内容时生效。"},{"i":138,"n":"第一百三十八条","txt":"无相对人的意思表示，表示完成时生效。法律另有规定的，依照其规定。"},{"i":139,"n":"第一百三十九条","txt":"以公告方式作出的意思表示，公告发布时生效。"},{"i":140,"n":"第一百四十条","txt":"行为人可以明示或者默示作出意思表示。"},{"i":141,"n":"第一百四十一条","txt":"行为人可以撤回意思表示。撤回意思表示的通知应当在意思表示到达相对人前或者与意思表示同时到达相对人。"},{"i":142,"n":"第一百四十二条","txt":"有相对人的意思表示的解释，应当按照所使用的词句，结合相关条款、行为的性质和目的、习惯以及诚信原则，确定意思表示的含义。"},{"i":143,"n":"第一百四十三条","txt":"具备下列条件的民事法律行为有效："},{"i":144,"n":"第一百四十四条","txt":"无民事行为能力人实施的民事法律行为无效。"},{"i":145,"n":"第一百四十五条","txt":"限制民事行为能力人实施的纯获利益的民事法律行为或者与其年龄、智力、精神健康状况相适应的民事法律行为有效；实施的其他民事法律行为经法定代理人同意或者追认后有效。"},{"i":146,"n":"第一百四十六条","txt":"行为人与相对人以虚假的意思表示实施的民事法律行为无效。"},{"i":147,"n":"第一百四十七条","txt":"基于重大误解实施的民事法律行为，行为人有权请求人民法院或者仲裁机构予以撤销。"},{"i":148,"n":"第一百四十八条","txt":"一方以欺诈手段，使对方在违背真实意思的情况下实施的民事法律行为，受欺诈方有权请求人民法院或者仲裁机构予以撤销。"},{"i":149,"n":"第一百四十九条","txt":"第三人实施欺诈行为，使一方在违背真实意思的情况下实施的民事法律行为，对方知道或者应当知道该欺诈行为的，受欺诈方有权请求人民法院或者仲裁机构予以撤销。"},{"i":150,"n":"第一百五十条","txt":"一方或者第三人以胁迫手段，使对方在违背真实意思的情况下实施的民事法律行为，受胁迫方有权请求人民法院或者仲裁机构予以撤销。"},{"i":151,"n":"第一百五十一条","txt":"一方利用对方处于危困状态、缺乏判断能力等情形，致使民事法律行为成立时显失公平的，受损害方有权请求人民法院或者仲裁机构予以撤销。"},{"i":152,"n":"第一百五十二条","txt":"有下列情形之一的，撤销权消灭："},{"i":153,"n":"第一百五十三条","txt":"违反法律、行政法规的强制性规定的民事法律行为无效，但是该强制性规定不导致该民事法律行为无效的除外。"},{"i":154,"n":"第一百五十四条","txt":"行为人与相对人恶意串通，损害他人合法权益的民事法律行为无效。"},{"i":155,"n":"第一百五十五条","txt":"无效的或者被撤销的民事法律行为自始没有法律约束力。"},{"i":156,"n":"第一百五十六条","txt":"民事法律行为部分无效，不影响其他部分效力的，其他部分仍然有效。"},{"i":157,"n":"第一百五十七条","txt":"民事法律行为无效、被撤销或者确定不发生效力后，行为人因该行为取得的财产，应当予以返还；不能返还或者没有必要返还的，应当折价补偿。有过错的一方应当赔偿对方由此所受到的损失；各方都有过错的，应当各自承担相应的责任。法律另有规定的，依照其规定。"},{"i":158,"n":"第一百五十八条","txt":"民事法律行为可以附条件，但是按照其性质不得附条件的除外。附生效条件的民事法律行为，自条件成就时生效。附解除条件的民事法律行为，自条件成就时失效。"},{"i":159,"n":"第一百五十九条","txt":"附条件的民事法律行为，当事人为自己的利益不正当地阻止条件成就的，视为条件已成就；不正当地促成条件成就的，视为条件不成就。"},{"i":160,"n":"第一百六十条","txt":"民事法律行为可以附期限，但是按照其性质不得附期限的除外。附生效期限的民事法律行为，自期限届至时生效。附终止期限的民事法律行为，自期限届满时失效。"},{"i":161,"n":"第一百六十一条","txt":"民事主体可以通过代理人实施民事法律行为。"},{"i":162,"n":"第一百六十二条","txt":"代理人在代理权限内，以被代理人名义实施的民事法律行为，对被代理人发生效力。"},{"i":163,"n":"第一百六十三条","txt":"代理包括委托代理和法定代理。"},{"i":164,"n":"第一百六十四条","txt":"代理人不履行或者不完全履行职责，造成被代理人损害的，应当承担民事责任。"},{"i":165,"n":"第一百六十五条","txt":"委托代理授权采用书面形式的，授权委托书应当载明代理人的姓名或者名称、代理事项、权限和期间，并由被代理人签名或者盖章。"},{"i":166,"n":"第一百六十六条","txt":"数人为同一代理事项的代理人的，应当共同行使代理权，但是当事人另有约定的除外。"},{"i":167,"n":"第一百六十七条","txt":"代理人知道或者应当知道代理事项违法仍然实施代理行为，或者被代理人知道或者应当知道代理人的代理行为违法未作反对表示的，被代理人和代理人应当承担连带责任。"},{"i":168,"n":"第一百六十八条","txt":"代理人不得以被代理人的名义与自己实施民事法律行为，但是被代理人同意或者追认的除外。"},{"i":169,"n":"第一百六十九条","txt":"代理人需要转委托第三人代理的，应当取得被代理人的同意或者追认。"},{"i":170,"n":"第一百七十条","txt":"执行法人或者非法人组织工作任务的人员，就其职权范围内的事项，以法人或者非法人组织的名义实施民事法律行为，对法人或者非法人组织发生效力。"},{"i":171,"n":"第一百七十一条","txt":"行为人没有代理权、超越代理权或者代理权终止后，仍然实施代理行为，未经被代理人追认的，对被代理人不发生效力。"},{"i":172,"n":"第一百七十二条","txt":"行为人没有代理权、超越代理权或者代理权终止后，仍然实施代理行为，相对人有理由相信行为人有代理权的，代理行为有效。"},{"i":173,"n":"第一百七十三条","txt":"有下列情形之一的，委托代理终止："},{"i":174,"n":"第一百七十四条","txt":"被代理人死亡后，有下列情形之一的，委托代理人实施的代理行为有效："},{"i":175,"n":"第一百七十五条","txt":"有下列情形之一的，法定代理终止："},{"i":176,"n":"第一百七十六条","txt":"民事主体依照法律规定和当事人约定，履行民事义务，承担民事责任。"},{"i":177,"n":"第一百七十七条","txt":"二人以上依法承担按份责任，能够确定责任大小的，各自承担相应的责任；难以确定责任大小的，平均承担责任。"},{"i":178,"n":"第一百七十八条","txt":"二人以上依法承担连带责任的，权利人有权请求部分或者全部连带责任人承担责任。"},{"i":179,"n":"第一百七十九条","txt":"承担民事责任的方式主要有："},{"i":180,"n":"第一百八十条","txt":"因不可抗力不能履行民事义务的，不承担民事责任。法律另有规定的，依照其规定。"},{"i":181,"n":"第一百八十一条","txt":"因正当防卫造成损害的，不承担民事责任。"},{"i":182,"n":"第一百八十二条","txt":"因紧急避险造成损害的，由引起险情发生的人承担民事责任。"},{"i":183,"n":"第一百八十三条","txt":"因保护他人民事权益使自己受到损害的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任，受害人请求补偿的，受益人应当给予适当补偿。"},{"i":184,"n":"第一百八十四条","txt":"因自愿实施紧急救助行为造成受助人损害的，救助人不承担民事责任。"},{"i":185,"n":"第一百八十五条","txt":"侵害英雄烈士等的姓名、肖像、名誉、荣誉，损害社会公共利益的，应当承担民事责任。"},{"i":186,"n":"第一百八十六条","txt":"因当事人一方的违约行为，损害对方人身权益、财产权益的，受损害方有权选择请求其承担违约责任或者侵权责任。"},{"i":187,"n":"第一百八十七条","txt":"民事主体因同一行为应当承担民事责任、行政责任和刑事责任的，承担行政责任或者刑事责任不影响承担民事责任；民事主体的财产不足以支付的，优先用于承担民事责任。"},{"i":188,"n":"第一百八十八条","txt":"向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定的，依照其规定。"},{"i":189,"n":"第一百八十九条","txt":"当事人约定同一债务分期履行的，诉讼时效期间自最后一期履行期限届满之日起计算。"},{"i":190,"n":"第一百九十条","txt":"无民事行为能力人或者限制民事行为能力人对其法定代理人的请求权的诉讼时效期间，自该法定代理终止之日起计算。"},{"i":191,"n":"第一百九十一条","txt":"未成年人遭受性侵害的损害赔偿请求权的诉讼时效期间，自受害人年满十八周岁之日起计算。"},{"i":192,"n":"第一百九十二条","txt":"诉讼时效期间届满的，义务人可以提出不履行义务的抗辩。"},{"i":193,"n":"第一百九十三条","txt":"人民法院不得主动适用诉讼时效的规定。"},{"i":194,"n":"第一百九十四条","txt":"在诉讼时效期间的最后六个月内，因下列障碍，不能行使请求权的，诉讼时效中止："},{"i":195,"n":"第一百九十五条","txt":"有下列情形之一的，诉讼时效中断，从中断、有关程序终结时起，诉讼时效期间重新计算："},{"i":196,"n":"第一百九十六条","txt":"下列请求权不适用诉讼时效的规定："},{"i":197,"n":"第一百九十七条","txt":"诉讼时效的期间、计算方法以及中止、中断的事由由法律规定，当事人约定无效。"},{"i":198,"n":"第一百九十八条","txt":"法律对仲裁时效有规定的，依照其规定；没有规定的，适用诉讼时效的规定。"},{"i":199,"n":"第一百九十九条","txt":"法律规定或者当事人约定的撤销权、解除权等权利的存续期间，除法律另有规定外，自权利人知道或者应当知道权利产生之日起计算，不适用有关诉讼时效中止、中断和延长的规定。存续期间届满，撤销权、解除权等权利消灭。"},{"i":200,"n":"第二百条","txt":"民法所称的期间按照公历年、月、日、小时计算。"},{"i":201,"n":"第二百零一条","txt":"按照年、月、日计算期间的，开始的当日不计入，自下一日开始计算。"},{"i":202,"n":"第二百零二条","txt":"按照年、月计算期间的，到期月的对应日为期间的最后一日；没有对应日的，月末日为期间的最后一日。"},{"i":203,"n":"第二百零三条","txt":"期间的最后一日是法定休假日的，以法定休假日结束的次日为期间的最后一日。"},{"i":204,"n":"第二百零四条","txt":"期间的计算方法依照本法的规定，但是法律另有规定或者当事人另有约定的除外。"},{"i":205,"n":"第二百零五条","txt":"民法所称的“以上”“以下”“以内”“届满”，包括本数；所称的“不满”“超过”“以外”，不包括本数。"},{"i":206,"n":"第二百零六条","txt":"本法自2017年10月1日起施行。"}],"qingjieshengchancujinfa":[{"i":1,"n":"第一条","txt":"为了促进清洁生产，提高资源利用效率，减少和避免污染物的产生，保护和改善环境，保障人体健康，促进经济与社会可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称清洁生产，是指不断采取改进设计、使用清洁的能源和原料、采用先进的工艺技术与设备、改善管理、综合利用等措施，从源头削减污染，提高资源利用效率，减少或者避免生产、服务和产品使用过程中污染物的产生和排放，以减轻或者消除对人类健康和环境的危害。"},{"i":3,"n":"第三条","txt":"在中华人民共和国领域内，从事生产和服务活动的单位以及从事相关管理活动的部门依照本法规定，组织、实施清洁生产。"},{"i":4,"n":"第四条","txt":"国家鼓励和促进清洁生产。国务院和县级以上地方人民政府，应当将清洁生产促进工作纳入国民经济和社会发展规划、年度计划以及环境保护、资源利用、产业发展、区域开发等规划。"},{"i":5,"n":"第五条","txt":"国务院清洁生产综合协调部门负责组织、协调全国的清洁生产促进工作。国务院环境保护、工业、科学技术、财政部门和其他有关部门，按照各自的职责，负责有关的清洁生产促进工作。"},{"i":6,"n":"第六条","txt":"国家鼓励开展有关清洁生产的科学研究、技术开发和国际合作，组织宣传、普及清洁生产知识，推广清洁生产技术。"},{"i":7,"n":"第七条","txt":"国务院应当制定有利于实施清洁生产的财政税收政策。"},{"i":8,"n":"第八条","txt":"国务院清洁生产综合协调部门会同国务院环境保护、工业、科学技术部门和其他有关部门，根据国民经济和社会发展规划及国家节约资源、降低能源消耗、减少重点污染物排放的要求，编制国家清洁生产推行规划，报经国务院批准后及时公布。"},{"i":9,"n":"第九条","txt":"中央预算应当加强对清洁生产促进工作的资金投入，包括中央财政清洁生产专项资金和中央预算安排的其他清洁生产资金，用于支持国家清洁生产推行规划确定的重点领域、重点行业、重点工程实施清洁生产及其技术推广工作，以及生态脆弱地区实施清洁生产的项目。中央预算用于支持清洁生产促进工作的资金使用的具体办法，由国务院财政部门、清洁生产综合协调部门会同国务院有关部门制定。"},{"i":10,"n":"第十条","txt":"国务院和省、自治区、直辖市人民政府的有关部门，应当组织和支持建立促进清洁生产信息系统和技术咨询服务体系，向社会提供有关清洁生产方法和技术、可再生利用的废物供求以及清洁生产政策等方面的信息和服务。"},{"i":11,"n":"第十一条","txt":"国务院清洁生产综合协调部门会同国务院环境保护、工业、科学技术、建设、农业等有关部门定期发布清洁生产技术、工艺、设备和产品导向目录。"},{"i":12,"n":"第十二条","txt":"国家对浪费资源和严重污染环境的落后生产技术、工艺、设备和产品实行限期淘汰制度。国务院有关部门按照职责分工，制定并发布限期淘汰的生产技术、工艺、设备以及产品的名录。"},{"i":13,"n":"第十三条","txt":"国务院有关部门可以根据需要批准设立节能、节水、废物再生利用等环境与资源保护方面的产品标志，并按照国家规定制定相应标准。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府科学技术部门和其他有关部门，应当指导和支持清洁生产技术和有利于环境与资源保护的产品的研究、开发以及清洁生产技术的示范和推广工作。"},{"i":15,"n":"第十五条","txt":"国务院教育部门，应当将清洁生产技术和管理课程纳入有关高等教育、职业教育和技术培训体系。"},{"i":16,"n":"第十六条","txt":"各级人民政府应当优先采购节能、节水、废物再生利用等有利于环境与资源保护的产品。"},{"i":17,"n":"第十七条","txt":"省、自治区、直辖市人民政府负责清洁生产综合协调的部门、环境保护部门，根据促进清洁生产工作的需要，在本地区主要媒体上公布未达到能源消耗控制指标、重点污染物排放控制指标的企业的名单，为公众监督企业实施清洁生产提供依据。"},{"i":18,"n":"第十八条","txt":"新建、改建和扩建项目应当进行环境影响评价，对原料使用、资源消耗、资源综合利用以及污染物产生与处置等进行分析论证，优先采用资源利用率高以及污染物产生量少的清洁生产技术、工艺和设备。"},{"i":19,"n":"第十九条","txt":"企业在进行技术改造过程中，应当采取以下清洁生产措施："},{"i":20,"n":"第二十条","txt":"产品和包装物的设计，应当考虑其在生命周期中对人类健康和环境的影响，优先选择无毒、无害、易于降解或者便于回收利用的方案。"},{"i":21,"n":"第二十一条","txt":"生产大型机电设备、机动运输工具以及国务院工业部门指定的其他产品的企业，应当按照国务院标准化部门或者其授权机构制定的技术规范，在产品的主体构件上注明材料成分的标准牌号。"},{"i":22,"n":"第二十二条","txt":"农业生产者应当科学地使用化肥、农药、农用薄膜和饲料添加剂，改进种植和养殖技术，实现农产品的优质、无害和农业生产废物的资源化，防止农业环境污染。"},{"i":23,"n":"第二十三条","txt":"餐饮、娱乐、宾馆等服务性企业，应当采用节能、节水和其他有利于环境保护的技术和设备，减少使用或者不使用浪费资源、污染环境的消费品。"},{"i":24,"n":"第二十四条","txt":"建筑工程应当采用节能、节水等有利于环境与资源保护的建筑设计方案、建筑和装修材料、建筑构配件及设备。"},{"i":25,"n":"第二十五条","txt":"矿产资源的勘查、开采，应当采用有利于合理利用资源、保护环境和防止污染的勘查、开采方法和工艺技术，提高资源利用水平。"},{"i":26,"n":"第二十六条","txt":"企业应当在经济技术可行的条件下对生产和服务过程中产生的废物、余热等自行回收利用或者转让给有条件的其他企业和个人利用。"},{"i":27,"n":"第二十七条","txt":"企业应当对生产和服务过程中的资源消耗以及废物的产生情况进行监测，并根据需要对生产和服务实施清洁生产审核。"},{"i":28,"n":"第二十八条","txt":"本法第二十七条第二款规定以外的企业，可以自愿与清洁生产综合协调部门和环境保护部门签订进一步节约资源、削减污染物排放量的协议。该清洁生产综合协调部门和环境保护部门应当在本地区主要媒体上公布该企业的名称以及节约资源、防治污染的成果。"},{"i":29,"n":"第二十九条","txt":"企业可以根据自愿原则，按照国家有关环境管理体系等认证的规定，委托经国务院认证认可监督管理部门认可的认证机构进行认证，提高清洁生产水平。"},{"i":30,"n":"第三十条","txt":"国家建立清洁生产表彰奖励制度。对在清洁生产工作中做出显著成绩的单位和个人，由人民政府给予表彰和奖励。"},{"i":31,"n":"第三十一条","txt":"对从事清洁生产研究、示范和培训，实施国家清洁生产重点技术改造项目和本法第二十八条规定的自愿节约资源、削减污染物排放量协议中载明的技术改造项目，由县级以上人民政府给予资金支持。"},{"i":32,"n":"第三十二条","txt":"在依照国家规定设立的中小企业发展基金中，应当根据需要安排适当数额用于支持中小企业实施清洁生产。"},{"i":33,"n":"第三十三条","txt":"依法利用废物和从废物中回收原料生产产品的，按照国家规定享受税收优惠。"},{"i":34,"n":"第三十四条","txt":"企业用于清洁生产审核和培训的费用，可以列入企业经营成本。"},{"i":35,"n":"第三十五条","txt":"清洁生产综合协调部门或者其他有关部门未依照本法规定履行职责的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":36,"n":"第三十六条","txt":"违反本法第十七条第二款规定，未按照规定公布能源消耗或者重点污染物产生、排放情况的，由县级以上地方人民政府负责清洁生产综合协调的部门、环境保护部门按照职责分工责令公布，可以处十万元以下的罚款。"},{"i":37,"n":"第三十七条","txt":"违反本法第二十一条规定，未标注产品材料的成分或者不如实标注的，由县级以上地方人民政府质量技术监督部门责令限期改正；拒不改正的，处以五万元以下的罚款。"},{"i":38,"n":"第三十八条","txt":"违反本法第二十四条第二款规定，生产、销售有毒、有害物质超过国家标准的建筑和装修材料的，依照产品质量法和有关民事、刑事法律的规定，追究行政、民事、刑事法律责任。"},{"i":39,"n":"第三十九条","txt":"违反本法第二十七条第二款、第四款规定，不实施强制性清洁生产审核或者在清洁生产审核中弄虚作假的，或者实施强制性清洁生产审核的企业不报告或者不如实报告审核结果的，由县级以上地方人民政府负责清洁生产综合协调的部门、环境保护部门按照职责分工责令限期改正；拒不改正的，处以五万元以上五十万元以下的罚款。"},{"i":40,"n":"第四十条","txt":"本法自2003年1月1日起施行。"}],"qinquanzerenfa":[{"i":1,"n":"第一条","txt":"为保护民事主体的合法权益，明确侵权责任，预防并制裁侵权行为，促进社会和谐稳定，制定本法。"},{"i":2,"n":"第二条","txt":"侵害民事权益，应当依照本法承担侵权责任。"},{"i":3,"n":"第三条","txt":"被侵权人有权请求侵权人承担侵权责任。"},{"i":4,"n":"第四条","txt":"侵权人因同一行为应当承担行政责任或者刑事责任的，不影响依法承担侵权责任。"},{"i":5,"n":"第五条","txt":"其他法律对侵权责任另有特别规定的，依照其规定。"},{"i":6,"n":"第六条","txt":"行为人因过错侵害他人民事权益，应当承担侵权责任。"},{"i":7,"n":"第七条","txt":"行为人损害他人民事权益，不论行为人有无过错，法律规定应当承担侵权责任的，依照其规定。"},{"i":8,"n":"第八条","txt":"二人以上共同实施侵权行为，造成他人损害的，应当承担连带责任。"},{"i":9,"n":"第九条","txt":"教唆、帮助他人实施侵权行为的，应当与行为人承担连带责任。"},{"i":10,"n":"第十条","txt":"二人以上实施危及他人人身、财产安全的行为，其中一人或者数人的行为造成他人损害，能够确定具体侵权人的，由侵权人承担责任；不能确定具体侵权人的，行为人承担连带责任。"},{"i":11,"n":"第十一条","txt":"二人以上分别实施侵权行为造成同一损害，每个人的侵权行为都足以造成全部损害的，行为人承担连带责任。"},{"i":12,"n":"第十二条","txt":"二人以上分别实施侵权行为造成同一损害，能够确定责任大小的，各自承担相应的责任；难以确定责任大小的，平均承担赔偿责任。"},{"i":13,"n":"第十三条","txt":"法律规定承担连带责任的，被侵权人有权请求部分或者全部连带责任人承担责任。"},{"i":14,"n":"第十四条","txt":"连带责任人根据各自责任大小确定相应的赔偿数额；难以确定责任大小的，平均承担赔偿责任。"},{"i":15,"n":"第十五条","txt":"承担侵权责任的方式主要有："},{"i":16,"n":"第十六条","txt":"侵害他人造成人身损害的，应当赔偿医疗费、护理费、交通费等为治疗和康复支出的合理费用，以及因误工减少的收入。造成残疾的，还应当赔偿残疾生活辅助具费和残疾赔偿金。造成死亡的，还应当赔偿丧葬费和死亡赔偿金。"},{"i":17,"n":"第十七条","txt":"因同一侵权行为造成多人死亡的，可以以相同数额确定死亡赔偿金。"},{"i":18,"n":"第十八条","txt":"被侵权人死亡的，其近亲属有权请求侵权人承担侵权责任。被侵权人为单位，该单位分立、合并的，承继权利的单位有权请求侵权人承担侵权责任。"},{"i":19,"n":"第十九条","txt":"侵害他人财产的，财产损失按照损失发生时的市场价格或者其他方式计算。"},{"i":20,"n":"第二十条","txt":"侵害他人人身权益造成财产损失的，按照被侵权人因此受到的损失赔偿；被侵权人的损失难以确定，侵权人因此获得利益的，按照其获得的利益赔偿；侵权人因此获得的利益难以确定，被侵权人和侵权人就赔偿数额协商不一致，向人民法院提起诉讼的，由人民法院根据实际情况确定赔偿数额。"},{"i":21,"n":"第二十一条","txt":"侵权行为危及他人人身、财产安全的，被侵权人可以请求侵权人承担停止侵害、排除妨碍、消除危险等侵权责任。"},{"i":22,"n":"第二十二条","txt":"侵害他人人身权益，造成他人严重精神损害的，被侵权人可以请求精神损害赔偿。"},{"i":23,"n":"第二十三条","txt":"因防止、制止他人民事权益被侵害而使自己受到损害的，由侵权人承担责任。侵权人逃逸或者无力承担责任，被侵权人请求补偿的，受益人应当给予适当补偿。"},{"i":24,"n":"第二十四条","txt":"受害人和行为人对损害的发生都没有过错的，可以根据实际情况，由双方分担损失。"},{"i":25,"n":"第二十五条","txt":"损害发生后，当事人可以协商赔偿费用的支付方式。协商不一致的，赔偿费用应当一次性支付；一次性支付确有困难的，可以分期支付，但应当提供相应的担保。"},{"i":26,"n":"第二十六条","txt":"被侵权人对损害的发生也有过错的，可以减轻侵权人的责任。"},{"i":27,"n":"第二十七条","txt":"损害是因受害人故意造成的，行为人不承担责任。"},{"i":28,"n":"第二十八条","txt":"损害是因第三人造成的，第三人应当承担侵权责任。"},{"i":29,"n":"第二十九条","txt":"因不可抗力造成他人损害的，不承担责任。法律另有规定的，依照其规定。"},{"i":30,"n":"第三十条","txt":"因正当防卫造成损害的，不承担责任。正当防卫超过必要的限度，造成不应有的损害的，正当防卫人应当承担适当的责任。"},{"i":31,"n":"第三十一条","txt":"因紧急避险造成损害的，由引起险情发生的人承担责任。如果危险是由自然原因引起的，紧急避险人不承担责任或者给予适当补偿。紧急避险采取措施不当或者超过必要的限度，造成不应有的损害的，紧急避险人应当承担适当的责任。"},{"i":32,"n":"第三十二条","txt":"无民事行为能力人、限制民事行为能力人造成他人损害的，由监护人承担侵权责任。监护人尽到监护责任的，可以减轻其侵权责任。"},{"i":33,"n":"第三十三条","txt":"完全民事行为能力人对自己的行为暂时没有意识或者失去控制造成他人损害有过错的，应当承担侵权责任；没有过错的，根据行为人的经济状况对受害人适当补偿。"},{"i":34,"n":"第三十四条","txt":"用人单位的工作人员因执行工作任务造成他人损害的，由用人单位承担侵权责任。"},{"i":35,"n":"第三十五条","txt":"个人之间形成劳务关系，提供劳务一方因劳务造成他人损害的，由接受劳务一方承担侵权责任。提供劳务一方因劳务自己受到损害的，根据双方各自的过错承担相应的责任。"},{"i":36,"n":"第三十六条","txt":"网络用户、网络服务提供者利用网络侵害他人民事权益的，应当承担侵权责任。"},{"i":37,"n":"第三十七条","txt":"宾馆、商场、银行、车站、娱乐场所等公共场所的管理人或者群众性活动的组织者，未尽到安全保障义务，造成他人损害的，应当承担侵权责任。"},{"i":38,"n":"第三十八条","txt":"无民事行为能力人在幼儿园、学校或者其他教育机构学习、生活期间受到人身损害的，幼儿园、学校或者其他教育机构应当承担责任，但能够证明尽到教育、管理职责的，不承担责任。"},{"i":39,"n":"第三十九条","txt":"限制民事行为能力人在学校或者其他教育机构学习、生活期间受到人身损害，学校或者其他教育机构未尽到教育、管理职责的，应当承担责任。"},{"i":40,"n":"第四十条","txt":"无民事行为能力人或者限制民事行为能力人在幼儿园、学校或者其他教育机构学习、生活期间，受到幼儿园、学校或者其他教育机构以外的人员人身损害的，由侵权人承担侵权责任；幼儿园、学校或者其他教育机构未尽到管理职责的，承担相应的补充责任。"},{"i":41,"n":"第四十一条","txt":"因产品存在缺陷造成他人损害的，生产者应当承担侵权责任。"},{"i":42,"n":"第四十二条","txt":"因销售者的过错使产品存在缺陷，造成他人损害的，销售者应当承担侵权责任。"},{"i":43,"n":"第四十三条","txt":"因产品存在缺陷造成损害的，被侵权人可以向产品的生产者请求赔偿，也可以向产品的销售者请求赔偿。"},{"i":44,"n":"第四十四条","txt":"因运输者、仓储者等第三人的过错使产品存在缺陷，造成他人损害的，产品的生产者、销售者赔偿后，有权向第三人追偿。"},{"i":45,"n":"第四十五条","txt":"因产品缺陷危及他人人身、财产安全的，被侵权人有权请求生产者、销售者承担排除妨碍、消除危险等侵权责任。"},{"i":46,"n":"第四十六条","txt":"产品投入流通后发现存在缺陷的，生产者、销售者应当及时采取警示、召回等补救措施。未及时采取补救措施或者补救措施不力造成损害的，应当承担侵权责任。"},{"i":47,"n":"第四十七条","txt":"明知产品存在缺陷仍然生产、销售，造成他人死亡或者健康严重损害的，被侵权人有权请求相应的惩罚性赔偿。"},{"i":48,"n":"第四十八条","txt":"机动车发生交通事故造成损害的，依照道路交通安全法的有关规定承担赔偿责任。"},{"i":49,"n":"第四十九条","txt":"因租赁、借用等情形机动车所有人与使用人不是同一人时，发生交通事故后属于该机动车一方责任的，由保险公司在机动车强制保险责任限额范围内予以赔偿。不足部分，由机动车使用人承担赔偿责任；机动车所有人对损害的发生有过错的，承担相应的赔偿责任。"},{"i":50,"n":"第五十条","txt":"当事人之间已经以买卖等方式转让并交付机动车但未办理所有权转移登记，发生交通事故后属于该机动车一方责任的，由保险公司在机动车强制保险责任限额范围内予以赔偿。不足部分，由受让人承担赔偿责任。"},{"i":51,"n":"第五十一条","txt":"以买卖等方式转让拼装或者已达到报废标准的机动车，发生交通事故造成损害的，由转让人和受让人承担连带责任。"},{"i":52,"n":"第五十二条","txt":"盗窃、抢劫或者抢夺的机动车发生交通事故造成损害的，由盗窃人、抢劫人或者抢夺人承担赔偿责任。保险公司在机动车强制保险责任限额范围内垫付抢救费用的，有权向交通事故责任人追偿。"},{"i":53,"n":"第五十三条","txt":"机动车驾驶人发生交通事故后逃逸，该机动车参加强制保险的，由保险公司在机动车强制保险责任限额范围内予以赔偿；机动车不明或者该机动车未参加强制保险，需要支付被侵权人人身伤亡的抢救、丧葬等费用的，由道路交通事故社会救助基金垫付。道路交通事故社会救助基金垫付后，其管理机构有权向交通事故责任人追偿。"},{"i":54,"n":"第五十四条","txt":"患者在诊疗活动中受到损害，医疗机构及其医务人员有过错的，由医疗机构承担赔偿责任。"},{"i":55,"n":"第五十五条","txt":"医务人员在诊疗活动中应当向患者说明病情和医疗措施。需要实施手术、特殊检查、特殊治疗的，医务人员应当及时向患者说明医疗风险、替代医疗方案等情况，并取得其书面同意；不宜向患者说明的，应当向患者的近亲属说明，并取得其书面同意。"},{"i":56,"n":"第五十六条","txt":"因抢救生命垂危的患者等紧急情况，不能取得患者或者其近亲属意见的，经医疗机构负责人或者授权的负责人批准，可以立即实施相应的医疗措施。"},{"i":57,"n":"第五十七条","txt":"医务人员在诊疗活动中未尽到与当时的医疗水平相应的诊疗义务，造成患者损害的，医疗机构应当承担赔偿责任。"},{"i":58,"n":"第五十八条","txt":"患者有损害，因下列情形之一的，推定医疗机构有过错："},{"i":59,"n":"第五十九条","txt":"因药品、消毒药剂、医疗器械的缺陷，或者输入不合格的血液造成患者损害的，患者可以向生产者或者血液提供机构请求赔偿，也可以向医疗机构请求赔偿。患者向医疗机构请求赔偿的，医疗机构赔偿后，有权向负有责任的生产者或者血液提供机构追偿。"},{"i":60,"n":"第六十条","txt":"患者有损害，因下列情形之一的，医疗机构不承担赔偿责任："},{"i":61,"n":"第六十一条","txt":"医疗机构及其医务人员应当按照规定填写并妥善保管住院志、医嘱单、检验报告、手术及麻醉记录、病理资料、护理记录、医疗费用等病历资料。"},{"i":62,"n":"第六十二条","txt":"医疗机构及其医务人员应当对患者的隐私保密。泄露患者隐私或者未经患者同意公开其病历资料，造成患者损害的，应当承担侵权责任。"},{"i":63,"n":"第六十三条","txt":"医疗机构及其医务人员不得违反诊疗规范实施不必要的检查。"},{"i":64,"n":"第六十四条","txt":"医疗机构及其医务人员的合法权益受法律保护。干扰医疗秩序，妨害医务人员工作、生活的，应当依法承担法律责任。"},{"i":65,"n":"第六十五条","txt":"因污染环境造成损害的，污染者应当承担侵权责任。"},{"i":66,"n":"第六十六条","txt":"因污染环境发生纠纷，污染者应当就法律规定的不承担责任或者减轻责任的情形及其行为与损害之间不存在因果关系承担举证责任。"},{"i":67,"n":"第六十七条","txt":"两个以上污染者污染环境，污染者承担责任的大小，根据污染物的种类、排放量等因素确定。"},{"i":68,"n":"第六十八条","txt":"因第三人的过错污染环境造成损害的，被侵权人可以向污染者请求赔偿，也可以向第三人请求赔偿。污染者赔偿后，有权向第三人追偿。"},{"i":69,"n":"第六十九条","txt":"从事高度危险作业造成他人损害的，应当承担侵权责任。"},{"i":70,"n":"第七十条","txt":"民用核设施发生核事故造成他人损害的，民用核设施的经营者应当承担侵权责任，但能够证明损害是因战争等情形或者受害人故意造成的，不承担责任。"},{"i":71,"n":"第七十一条","txt":"民用航空器造成他人损害的，民用航空器的经营者应当承担侵权责任，但能够证明损害是因受害人故意造成的，不承担责任。"},{"i":72,"n":"第七十二条","txt":"占有或者使用易燃、易爆、剧毒、放射性等高度危险物造成他人损害的，占有人或者使用人应当承担侵权责任，但能够证明损害是因受害人故意或者不可抗力造成的，不承担责任。被侵权人对损害的发生有重大过失的，可以减轻占有人或者使用人的责任。"},{"i":73,"n":"第七十三条","txt":"从事高空、高压、地下挖掘活动或者使用高速轨道运输工具造成他人损害的，经营者应当承担侵权责任，但能够证明损害是因受害人故意或者不可抗力造成的，不承担责任。被侵权人对损害的发生有过失的，可以减轻经营者的责任。"},{"i":74,"n":"第七十四条","txt":"遗失、抛弃高度危险物造成他人损害的，由所有人承担侵权责任。所有人将高度危险物交由他人管理的，由管理人承担侵权责任；所有人有过错的，与管理人承担连带责任。"},{"i":75,"n":"第七十五条","txt":"非法占有高度危险物造成他人损害的，由非法占有人承担侵权责任。所有人、管理人不能证明对防止他人非法占有尽到高度注意义务的，与非法占有人承担连带责任。"},{"i":76,"n":"第七十六条","txt":"未经许可进入高度危险活动区域或者高度危险物存放区域受到损害，管理人已经采取安全措施并尽到警示义务的，可以减轻或者不承担责任。"},{"i":77,"n":"第七十七条","txt":"承担高度危险责任，法律规定赔偿限额的，依照其规定。"},{"i":78,"n":"第七十八条","txt":"饲养的动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任，但能够证明损害是因被侵权人故意或者重大过失造成的，可以不承担或者减轻责任。"},{"i":79,"n":"第七十九条","txt":"违反管理规定，未对动物采取安全措施造成他人损害的，动物饲养人或者管理人应当承担侵权责任。"},{"i":80,"n":"第八十条","txt":"禁止饲养的烈性犬等危险动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任。"},{"i":81,"n":"第八十一条","txt":"动物园的动物造成他人损害的，动物园应当承担侵权责任，但能够证明尽到管理职责的，不承担责任。"},{"i":82,"n":"第八十二条","txt":"遗弃、逃逸的动物在遗弃、逃逸期间造成他人损害的，由原动物饲养人或者管理人承担侵权责任。"},{"i":83,"n":"第八十三条","txt":"因第三人的过错致使动物造成他人损害的，被侵权人可以向动物饲养人或者管理人请求赔偿，也可以向第三人请求赔偿。动物饲养人或者管理人赔偿后，有权向第三人追偿。"},{"i":84,"n":"第八十四条","txt":"饲养动物应当遵守法律，尊重社会公德，不得妨害他人生活。"},{"i":85,"n":"第八十五条","txt":"建筑物、构筑物或者其他设施及其搁置物、悬挂物发生脱落、坠落造成他人损害，所有人、管理人或者使用人不能证明自己没有过错的，应当承担侵权责任。所有人、管理人或者使用人赔偿后，有其他责任人的，有权向其他责任人追偿。"},{"i":86,"n":"第八十六条","txt":"建筑物、构筑物或者其他设施倒塌造成他人损害的，由建设单位与施工单位承担连带责任。建设单位、施工单位赔偿后，有其他责任人的，有权向其他责任人追偿。"},{"i":87,"n":"第八十七条","txt":"从建筑物中抛掷物品或者从建筑物上坠落的物品造成他人损害，难以确定具体侵权人的，除能够证明自己不是侵权人的外，由可能加害的建筑物使用人给予补偿。"},{"i":88,"n":"第八十八条","txt":"堆放物倒塌造成他人损害，堆放人不能证明自己没有过错的，应当承担侵权责任。"},{"i":89,"n":"第八十九条","txt":"在公共道路上堆放、倾倒、遗撒妨碍通行的物品造成他人损害的，有关单位或者个人应当承担侵权责任。"},{"i":90,"n":"第九十条","txt":"因林木折断造成他人损害，林木的所有人或者管理人不能证明自己没有过错的，应当承担侵权责任。"},{"i":91,"n":"第九十一条","txt":"在公共场所或者道路上挖坑、修缮安装地下设施等，没有设置明显标志和采取安全措施造成他人损害的，施工人应当承担侵权责任。"},{"i":92,"n":"第九十二条","txt":"本法自2010年7月1日起施行。"}],"quanguorenmindaibiaodahuichangwuweiyuanhuiguanyudu049ae2":[],"quanguorenmindaibiaodahuichangwuweiyuanhuiguanyuwaf07963":[],"quanminsuoyouzhigongyeqiyefa":[{"i":1,"n":"第一条","txt":"为保障全民所有制经济的巩固和发展，明确全民所有制工业企业的权利和义务，保障其合法权益，增强其活力，促进社会主义现代化建设，根据《中华人民共和国宪法》，制定本法。"},{"i":2,"n":"第二条","txt":"全民所有制工业企业（以下简称企业）是依法自主经营、自负盈亏、独立核算的社会主义商品生产和经营单位。"},{"i":3,"n":"第三条","txt":"企业的根本任务是：根据国家计划和市场需求，发展商品生产，创造财富，增加积累，满足社会日益增长的物质和文化生活需要。"},{"i":4,"n":"第四条","txt":"企业必须坚持在建设社会主义物质文明的同时，建设社会主义精神文明，建设有理想、有道德、有文化、有纪律的职工队伍。"},{"i":5,"n":"第五条","txt":"企业必须遵守法律、法规，坚持社会主义方向。"},{"i":6,"n":"第六条","txt":"企业必须有效地利用国家授予其经营管理的财产，实现资产增殖；依法缴纳税金、费用、利润。"},{"i":7,"n":"第七条","txt":"企业实行厂长（经理）负责制。"},{"i":8,"n":"第八条","txt":"中国共产党在企业中的基层组织，对党和国家的方针、政策在本企业的贯彻执行实行保证监督。"},{"i":9,"n":"第九条","txt":"国家保障职工的主人翁地位，职工的合法权益受法律保护。"},{"i":10,"n":"第十条","txt":"企业通过职工代表大会和其他形式，实行民主管理。"},{"i":11,"n":"第十一条","txt":"企业工会代表和维护职工利益，依法独立自主地开展工作。企业工会组织职工参加民主管理和民主监督。"},{"i":12,"n":"第十二条","txt":"企业必须加强和改善经营管理，实行经济责任制，推进科学技术进步，厉行节约，反对浪费，提高经济效益，促进企业的改造和发展。"},{"i":13,"n":"第十三条","txt":"企业贯彻按劳分配原则。在法律规定的范围内，企业可以采取其他分配方式。"},{"i":14,"n":"第十四条","txt":"国家授予企业经营管理的财产受法律保护，不受侵犯。"},{"i":15,"n":"第十五条","txt":"企业的合法权益受法律保护，不受侵犯。"},{"i":16,"n":"第十六条","txt":"设立企业，必须依照法律和国务院规定，报请政府或者政府主管部门审核批准。经工商行政管理部门核准登记、发给营业执照，企业取得法人资格。"},{"i":17,"n":"第十七条","txt":"设立企业必须具备以下条件："},{"i":18,"n":"第十八条","txt":"企业合并或者分立，依照法律、行政法规的规定，由政府或者政府主管部门批准。"},{"i":19,"n":"第十九条","txt":"企业由于下列原因之一终止："},{"i":20,"n":"第二十条","txt":"企业合并、分立或者终止时，必须保护其财产，依法清理债权、债务。"},{"i":21,"n":"第二十一条","txt":"企业的合并、分立、终止，以及经营范围等登记事项的变更，须经工商行政管理部门核准登记。"},{"i":22,"n":"第二十二条","txt":"在国家计划指导下，企业有权自行安排生产社会需要的产品或者为社会提供服务。"},{"i":23,"n":"第二十三条","txt":"企业有权要求调整没有必需的计划供应物资或者产品销售安排的指令性计划。"},{"i":24,"n":"第二十四条","txt":"企业有权自行销售本企业的产品。国务院另有规定的除外。"},{"i":25,"n":"第二十五条","txt":"企业有权自行选择供货单位，购进生产需要的物资。"},{"i":26,"n":"第二十六条","txt":"除国务院规定由物价部门和有关主管部门控制价格的以外，企业有权自行确定产品价格、劳务价格。"},{"i":27,"n":"第二十七条","txt":"企业有权依照国务院规定与外商谈判并签订合同。"},{"i":28,"n":"第二十八条","txt":"企业有权依照国务院规定支配使用留用资金。"},{"i":29,"n":"第二十九条","txt":"企业有权依照国务院规定出租或者有偿转让国家授予其经营管理的固定资产，所得的收益必须用于设备更新和技术改造。"},{"i":30,"n":"第三十条","txt":"企业有权确定适合本企业情况的工资形式和奖金分配办法。"},{"i":31,"n":"第三十一条","txt":"企业有权依照法律和国务院规定录用、辞退职工。"},{"i":32,"n":"第三十二条","txt":"企业有权决定机构设置及其人员编制。"},{"i":33,"n":"第三十三条","txt":"企业有权拒绝任何机关和单位向企业摊派人力、物力、财力。除法律、法规另有规定外，任何机关和单位以任何方式要求企业提供人力、物力、财力的，都属于摊派。"},{"i":34,"n":"第三十四条","txt":"企业有权依照法律和国务院规定与其他企业、事业单位联营，向其他企业、事业单位投资，持有其他企业的股份。"},{"i":35,"n":"第三十五条","txt":"企业必须完成指令性计划。（2009年8月27日删除）"},{"i":36,"n":"第三十六条","txt":"企业必须保障固定资产的正常维修，改进和更新设备。"},{"i":37,"n":"第三十七条","txt":"企业必须遵守国家关于财务、劳动工资和物价管理等方面的规定，接受财政、审计、劳动工资和物价等机关的监督。"},{"i":38,"n":"第三十八条","txt":"企业必须保证产品质量和服务质量，对用户和消费者负责。"},{"i":39,"n":"第三十九条","txt":"企业必须提高劳动效率，节约能源和原材料，努力降低成本。"},{"i":40,"n":"第四十条","txt":"企业必须加强保卫工作，维护生产秩序，保护国家财产。"},{"i":41,"n":"第四十一条","txt":"企业必须贯彻安全生产制度，改善劳动条件，做好劳动保护和环境保护工作，做到安全生产和文明生产。"},{"i":42,"n":"第四十二条","txt":"企业应当加强思想政治教育、法制教育、国防教育、科学文化教育和技术业务培训，提高职工队伍的素质。"},{"i":43,"n":"第四十三条","txt":"企业应当支持和奖励职工进行科学研究、发明创造，开展技术革新、合理化建议和社会主义劳动竞赛活动。"},{"i":44,"n":"第四十四条","txt":"厂长的产生，除国务院另有规定外，由政府主管部门根据企业的情况决定采取下列一种方式："},{"i":45,"n":"第四十五条","txt":"厂长是企业的法定代表人。"},{"i":46,"n":"第四十六条","txt":"厂长必须依靠职工群众履行本法规定的企业的各项义务，支持职工代表大会、工会和其他群众组织的工作，执行职工代表大会依法作出的决定。"},{"i":47,"n":"第四十七条","txt":"企业设立管理委员会或者通过其他形式，协助厂长决定企业的重大问题。管理委员会由企业各方面的负责人和职工代表组成。厂长任管理委员会主任。"},{"i":48,"n":"第四十八条","txt":"厂长在领导企业完成计划、提高产品质量和服务质量、提高经济效益和加强精神文明建设等方面成绩显著的，由政府主管部门给予奖励。"},{"i":49,"n":"第四十九条","txt":"职工有参加企业民主管理的权利，有对企业的生产和工作提出意见和建议的权利；有依法享受劳动保护、劳动保险、休息、休假的权利；有向国家机关反映真实情况，对企业领导干部提出批评和控告的权利。女职工有依照国家规定享受特殊劳动保护和劳动保险的权利。"},{"i":50,"n":"第五十条","txt":"职工应当以国家主人翁的态度从事劳动，遵守劳动纪律和规章制度，完成生产和工作任务。"},{"i":51,"n":"第五十一条","txt":"职工代表大会是企业实行民主管理的基本形式，是职工行使民主管理权力的机构。"},{"i":52,"n":"第五十二条","txt":"职工代表大会行使下列职权："},{"i":53,"n":"第五十三条","txt":"车间通过职工大会、职工代表组或者其他形式实行民主管理；工人直接参加班组的民主管理。"},{"i":54,"n":"第五十四条","txt":"职工代表大会应当支持厂长依法行使职权，教育职工履行本法规定的义务。"},{"i":55,"n":"第五十五条","txt":"政府或者政府主管部门依照国务院规定统一对企业下达指令性计划，保证企业完成指令性计划所需的计划供应物资，审查批准企业提出的基本建设、重大技术改造等计划；任免、奖惩厂长，根据厂长的提议，任免、奖惩副厂级行政领导干部，考核、培训厂级行政领导干部。（2009年8月27日删除）"},{"i":56,"n":"第五十六条","txt":"政府有关部门按照国家调节市场、市场引导企业的目标，为企业提供服务，并根据各自的职责，依照法律、法规的规定，对企业实行管理和监督。"},{"i":57,"n":"第五十七条","txt":"企业所在地的县级以上的地方政府应当提供企业所需的由地方计划管理的物资，协调企业与当地其他单位之间的关系，努力办好与企业有关的公共福利事业。"},{"i":58,"n":"第五十八条","txt":"任何机关和单位不得侵犯企业依法享有的经营管理自主权；不得向企业摊派人力、物力、财力；不得要求企业设置机构或者规定机构的编制人数。"},{"i":59,"n":"第五十九条","txt":"违反本法第十六条规定，未经政府或者政府主管部门审核批准和工商行政管理部门核准登记，以企业名义进行生产经营活动的，责令停业，没收违法所得。"},{"i":60,"n":"第六十条","txt":"企业因生产、销售质量不合格的产品，给用户和消费者造成财产、人身损害的，应当承担赔偿责任；构成犯罪的，对直接责任人员依法追究刑事责任。"},{"i":61,"n":"第六十一条","txt":"政府和政府有关部门的决定违反本法第五十八条规定的，企业有权向作出决定的机关申请撤销；不予撤销的，企业有权向作出决定的机关的上一级机关或者政府监察部门申诉。接受申诉的机关应于接到申诉之日起三十日内作出裁决并通知企业。"},{"i":62,"n":"第六十二条","txt":"企业领导干部滥用职权，侵犯职工合法权益，情节严重的，由政府主管部门给予行政处分；滥用职权、假公济私，对职工实行报复陷害的，依照刑法有关规定追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"企业和政府有关部门的领导干部，因工作过失给企业和国家造成较大损失的，由政府主管部门或者有关上级机关给予行政处分。"},{"i":64,"n":"第六十四条","txt":"阻碍企业领导干部依法执行职务，未使用暴力、威胁方法的，由企业所在地公安机关依照《中华人民共和国治安管理处罚条例》第十九条的规定处罚；以暴力、威胁方法阻碍企业领导干部依法执行职务的，依照《中华人民共和国刑法》第一百五十七条的规定追究刑事责任。（2009年8月27日删除）"},{"i":65,"n":"第六十五条","txt":"本法的原则适用于全民所有制交通运输、邮电、地质勘探、建筑安装、商业、外贸、物资、农林、水利企业。"},{"i":66,"n":"第六十六条","txt":"企业实行承包、租赁经营责任制的，除遵守本法规定外，发包方和承包方、出租方和承租方的权利、义务依照国务院有关规定执行。"},{"i":67,"n":"第六十七条","txt":"国务院根据本法制定实施条例。"},{"i":68,"n":"第六十八条","txt":"自治区人民代表大会常务委员会可以根据本法和《中华人民共和国民族区域自治法》的原则，结合当地的特点，制定实施办法，报全国人民代表大会常务委员会备案。"},{"i":69,"n":"第六十九条","txt":"本法自1988年8月1日起施行。"}],"shouyangfa":[{"i":1,"n":"第一条","txt":"为保护合法的收养关系，维护收养关系当事人的权利，制定本法。"},{"i":2,"n":"第二条","txt":"收养应当有利于被收养的未成年人的抚养、成长，保障被收养人和收养人的合法权益，遵循平等自愿的原则，并不得违背社会公德。"},{"i":3,"n":"第三条","txt":"收养不得违背计划生育的法律、法规。"},{"i":4,"n":"第四条","txt":"下列不满十四周岁的未成年人可以被收养："},{"i":5,"n":"第五条","txt":"下列公民、组织可以作送养人："},{"i":6,"n":"第六条","txt":"收养人应当同时具备下列条件："},{"i":7,"n":"第七条","txt":"收养三代以内同辈旁系血亲的子女，可以不受本法第四条第三项、第五条第三项、第九条和被收养人不满十四周岁的限制。"},{"i":8,"n":"第八条","txt":"收养人只能收养一名子女。"},{"i":9,"n":"第九条","txt":"无配偶的男性收养女性的，收养人与被收养人的年龄应当相差四十周岁以上。"},{"i":10,"n":"第十条","txt":"生父母送养子女，须双方共同送养。生父母一方不明或者查找不到的可以单方送养。"},{"i":11,"n":"第十一条","txt":"收养人收养与送养人送养，须双方自愿。收养年满十周岁以上未成年人的，应当征得被收养人的同意。"},{"i":12,"n":"第十二条","txt":"未成年人的父母均不具备完全民事行为能力的，该未成年人的监护人不得将其送养，但父母对该未成年人有严重危害可能的除外。"},{"i":13,"n":"第十三条","txt":"监护人送养未成年孤儿的，须征得有抚养义务的人同意。有抚养义务的人不同意送养、监护人不愿意继续履行监护职责的，应当依照《中华人民共和国民法通则》的规定变更监护人。"},{"i":14,"n":"第十四条","txt":"继父或者继母经继子女的生父母同意，可以收养继子女，并可以不受本法第四条第三项、第五条第三项、第六条和被收养人不满十四周岁以及收养一名的限制。"},{"i":15,"n":"第十五条","txt":"收养应当向县级以上人民政府民政部门登记。收养关系自登记之日起成立。"},{"i":16,"n":"第十六条","txt":"收养关系成立后，公安部门应当依照国家有关规定为被收养人办理户口登记。"},{"i":17,"n":"第十七条","txt":"孤儿或者生父母无力抚养的子女，可以由生父母的亲属、朋友抚养。"},{"i":18,"n":"第十八条","txt":"配偶一方死亡，另一方送养未成年子女的，死亡一方的父母有优先抚养的权利。"},{"i":19,"n":"第十九条","txt":"送养人不得以送养子女为理由违反计划生育的规定再生育子女。"},{"i":20,"n":"第二十条","txt":"严禁买卖儿童或者借收养名义买卖儿童。"},{"i":21,"n":"第二十一条","txt":"外国人依照本法可以在中华人民共和国收养子女。"},{"i":22,"n":"第二十二条","txt":"收养人、送养人要求保守收养秘密的，其他人应当尊重其意愿，不得泄露。"},{"i":23,"n":"第二十三条","txt":"自收养关系成立之日起，养父母与养子女间的权利义务关系，适用法律关于父母子女关系的规定；养子女与养父母的近亲属间的权利义务关系，适用法律关于子女与父母的近亲属关系的规定。"},{"i":24,"n":"第二十四条","txt":"养子女可以随养父或者养母的姓，经当事人协商一致，也可以保留原姓。"},{"i":25,"n":"第二十五条","txt":"违反《中华人民共和国民法通则》第五十五条和本法规定的收养行为无法律效力。"},{"i":26,"n":"第二十六条","txt":"收养人在被收养人成年以前，不得解除收养关系，但收养人、送养人双方协议解除的除外，养子女年满十周岁以上的，应当征得本人同意。"},{"i":27,"n":"第二十七条","txt":"养父母与成年养子女关系恶化、无法共同生活的，可以协议解除收养关系。不能达成协议的，可以向人民法院起诉。"},{"i":28,"n":"第二十八条","txt":"当事人协议解除收养关系的，应当到民政部门办理解除收养关系的登记。"},{"i":29,"n":"第二十九条","txt":"收养关系解除后，养子女与养父母及其他近亲属间的权利义务关系即行消除，与生父母及其他近亲属间的权利义务关系自行恢复，但成年养子女与生父母及其他近亲属间的权利义务关系是否恢复，可以协商确定。"},{"i":30,"n":"第三十条","txt":"收养关系解除后，经养父母抚养的成年养子女，对缺乏劳动能力又缺乏生活来源的养父母，应当给付生活费。因养子女成年后虐待、遗弃养父母而解除收养关系的，养父母可以要求养子女补偿收养期间支出的生活费和教育费。"},{"i":31,"n":"第三十一条","txt":"借收养名义拐卖儿童的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"民族自治地方的人民代表大会及其常务委员会可以根据本法的原则，结合当地情况，制定变通的或者补充的规定。自治区的规定，报全国人民代表大会常务委员会备案。自治州、自治县的规定，报省或者自治区的人民代表大会常务委员会批准后生效，并报全国人民代表大会常务委员会备案。"},{"i":33,"n":"第三十三条","txt":"国务院可以根据本法制定实施办法。"},{"i":34,"n":"第三十四条","txt":"本法自1992年4月1日起施行。"}],"shuiwuranfangzhifa":[{"i":1,"n":"第一条","txt":"为了保护和改善环境，防治水污染，保护水生态，保障饮用水安全，维护公众健康，推进生态文明建设，促进经济社会可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于中华人民共和国领域内的江河、湖泊、运河、渠道、水库等地表水体以及地下水体的污染防治。"},{"i":3,"n":"第三条","txt":"水污染防治应当坚持预防为主、防治结合、综合治理的原则，优先保护饮用水水源，严格控制工业污染、城镇生活污染，防治农业面源污染，积极推进生态治理工程建设，预防、控制和减少水环境污染和生态破坏。"},{"i":4,"n":"第四条","txt":"县级以上人民政府应当将水环境保护工作纳入国民经济和社会发展规划。"},{"i":5,"n":"第五条","txt":"省、市、县、乡建立河长制，分级分段组织领导本行政区域内江河、湖泊的水资源保护、水域岸线管理、水污染防治、水环境治理等工作。"},{"i":6,"n":"第六条","txt":"国家实行水环境保护目标责任制和考核评价制度，将水环境保护目标完成情况作为对地方人民政府及其负责人考核评价的内容。"},{"i":7,"n":"第七条","txt":"国家鼓励、支持水污染防治的科学技术研究和先进适用技术的推广应用，加强水环境保护的宣传教育。"},{"i":8,"n":"第八条","txt":"国家通过财政转移支付等方式，建立健全对位于饮用水水源保护区区域和江河、湖泊、水库上游地区的水环境生态保护补偿机制。"},{"i":9,"n":"第九条","txt":"县级以上人民政府环境保护主管部门对水污染防治实施统一监督管理。"},{"i":10,"n":"第十条","txt":"排放水污染物，不得超过国家或者地方规定的水污染物排放标准和重点水污染物排放总量控制指标。"},{"i":11,"n":"第十一条","txt":"任何单位和个人都有义务保护水环境，并有权对污染损害水环境的行为进行检举。"},{"i":12,"n":"第十二条","txt":"国务院环境保护主管部门制定国家水环境质量标准。"},{"i":13,"n":"第十三条","txt":"国务院环境保护主管部门会同国务院水行政主管部门和有关省、自治区、直辖市人民政府，可以根据国家确定的重要江河、湖泊流域水体的使用功能以及有关地区的经济、技术条件，确定该重要江河、湖泊流域的省界水体适用的水环境质量标准，报国务院批准后施行。"},{"i":14,"n":"第十四条","txt":"国务院环境保护主管部门根据国家水环境质量标准和国家经济、技术条件，制定国家水污染物排放标准。"},{"i":15,"n":"第十五条","txt":"国务院环境保护主管部门和省、自治区、直辖市人民政府，应当根据水污染防治的要求和国家或者地方的经济、技术条件，适时修订水环境质量标准和水污染物排放标准。"},{"i":16,"n":"第十六条","txt":"防治水污染应当按流域或者按区域进行统一规划。国家确定的重要江河、湖泊的流域水污染防治规划，由国务院环境保护主管部门会同国务院经济综合宏观调控、水行政等部门和有关省、自治区、直辖市人民政府编制，报国务院批准。"},{"i":17,"n":"第十七条","txt":"有关市、县级人民政府应当按照水污染防治规划确定的水环境质量改善目标的要求，制定限期达标规划，采取措施按期达标。"},{"i":18,"n":"第十八条","txt":"市、县级人民政府每年在向本级人民代表大会或者其常务委员会报告环境状况和环境保护目标完成情况时，应当报告水环境质量限期达标规划执行情况，并向社会公开。"},{"i":19,"n":"第十九条","txt":"新建、改建、扩建直接或者间接向水体排放污染物的建设项目和其他水上设施，应当依法进行环境影响评价。"},{"i":20,"n":"第二十条","txt":"国家对重点水污染物排放实施总量控制制度。"},{"i":21,"n":"第二十一条","txt":"直接或者间接向水体排放工业废水和医疗污水以及其他按照规定应当取得排污许可证方可排放的废水、污水的企业事业单位和其他生产经营者，应当取得排污许可证；城镇污水集中处理设施的运营单位，也应当取得排污许可证。排污许可证应当明确排放水污染物的种类、浓度、总量和排放去向等要求。排污许可的具体办法由国务院规定。"},{"i":22,"n":"第二十二条","txt":"向水体排放污染物的企业事业单位和其他生产经营者，应当按照法律、行政法规和国务院环境保护主管部门的规定设置排污口；在江河、湖泊设置排污口的，还应当遵守国务院水行政主管部门的规定。"},{"i":23,"n":"第二十三条","txt":"实行排污许可管理的企业事业单位和其他生产经营者应当按照国家有关规定和监测规范，对所排放的水污染物自行监测，并保存原始监测记录。重点排污单位还应当安装水污染物排放自动监测设备，与环境保护主管部门的监控设备联网，并保证监测设备正常运行。具体办法由国务院环境保护主管部门规定。"},{"i":24,"n":"第二十四条","txt":"实行排污许可管理的企业事业单位和其他生产经营者应当对监测数据的真实性和准确性负责。"},{"i":25,"n":"第二十五条","txt":"国家建立水环境质量监测和水污染物排放监测制度。国务院环境保护主管部门负责制定水环境监测规范，统一发布国家水环境状况信息，会同国务院水行政等部门组织监测网络，统一规划国家水环境质量监测站（点）的设置，建立监测数据共享机制，加强对水环境监测的管理。"},{"i":26,"n":"第二十六条","txt":"国家确定的重要江河、湖泊流域的水资源保护工作机构负责监测其所在流域的省界水体的水环境质量状况，并将监测结果及时报国务院环境保护主管部门和国务院水行政主管部门；有经国务院批准成立的流域水资源保护领导机构的，应当将监测结果及时报告流域水资源保护领导机构。"},{"i":27,"n":"第二十七条","txt":"国务院有关部门和县级以上地方人民政府开发、利用和调节、调度水资源时，应当统筹兼顾，维持江河的合理流量和湖泊、水库以及地下水体的合理水位，保障基本生态用水，维护水体的生态功能。"},{"i":28,"n":"第二十八条","txt":"国务院环境保护主管部门应当会同国务院水行政等部门和有关省、自治区、直辖市人民政府，建立重要江河、湖泊的流域水环境保护联合协调机制，实行统一规划、统一标准、统一监测、统一的防治措施。"},{"i":29,"n":"第二十九条","txt":"国务院环境保护主管部门和省、自治区、直辖市人民政府环境保护主管部门应当会同同级有关部门根据流域生态环境功能需要，明确流域生态环境保护要求，组织开展流域环境资源承载能力监测、评价，实施流域环境资源承载能力预警。"},{"i":30,"n":"第三十条","txt":"环境保护主管部门和其他依照本法规定行使监督管理权的部门，有权对管辖范围内的排污单位进行现场检查，被检查的单位应当如实反映情况，提供必要的资料。检查机关有义务为被检查的单位保守在检查中获取的商业秘密。"},{"i":31,"n":"第三十一条","txt":"跨行政区域的水污染纠纷，由有关地方人民政府协商解决，或者由其共同的上级人民政府协调解决。"},{"i":32,"n":"第三十二条","txt":"国务院环境保护主管部门应当会同国务院卫生主管部门，根据对公众健康和生态环境的危害和影响程度，公布有毒有害水污染物名录，实行风险管理。"},{"i":33,"n":"第三十三条","txt":"禁止向水体排放油类、酸液、碱液或者剧毒废液。"},{"i":34,"n":"第三十四条","txt":"禁止向水体排放、倾倒放射性固体废物或者含有高放射性和中放射性物质的废水。"},{"i":35,"n":"第三十五条","txt":"向水体排放含热废水，应当采取措施，保证水体的水温符合水环境质量标准。"},{"i":36,"n":"第三十六条","txt":"含病原体的污水应当经过消毒处理；符合国家有关标准后，方可排放。"},{"i":37,"n":"第三十七条","txt":"禁止向水体排放、倾倒工业废渣、城镇垃圾和其他废弃物。"},{"i":38,"n":"第三十八条","txt":"禁止在江河、湖泊、运河、渠道、水库最高水位线以下的滩地和岸坡堆放、存贮固体废弃物和其他污染物。"},{"i":39,"n":"第三十九条","txt":"禁止利用渗井、渗坑、裂隙、溶洞，私设暗管，篡改、伪造监测数据，或者不正常运行水污染防治设施等逃避监管的方式排放水污染物。"},{"i":40,"n":"第四十条","txt":"化学品生产企业以及工业集聚区、矿山开采区、尾矿库、危险废物处置场、垃圾填埋场等的运营、管理单位，应当采取防渗漏等措施，并建设地下水水质监测井进行监测，防止地下水污染。"},{"i":41,"n":"第四十一条","txt":"多层地下水的含水层水质差异大的，应当分层开采；对已受污染的潜水和承压水，不得混合开采。"},{"i":42,"n":"第四十二条","txt":"兴建地下工程设施或者进行地下勘探、采矿等活动，应当采取防护性措施，防止地下水污染。"},{"i":43,"n":"第四十三条","txt":"人工回灌补给地下水，不得恶化地下水质。"},{"i":44,"n":"第四十四条","txt":"国务院有关部门和县级以上地方人民政府应当合理规划工业布局，要求造成水污染的企业进行技术改造，采取综合防治措施，提高水的重复利用率，减少废水和污染物排放量。"},{"i":45,"n":"第四十五条","txt":"排放工业废水的企业应当采取有效措施，收集和处理产生的全部废水，防止污染环境。含有毒有害水污染物的工业废水应当分类收集和处理，不得稀释排放。"},{"i":46,"n":"第四十六条","txt":"国家对严重污染水环境的落后工艺和设备实行淘汰制度。"},{"i":47,"n":"第四十七条","txt":"国家禁止新建不符合国家产业政策的小型造纸、制革、印染、染料、炼焦、炼硫、炼砷、炼汞、炼油、电镀、农药、石棉、水泥、玻璃、钢铁、火电以及其他严重污染水环境的生产项目。"},{"i":48,"n":"第四十八条","txt":"企业应当采用原材料利用效率高、污染物排放量少的清洁工艺，并加强管理，减少水污染物的产生。"},{"i":49,"n":"第四十九条","txt":"城镇污水应当集中处理。"},{"i":50,"n":"第五十条","txt":"向城镇污水集中处理设施排放水污染物，应当符合国家或者地方规定的水污染物排放标准。"},{"i":51,"n":"第五十一条","txt":"城镇污水集中处理设施的运营单位或者污泥处理处置单位应当安全处理处置污泥，保证处理处置后的污泥符合国家标准，并对污泥的去向等进行记录。"},{"i":52,"n":"第五十二条","txt":"国家支持农村污水、垃圾处理设施的建设，推进农村污水、垃圾集中处理。"},{"i":53,"n":"第五十三条","txt":"制定化肥、农药等产品的质量标准和使用标准，应当适应水环境保护要求。"},{"i":54,"n":"第五十四条","txt":"使用农药，应当符合国家有关农药安全使用的规定和标准。"},{"i":55,"n":"第五十五条","txt":"县级以上地方人民政府农业主管部门和其他有关部门，应当采取措施，指导农业生产者科学、合理地施用化肥和农药，推广测土配方施肥技术和高效低毒低残留农药，控制化肥和农药的过量使用，防止造成水污染。"},{"i":56,"n":"第五十六条","txt":"国家支持畜禽养殖场、养殖小区建设畜禽粪便、废水的综合利用或者无害化处理设施。"},{"i":57,"n":"第五十七条","txt":"从事水产养殖应当保护水域生态环境，科学确定养殖密度，合理投饵和使用药物，防止污染水环境。"},{"i":58,"n":"第五十八条","txt":"农田灌溉用水应当符合相应的水质标准，防止污染土壤、地下水和农产品。"},{"i":59,"n":"第五十九条","txt":"船舶排放含油污水、生活污水，应当符合船舶污染物排放标准。从事海洋航运的船舶进入内河和港口的，应当遵守内河的船舶污染物排放标准。"},{"i":60,"n":"第六十条","txt":"船舶应当按照国家有关规定配置相应的防污设备和器材，并持有合法有效的防止水域环境污染的证书与文书。"},{"i":61,"n":"第六十一条","txt":"港口、码头、装卸站和船舶修造厂所在地市、县级人民政府应当统筹规划建设船舶污染物、废弃物的接收、转运及处理处置设施。"},{"i":62,"n":"第六十二条","txt":"船舶及有关作业单位从事有污染风险的作业活动，应当按照有关法律法规和标准，采取有效措施，防止造成水污染。海事管理机构、渔业主管部门应当加强对船舶及有关作业活动的监督管理。"},{"i":63,"n":"第六十三条","txt":"国家建立饮用水水源保护区制度。饮用水水源保护区分为一级保护区和二级保护区；必要时，可以在饮用水水源保护区外围划定一定的区域作为准保护区。"},{"i":64,"n":"第六十四条","txt":"在饮用水水源保护区内，禁止设置排污口。"},{"i":65,"n":"第六十五条","txt":"禁止在饮用水水源一级保护区内新建、改建、扩建与供水设施和保护水源无关的建设项目；已建成的与供水设施和保护水源无关的建设项目，由县级以上人民政府责令拆除或者关闭。"},{"i":66,"n":"第六十六条","txt":"禁止在饮用水水源二级保护区内新建、改建、扩建排放污染物的建设项目；已建成的排放污染物的建设项目，由县级以上人民政府责令拆除或者关闭。"},{"i":67,"n":"第六十七条","txt":"禁止在饮用水水源准保护区内新建、扩建对水体污染严重的建设项目；改建建设项目，不得增加排污量。"},{"i":68,"n":"第六十八条","txt":"县级以上地方人民政府应当根据保护饮用水水源的实际需要，在准保护区内采取工程措施或者建造湿地、水源涵养林等生态保护措施，防止水污染物直接排入饮用水水体，确保饮用水安全。"},{"i":69,"n":"第六十九条","txt":"县级以上地方人民政府应当组织环境保护等部门，对饮用水水源保护区、地下水型饮用水源的补给区及供水单位周边区域的环境状况和污染风险进行调查评估，筛查可能存在的污染风险因素，并采取相应的风险防范措施。"},{"i":70,"n":"第七十条","txt":"单一水源供水城市的人民政府应当建设应急水源或者备用水源，有条件的地区可以开展区域联网供水。"},{"i":71,"n":"第七十一条","txt":"饮用水供水单位应当做好取水口和出水口的水质检测工作。发现取水口水质不符合饮用水水源水质标准或者出水口水质不符合饮用水卫生标准的，应当及时采取相应措施，并向所在地市、县级人民政府供水主管部门报告。供水主管部门接到报告后，应当通报环境保护、卫生、水行政等部门。"},{"i":72,"n":"第七十二条","txt":"县级以上地方人民政府应当组织有关部门监测、评估本行政区域内饮用水水源、供水单位供水和用户水龙头出水的水质等饮用水安全状况。"},{"i":73,"n":"第七十三条","txt":"国务院和省、自治区、直辖市人民政府根据水环境保护的需要，可以规定在饮用水水源保护区内，采取禁止或者限制使用含磷洗涤剂、化肥、农药以及限制种植养殖等措施。"},{"i":74,"n":"第七十四条","txt":"县级以上人民政府可以对风景名胜区水体、重要渔业水体和其他具有特殊经济文化价值的水体划定保护区，并采取措施，保证保护区的水质符合规定用途的水环境质量标准。"},{"i":75,"n":"第七十五条","txt":"在风景名胜区水体、重要渔业水体和其他具有特殊经济文化价值的水体的保护区内，不得新建排污口。在保护区附近新建排污口，应当保证保护区水体不受污染。"},{"i":76,"n":"第七十六条","txt":"各级人民政府及其有关部门，可能发生水污染事故的企业事业单位，应当依照《中华人民共和国突发事件应对法》的规定，做好突发水污染事故的应急准备、应急处置和事后恢复等工作。"},{"i":77,"n":"第七十七条","txt":"可能发生水污染事故的企业事业单位，应当制定有关水污染事故的应急方案，做好应急准备，并定期进行演练。"},{"i":78,"n":"第七十八条","txt":"企业事业单位发生事故或者其他突发性事件，造成或者可能造成水污染事故的，应当立即启动本单位的应急方案，采取隔离等应急措施，防止水污染物进入水体，并向事故发生地的县级以上地方人民政府或者环境保护主管部门报告。环境保护主管部门接到报告后，应当及时向本级人民政府报告，并抄送有关部门。"},{"i":79,"n":"第七十九条","txt":"市、县级人民政府应当组织编制饮用水安全突发事件应急预案。"},{"i":80,"n":"第八十条","txt":"环境保护主管部门或者其他依照本法规定行使监督管理权的部门，不依法作出行政许可或者办理批准文件的，发现违法行为或者接到对违法行为的举报后不予查处的，或者有其他未依照本法规定履行职责的行为的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":81,"n":"第八十一条","txt":"以拖延、围堵、滞留执法人员等方式拒绝、阻挠环境保护主管部门或者其他依照本法规定行使监督管理权的部门的监督检查，或者在接受监督检查时弄虚作假的，由县级以上人民政府环境保护主管部门或者其他依照本法规定行使监督管理权的部门责令改正，处二万元以上二十万元以下的罚款。"},{"i":82,"n":"第八十二条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府环境保护主管部门责令限期改正，处二万元以上二十万元以下的罚款；逾期不改正的，责令停产整治："},{"i":83,"n":"第八十三条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府环境保护主管部门责令改正或者责令限制生产、停产整治，并处十万元以上一百万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":84,"n":"第八十四条","txt":"在饮用水水源保护区内设置排污口的，由县级以上地方人民政府责令限期拆除，处十万元以上五十万元以下的罚款；逾期不拆除的，强制拆除，所需费用由违法者承担，处五十万元以上一百万元以下的罚款，并可以责令停产整治。"},{"i":85,"n":"第八十五条","txt":"有下列行为之一的，由县级以上地方人民政府环境保护主管部门责令停止违法行为，限期采取治理措施，消除污染，处以罚款；逾期不采取治理措施的，环境保护主管部门可以指定有治理能力的单位代为治理，所需费用由违法者承担："},{"i":86,"n":"第八十六条","txt":"违反本法规定，生产、销售、进口或者使用列入禁止生产、销售、进口、使用的严重污染水环境的设备名录中的设备，或者采用列入禁止采用的严重污染水环境的工艺名录中的工艺的，由县级以上人民政府经济综合宏观调控部门责令改正，处五万元以上二十万元以下的罚款；情节严重的，由县级以上人民政府经济综合宏观调控部门提出意见，报请本级人民政府责令停业、关闭。"},{"i":87,"n":"第八十七条","txt":"违反本法规定，建设不符合国家产业政策的小型造纸、制革、印染、染料、炼焦、炼硫、炼砷、炼汞、炼油、电镀、农药、石棉、水泥、玻璃、钢铁、火电以及其他严重污染水环境的生产项目的，由所在地的市、县人民政府责令关闭。"},{"i":88,"n":"第八十八条","txt":"城镇污水集中处理设施的运营单位或者污泥处理处置单位，处理处置后的污泥不符合国家标准，或者对污泥去向等未进行记录的，由城镇排水主管部门责令限期采取治理措施，给予警告；造成严重后果的，处十万元以上二十万元以下的罚款；逾期不采取治理措施的，城镇排水主管部门可以指定有治理能力的单位代为治理，所需费用由违法者承担。"},{"i":89,"n":"第八十九条","txt":"船舶未配置相应的防污染设备和器材，或者未持有合法有效的防止水域环境污染的证书与文书的，由海事管理机构、渔业主管部门按照职责分工责令限期改正，处二千元以上二万元以下的罚款；逾期不改正的，责令船舶临时停航。"},{"i":90,"n":"第九十条","txt":"违反本法规定，有下列行为之一的，由海事管理机构、渔业主管部门按照职责分工责令停止违法行为，处一万元以上十万元以下的罚款；造成水污染的，责令限期采取治理措施，消除污染，处二万元以上二十万元以下的罚款；逾期不采取治理措施的，海事管理机构、渔业主管部门按照职责分工可以指定有治理能力的单位代为治理，所需费用由船舶承担："},{"i":91,"n":"第九十一条","txt":"有下列行为之一的，由县级以上地方人民政府环境保护主管部门责令停止违法行为，处十万元以上五十万元以下的罚款；并报经有批准权的人民政府批准，责令拆除或者关闭："},{"i":92,"n":"第九十二条","txt":"饮用水供水单位供水水质不符合国家规定标准的，由所在地市、县级人民政府供水主管部门责令改正，处二万元以上二十万元以下的罚款；情节严重的，报经有批准权的人民政府批准，可以责令停业整顿；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":93,"n":"第九十三条","txt":"企业事业单位有下列行为之一的，由县级以上人民政府环境保护主管部门责令改正；情节严重的，处二万元以上十万元以下的罚款："},{"i":94,"n":"第九十四条","txt":"企业事业单位违反本法规定，造成水污染事故的，除依法承担赔偿责任外，由县级以上人民政府环境保护主管部门依照本条第二款的规定处以罚款，责令限期采取治理措施，消除污染；未按照要求采取治理措施或者不具备治理能力的，由环境保护主管部门指定有治理能力的单位代为治理，所需费用由违法者承担；对造成重大或者特大水污染事故的，还可以报经有批准权的人民政府批准，责令关闭；对直接负责的主管人员和其他直接责任人员可以处上一年度从本单位取得的收入百分之五十以下的罚款；有《中华人民共和国环境保护法》第六十三条规定的违法排放水污染物等行为之一，尚不构成犯罪的，由公安机关对直接负责的主管人员和其他直接责任人员处十日以上十五日以下的拘留；情节较轻的，处五日以上十日以下的拘留。"},{"i":95,"n":"第九十五条","txt":"企业事业单位和其他生产经营者违法排放水污染物，受到罚款处罚，被责令改正的，依法作出处罚决定的行政机关应当组织复查，发现其继续违法排放水污染物或者拒绝、阻挠复查的，依照《中华人民共和国环境保护法》的规定按日连续处罚。"},{"i":96,"n":"第九十六条","txt":"因水污染受到损害的当事人，有权要求排污方排除危害和赔偿损失。"},{"i":97,"n":"第九十七条","txt":"因水污染引起的损害赔偿责任和赔偿金额的纠纷，可以根据当事人的请求，由环境保护主管部门或者海事管理机构、渔业主管部门按照职责分工调解处理；调解不成的，当事人可以向人民法院提起诉讼。当事人也可以直接向人民法院提起诉讼。"},{"i":98,"n":"第九十八条","txt":"因水污染引起的损害赔偿诉讼，由排污方就法律规定的免责事由及其行为与损害结果之间不存在因果关系承担举证责任。"},{"i":99,"n":"第九十九条","txt":"因水污染受到损害的当事人人数众多的，可以依法由当事人推选代表人进行共同诉讼。"},{"i":100,"n":"第一百条","txt":"因水污染引起的损害赔偿责任和赔偿金额的纠纷，当事人可以委托环境监测机构提供监测数据。环境监测机构应当接受委托，如实提供有关监测数据。"},{"i":101,"n":"第一百零一条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":102,"n":"第一百零二条","txt":"本法中下列用语的含义："},{"i":103,"n":"第一百零三条","txt":"本法自2008年6月1日起施行。"}],"turangwuranfangzhifa":[{"i":1,"n":"第一条","txt":"为了保护和改善生态环境，防治土壤污染，保障公众健康，推动土壤资源永续利用，推进生态文明建设，促进经济社会可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域及管辖的其他海域从事土壤污染防治及相关活动，适用本法。"},{"i":3,"n":"第三条","txt":"土壤污染防治应当坚持预防为主、保护优先、分类管理、风险管控、污染担责、公众参与的原则。"},{"i":4,"n":"第四条","txt":"任何组织和个人都有保护土壤、防止土壤污染的义务。"},{"i":5,"n":"第五条","txt":"地方各级人民政府应当对本行政区域土壤污染防治和安全利用负责。"},{"i":6,"n":"第六条","txt":"各级人民政府应当加强对土壤污染防治工作的领导，组织、协调、督促有关部门依法履行土壤污染防治监督管理职责。"},{"i":7,"n":"第七条","txt":"国务院生态环境主管部门对全国土壤污染防治工作实施统一监督管理；国务院农业农村、自然资源、住房城乡建设、林业草原等主管部门在各自职责范围内对土壤污染防治工作实施监督管理。"},{"i":8,"n":"第八条","txt":"国家建立土壤环境信息共享机制。"},{"i":9,"n":"第九条","txt":"国家支持土壤污染风险管控和修复、监测等污染防治科学技术研究开发、成果转化和推广应用，鼓励土壤污染防治产业发展，加强土壤污染防治专业技术人才培养，促进土壤污染防治科学技术进步。"},{"i":10,"n":"第十条","txt":"各级人民政府及其有关部门、基层群众性自治组织和新闻媒体应当加强土壤污染防治宣传教育和科学普及，增强公众土壤污染防治意识，引导公众依法参与土壤污染防治工作。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府应当将土壤污染防治工作纳入国民经济和社会发展规划、环境保护规划。"},{"i":12,"n":"第十二条","txt":"国务院生态环境主管部门根据土壤污染状况、公众健康风险、生态风险和科学技术水平，并按照土地用途，制定国家土壤污染风险管控标准，加强土壤污染防治标准体系建设。"},{"i":13,"n":"第十三条","txt":"制定土壤污染风险管控标准，应当组织专家进行审查和论证，并征求有关部门、行业协会、企业事业单位和公众等方面的意见。"},{"i":14,"n":"第十四条","txt":"国务院统一领导全国土壤污染状况普查。国务院生态环境主管部门会同国务院农业农村、自然资源、住房城乡建设、林业草原等主管部门，每十年至少组织开展一次全国土壤污染状况普查。"},{"i":15,"n":"第十五条","txt":"国家实行土壤环境监测制度。"},{"i":16,"n":"第十六条","txt":"地方人民政府农业农村、林业草原主管部门应当会同生态环境、自然资源主管部门对下列农用地地块进行重点监测："},{"i":17,"n":"第十七条","txt":"地方人民政府生态环境主管部门应当会同自然资源主管部门对下列建设用地地块进行重点监测："},{"i":18,"n":"第十八条","txt":"各类涉及土地利用的规划和可能造成土壤污染的建设项目，应当依法进行环境影响评价。环境影响评价文件应当包括对土壤可能造成的不良影响及应当采取的相应预防措施等内容。"},{"i":19,"n":"第十九条","txt":"生产、使用、贮存、运输、回收、处置、排放有毒有害物质的单位和个人，应当采取有效措施，防止有毒有害物质渗漏、流失、扬散，避免土壤受到污染。"},{"i":20,"n":"第二十条","txt":"国务院生态环境主管部门应当会同国务院卫生健康等主管部门，根据对公众健康、生态环境的危害和影响程度，对土壤中有毒有害物质进行筛查评估，公布重点控制的土壤有毒有害物质名录，并适时更新。"},{"i":21,"n":"第二十一条","txt":"设区的市级以上地方人民政府生态环境主管部门应当按照国务院生态环境主管部门的规定，根据有毒有害物质排放等情况，制定本行政区域土壤污染重点监管单位名录，向社会公开并适时更新。"},{"i":22,"n":"第二十二条","txt":"企业事业单位拆除设施、设备或者建筑物、构筑物的，应当采取相应的土壤污染防治措施。"},{"i":23,"n":"第二十三条","txt":"各级人民政府生态环境、自然资源主管部门应当依法加强对矿产资源开发区域土壤污染防治的监督管理，按照相关标准和总量控制的要求，严格控制可能造成土壤污染的重点污染物排放。"},{"i":24,"n":"第二十四条","txt":"国家鼓励在建筑、通信、电力、交通、水利等领域的信息、网络、防雷、接地等建设工程中采用新技术、新材料，防止土壤污染。"},{"i":25,"n":"第二十五条","txt":"建设和运行污水集中处理设施、固体废物处置设施，应当依照法律法规和相关标准的要求，采取措施防止土壤污染。"},{"i":26,"n":"第二十六条","txt":"国务院农业农村、林业草原主管部门应当制定规划，完善相关标准和措施，加强农用地农药、化肥使用指导和使用总量控制，加强农用薄膜使用控制。"},{"i":27,"n":"第二十七条","txt":"地方人民政府农业农村、林业草原主管部门应当开展农用地土壤污染防治宣传和技术培训活动，扶持农业生产专业化服务，指导农业生产者合理使用农药、兽药、肥料、饲料、农用薄膜等农业投入品，控制农药、兽药、化肥等的使用量。"},{"i":28,"n":"第二十八条","txt":"禁止向农用地排放重金属或者其他有毒有害物质含量超标的污水、污泥，以及可能造成土壤污染的清淤底泥、尾矿、矿渣等。"},{"i":29,"n":"第二十九条","txt":"国家鼓励和支持农业生产者采取下列措施："},{"i":30,"n":"第三十条","txt":"禁止生产、销售、使用国家明令禁止的农业投入品。"},{"i":31,"n":"第三十一条","txt":"国家加强对未污染土壤的保护。"},{"i":32,"n":"第三十二条","txt":"县级以上地方人民政府及其有关部门应当按照土地利用总体规划和城乡规划，严格执行相关行业企业布局选址要求，禁止在居民区和学校、医院、疗养院、养老院等单位周边新建、改建、扩建可能造成土壤污染的建设项目。"},{"i":33,"n":"第三十三条","txt":"国家加强对土壤资源的保护和合理利用。对开发建设过程中剥离的表土，应当单独收集和存放，符合条件的应当优先用于土地复垦、土壤改良、造地和绿化等。"},{"i":34,"n":"第三十四条","txt":"因科学研究等特殊原因，需要进口土壤的，应当遵守国家出入境检验检疫的有关规定。"},{"i":35,"n":"第三十五条","txt":"土壤污染风险管控和修复，包括土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估、后期管理等活动。"},{"i":36,"n":"第三十六条","txt":"实施土壤污染状况调查活动，应当编制土壤污染状况调查报告。"},{"i":37,"n":"第三十七条","txt":"实施土壤污染风险评估活动，应当编制土壤污染风险评估报告。"},{"i":38,"n":"第三十八条","txt":"实施风险管控、修复活动，应当因地制宜、科学合理，提高针对性和有效性。"},{"i":39,"n":"第三十九条","txt":"实施风险管控、修复活动前，地方人民政府有关部门有权根据实际情况，要求土壤污染责任人、土地使用权人采取移除污染源、防止污染扩散等措施。"},{"i":40,"n":"第四十条","txt":"实施风险管控、修复活动中产生的废水、废气和固体废物，应当按照规定进行处理、处置，并达到相关环境保护标准。"},{"i":41,"n":"第四十一条","txt":"修复施工单位转运污染土壤的，应当制定转运计划，将运输时间、方式、线路和污染土壤数量、去向、最终处置措施等，提前报所在地和接收地生态环境主管部门。"},{"i":42,"n":"第四十二条","txt":"实施风险管控效果评估、修复效果评估活动，应当编制效果评估报告。"},{"i":43,"n":"第四十三条","txt":"从事土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估、后期管理等活动的单位，应当具备相应的专业能力。"},{"i":44,"n":"第四十四条","txt":"发生突发事件可能造成土壤污染的，地方人民政府及其有关部门和相关企业事业单位以及其他生产经营者应当立即采取应急措施，防止土壤污染，并依照本法规定做好土壤污染状况监测、调查和土壤污染风险评估、风险管控、修复等工作。"},{"i":45,"n":"第四十五条","txt":"土壤污染责任人负有实施土壤污染风险管控和修复的义务。土壤污染责任人无法认定的，土地使用权人应当实施土壤污染风险管控和修复。"},{"i":46,"n":"第四十六条","txt":"因实施或者组织实施土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估、后期管理等活动所支出的费用，由土壤污染责任人承担。"},{"i":47,"n":"第四十七条","txt":"土壤污染责任人变更的，由变更后承继其债权、债务的单位或者个人履行相关土壤污染风险管控和修复义务并承担相关费用。"},{"i":48,"n":"第四十八条","txt":"土壤污染责任人不明确或者存在争议的，农用地由地方人民政府农业农村、林业草原主管部门会同生态环境、自然资源主管部门认定，建设用地由地方人民政府生态环境主管部门会同自然资源主管部门认定。认定办法由国务院生态环境主管部门会同有关部门制定。"},{"i":49,"n":"第四十九条","txt":"国家建立农用地分类管理制度。按照土壤污染程度和相关标准，将农用地划分为优先保护类、安全利用类和严格管控类。"},{"i":50,"n":"第五十条","txt":"县级以上地方人民政府应当依法将符合条件的优先保护类耕地划为永久基本农田，实行严格保护。"},{"i":51,"n":"第五十一条","txt":"未利用地、复垦土地等拟开垦为耕地的，地方人民政府农业农村主管部门应当会同生态环境、自然资源主管部门进行土壤污染状况调查，依法进行分类管理。"},{"i":52,"n":"第五十二条","txt":"对土壤污染状况普查、详查和监测、现场检查表明有土壤污染风险的农用地地块，地方人民政府农业农村、林业草原主管部门应当会同生态环境、自然资源主管部门进行土壤污染状况调查。"},{"i":53,"n":"第五十三条","txt":"对安全利用类农用地地块，地方人民政府农业农村、林业草原主管部门，应当结合主要作物品种和种植习惯等情况，制定并实施安全利用方案。"},{"i":54,"n":"第五十四条","txt":"对严格管控类农用地地块，地方人民政府农业农村、林业草原主管部门应当采取下列风险管控措施："},{"i":55,"n":"第五十五条","txt":"安全利用类和严格管控类农用地地块的土壤污染影响或者可能影响地下水、饮用水水源安全的，地方人民政府生态环境主管部门应当会同农业农村、林业草原等主管部门制定防治污染的方案，并采取相应的措施。"},{"i":56,"n":"第五十六条","txt":"对安全利用类和严格管控类农用地地块，土壤污染责任人应当按照国家有关规定以及土壤污染风险评估报告的要求，采取相应的风险管控措施，并定期向地方人民政府农业农村、林业草原主管部门报告。"},{"i":57,"n":"第五十七条","txt":"对产出的农产品污染物含量超标，需要实施修复的农用地地块，土壤污染责任人应当编制修复方案，报地方人民政府农业农村、林业草原主管部门备案并实施。修复方案应当包括地下水污染防治的内容。"},{"i":58,"n":"第五十八条","txt":"国家实行建设用地土壤污染风险管控和修复名录制度。"},{"i":59,"n":"第五十九条","txt":"对土壤污染状况普查、详查和监测、现场检查表明有土壤污染风险的建设用地地块，地方人民政府生态环境主管部门应当要求土地使用权人按照规定进行土壤污染状况调查。"},{"i":60,"n":"第六十条","txt":"对土壤污染状况调查报告评审表明污染物含量超过土壤污染风险管控标准的建设用地地块，土壤污染责任人、土地使用权人应当按照国务院生态环境主管部门的规定进行土壤污染风险评估，并将土壤污染风险评估报告报省级人民政府生态环境主管部门。"},{"i":61,"n":"第六十一条","txt":"省级人民政府生态环境主管部门应当会同自然资源等主管部门按照国务院生态环境主管部门的规定，对土壤污染风险评估报告组织评审，及时将需要实施风险管控、修复的地块纳入建设用地土壤污染风险管控和修复名录，并定期向国务院生态环境主管部门报告。"},{"i":62,"n":"第六十二条","txt":"对建设用地土壤污染风险管控和修复名录中的地块，土壤污染责任人应当按照国家有关规定以及土壤污染风险评估报告的要求，采取相应的风险管控措施，并定期向地方人民政府生态环境主管部门报告。风险管控措施应当包括地下水污染防治的内容。"},{"i":63,"n":"第六十三条","txt":"对建设用地土壤污染风险管控和修复名录中的地块，地方人民政府生态环境主管部门可以根据实际情况采取下列风险管控措施："},{"i":64,"n":"第六十四条","txt":"对建设用地土壤污染风险管控和修复名录中需要实施修复的地块，土壤污染责任人应当结合土地利用总体规划和城乡规划编制修复方案，报地方人民政府生态环境主管部门备案并实施。修复方案应当包括地下水污染防治的内容。"},{"i":65,"n":"第六十五条","txt":"风险管控、修复活动完成后，土壤污染责任人应当另行委托有关单位对风险管控效果、修复效果进行评估，并将效果评估报告报地方人民政府生态环境主管部门备案。"},{"i":66,"n":"第六十六条","txt":"对达到土壤污染风险评估报告确定的风险管控、修复目标的建设用地地块，土壤污染责任人、土地使用权人可以申请省级人民政府生态环境主管部门移出建设用地土壤污染风险管控和修复名录。"},{"i":67,"n":"第六十七条","txt":"土壤污染重点监管单位生产经营用地的用途变更或者在其土地使用权收回、转让前，应当由土地使用权人按照规定进行土壤污染状况调查。土壤污染状况调查报告应当作为不动产登记资料送交地方人民政府不动产登记机构，并报地方人民政府生态环境主管部门备案。"},{"i":68,"n":"第六十八条","txt":"土地使用权已经被地方人民政府收回，土壤污染责任人为原土地使用权人的，由地方人民政府组织实施土壤污染风险管控和修复。"},{"i":69,"n":"第六十九条","txt":"国家采取有利于土壤污染防治的财政、税收、价格、金融等经济政策和措施。"},{"i":70,"n":"第七十条","txt":"各级人民政府应当加强对土壤污染的防治，安排必要的资金用于下列事项："},{"i":71,"n":"第七十一条","txt":"国家加大土壤污染防治资金投入力度，建立土壤污染防治基金制度。设立中央土壤污染防治专项资金和省级土壤污染防治基金，主要用于农用地土壤污染防治和土壤污染责任人或者土地使用权人无法认定的土壤污染风险管控和修复以及政府规定的其他事项。"},{"i":72,"n":"第七十二条","txt":"国家鼓励金融机构加大对土壤污染风险管控和修复项目的信贷投放。"},{"i":73,"n":"第七十三条","txt":"从事土壤污染风险管控和修复的单位依照法律、行政法规的规定，享受税收优惠。"},{"i":74,"n":"第七十四条","txt":"国家鼓励并提倡社会各界为防治土壤污染捐赠财产，并依照法律、行政法规的规定，给予税收优惠。"},{"i":75,"n":"第七十五条","txt":"县级以上人民政府应当将土壤污染防治情况纳入环境状况和环境保护目标完成情况年度报告，向本级人民代表大会或者人民代表大会常务委员会报告。"},{"i":76,"n":"第七十六条","txt":"省级以上人民政府生态环境主管部门应当会同有关部门对土壤污染问题突出、防治工作不力、群众反映强烈的地区，约谈设区的市级以上地方人民政府及其有关部门主要负责人，要求其采取措施及时整改。约谈整改情况应当向社会公开。"},{"i":77,"n":"第七十七条","txt":"生态环境主管部门及其环境执法机构和其他负有土壤污染防治监督管理职责的部门，有权对从事可能造成土壤污染活动的企业事业单位和其他生产经营者进行现场检查、取样，要求被检查者提供有关资料、就有关问题作出说明。"},{"i":78,"n":"第七十八条","txt":"企业事业单位和其他生产经营者违反法律法规规定排放有毒有害物质，造成或者可能造成严重土壤污染的，或者有关证据可能灭失或者被隐匿的，生态环境主管部门和其他负有土壤污染防治监督管理职责的部门，可以查封、扣押有关设施、设备、物品。"},{"i":79,"n":"第七十九条","txt":"地方人民政府安全生产监督管理部门应当监督尾矿库运营、管理单位履行防治土壤污染的法定义务，防止其发生可能污染土壤的事故；地方人民政府生态环境主管部门应当加强对尾矿库土壤污染防治情况的监督检查和定期评估，发现风险隐患的，及时督促尾矿库运营、管理单位采取相应措施。"},{"i":80,"n":"第八十条","txt":"省级以上人民政府生态环境主管部门和其他负有土壤污染防治监督管理职责的部门应当将从事土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估、后期管理等活动的单位和个人的执业情况，纳入信用系统建立信用记录，将违法信息记入社会诚信档案，并纳入全国信用信息共享平台和国家企业信用信息公示系统向社会公布。"},{"i":81,"n":"第八十一条","txt":"生态环境主管部门和其他负有土壤污染防治监督管理职责的部门应当依法公开土壤污染状况和防治信息。"},{"i":82,"n":"第八十二条","txt":"土壤污染状况普查报告、监测数据、调查报告和土壤污染风险评估报告、风险管控效果评估报告、修复效果评估报告等，应当及时上传全国土壤环境信息平台。"},{"i":83,"n":"第八十三条","txt":"新闻媒体对违反土壤污染防治法律法规的行为享有舆论监督的权利，受监督的单位和个人不得打击报复。"},{"i":84,"n":"第八十四条","txt":"任何组织和个人对污染土壤的行为，均有向生态环境主管部门和其他负有土壤污染防治监督管理职责的部门报告或者举报的权利。"},{"i":85,"n":"第八十五条","txt":"地方各级人民政府、生态环境主管部门或者其他负有土壤污染防治监督管理职责的部门未依照本法规定履行职责的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":86,"n":"第八十六条","txt":"违反本法规定，有下列行为之一的，由地方人民政府生态环境主管部门或者其他负有土壤污染防治监督管理职责的部门责令改正，处以罚款；拒不改正的，责令停产整治："},{"i":87,"n":"第八十七条","txt":"违反本法规定，向农用地排放重金属或者其他有毒有害物质含量超标的污水、污泥，以及可能造成土壤污染的清淤底泥、尾矿、矿渣等的，由地方人民政府生态环境主管部门责令改正，处十万元以上五十万元以下的罚款；情节严重的，处五十万元以上二百万元以下的罚款，并可以将案件移送公安机关，对直接负责的主管人员和其他直接责任人员处五日以上十五日以下的拘留；有违法所得的，没收违法所得。"},{"i":88,"n":"第八十八条","txt":"违反本法规定，农业投入品生产者、销售者、使用者未按照规定及时回收肥料等农业投入品的包装废弃物或者农用薄膜，或者未按照规定及时回收农药包装废弃物交由专门的机构或者组织进行无害化处理的，由地方人民政府农业农村主管部门责令改正，处一万元以上十万元以下的罚款；农业投入品使用者为个人的，可以处二百元以上二千元以下的罚款。"},{"i":89,"n":"第八十九条","txt":"违反本法规定，将重金属或者其他有毒有害物质含量超标的工业固体废物、生活垃圾或者污染土壤用于土地复垦的，由地方人民政府生态环境主管部门责令改正，处十万元以上一百万元以下的罚款；有违法所得的，没收违法所得。"},{"i":90,"n":"第九十条","txt":"违反本法规定，受委托从事土壤污染状况调查和土壤污染风险评估、风险管控效果评估、修复效果评估活动的单位，出具虚假调查报告、风险评估报告、风险管控效果评估报告、修复效果评估报告的，由地方人民政府生态环境主管部门处十万元以上五十万元以下的罚款；情节严重的，禁止从事上述业务，并处五十万元以上一百万元以下的罚款；有违法所得的，没收违法所得。"},{"i":91,"n":"第九十一条","txt":"违反本法规定，有下列行为之一的，由地方人民政府生态环境主管部门责令改正，处十万元以上五十万元以下的罚款；情节严重的，处五十万元以上一百万元以下的罚款；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员处五千元以上二万元以下的罚款："},{"i":92,"n":"第九十二条","txt":"违反本法规定，土壤污染责任人或者土地使用权人未按照规定实施后期管理的，由地方人民政府生态环境主管部门或者其他负有土壤污染防治监督管理职责的部门责令改正，处一万元以上五万元以下的罚款；情节严重的，处五万元以上五十万元以下的罚款。"},{"i":93,"n":"第九十三条","txt":"违反本法规定，被检查者拒不配合检查，或者在接受检查时弄虚作假的，由地方人民政府生态环境主管部门或者其他负有土壤污染防治监督管理职责的部门责令改正，处二万元以上二十万元以下的罚款；对直接负责的主管人员和其他直接责任人员处五千元以上二万元以下的罚款。"},{"i":94,"n":"第九十四条","txt":"违反本法规定，土壤污染责任人或者土地使用权人有下列行为之一的，由地方人民政府生态环境主管部门或者其他负有土壤污染防治监督管理职责的部门责令改正，处二万元以上二十万元以下的罚款；拒不改正的，处二十万元以上一百万元以下的罚款，并委托他人代为履行，所需费用由土壤污染责任人或者土地使用权人承担；对直接负责的主管人员和其他直接责任人员处五千元以上二万元以下的罚款："},{"i":95,"n":"第九十五条","txt":"违反本法规定，有下列行为之一的，由地方人民政府有关部门责令改正；拒不改正的，处一万元以上五万元以下的罚款："},{"i":96,"n":"第九十六条","txt":"污染土壤造成他人人身或者财产损害的，应当依法承担侵权责任。"},{"i":97,"n":"第九十七条","txt":"污染土壤损害国家利益、社会公共利益的，有关机关和组织可以依照《中华人民共和国环境保护法》《中华人民共和国民事诉讼法》《中华人民共和国行政诉讼法》等法律的规定向人民法院提起诉讼。"},{"i":98,"n":"第九十八条","txt":"违反本法规定，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":99,"n":"第九十九条","txt":"本法自2019年1月1日起施行。"}],"waiziqiyefa":[{"i":1,"n":"第一条","txt":"为了扩大对外经济合作和技术交流，促进中国国民经济的发展，中华人民共和国允许外国的企业和其他经济组织或者个人（以下简称外国投资者）在中国境内举办外资企业，保护外资企业的合法权益。"},{"i":2,"n":"第二条","txt":"本法所称的外资企业是指依照中国有关法律在中国境内设立的全部资本由外国投资者投资的企业，不包括外国的企业和其他经济组织在中国境内的分支机构。"},{"i":3,"n":"第三条","txt":"设立外资企业，必须有利于中国国民经济的发展。国家鼓励举办产品出口或者技术先进的外资企业。"},{"i":4,"n":"第四条","txt":"外国投资者在中国境内的投资、获得的利润和其他合法权益，受中国法律保护。"},{"i":5,"n":"第五条","txt":"国家对外资企业不实行国有化和征收；在特殊情况下，根据社会公共利益的需要，对外资企业可以依照法律程序实行征收，并给予相应的补偿。"},{"i":6,"n":"第六条","txt":"设立外资企业的申请，由国务院对外经济贸易主管部门或者国务院授权的机关审查批准。审查批准机关应当在接到申请之日起九十天内决定批准或者不批准。"},{"i":7,"n":"第七条","txt":"设立外资企业的申请经批准后，外国投资者应当在接到批准证书之日起三十天内向工商行政管理机关申请登记，领取营业执照。外资企业的营业执照签发日期，为该企业成立日期。"},{"i":8,"n":"第八条","txt":"外资企业符合中国法律关于法人条件的规定的，依法取得中国法人资格。"},{"i":9,"n":"第九条","txt":"外资企业应当在审查批准机关核准的期限内在中国境内投资；逾期不投资的，工商行政管理机关有权吊销营业执照。"},{"i":10,"n":"第十条","txt":"外资企业分立、合并或者其他重要事项变更，应当报审查批准机关批准，并向工商行政管理机关办理变更登记手续。"},{"i":11,"n":"第十一条","txt":"外资企业依照经批准的章程进行经营管理活动，不受干涉。"},{"i":12,"n":"第十二条","txt":"外资企业雇用中国职工应当依法签定合同，并在合同中订明雇用、解雇、报酬、福利、劳动保护、劳动保险等事项。"},{"i":13,"n":"第十三条","txt":"外资企业的职工依法建立工会组织，开展工会活动，维护职工的合法权益。"},{"i":14,"n":"第十四条","txt":"外资企业必须在中国境内设置会计帐簿，进行独立核算，按照规定报送会计报表，并接受财政税务机关的监督。"},{"i":15,"n":"第十五条","txt":"外资企业在批准的经营范围内所需的原材料、燃料等物资，按照公平、合理的原则，可以在国内市场或者在国际市场购买。"},{"i":16,"n":"第十六条","txt":"外资企业的各项保险应当向中国境内的保险公司投保。"},{"i":17,"n":"第十七条","txt":"外资企业依照国家有关税收的规定纳税并可以享受减税、免税的优惠待遇。"},{"i":18,"n":"第十八条","txt":"外资企业的外汇事宜，依照国家外汇管理规定办理。"},{"i":19,"n":"第十九条","txt":"外国投资者从外资企业获得的合法利润、其他合法收入和清算后的资金，可以汇往国外。"},{"i":20,"n":"第二十条","txt":"外资企业的经营期限由外国投资者申报，由审查批准机关批准。期满需要延长的，应当在期满一百八十天以前向审查批准机关提出申请。审查批准机关应当在接到申请之日起三十天内决定批准或者不批准。"},{"i":21,"n":"第二十一条","txt":"外资企业终止，应当及时公告，按照法定程序进行清算。"},{"i":22,"n":"第二十二条","txt":"外资企业终止，应当向工商行政管理机关办理注销登记手续，缴销营业执照。"},{"i":23,"n":"第二十三条","txt":"举办外资企业不涉及国家规定实施准入特别管理措施的，对本法第六条、第十条、第二十条规定的审批事项，适用备案管理。国家规定的准入特别管理措施由国务院发布或者批准发布。"},{"i":24,"n":"第二十四条","txt":"国务院对外经济贸易主管部门根据本法制定实施细则，报国务院批准后施行。"},{"i":25,"n":"第二十五条","txt":"本法自公布之日起施行。"}],"wuquanfa":[{"i":1,"n":"第一条","txt":"为了维护国家基本经济制度，维护社会主义市场经济秩序，明确物的归属，发挥物的效用，保护权利人的物权，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"因物的归属和利用而产生的民事关系，适用本法。"},{"i":3,"n":"第三条","txt":"国家在社会主义初级阶段，坚持公有制为主体、多种所有制经济共同发展的基本经济制度。"},{"i":4,"n":"第四条","txt":"国家、集体、私人的物权和其他权利人的物权受法律保护，任何单位和个人不得侵犯。"},{"i":5,"n":"第五条","txt":"物权的种类和内容，由法律规定。"},{"i":6,"n":"第六条","txt":"不动产物权的设立、变更、转让和消灭，应当依照法律规定登记。动产物权的设立和转让，应当依照法律规定交付。"},{"i":7,"n":"第七条","txt":"物权的取得和行使，应当遵守法律，尊重社会公德，不得损害公共利益和他人合法权益。"},{"i":8,"n":"第八条","txt":"其他相关法律对物权另有特别规定的，依照其规定。"},{"i":9,"n":"第九条","txt":"不动产物权的设立、变更、转让和消灭，经依法登记，发生效力；未经登记，不发生效力，但法律另有规定的除外。"},{"i":10,"n":"第十条","txt":"不动产登记，由不动产所在地的登记机构办理。"},{"i":11,"n":"第十一条","txt":"当事人申请登记，应当根据不同登记事项提供权属证明和不动产界址、面积等必要材料。"},{"i":12,"n":"第十二条","txt":"登记机构应当履行下列职责："},{"i":13,"n":"第十三条","txt":"登记机构不得有下列行为："},{"i":14,"n":"第十四条","txt":"不动产物权的设立、变更、转让和消灭，依照法律规定应当登记的，自记载于不动产登记簿时发生效力。"},{"i":15,"n":"第十五条","txt":"当事人之间订立有关设立、变更、转让和消灭不动产物权的合同，除法律另有规定或者合同另有约定外，自合同成立时生效；未办理物权登记的，不影响合同效力。"},{"i":16,"n":"第十六条","txt":"不动产登记簿是物权归属和内容的根据。"},{"i":17,"n":"第十七条","txt":"不动产权属证书是权利人享有该不动产物权的证明。不动产权属证书记载的事项，应当与不动产登记簿一致；记载不一致的，除有证据证明不动产登记簿确有错误外，以不动产登记簿为准。"},{"i":18,"n":"第十八条","txt":"权利人、利害关系人可以申请查询、复制登记资料，登记机构应当提供。"},{"i":19,"n":"第十九条","txt":"权利人、利害关系人认为不动产登记簿记载的事项错误的，可以申请更正登记。不动产登记簿记载的权利人书面同意更正或者有证据证明登记确有错误的，登记机构应当予以更正。"},{"i":20,"n":"第二十条","txt":"当事人签订买卖房屋或者其他不动产物权的协议，为保障将来实现物权，按照约定可以向登记机构申请预告登记。预告登记后，未经预告登记的权利人同意，处分该不动产的，不发生物权效力。"},{"i":21,"n":"第二十一条","txt":"当事人提供虚假材料申请登记，给他人造成损害的，应当承担赔偿责任。"},{"i":22,"n":"第二十二条","txt":"不动产登记费按件收取，不得按照不动产的面积、体积或者价款的比例收取。具体收费标准由国务院有关部门会同价格主管部门规定。"},{"i":23,"n":"第二十三条","txt":"动产物权的设立和转让，自交付时发生效力，但法律另有规定的除外。"},{"i":24,"n":"第二十四条","txt":"船舶、航空器和机动车等物权的设立、变更、转让和消灭，未经登记，不得对抗善意第三人。"},{"i":25,"n":"第二十五条","txt":"动产物权设立和转让前，权利人已经依法占有该动产的，物权自法律行为生效时发生效力。"},{"i":26,"n":"第二十六条","txt":"动产物权设立和转让前，第三人依法占有该动产的，负有交付义务的人可以通过转让请求第三人返还原物的权利代替交付。"},{"i":27,"n":"第二十七条","txt":"动产物权转让时，双方又约定由出让人继续占有该动产的，物权自该约定生效时发生效力。"},{"i":28,"n":"第二十八条","txt":"因人民法院、仲裁委员会的法律文书或者人民政府的征收决定等，导致物权设立、变更、转让或者消灭的，自法律文书或者人民政府的征收决定等生效时发生效力。"},{"i":29,"n":"第二十九条","txt":"因继承或者受遗赠取得物权的，自继承或者受遗赠开始时发生效力。"},{"i":30,"n":"第三十条","txt":"因合法建造、拆除房屋等事实行为设立或者消灭物权的，自事实行为成就时发生效力。"},{"i":31,"n":"第三十一条","txt":"依照本法第二十八条至第三十条规定享有不动产物权的，处分该物权时，依照法律规定需要办理登记的，未经登记，不发生物权效力。"},{"i":32,"n":"第三十二条","txt":"物权受到侵害的，权利人可以通过和解、调解、仲裁、诉讼等途径解决。"},{"i":33,"n":"第三十三条","txt":"因物权的归属、内容发生争议的，利害关系人可以请求确认权利。"},{"i":34,"n":"第三十四条","txt":"无权占有不动产或者动产的，权利人可以请求返还原物。"},{"i":35,"n":"第三十五条","txt":"妨害物权或者可能妨害物权的，权利人可以请求排除妨害或者消除危险。"},{"i":36,"n":"第三十六条","txt":"造成不动产或者动产毁损的，权利人可以请求修理、重作、更换或者恢复原状。"},{"i":37,"n":"第三十七条","txt":"侵害物权，造成权利人损害的，权利人可以请求损害赔偿，也可以请求承担其他民事责任。"},{"i":38,"n":"第三十八条","txt":"本章规定的物权保护方式，可以单独适用，也可以根据权利被侵害的情形合并适用。"},{"i":39,"n":"第三十九条","txt":"所有权人对自己的不动产或者动产，依法享有占有、使用、收益和处分的权利。"},{"i":40,"n":"第四十条","txt":"所有权人有权在自己的不动产或者动产上设立用益物权和担保物权。用益物权人、担保物权人行使权利，不得损害所有权人的权益。"},{"i":41,"n":"第四十一条","txt":"法律规定专属于国家所有的不动产和动产，任何单位和个人不能取得所有权。"},{"i":42,"n":"第四十二条","txt":"为了公共利益的需要，依照法律规定的权限和程序可以征收集体所有的土地和单位、个人的房屋及其他不动产。"},{"i":43,"n":"第四十三条","txt":"国家对耕地实行特殊保护，严格限制农用地转为建设用地，控制建设用地总量。不得违反法律规定的权限和程序征收集体所有的土地。"},{"i":44,"n":"第四十四条","txt":"因抢险、救灾等紧急需要，依照法律规定的权限和程序可以征用单位、个人的不动产或者动产。被征用的不动产或者动产使用后，应当返还被征用人。单位、个人的不动产或者动产被征用或者征用后毁损、灭失的，应当给予补偿。"},{"i":45,"n":"第四十五条","txt":"法律规定属于国家所有的财产，属于国家所有即全民所有。"},{"i":46,"n":"第四十六条","txt":"矿藏、水流、海域属于国家所有。"},{"i":47,"n":"第四十七条","txt":"城市的土地，属于国家所有。法律规定属于国家所有的农村和城市郊区的土地，属于国家所有。"},{"i":48,"n":"第四十八条","txt":"森林、山岭、草原、荒地、滩涂等自然资源，属于国家所有，但法律规定属于集体所有的除外。"},{"i":49,"n":"第四十九条","txt":"法律规定属于国家所有的野生动植物资源，属于国家所有。"},{"i":50,"n":"第五十条","txt":"无线电频谱资源属于国家所有。"},{"i":51,"n":"第五十一条","txt":"法律规定属于国家所有的文物，属于国家所有。"},{"i":52,"n":"第五十二条","txt":"国防资产属于国家所有。"},{"i":53,"n":"第五十三条","txt":"国家机关对其直接支配的不动产和动产，享有占有、使用以及依照法律和国务院的有关规定处分的权利。"},{"i":54,"n":"第五十四条","txt":"国家举办的事业单位对其直接支配的不动产和动产，享有占有、使用以及依照法律和国务院的有关规定收益、处分的权利。"},{"i":55,"n":"第五十五条","txt":"国家出资的企业，由国务院、地方人民政府依照法律、行政法规规定分别代表国家履行出资人职责，享有出资人权益。"},{"i":56,"n":"第五十六条","txt":"国家所有的财产受法律保护，禁止任何单位和个人侵占、哄抢、私分、截留、破坏。"},{"i":57,"n":"第五十七条","txt":"履行国有财产管理、监督职责的机构及其工作人员，应当依法加强对国有财产的管理、监督，促进国有财产保值增值，防止国有财产损失；滥用职权，玩忽职守，造成国有财产损失的，应当依法承担法律责任。"},{"i":58,"n":"第五十八条","txt":"集体所有的不动产和动产包括："},{"i":59,"n":"第五十九条","txt":"农民集体所有的不动产和动产，属于本集体成员集体所有。"},{"i":60,"n":"第六十条","txt":"对于集体所有的土地和森林、山岭、草原、荒地、滩涂等，依照下列规定行使所有权："},{"i":61,"n":"第六十一条","txt":"城镇集体所有的不动产和动产，依照法律、行政法规的规定由本集体享有占有、使用、收益和处分的权利。"},{"i":62,"n":"第六十二条","txt":"集体经济组织或者村民委员会、村民小组应当依照法律、行政法规以及章程、村规民约向本集体成员公布集体财产的状况。"},{"i":63,"n":"第六十三条","txt":"集体所有的财产受法律保护，禁止任何单位和个人侵占、哄抢、私分、破坏。"},{"i":64,"n":"第六十四条","txt":"私人对其合法的收入、房屋、生活用品、生产工具、原材料等不动产和动产享有所有权。"},{"i":65,"n":"第六十五条","txt":"私人合法的储蓄、投资及其收益受法律保护。"},{"i":66,"n":"第六十六条","txt":"私人的合法财产受法律保护，禁止任何单位和个人侵占、哄抢、破坏。"},{"i":67,"n":"第六十七条","txt":"国家、集体和私人依法可以出资设立有限责任公司、股份有限公司或者其他企业。国家、集体和私人所有的不动产或者动产，投到企业的，由出资人按照约定或者出资比例享有资产收益、重大决策以及选择经营管理者等权利并履行义务。"},{"i":68,"n":"第六十八条","txt":"企业法人对其不动产和动产依照法律、行政法规以及章程享有占有、使用、收益和处分的权利。"},{"i":69,"n":"第六十九条","txt":"社会团体依法所有的不动产和动产，受法律保护。"},{"i":70,"n":"第七十条","txt":"业主对建筑物内的住宅、经营性用房等专有部分享有所有权，对专有部分以外的共有部分享有共有和共同管理的权利。"},{"i":71,"n":"第七十一条","txt":"业主对其建筑物专有部分享有占有、使用、收益和处分的权利。业主行使权利不得危及建筑物的安全，不得损害其他业主的合法权益。"},{"i":72,"n":"第七十二条","txt":"业主对建筑物专有部分以外的共有部分，享有权利，承担义务；不得以放弃权利不履行义务。"},{"i":73,"n":"第七十三条","txt":"建筑区划内的道路，属于业主共有，但属于城镇公共道路的除外。建筑区划内的绿地，属于业主共有，但属于城镇公共绿地或者明示属于个人的除外。建筑区划内的其他公共场所、公用设施和物业服务用房，属于业主共有。"},{"i":74,"n":"第七十四条","txt":"建筑区划内，规划用于停放汽车的车位、车库应当首先满足业主的需要。"},{"i":75,"n":"第七十五条","txt":"业主可以设立业主大会，选举业主委员会。"},{"i":76,"n":"第七十六条","txt":"下列事项由业主共同决定："},{"i":77,"n":"第七十七条","txt":"业主不得违反法律、法规以及管理规约，将住宅改变为经营性用房。业主将住宅改变为经营性用房的，除遵守法律、法规以及管理规约外，应当经有利害关系的业主同意。"},{"i":78,"n":"第七十八条","txt":"业主大会或者业主委员会的决定，对业主具有约束力。"},{"i":79,"n":"第七十九条","txt":"建筑物及其附属设施的维修资金，属于业主共有。经业主共同决定，可以用于电梯、水箱等共有部分的维修。维修资金的筹集、使用情况应当公布。"},{"i":80,"n":"第八十条","txt":"建筑物及其附属设施的费用分摊、收益分配等事项，有约定的，按照约定；没有约定或者约定不明确的，按照业主专有部分占建筑物总面积的比例确定。"},{"i":81,"n":"第八十一条","txt":"业主可以自行管理建筑物及其附属设施，也可以委托物业服务企业或者其他管理人管理。"},{"i":82,"n":"第八十二条","txt":"物业服务企业或者其他管理人根据业主的委托管理建筑区划内的建筑物及其附属设施，并接受业主的监督。"},{"i":83,"n":"第八十三条","txt":"业主应当遵守法律、法规以及管理规约。"},{"i":84,"n":"第八十四条","txt":"不动产的相邻权利人应当按照有利生产、方便生活、团结互助、公平合理的原则，正确处理相邻关系。"},{"i":85,"n":"第八十五条","txt":"法律、法规对处理相邻关系有规定的，依照其规定；法律、法规没有规定的，可以按照当地习惯。"},{"i":86,"n":"第八十六条","txt":"不动产权利人应当为相邻权利人用水、排水提供必要的便利。"},{"i":87,"n":"第八十七条","txt":"不动产权利人对相邻权利人因通行等必须利用其土地的，应当提供必要的便利。"},{"i":88,"n":"第八十八条","txt":"不动产权利人因建造、修缮建筑物以及铺设电线、电缆、水管、暖气和燃气管线等必须利用相邻土地、建筑物的，该土地、建筑物的权利人应当提供必要的便利。"},{"i":89,"n":"第八十九条","txt":"建造建筑物，不得违反国家有关工程建设标准，妨碍相邻建筑物的通风、采光和日照。"},{"i":90,"n":"第九十条","txt":"不动产权利人不得违反国家规定弃置固体废物，排放大气污染物、水污染物、噪声、光、电磁波辐射等有害物质。"},{"i":91,"n":"第九十一条","txt":"不动产权利人挖掘土地、建造建筑物、铺设管线以及安装设备等，不得危及相邻不动产的安全。"},{"i":92,"n":"第九十二条","txt":"不动产权利人因用水、排水、通行、铺设管线等利用相邻不动产的，应当尽量避免对相邻的不动产权利人造成损害；造成损害的，应当给予赔偿。"},{"i":93,"n":"第九十三条","txt":"不动产或者动产可以由两个以上单位、个人共有。共有包括按份共有和共同共有。"},{"i":94,"n":"第九十四条","txt":"按份共有人对共有的不动产或者动产按照其份额享有所有权。"},{"i":95,"n":"第九十五条","txt":"共同共有人对共有的不动产或者动产共同享有所有权。"},{"i":96,"n":"第九十六条","txt":"共有人按照约定管理共有的不动产或者动产；没有约定或者约定不明确的，各共有人都有管理的权利和义务。"},{"i":97,"n":"第九十七条","txt":"处分共有的不动产或者动产以及对共有的不动产或者动产作重大修缮的，应当经占份额三分之二以上的按份共有人或者全体共同共有人同意，但共有人之间另有约定的除外。"},{"i":98,"n":"第九十八条","txt":"对共有物的管理费用以及其他负担，有约定的，按照约定；没有约定或者约定不明确的，按份共有人按照其份额负担，共同共有人共同负担。"},{"i":99,"n":"第九十九条","txt":"共有人约定不得分割共有的不动产或者动产，以维持共有关系的，应当按照约定，但共有人有重大理由需要分割的，可以请求分割；没有约定或者约定不明确的，按份共有人可以随时请求分割，共同共有人在共有的基础丧失或者有重大理由需要分割时可以请求分割。因分割对其他共有人造成损害的，应当给予赔偿。"},{"i":100,"n":"第一百条","txt":"共有人可以协商确定分割方式。达不成协议，共有的不动产或者动产可以分割并且不会因分割减损价值的，应当对实物予以分割；难以分割或者因分割会减损价值的，应当对折价或者拍卖、变卖取得的价款予以分割。"},{"i":101,"n":"第一百零一条","txt":"按份共有人可以转让其享有的共有的不动产或者动产份额。其他共有人在同等条件下享有优先购买的权利。"},{"i":102,"n":"第一百零二条","txt":"因共有的不动产或者动产产生的债权债务，在对外关系上，共有人享有连带债权、承担连带债务，但法律另有规定或者第三人知道共有人不具有连带债权债务关系的除外；在共有人内部关系上，除共有人另有约定外，按份共有人按照份额享有债权、承担债务，共同共有人共同享有债权、承担债务。偿还债务超过自己应当承担份额的按份共有人，有权向其他共有人追偿。"},{"i":103,"n":"第一百零三条","txt":"共有人对共有的不动产或者动产没有约定为按份共有或者共同共有，或者约定不明确的，除共有人具有家庭关系等外，视为按份共有。"},{"i":104,"n":"第一百零四条","txt":"按份共有人对共有的不动产或者动产享有的份额，没有约定或者约定不明确的，按照出资额确定；不能确定出资额的，视为等额享有。"},{"i":105,"n":"第一百零五条","txt":"两个以上单位、个人共同享有用益物权、担保物权的，参照本章规定。"},{"i":106,"n":"第一百零六条","txt":"无处分权人将不动产或者动产转让给受让人的，所有权人有权追回；除法律另有规定外，符合下列情形的，受让人取得该不动产或者动产的所有权："},{"i":107,"n":"第一百零七条","txt":"所有权人或者其他权利人有权追回遗失物。该遗失物通过转让被他人占有的，权利人有权向无处分权人请求损害赔偿，或者自知道或者应当知道受让人之日起二年内向受让人请求返还原物，但受让人通过拍卖或者向具有经营资格的经营者购得该遗失物的，权利人请求返还原物时应当支付受让人所付的费用。权利人向受让人支付所付费用后，有权向无处分权人追偿。"},{"i":108,"n":"第一百零八条","txt":"善意受让人取得动产后，该动产上的原有权利消灭，但善意受让人在受让时知道或者应当知道该权利的除外。"},{"i":109,"n":"第一百零九条","txt":"拾得遗失物，应当返还权利人。拾得人应当及时通知权利人领取，或者送交公安等有关部门。"},{"i":110,"n":"第一百一十条","txt":"有关部门收到遗失物，知道权利人的，应当及时通知其领取；不知道的，应当及时发布招领公告。"},{"i":111,"n":"第一百一十一条","txt":"拾得人在遗失物送交有关部门前，有关部门在遗失物被领取前，应当妥善保管遗失物。因故意或者重大过失致使遗失物毁损、灭失的，应当承担民事责任。"},{"i":112,"n":"第一百一十二条","txt":"权利人领取遗失物时，应当向拾得人或者有关部门支付保管遗失物等支出的必要费用。"},{"i":113,"n":"第一百一十三条","txt":"遗失物自发布招领公告之日起六个月内无人认领的，归国家所有。"},{"i":114,"n":"第一百一十四条","txt":"拾得漂流物、发现埋藏物或者隐藏物的，参照拾得遗失物的有关规定。文物保护法等法律另有规定的，依照其规定。"},{"i":115,"n":"第一百一十五条","txt":"主物转让的，从物随主物转让，但当事人另有约定的除外。"},{"i":116,"n":"第一百一十六条","txt":"天然孳息，由所有权人取得；既有所有权人又有用益物权人的，由用益物权人取得。当事人另有约定的，按照约定。"},{"i":117,"n":"第一百一十七条","txt":"用益物权人对他人所有的不动产或者动产，依法享有占有、使用和收益的权利。"},{"i":118,"n":"第一百一十八条","txt":"国家所有或者国家所有由集体使用以及法律规定属于集体所有的自然资源，单位、个人依法可以占有、使用和收益。"},{"i":119,"n":"第一百一十九条","txt":"国家实行自然资源有偿使用制度，但法律另有规定的除外。"},{"i":120,"n":"第一百二十条","txt":"用益物权人行使权利，应当遵守法律有关保护和合理开发利用资源的规定。所有权人不得干涉用益物权人行使权利。"},{"i":121,"n":"第一百二十一条","txt":"因不动产或者动产被征收、征用致使用益物权消灭或者影响用益物权行使的，用益物权人有权依照本法第四十二条、第四十四条的规定获得相应补偿。"},{"i":122,"n":"第一百二十二条","txt":"依法取得的海域使用权受法律保护。"},{"i":123,"n":"第一百二十三条","txt":"依法取得的探矿权、采矿权、取水权和使用水域、滩涂从事养殖、捕捞的权利受法律保护。"},{"i":124,"n":"第一百二十四条","txt":"农村集体经济组织实行家庭承包经营为基础、统分结合的双层经营体制。"},{"i":125,"n":"第一百二十五条","txt":"土地承包经营权人依法对其承包经营的耕地、林地、草地等享有占有、使用和收益的权利，有权从事种植业、林业、畜牧业等农业生产。"},{"i":126,"n":"第一百二十六条","txt":"耕地的承包期为三十年。草地的承包期为三十年至五十年。林地的承包期为三十年至七十年；特殊林木的林地承包期，经国务院林业行政主管部门批准可以延长。"},{"i":127,"n":"第一百二十七条","txt":"土地承包经营权自土地承包经营权合同生效时设立。"},{"i":128,"n":"第一百二十八条","txt":"土地承包经营权人依照农村土地承包法的规定，有权将土地承包经营权采取转包、互换、转让等方式流转。流转的期限不得超过承包期的剩余期限。未经依法批准，不得将承包地用于非农建设。"},{"i":129,"n":"第一百二十九条","txt":"土地承包经营权人将土地承包经营权互换、转让，当事人要求登记的，应当向县级以上地方人民政府申请土地承包经营权变更登记；未经登记，不得对抗善意第三人。"},{"i":130,"n":"第一百三十条","txt":"承包期内发包人不得调整承包地。"},{"i":131,"n":"第一百三十一条","txt":"承包期内发包人不得收回承包地。农村土地承包法等法律另有规定的，依照其规定。"},{"i":132,"n":"第一百三十二条","txt":"承包地被征收的，土地承包经营权人有权依照本法第四十二条第二款的规定获得相应补偿。"},{"i":133,"n":"第一百三十三条","txt":"通过招标、拍卖、公开协商等方式承包荒地等农村土地，依照农村土地承包法等法律和国务院的有关规定，其土地承包经营权可以转让、入股、抵押或者以其他方式流转。"},{"i":134,"n":"第一百三十四条","txt":"国家所有的农用地实行承包经营的，参照本法的有关规定。"},{"i":135,"n":"第一百三十五条","txt":"建设用地使用权人依法对国家所有的土地享有占有、使用和收益的权利，有权利用该土地建造建筑物、构筑物及其附属设施。"},{"i":136,"n":"第一百三十六条","txt":"建设用地使用权可以在土地的地表、地上或者地下分别设立。新设立的建设用地使用权，不得损害已设立的用益物权。"},{"i":137,"n":"第一百三十七条","txt":"设立建设用地使用权，可以采取出让或者划拨等方式。"},{"i":138,"n":"第一百三十八条","txt":"采取招标、拍卖、协议等出让方式设立建设用地使用权的，当事人应当采取书面形式订立建设用地使用权出让合同。"},{"i":139,"n":"第一百三十九条","txt":"设立建设用地使用权的，应当向登记机构申请建设用地使用权登记。建设用地使用权自登记时设立。登记机构应当向建设用地使用权人发放建设用地使用权证书。"},{"i":140,"n":"第一百四十条","txt":"建设用地使用权人应当合理利用土地，不得改变土地用途；需要改变土地用途的，应当依法经有关行政主管部门批准。"},{"i":141,"n":"第一百四十一条","txt":"建设用地使用权人应当依照法律规定以及合同约定支付出让金等费用。"},{"i":142,"n":"第一百四十二条","txt":"建设用地使用权人建造的建筑物、构筑物及其附属设施的所有权属于建设用地使用权人，但有相反证据证明的除外。"},{"i":143,"n":"第一百四十三条","txt":"建设用地使用权人有权将建设用地使用权转让、互换、出资、赠与或者抵押，但法律另有规定的除外。"},{"i":144,"n":"第一百四十四条","txt":"建设用地使用权转让、互换、出资、赠与或者抵押的，当事人应当采取书面形式订立相应的合同。使用期限由当事人约定，但不得超过建设用地使用权的剩余期限。"},{"i":145,"n":"第一百四十五条","txt":"建设用地使用权转让、互换、出资或者赠与的，应当向登记机构申请变更登记。"},{"i":146,"n":"第一百四十六条","txt":"建设用地使用权转让、互换、出资或者赠与的，附着于该土地上的建筑物、构筑物及其附属设施一并处分。"},{"i":147,"n":"第一百四十七条","txt":"建筑物、构筑物及其附属设施转让、互换、出资或者赠与的，该建筑物、构筑物及其附属设施占用范围内的建设用地使用权一并处分。"},{"i":148,"n":"第一百四十八条","txt":"建设用地使用权期间届满前，因公共利益需要提前收回该土地的，应当依照本法第四十二条的规定对该土地上的房屋及其他不动产给予补偿，并退还相应的出让金。"},{"i":149,"n":"第一百四十九条","txt":"住宅建设用地使用权期间届满的，自动续期。"},{"i":150,"n":"第一百五十条","txt":"建设用地使用权消灭的，出让人应当及时办理注销登记。登记机构应当收回建设用地使用权证书。"},{"i":151,"n":"第一百五十一条","txt":"集体所有的土地作为建设用地的，应当依照土地管理法等法律规定办理。"},{"i":152,"n":"第一百五十二条","txt":"宅基地使用权人依法对集体所有的土地享有占有和使用的权利，有权依法利用该土地建造住宅及其附属设施。"},{"i":153,"n":"第一百五十三条","txt":"宅基地使用权的取得、行使和转让，适用土地管理法等法律和国家有关规定。"},{"i":154,"n":"第一百五十四条","txt":"宅基地因自然灾害等原因灭失的，宅基地使用权消灭。对失去宅基地的村民，应当重新分配宅基地。"},{"i":155,"n":"第一百五十五条","txt":"已经登记的宅基地使用权转让或者消灭的，应当及时办理变更登记或者注销登记。"},{"i":156,"n":"第一百五十六条","txt":"地役权人有权按照合同约定，利用他人的不动产，以提高自己的不动产的效益。"},{"i":157,"n":"第一百五十七条","txt":"设立地役权，当事人应当采取书面形式订立地役权合同。"},{"i":158,"n":"第一百五十八条","txt":"地役权自地役权合同生效时设立。当事人要求登记的，可以向登记机构申请地役权登记；未经登记，不得对抗善意第三人。"},{"i":159,"n":"第一百五十九条","txt":"供役地权利人应当按照合同约定，允许地役权人利用其土地，不得妨害地役权人行使权利。"},{"i":160,"n":"第一百六十条","txt":"地役权人应当按照合同约定的利用目的和方法利用供役地，尽量减少对供役地权利人物权的限制。"},{"i":161,"n":"第一百六十一条","txt":"地役权的期限由当事人约定，但不得超过土地承包经营权、建设用地使用权等用益物权的剩余期限。"},{"i":162,"n":"第一百六十二条","txt":"土地所有权人享有地役权或者负担地役权的，设立土地承包经营权、宅基地使用权时，该土地承包经营权人、宅基地使用权人继续享有或者负担已设立的地役权。"},{"i":163,"n":"第一百六十三条","txt":"土地上已设立土地承包经营权、建设用地使用权、宅基地使用权等权利的，未经用益物权人同意，土地所有权人不得设立地役权。"},{"i":164,"n":"第一百六十四条","txt":"地役权不得单独转让。土地承包经营权、建设用地使用权等转让的，地役权一并转让，但合同另有约定的除外。"},{"i":165,"n":"第一百六十五条","txt":"地役权不得单独抵押。土地承包经营权、建设用地使用权等抵押的，在实现抵押权时，地役权一并转让。"},{"i":166,"n":"第一百六十六条","txt":"需役地以及需役地上的土地承包经营权、建设用地使用权部分转让时，转让部分涉及地役权的，受让人同时享有地役权。"},{"i":167,"n":"第一百六十七条","txt":"供役地以及供役地上的土地承包经营权、建设用地使用权部分转让时，转让部分涉及地役权的，地役权对受让人具有约束力。"},{"i":168,"n":"第一百六十八条","txt":"地役权人有下列情形之一的，供役地权利人有权解除地役权合同，地役权消灭："},{"i":169,"n":"第一百六十九条","txt":"已经登记的地役权变更、转让或者消灭的，应当及时办理变更登记或者注销登记。"},{"i":170,"n":"第一百七十条","txt":"担保物权人在债务人不履行到期债务或者发生当事人约定的实现担保物权的情形，依法享有就担保财产优先受偿的权利，但法律另有规定的除外。"},{"i":171,"n":"第一百七十一条","txt":"债权人在借贷、买卖等民事活动中，为保障实现其债权，需要担保的，可以依照本法和其他法律的规定设立担保物权。"},{"i":172,"n":"第一百七十二条","txt":"设立担保物权，应当依照本法和其他法律的规定订立担保合同。担保合同是主债权债务合同的从合同。主债权债务合同无效，担保合同无效，但法律另有规定的除外。"},{"i":173,"n":"第一百七十三条","txt":"担保物权的担保范围包括主债权及其利息、违约金、损害赔偿金、保管担保财产和实现担保物权的费用。当事人另有约定的，按照约定。"},{"i":174,"n":"第一百七十四条","txt":"担保期间，担保财产毁损、灭失或者被征收等，担保物权人可以就获得的保险金、赔偿金或者补偿金等优先受偿。被担保债权的履行期未届满的，也可以提存该保险金、赔偿金或者补偿金等。"},{"i":175,"n":"第一百七十五条","txt":"第三人提供担保，未经其书面同意，债权人允许债务人转移全部或者部分债务的，担保人不再承担相应的担保责任。"},{"i":176,"n":"第一百七十六条","txt":"被担保的债权既有物的担保又有人的担保的，债务人不履行到期债务或者发生当事人约定的实现担保物权的情形，债权人应当按照约定实现债权；没有约定或者约定不明确，债务人自己提供物的担保的，债权人应当先就该物的担保实现债权；第三人提供物的担保的，债权人可以就物的担保实现债权，也可以要求保证人承担保证责任。提供担保的第三人承担担保责任后，有权向债务人追偿。"},{"i":177,"n":"第一百七十七条","txt":"有下列情形之一的，担保物权消灭："},{"i":178,"n":"第一百七十八条","txt":"担保法与本法的规定不一致的，适用本法。"},{"i":179,"n":"第一百七十九条","txt":"为担保债务的履行，债务人或者第三人不转移财产的占有，将该财产抵押给债权人的，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，债权人有权就该财产优先受偿。"},{"i":180,"n":"第一百八十条","txt":"债务人或者第三人有权处分的下列财产可以抵押："},{"i":181,"n":"第一百八十一条","txt":"经当事人书面协议，企业、个体工商户、农业生产经营者可以将现有的以及将有的生产设备、原材料、半成品、产品抵押，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，债权人有权就实现抵押权时的动产优先受偿。"},{"i":182,"n":"第一百八十二条","txt":"以建筑物抵押的，该建筑物占用范围内的建设用地使用权一并抵押。以建设用地使用权抵押的，该土地上的建筑物一并抵押。"},{"i":183,"n":"第一百八十三条","txt":"乡镇、村企业的建设用地使用权不得单独抵押。以乡镇、村企业的厂房等建筑物抵押的，其占用范围内的建设用地使用权一并抵押。"},{"i":184,"n":"第一百八十四条","txt":"下列财产不得抵押："},{"i":185,"n":"第一百八十五条","txt":"设立抵押权，当事人应当采取书面形式订立抵押合同。"},{"i":186,"n":"第一百八十六条","txt":"抵押权人在债务履行期届满前，不得与抵押人约定债务人不履行到期债务时抵押财产归债权人所有。"},{"i":187,"n":"第一百八十七条","txt":"以本法第一百八十条第一款第一项至第三项规定的财产或者第五项规定的正在建造的建筑物抵押的，应当办理抵押登记。抵押权自登记时设立。"},{"i":188,"n":"第一百八十八条","txt":"以本法第一百八十条第一款第四项、第六项规定的财产或者第五项规定的正在建造的船舶、航空器抵押的，抵押权自抵押合同生效时设立；未经登记，不得对抗善意第三人。"},{"i":189,"n":"第一百八十九条","txt":"企业、个体工商户、农业生产经营者以本法第一百八十一条规定的动产抵押的，应当向抵押人住所地的工商行政管理部门办理登记。抵押权自抵押合同生效时设立；未经登记，不得对抗善意第三人。"},{"i":190,"n":"第一百九十条","txt":"订立抵押合同前抵押财产已出租的，原租赁关系不受该抵押权的影响。抵押权设立后抵押财产出租的，该租赁关系不得对抗已登记的抵押权。"},{"i":191,"n":"第一百九十一条","txt":"抵押期间，抵押人经抵押权人同意转让抵押财产的，应当将转让所得的价款向抵押权人提前清偿债务或者提存。转让的价款超过债权数额的部分归抵押人所有，不足部分由债务人清偿。"},{"i":192,"n":"第一百九十二条","txt":"抵押权不得与债权分离而单独转让或者作为其他债权的担保。债权转让的，担保该债权的抵押权一并转让，但法律另有规定或者当事人另有约定的除外。"},{"i":193,"n":"第一百九十三条","txt":"抵押人的行为足以使抵押财产价值减少的，抵押权人有权要求抵押人停止其行为。抵押财产价值减少的，抵押权人有权要求恢复抵押财产的价值，或者提供与减少的价值相应的担保。抵押人不恢复抵押财产的价值也不提供担保的，抵押权人有权要求债务人提前清偿债务。"},{"i":194,"n":"第一百九十四条","txt":"抵押权人可以放弃抵押权或者抵押权的顺位。抵押权人与抵押人可以协议变更抵押权顺位以及被担保的债权数额等内容，但抵押权的变更，未经其他抵押权人书面同意，不得对其他抵押权人产生不利影响。"},{"i":195,"n":"第一百九十五条","txt":"债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，抵押权人可以与抵押人协议以抵押财产折价或者以拍卖、变卖该抵押财产所得的价款优先受偿。协议损害其他债权人利益的，其他债权人可以在知道或者应当知道撤销事由之日起一年内请求人民法院撤销该协议。"},{"i":196,"n":"第一百九十六条","txt":"依照本法第一百八十一条规定设定抵押的，抵押财产自下列情形之一发生时确定："},{"i":197,"n":"第一百九十七条","txt":"债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，致使抵押财产被人民法院依法扣押的，自扣押之日起抵押权人有权收取该抵押财产的天然孳息或者法定孳息，但抵押权人未通知应当清偿法定孳息的义务人的除外。"},{"i":198,"n":"第一百九十八条","txt":"抵押财产折价或者拍卖、变卖后，其价款超过债权数额的部分归抵押人所有，不足部分由债务人清偿。"},{"i":199,"n":"第一百九十九条","txt":"同一财产向两个以上债权人抵押的，拍卖、变卖抵押财产所得的价款依照下列规定清偿："},{"i":200,"n":"第二百条","txt":"建设用地使用权抵押后，该土地上新增的建筑物不属于抵押财产。该建设用地使用权实现抵押权时，应当将该土地上新增的建筑物与建设用地使用权一并处分，但新增建筑物所得的价款，抵押权人无权优先受偿。"},{"i":201,"n":"第二百零一条","txt":"依照本法第一百八十条第一款第三项规定的土地承包经营权抵押的，或者依照本法第一百八十三条规定以乡镇、村企业的厂房等建筑物占用范围内的建设用地使用权一并抵押的，实现抵押权后，未经法定程序，不得改变土地所有权的性质和土地用途。"},{"i":202,"n":"第二百零二条","txt":"抵押权人应当在主债权诉讼时效期间行使抵押权；未行使的，人民法院不予保护。"},{"i":203,"n":"第二百零三条","txt":"为担保债务的履行，债务人或者第三人对一定期间内将要连续发生的债权提供担保财产的，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，抵押权人有权在最高债权额限度内就该担保财产优先受偿。"},{"i":204,"n":"第二百零四条","txt":"最高额抵押担保的债权确定前，部分债权转让的，最高额抵押权不得转让，但当事人另有约定的除外。"},{"i":205,"n":"第二百零五条","txt":"最高额抵押担保的债权确定前，抵押权人与抵押人可以通过协议变更债权确定的期间、债权范围以及最高债权额，但变更的内容不得对其他抵押权人产生不利影响。"},{"i":206,"n":"第二百零六条","txt":"有下列情形之一的，抵押权人的债权确定："},{"i":207,"n":"第二百零七条","txt":"最高额抵押权除适用本节规定外，适用本章第一节一般抵押权的规定。"},{"i":208,"n":"第二百零八条","txt":"为担保债务的履行，债务人或者第三人将其动产出质给债权人占有的，债务人不履行到期债务或者发生当事人约定的实现质权的情形，债权人有权就该动产优先受偿。"},{"i":209,"n":"第二百零九条","txt":"法律、行政法规禁止转让的动产不得出质。"},{"i":210,"n":"第二百一十条","txt":"设立质权，当事人应当采取书面形式订立质权合同。"},{"i":211,"n":"第二百一十一条","txt":"质权人在债务履行期届满前，不得与出质人约定债务人不履行到期债务时质押财产归债权人所有。"},{"i":212,"n":"第二百一十二条","txt":"质权自出质人交付质押财产时设立。"},{"i":213,"n":"第二百一十三条","txt":"质权人有权收取质押财产的孳息，但合同另有约定的除外。"},{"i":214,"n":"第二百一十四条","txt":"质权人在质权存续期间，未经出质人同意，擅自使用、处分质押财产，给出质人造成损害的，应当承担赔偿责任。"},{"i":215,"n":"第二百一十五条","txt":"质权人负有妥善保管质押财产的义务；因保管不善致使质押财产毁损、灭失的，应当承担赔偿责任。"},{"i":216,"n":"第二百一十六条","txt":"因不能归责于质权人的事由可能使质押财产毁损或者价值明显减少，足以危害质权人权利的，质权人有权要求出质人提供相应的担保；出质人不提供的，质权人可以拍卖、变卖质押财产，并与出质人通过协议将拍卖、变卖所得的价款提前清偿债务或者提存。"},{"i":217,"n":"第二百一十七条","txt":"质权人在质权存续期间，未经出质人同意转质，造成质押财产毁损、灭失的，应当向出质人承担赔偿责任。"},{"i":218,"n":"第二百一十八条","txt":"质权人可以放弃质权。债务人以自己的财产出质，质权人放弃该质权的，其他担保人在质权人丧失优先受偿权益的范围内免除担保责任，但其他担保人承诺仍然提供担保的除外。"},{"i":219,"n":"第二百一十九条","txt":"债务人履行债务或者出质人提前清偿所担保的债权的，质权人应当返还质押财产。"},{"i":220,"n":"第二百二十条","txt":"出质人可以请求质权人在债务履行期届满后及时行使质权；质权人不行使的，出质人可以请求人民法院拍卖、变卖质押财产。"},{"i":221,"n":"第二百二十一条","txt":"质押财产折价或者拍卖、变卖后，其价款超过债权数额的部分归出质人所有，不足部分由债务人清偿。"},{"i":222,"n":"第二百二十二条","txt":"出质人与质权人可以协议设立最高额质权。"},{"i":223,"n":"第二百二十三条","txt":"债务人或者第三人有权处分的下列权利可以出质："},{"i":224,"n":"第二百二十四条","txt":"以汇票、支票、本票、债券、存款单、仓单、提单出质的，当事人应当订立书面合同。质权自权利凭证交付质权人时设立；没有权利凭证的，质权自有关部门办理出质登记时设立。"},{"i":225,"n":"第二百二十五条","txt":"汇票、支票、本票、债券、存款单、仓单、提单的兑现日期或者提货日期先于主债权到期的，质权人可以兑现或者提货，并与出质人协议将兑现的价款或者提取的货物提前清偿债务或者提存。"},{"i":226,"n":"第二百二十六条","txt":"以基金份额、股权出质的，当事人应当订立书面合同。以基金份额、证券登记结算机构登记的股权出质的，质权自证券登记结算机构办理出质登记时设立；以其他股权出质的，质权自工商行政管理部门办理出质登记时设立。"},{"i":227,"n":"第二百二十七条","txt":"以注册商标专用权、专利权、著作权等知识产权中的财产权出质的，当事人应当订立书面合同。质权自有关主管部门办理出质登记时设立。"},{"i":228,"n":"第二百二十八条","txt":"以应收账款出质的，当事人应当订立书面合同。质权自信贷征信机构办理出质登记时设立。"},{"i":229,"n":"第二百二十九条","txt":"权利质权除适用本节规定外，适用本章第一节动产质权的规定。"},{"i":230,"n":"第二百三十条","txt":"债务人不履行到期债务，债权人可以留置已经合法占有的债务人的动产，并有权就该动产优先受偿。"},{"i":231,"n":"第二百三十一条","txt":"债权人留置的动产，应当与债权属于同一法律关系，但企业之间留置的除外。"},{"i":232,"n":"第二百三十二条","txt":"法律规定或者当事人约定不得留置的动产，不得留置。"},{"i":233,"n":"第二百三十三条","txt":"留置财产为可分物的，留置财产的价值应当相当于债务的金额。"},{"i":234,"n":"第二百三十四条","txt":"留置权人负有妥善保管留置财产的义务；因保管不善致使留置财产毁损、灭失的，应当承担赔偿责任。"},{"i":235,"n":"第二百三十五条","txt":"留置权人有权收取留置财产的孳息。"},{"i":236,"n":"第二百三十六条","txt":"留置权人与债务人应当约定留置财产后的债务履行期间；没有约定或者约定不明确的，留置权人应当给债务人两个月以上履行债务的期间，但鲜活易腐等不易保管的动产除外。债务人逾期未履行的，留置权人可以与债务人协议以留置财产折价，也可以就拍卖、变卖留置财产所得的价款优先受偿。"},{"i":237,"n":"第二百三十七条","txt":"债务人可以请求留置权人在债务履行期届满后行使留置权；留置权人不行使的，债务人可以请求人民法院拍卖、变卖留置财产。"},{"i":238,"n":"第二百三十八条","txt":"留置财产折价或者拍卖、变卖后，其价款超过债权数额的部分归债务人所有，不足部分由债务人清偿。"},{"i":239,"n":"第二百三十九条","txt":"同一动产上已设立抵押权或者质权，该动产又被留置的，留置权人优先受偿。"},{"i":240,"n":"第二百四十条","txt":"留置权人对留置财产丧失占有或者留置权人接受债务人另行提供担保的，留置权消灭。"},{"i":241,"n":"第二百四十一条","txt":"基于合同关系等产生的占有，有关不动产或者动产的使用、收益、违约责任等，按照合同约定；合同没有约定或者约定不明确的，依照有关法律规定。"},{"i":242,"n":"第二百四十二条","txt":"占有人因使用占有的不动产或者动产，致使该不动产或者动产受到损害的，恶意占有人应当承担赔偿责任。"},{"i":243,"n":"第二百四十三条","txt":"不动产或者动产被占有人占有的，权利人可以请求返还原物及其孳息，但应当支付善意占有人因维护该不动产或者动产支出的必要费用。"},{"i":244,"n":"第二百四十四条","txt":"占有的不动产或者动产毁损、灭失，该不动产或者动产的权利人请求赔偿的，占有人应当将因毁损、灭失取得的保险金、赔偿金或者补偿金等返还给权利人；权利人的损害未得到足够弥补的，恶意占有人还应当赔偿损失。"},{"i":245,"n":"第二百四十五条","txt":"占有的不动产或者动产被侵占的，占有人有权请求返还原物；对妨害占有的行为，占有人有权请求排除妨害或者消除危险；因侵占或者妨害造成损害的，占有人有权请求损害赔偿。"},{"i":246,"n":"第二百四十六条","txt":"法律、行政法规对不动产统一登记的范围、登记机构和登记办法作出规定前，地方性法规可以依照本法有关规定作出规定。"},{"i":247,"n":"第二百四十七条","txt":"本法自2007年10月1日起施行。"}],"xiangzhenqiyefa":[{"i":1,"n":"第一条","txt":"为了扶持和引导乡镇企业持续健康发展，保护乡镇企业的合法权益，规范乡镇企业的行为，繁荣农村经济，促进社会主义现代化建设，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称乡镇企业，是指农村集体经济组织或者农民投资为主，在乡镇（包括所辖村）举办的承担支援农业义务的各类企业。"},{"i":3,"n":"第三条","txt":"乡镇企业是农村经济的重要支柱和国民经济的重要组成部分。"},{"i":4,"n":"第四条","txt":"发展乡镇企业，坚持以农村集体经济为主导，多种经济成分共同发展的原则。"},{"i":5,"n":"第五条","txt":"国家对乡镇企业积极扶持、合理规划、分类指导、依法管理。"},{"i":6,"n":"第六条","txt":"国家鼓励和重点扶持经济欠发达地区、少数民族地区发展乡镇企业，鼓励经济发达地区的乡镇企业或者其他经济组织采取多种形式支持经济欠发达地区和少数民族地区举办乡镇企业。"},{"i":7,"n":"第七条","txt":"国务院乡镇企业行政管理部门和有关部门按照各自的职责对全国的乡镇企业进行规划、协调、监督、服务；县级以上地方各级人民政府乡镇企业行政管理部门和有关部门按照各自的职责对本行政区域内的乡镇企业进行规划、协调、监督、服务。"},{"i":8,"n":"第八条","txt":"经依法登记设立的乡镇企业，应当向当地乡镇企业行政管理部门办理登记备案手续。"},{"i":9,"n":"第九条","txt":"乡镇企业在城市设立的分支机构，或者农村集体经济组织在城市开办的并承担支援农业义务的企业，按照乡镇企业对待。"},{"i":10,"n":"第十条","txt":"农村集体经济组织投资设立的乡镇企业，其企业财产权属于设立该企业的全体农民集体所有。"},{"i":11,"n":"第十一条","txt":"乡镇企业依法实行独立核算，自主经营，自负盈亏。"},{"i":12,"n":"第十二条","txt":"国家保护乡镇企业的合法权益；乡镇企业的合法财产不受侵犯。"},{"i":13,"n":"第十三条","txt":"乡镇企业按照法律、行政法规规定的企业形式设立，投资者依照有关法律、行政法规决定企业的重大事项，建立经营管理制度，依法享有权利和承担义务。"},{"i":14,"n":"第十四条","txt":"乡镇企业依法实行民主管理，投资者在确定企业经营管理制度和企业负责人，作出重大经营决策和决定职工工资、生活福利、劳动保护、劳动安全等重大问题时，应当听取本企业工会或者职工的意见，实施情况要定期向职工公布，接受职工监督。"},{"i":15,"n":"第十五条","txt":"国家鼓励有条件的地区建立、健全乡镇企业职工社会保险制度。"},{"i":16,"n":"第十六条","txt":"乡镇企业停业、终止，已经建立社会保险制度的，按照有关规定安排职工；依法订立劳动合同的，按照合同的约定办理。原属于农村集体经济组织的职工有权返回农村集体经济组织从事生产，或者由职工自谋职业。"},{"i":17,"n":"第十七条","txt":"乡镇企业从税后利润中提取一定比例的资金用于支援农业和农村社会性支出，其比例和管理使用办法由省、自治区、直辖市人民政府规定。"},{"i":18,"n":"第十八条","txt":"国家根据乡镇企业发展的情况，在一定时期内对乡镇企业减征一定比例的税收。减征税收的税种、期限和比例由国务院规定。"},{"i":19,"n":"第十九条","txt":"国家对符合下列条件之一的中小型乡镇企业，根据不同情况实行一定期限的税收优惠："},{"i":20,"n":"第二十条","txt":"国家运用信贷手段，鼓励和扶持乡镇企业发展。对于符合前条规定条件之一并且符合贷款条件的乡镇企业，国家有关金融机构可以给予优先贷款，对其中生产资金困难且有发展前途的可以给予优惠贷款。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府依照国家有关规定，可以设立乡镇企业发展基金。基金由下列资金组成："},{"i":22,"n":"第二十二条","txt":"乡镇企业发展基金专门用于扶持乡镇企业发展，其使用范围如下："},{"i":23,"n":"第二十三条","txt":"国家积极培养乡镇企业人才，鼓励科技人员、经营管理人员及大中专毕业生到乡镇企业工作，通过多种方式为乡镇企业服务。"},{"i":24,"n":"第二十四条","txt":"国家采取优惠措施，鼓励乡镇企业同科研机构、高等院校、国有企业及其他企业、组织之间开展各种形式的经济技术合作。"},{"i":25,"n":"第二十五条","txt":"国家鼓励乡镇企业开展对外经济技术合作与交流，建设出口商品生产基地，增加出口创汇。"},{"i":26,"n":"第二十六条","txt":"地方各级人民政府按照统一规划、合理布局的原则，将发展乡镇企业同小城镇建设相结合，引导和促进乡镇企业适当集中发展，逐步加强基础设施和服务设施建设，以加快小城镇建设。"},{"i":27,"n":"第二十七条","txt":"乡镇企业应当按照市场需要和国家产业政策，合理调整产业结构和产品结构，加强技术改造，不断采用先进的技术、生产工艺和设备，提高企业经营管理水平。"},{"i":28,"n":"第二十八条","txt":"举办乡镇企业，其建设用地应当符合土地利用总体规划，严格控制、合理利用和节约使用土地，凡有荒地、劣地可以利用的，不得占用耕地、好地。"},{"i":29,"n":"第二十九条","txt":"乡镇企业应当依法合理开发和使用自然资源。"},{"i":30,"n":"第三十条","txt":"乡镇企业应当按照国家有关规定，建立财务会计制度，加强财务管理，依法设置会计帐册，如实记录财务活动。"},{"i":31,"n":"第三十一条","txt":"乡镇企业必须按照国家统计制度，如实报送统计资料。对于违反国家规定制发的统计调查报表，乡镇企业有权拒绝填报。"},{"i":32,"n":"第三十二条","txt":"乡镇企业应当依法办理税务登记，按期进行纳税申报，足额缴纳税款。"},{"i":33,"n":"第三十三条","txt":"乡镇企业应当加强产品质量管理，努力提高产品质量；生产和销售的产品必须符合保障人体健康，人身、财产安全的国家标准和行业标准；不得生产、销售失效、变质产品和国家明令淘汰的产品；不得在产品中掺杂、掺假，以假充真，以次充好。"},{"i":34,"n":"第三十四条","txt":"乡镇企业应当依法使用商标，重视企业信誉；按照国家规定，制作所生产经营的商品标识，不得伪造产品的产地或者伪造、冒用他人厂名、厂址和认证标志、名优标志。"},{"i":35,"n":"第三十五条","txt":"乡镇企业必须遵守有关环境保护的法律、法规，按照国家产业政策，在当地人民政府的统一指导下，采取措施，积极发展无污染、少污染和低资源消耗的企业，切实防治环境污染和生态破坏，保护和改善环境。"},{"i":36,"n":"第三十六条","txt":"乡镇企业建设对环境有影响的项目，必须严格执行环境影响评价制度。"},{"i":37,"n":"第三十七条","txt":"乡镇企业必须遵守有关劳动保护、劳动安全的法律、法规，认真贯彻执行安全第一、预防为主的方针，采取有效的劳动卫生技术措施和管理措施，防止生产伤亡事故和职业病的发生；对危害职工安全的事故隐患，应当限期解决或者停产整顿。严禁管理者违章指挥，强令职工冒险作业。发生生产伤亡事故，应当采取积极抢救措施，依法妥善处理，并向有关部门报告。"},{"i":38,"n":"第三十八条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府乡镇企业行政管理部门责令改正："},{"i":39,"n":"第三十九条","txt":"乡镇企业有权向审计、监察、财政、物价和乡镇企业行政管理部门控告、检举向企业非法收费、摊派或者罚款的单位和个人。有关部门和上级机关应当责令责任人停止其行为，并限期归还有关财物。对直接责任人员，有关部门可以根据情节轻重，给予相应的处罚。"},{"i":40,"n":"第四十条","txt":"乡镇企业违反国家产品质量、环境保护、土地管理、自然资源开发、劳动安全、税收及其他有关法律、法规的，除依照有关法律、法规处理外，在其改正之前，应当根据情节轻重停止其享受本法规定的部分或者全部优惠。"},{"i":41,"n":"第四十一条","txt":"乡镇企业违反本法规定，不承担支援农业义务的，由乡镇企业行政管理部门责令改正，在其改正之前，可以停止其享受本法规定的部分或者全部优惠。"},{"i":42,"n":"第四十二条","txt":"对依照本法第三十八条至第四十一条规定所作处罚、处理决定不服的，当事人可以依法申请行政复议、提起诉讼。"},{"i":43,"n":"第四十三条","txt":"本法自1997年1月1日起施行。"}],"xueweitiaoli":[{"i":1,"n":"第一条","txt":"为了促进我国科学专门人才的成长，促进各门学科学术水平的提高和教育、科学事业的发展，以适应社会主义现代化建设的需要，特制定本条例。"},{"i":2,"n":"第二条","txt":"凡是拥护中国共产党的领导、拥护社会主义制度，具有一定学术水平的公民，都可以按照本条例的规定申请相应的学位。"},{"i":3,"n":"第三条","txt":"学位分学士、硕士、博士三级。"},{"i":4,"n":"第四条","txt":"高等学校本科毕业生，成绩优良，达到下述学术水平者，授予学士学位："},{"i":5,"n":"第五条","txt":"高等学校和科学研究机构的研究生，或具有研究生毕业同等学力的人员，通过硕士学位的课程考试和论文答辩，成绩合格，达到下述学术水平者，授予硕士学位："},{"i":6,"n":"第六条","txt":"高等学校和科学研究机构的研究生，或具有研究生毕业同等学力的人员，通过博士学位的课程考试和论文答辩，成绩合格，达到下述学术水平者，授予博士学位："},{"i":7,"n":"第七条","txt":"国务院设立学位委员会，负责领导全国学位授予工作。学位委员会设主任委员一人，副主任委员和委员若干人。主任委员、副主任委员和委员由国务院任免。"},{"i":8,"n":"第八条","txt":"学士学位，由国务院授权的高等学校授予；硕士学位、博士学位，由国务院授权的高等学校和科学研究机构授予。"},{"i":9,"n":"第九条","txt":"学位授予单位，应当设立学位评定委员会，并组织有关学科的学位论文答辩委员会。"},{"i":10,"n":"第十条","txt":"学位论文答辩委员会负责审查硕士和博士学位论文、组织答辩，就是否授予硕士学位或博士学位作出决议。决议以不记名投票方式，经全体成员三分之二以上通过，报学位评定委员会。"},{"i":11,"n":"第十一条","txt":"学位授予单位，在学位评定委员会作出授予学位的决议后，发给学位获得者相应的学位证书。"},{"i":12,"n":"第十二条","txt":"非学位授予单位应届毕业的研究生，由原单位推荐，可以就近向学位授予单位申请学位。经学位授予单位审查同意，通过论文答辩，达到本条例规定的学术水平者，授予相应的学位。"},{"i":13,"n":"第十三条","txt":"对于在科学或专门技术上有重要的著作、发明、发现或发展者，经有关专家推荐，学位授予单位同意，可以免除考试，直接参加博士学位论文答辩。对于通过论文答辩者，授予博士学位。"},{"i":14,"n":"第十四条","txt":"对于国内外卓越的学者或著名的社会活动家，经学位授予单位提名，国务院学位委员会批准，可以授予名誉博士学位。"},{"i":15,"n":"第十五条","txt":"在我国学习的外国留学生和从事研究工作的外国学者，可以向学位授予单位申请学位。对于具有本条例规定的学术水平者，授予相应的学位。"},{"i":16,"n":"第十六条","txt":"非学位授予单位和学术团体对于授予学位的决议和决定持有不同意见时，可以向学位授予单位或国务院学位委员会提出异议。学位授予单位和国务院学位委员会应当对提出的异议进行研究和处理。"},{"i":17,"n":"第十七条","txt":"学位授予单位对于已经授予的学位，如发现有舞弊作伪等严重违反本条例规定的情况，经学位评定委员会复议，可以撤销。"},{"i":18,"n":"第十八条","txt":"国务院对于已经批准授予学位的单位，在确认其不能保证所授学位的学术水平时，可以停止或撤销其授予学位的资格。"},{"i":19,"n":"第十九条","txt":"本条例的实施办法，由国务院学位委员会制定，报国务院批准。"},{"i":20,"n":"第二十条","txt":"本条例自1981年1月1日起施行。"}],"yubeiyijunguanfa":[{"i":1,"n":"第一条","txt":"为了健全预备役军官制度，完善国家武装力量动员体制，加强国防后备力量建设，根据宪法和兵役法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称预备役军官是被确定为人民解放军预备役排级以上职务等级或者初级以上专业技术职务等级，被授予相应的预备役军官军衔，并经兵役机关登记的预备役人员。"},{"i":3,"n":"第三条","txt":"预备役军官是国防后备力量的重要组成部分，是战时补充现役军官的主要来源之一。"},{"i":4,"n":"第四条","txt":"预备役军官按照职务性质分为军事军官、政治军官、后勤军官、装备军官和专业技术军官。"},{"i":5,"n":"第五条","txt":"全国的预备役军官管理工作在国务院、中央军事委员会领导下，由人民解放军总政治部主管。"},{"i":6,"n":"第六条","txt":"国务院有关部门、地方各级人民政府应当根据职责分工，依照本法和有关法律、法规的规定，做好预备役军官的有关管理工作。"},{"i":7,"n":"第七条","txt":"人民解放军总政治部、军区政治部、省军区（卫戍区、警备区）政治部、军分区（警备区）政治部和县人民武装部会同有关政府部门，建立健全军地预备役军官工作联席会议制度，定期召开军队和地方有关部门、当地预备役部队和预编预备役军官的现役部队参加的联席会议，协调解决预备役军官工作中的有关问题。有特殊需要时，可以临时召集会议。"},{"i":8,"n":"第八条","txt":"预备役军官所在的工作单位，应当支持预备役军官参加军事训练、执行军事勤务和履行其他兵役义务，协助做好预备役军官管理工作。"},{"i":9,"n":"第九条","txt":"预备役军官应当遵守宪法和法律、法规以及军队的有关规章、制度，参加军事训练和军事勤务活动，接受政治教育，增强组织指挥能力和专业技能，随时准备应召服现役。"},{"i":10,"n":"第十条","txt":"对在履行兵役义务过程中做出突出贡献的预备役军官，应当依照中央军事委员会的有关规定给予嘉奖、记功或者授予荣誉称号。"},{"i":11,"n":"第十一条","txt":"预备役军官应当具备下列基本条件："},{"i":12,"n":"第十二条","txt":"预备役军官从下列人员中选拔："},{"i":13,"n":"第十三条","txt":"选拔预备役军官的计划，由中央军事委员会确定，人民解放军总政治部会同有关部门组织实施。"},{"i":14,"n":"第十四条","txt":"依照本法第十二条的规定，从退出现役的军官和文职干部中选拔的预备役军官，由部队团级以上单位政治机关提出转服军官预备役的意见，按照规定的权限批准后，到安置地的县人民武装部办理预备役军官登记。"},{"i":15,"n":"第十五条","txt":"预备役军事、政治、后勤、装备军官的职务等级设置为：正师职、副师职、正团职、副团职、正营职、副营职、正连职、副连职、排职。"},{"i":16,"n":"第十六条","txt":"对被确定服军官预备役的人员，应当确定职务等级。"},{"i":17,"n":"第十七条","txt":"在预备役部队和预编到现役部队任职的预备役军官，除依照本法第十六条的规定确定职务等级外，其职务依照下列规定的权限任免："},{"i":18,"n":"第十八条","txt":"对预备役军官应当进行考核。考核工作由预备役军官所在部队或者兵役机关会同地方有关部门，根据国家有关规定，按照职责分工，共同组织实施。考核结果作为任免预备役军官职务的主要依据。"},{"i":19,"n":"第十九条","txt":"预备役军官职务等级的确定和职务的任免，按照中央军事委员会规定的程序办理。"},{"i":20,"n":"第二十条","txt":"国家实行预备役军官军衔制度。"},{"i":21,"n":"第二十一条","txt":"预备役军官军衔设下列三等八级："},{"i":22,"n":"第二十二条","txt":"预备役军官军衔分为："},{"i":23,"n":"第二十三条","txt":"预备役军官实行职务等级编制军衔。"},{"i":24,"n":"第二十四条","txt":"预备役军官参加军事训练、执行军事勤务期间，军衔高的预备役军官为军衔低的预备役军官的上级；军衔高的预备役军官在职务上隶属于军衔低的预备役军官的，职务高的为上级。"},{"i":25,"n":"第二十五条","txt":"评定和授予预备役军官军衔，以预备役军官职务等级、工作（任职）年限、德才表现和工作实绩为依据。"},{"i":26,"n":"第二十六条","txt":"授予预备役军官军衔，依照下列规定的权限批准："},{"i":27,"n":"第二十七条","txt":"转服军官预备役的军官和文职干部，其预备役军官军衔，按照其原现役军官军衔等级或者文职干部级别确定。"},{"i":28,"n":"第二十八条","txt":"预备役军官军衔，依照下列规定晋级："},{"i":29,"n":"第二十九条","txt":"预备役军官军衔的晋级，按照下列规定的权限批准："},{"i":30,"n":"第三十条","txt":"预备役军官违反军纪的，按照中央军事委员会的有关规定，可以给予军衔降级处分。批准预备役军官军衔降级的权限，与批准授予该级预备役军官军衔的权限相同。"},{"i":31,"n":"第三十一条","txt":"对被取消预备役军官身份的人员，应当取消其预备役军官军衔。批准取消预备役军官军衔的权限，与批准授予该级预备役军官军衔的权限相同。"},{"i":32,"n":"第三十二条","txt":"预备役军官犯罪，被依法判处剥夺政治权利或者三年以上有期徒刑的，应当剥夺其预备役军官军衔。批准剥夺预备役军官军衔的权限，与批准授予该级预备役军官军衔的权限相同。"},{"i":33,"n":"第三十三条","txt":"预备役军官退出预备役后，其预备役军官军衔予以保留，在其军衔前冠以“退役”。"},{"i":34,"n":"第三十四条","txt":"预备役军官军衔的肩章、符号标志式样及佩带办法，由中央军事委员会颁布。"},{"i":35,"n":"第三十五条","txt":"预备役军官的登记，由县人民武装部办理。"},{"i":36,"n":"第三十六条","txt":"预备役军官因工作调动或者迁居需要变更预备役军官登记地的，应当办理转出手续，并自到达新的工作单位或者居住地之日起三十日内，到所在地的县人民武装部办理转入手续。"},{"i":37,"n":"第三十七条","txt":"预备役军官有下列情形之一的，应当由县人民武装部注销其预备役军官登记："},{"i":38,"n":"第三十八条","txt":"县人民武装部必须按照规定对在本行政区域内登记的预备役军官，每年进行一次核对，并逐级统计上报。"},{"i":39,"n":"第三十九条","txt":"未服过现役或者未接受过军事专业培训的人员，被选拔为预备役军官的，在确定预备役军官职务等级前，应当接受军事专业培训。"},{"i":40,"n":"第四十条","txt":"预备役军官在服预备役期间，应当依照兵役法和本法的规定接受军事训练和政治教育。"},{"i":41,"n":"第四十一条","txt":"国务院和中央军事委员会在必要的时候，可以决定对预备役军官实施应急训练。预备役军官必须按照规定接受应急训练。"},{"i":42,"n":"第四十二条","txt":"预备役军官的军事训练和政治教育大纲，由人民解放军总参谋部、总政治部、总后勤部、总装备部制定。"},{"i":43,"n":"第四十三条","txt":"服第一类军官预备役的人员的培训，由省军区（卫戍区、警备区）或者所在部队组织实施；服第二类军官预备役的人员的培训，由省军区（卫戍区、警备区）、军分区（警备区）和县人民武装部组织实施。人民解放军总参谋部、总政治部和军兵种、军区根据需要组织预备役军官的培训。"},{"i":44,"n":"第四十四条","txt":"省军区（卫戍区、警备区）、军分区（警备区）和县人民武装部应当根据国防动员的需要，会同县级以上地方人民政府有关部门制定预备役军官征召预案，其中，服第一类军官预备役的人员的征召预案，应当会同有关预备役部队、现役部队制定。"},{"i":45,"n":"第四十五条","txt":"国家决定实施国防动员后，县人民武装部应当根据上级的命令迅速向被确定为征召对象的预备役军官下达征召通知；必要时，预备役部队和预编预备役军官的现役部队也可以直接向所属的被确定为征召对象的预备役军官下达征召通知，并通报预备役军官登记地的县人民武装部。"},{"i":46,"n":"第四十六条","txt":"预备役军官接到征召的通知后，必须按照规定时间到指定地点报到，由于伤病等原因暂时不能应召的，经县人民武装部核实，并报上一级兵役机关批准，可以暂缓应召。"},{"i":47,"n":"第四十七条","txt":"国家决定实施国防动员后，尚未被征召的预备役军官，未经其所在部队或者登记地的县人民武装部批准，不得离开预备役登记地；已经离开的，接到征召通知，应当按照通知要求立即返回或者到指定地点报到。"},{"i":48,"n":"第四十八条","txt":"被征召的预备役军官转服现役的，按照战时现役军官任免权限下达任职命令，改授现役军官军衔，履行现役军官相应的职责；未转服现役的，按照上级下达的任务履行职责。"},{"i":49,"n":"第四十九条","txt":"被征召的预备役军官所在单位应当协助兵役机关做好预备役军官的征召工作。"},{"i":50,"n":"第五十条","txt":"国家解除国防动员的实施措施后，被征召转服现役的预备役军官，除根据部队需要继续服现役的，应当退出现役。"},{"i":51,"n":"第五十一条","txt":"预备役军官履行兵役义务的工作实绩，应当作为所在单位对其考核评定、晋升职务及工资等级的依据之一；立功或者被授予荣誉称号的，享受国家和地方给予同等立功受奖者的奖励和优待。"},{"i":52,"n":"第五十二条","txt":"预备役军官参加军事训练、执行军事勤务期间，应当按照规定着装；参加国庆节、建军节或者其他重大庆典活动的，可以着预备役军官制式服装，并佩带预备役军官军衔肩章、符号标志。"},{"i":53,"n":"第五十三条","txt":"预备役军官参加军事训练、执行军事勤务期间，其工作单位是国家机关、社会团体、企业事业单位的，由其所在单位照发工资和奖金，其享受的福利待遇不变。"},{"i":54,"n":"第五十四条","txt":"对按照规定参加军事训练、执行军事勤务的预备役军官，按照参加军事训练、执行军事勤务的时间及其职务等级发给补贴。补贴标准由财政部和人民解放军总参谋部、总政治部、总后勤部制定，所需经费由中央财政保障。"},{"i":55,"n":"第五十五条","txt":"预备役军官在参加军事训练、执行军事勤务等军事活动中牺牲、伤残的，参照国家关于军人抚恤优待的规定办理。"},{"i":56,"n":"第五十六条","txt":"预备役军官达到平时服预备役最高年龄时，应当退出预备役。"},{"i":57,"n":"第五十七条","txt":"预备役军事、政治、后勤、装备军官平时服预备役的最高年龄："},{"i":58,"n":"第五十八条","txt":"预备役专业技术军官平时服预备役的最高年龄："},{"i":59,"n":"第五十九条","txt":"未达到平时服预备役最高年龄的预备役军官，由于伤病残或者其他原因不能继续服预备役的，应当退出预备役。"},{"i":60,"n":"第六十条","txt":"预备役军官退出预备役的批准权限，与本法第十六条第三款规定的权限相同。"},{"i":61,"n":"第六十一条","txt":"预备役军官退出预备役时，根据其服预备役的时间和贡献，颁发相应的荣誉证章。"},{"i":62,"n":"第六十二条","txt":"预备役军官参加军事训练、执行军事勤务期间，违反纪律的，依照有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"预备役军官有下列行为之一的，由县级人民政府责令限期改正；逾期不改正的，由县级以上地方人民政府强制其履行兵役义务；属于国家工作人员的，依法给予处分；构成犯罪的，依法追究刑事责任："},{"i":64,"n":"第六十四条","txt":"在预备役军官管理工作中，收受贿赂、徇私舞弊，或者玩忽职守致使预备役工作遭受严重损失，构成犯罪的，依法追究刑事责任；未构成犯罪的，依法给予处分。"},{"i":65,"n":"第六十五条","txt":"中国人民武装警察部队退出现役的人员，服人民解放军军官预备役的，适用本法。"},{"i":66,"n":"第六十六条","txt":"本法自1996年1月1日起施行。"}],"zaoshengwuranfangzhifa":[{"i":1,"n":"第一条","txt":"为了防治噪声污染，保障公众健康，保护和改善生活环境，维护社会和谐，推进生态文明建设，促进经济社会可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称噪声，是指在工业生产、建筑施工、交通运输和社会生活中产生的干扰周围生活环境的声音。"},{"i":3,"n":"第三条","txt":"噪声污染的防治，适用本法。"},{"i":4,"n":"第四条","txt":"噪声污染防治应当坚持统筹规划、源头防控、分类管理、社会共治、损害担责的原则。"},{"i":5,"n":"第五条","txt":"县级以上人民政府应当将噪声污染防治工作纳入国民经济和社会发展规划、生态环境保护规划，将噪声污染防治工作经费纳入本级政府预算。"},{"i":6,"n":"第六条","txt":"地方各级人民政府对本行政区域声环境质量负责，采取有效措施，改善声环境质量。"},{"i":7,"n":"第七条","txt":"县级以上地方人民政府应当依照本法和国务院的规定，明确有关部门的噪声污染防治监督管理职责，根据需要建立噪声污染防治工作协调联动机制，加强部门协同配合、信息共享，推进本行政区域噪声污染防治工作。"},{"i":8,"n":"第八条","txt":"国务院生态环境主管部门对全国噪声污染防治实施统一监督管理。"},{"i":9,"n":"第九条","txt":"任何单位和个人都有保护声环境的义务，同时依法享有获取声环境信息、参与和监督噪声污染防治的权利。"},{"i":10,"n":"第十条","txt":"各级人民政府及其有关部门应当加强噪声污染防治法律法规和知识的宣传教育普及工作，增强公众噪声污染防治意识，引导公众依法参与噪声污染防治工作。"},{"i":11,"n":"第十一条","txt":"国家鼓励、支持噪声污染防治科学技术研究开发、成果转化和推广应用，加强噪声污染防治专业技术人才培养，促进噪声污染防治科学技术进步和产业发展。"},{"i":12,"n":"第十二条","txt":"对在噪声污染防治工作中做出显著成绩的单位和个人，按照国家规定给予表彰、奖励。"},{"i":13,"n":"第十三条","txt":"国家推进噪声污染防治标准体系建设。"},{"i":14,"n":"第十四条","txt":"国务院生态环境主管部门制定国家声环境质量标准。"},{"i":15,"n":"第十五条","txt":"国务院生态环境主管部门根据国家声环境质量标准和国家经济、技术条件，制定国家噪声排放标准以及相关的环境振动控制标准。"},{"i":16,"n":"第十六条","txt":"国务院标准化主管部门会同国务院发展改革、生态环境、工业和信息化、住房和城乡建设、交通运输、铁路监督管理、民用航空、海事等部门，对可能产生噪声污染的工业设备、施工机械、机动车、铁路机车车辆、城市轨道交通车辆、民用航空器、机动船舶、电气电子产品、建筑附属设备等产品，根据声环境保护的要求和国家经济、技术条件，在其技术规范或者产品质量标准中规定噪声限值。"},{"i":17,"n":"第十七条","txt":"声环境质量标准、噪声排放标准和其他噪声污染防治相关标准应当定期评估，并根据评估结果适时修订。"},{"i":18,"n":"第十八条","txt":"各级人民政府及其有关部门制定、修改国土空间规划和相关规划，应当依法进行环境影响评价，充分考虑城乡区域开发、改造和建设项目产生的噪声对周围生活环境的影响，统筹规划，合理安排土地用途和建设布局，防止、减轻噪声污染。有关环境影响篇章、说明或者报告书中应当包括噪声污染防治内容。"},{"i":19,"n":"第十九条","txt":"确定建设布局，应当根据国家声环境质量标准和民用建筑隔声设计相关标准，合理划定建筑物与交通干线等的防噪声距离，并提出相应的规划设计要求。"},{"i":20,"n":"第二十条","txt":"未达到国家声环境质量标准的区域所在的设区的市、县级人民政府，应当及时编制声环境质量改善规划及其实施方案，采取有效措施，改善声环境质量。"},{"i":21,"n":"第二十一条","txt":"编制声环境质量改善规划及其实施方案，制定、修订噪声污染防治相关标准，应当征求有关行业协会、企业事业单位、专家和公众等的意见。"},{"i":22,"n":"第二十二条","txt":"排放噪声、产生振动，应当符合噪声排放标准以及相关的环境振动控制标准和有关法律、法规、规章的要求。"},{"i":23,"n":"第二十三条","txt":"国务院生态环境主管部门负责制定噪声监测和评价规范，会同国务院有关部门组织声环境质量监测网络，规划国家声环境质量监测站（点）的设置，组织开展全国声环境质量监测，推进监测自动化，统一发布全国声环境质量状况信息。"},{"i":24,"n":"第二十四条","txt":"新建、改建、扩建可能产生噪声污染的建设项目，应当依法进行环境影响评价。"},{"i":25,"n":"第二十五条","txt":"建设项目的噪声污染防治设施应当与主体工程同时设计、同时施工、同时投产使用。"},{"i":26,"n":"第二十六条","txt":"建设噪声敏感建筑物，应当符合民用建筑隔声设计相关标准要求，不符合标准要求的，不得通过验收、交付使用；在交通干线两侧、工业企业周边等地方建设噪声敏感建筑物，还应当按照规定间隔一定距离，并采取减少振动、降低噪声的措施。"},{"i":27,"n":"第二十七条","txt":"国家鼓励、支持低噪声工艺和设备的研究开发和推广应用，实行噪声污染严重的落后工艺和设备淘汰制度。"},{"i":28,"n":"第二十八条","txt":"对未完成声环境质量改善规划设定目标的地区以及噪声污染问题突出、群众反映强烈的地区，省级以上人民政府生态环境主管部门会同其他负有噪声污染防治监督管理职责的部门约谈该地区人民政府及其有关部门的主要负责人，要求其采取有效措施及时整改。约谈和整改情况应当向社会公开。"},{"i":29,"n":"第二十九条","txt":"生态环境主管部门和其他负有噪声污染防治监督管理职责的部门，有权对排放噪声的单位或者场所进行现场检查。被检查者应当如实反映情况，提供必要的资料，不得拒绝或者阻挠。实施检查的部门、人员对现场检查中知悉的商业秘密应当保密。"},{"i":30,"n":"第三十条","txt":"排放噪声造成严重污染，被责令改正拒不改正的，生态环境主管部门或者其他负有噪声污染防治监督管理职责的部门，可以查封、扣押排放噪声的场所、设施、设备、工具和物品。"},{"i":31,"n":"第三十一条","txt":"任何单位和个人都有权向生态环境主管部门或者其他负有噪声污染防治监督管理职责的部门举报造成噪声污染的行为。"},{"i":32,"n":"第三十二条","txt":"国家鼓励开展宁静小区、静音车厢等宁静区域创建活动，共同维护生活环境和谐安宁。"},{"i":33,"n":"第三十三条","txt":"在举行中等学校招生考试、高等学校招生统一考试等特殊活动期间，地方人民政府或者其指定的部门可以对可能产生噪声影响的活动，作出时间和区域的限制性规定，并提前向社会公告。"},{"i":34,"n":"第三十四条","txt":"本法所称工业噪声，是指在工业生产活动中产生的干扰周围生活环境的声音。"},{"i":35,"n":"第三十五条","txt":"工业企业选址应当符合国土空间规划以及相关规划要求，县级以上地方人民政府应当按照规划要求优化工业企业布局，防止工业噪声污染。"},{"i":36,"n":"第三十六条","txt":"排放工业噪声的企业事业单位和其他生产经营者，应当采取有效措施，减少振动、降低噪声，依法取得排污许可证或者填报排污登记表。"},{"i":37,"n":"第三十七条","txt":"设区的市级以上地方人民政府生态环境主管部门应当按照国务院生态环境主管部门的规定，根据噪声排放、声环境质量改善要求等情况，制定本行政区域噪声重点排污单位名录，向社会公开并适时更新。"},{"i":38,"n":"第三十八条","txt":"实行排污许可管理的单位应当按照规定，对工业噪声开展自行监测，保存原始监测记录，向社会公开监测结果，对监测数据的真实性和准确性负责。"},{"i":39,"n":"第三十九条","txt":"本法所称建筑施工噪声，是指在建筑施工过程中产生的干扰周围生活环境的声音。"},{"i":40,"n":"第四十条","txt":"建设单位应当按照规定将噪声污染防治费用列入工程造价，在施工合同中明确施工单位的噪声污染防治责任。"},{"i":41,"n":"第四十一条","txt":"在噪声敏感建筑物集中区域施工作业，应当优先使用低噪声施工工艺和设备。"},{"i":42,"n":"第四十二条","txt":"在噪声敏感建筑物集中区域施工作业，建设单位应当按照国家规定，设置噪声自动监测系统，与监督管理部门联网，保存原始监测记录，对监测数据的真实性和准确性负责。"},{"i":43,"n":"第四十三条","txt":"在噪声敏感建筑物集中区域，禁止夜间进行产生噪声的建筑施工作业，但抢修、抢险施工作业，因生产工艺要求或者其他特殊需要必须连续施工作业的除外。"},{"i":44,"n":"第四十四条","txt":"本法所称交通运输噪声，是指机动车、铁路机车车辆、城市轨道交通车辆、机动船舶、航空器等交通运输工具在运行时产生的干扰周围生活环境的声音。"},{"i":45,"n":"第四十五条","txt":"各级人民政府及其有关部门制定、修改国土空间规划和交通运输等相关规划，应当综合考虑公路、城市道路、铁路、城市轨道交通线路、水路、港口和民用机场及其起降航线对周围声环境的影响。"},{"i":46,"n":"第四十六条","txt":"制定交通基础设施工程技术规范，应当明确噪声污染防治要求。"},{"i":47,"n":"第四十七条","txt":"机动车的消声器和喇叭应当符合国家规定。禁止驾驶拆除或者损坏消声器、加装排气管等擅自改装的机动车以轰鸣、疾驶等方式造成噪声污染。"},{"i":48,"n":"第四十八条","txt":"机动车、铁路机车车辆、城市轨道交通车辆、机动船舶等交通运输工具运行时，应当按照规定使用喇叭等声响装置。"},{"i":49,"n":"第四十九条","txt":"地方人民政府生态环境主管部门会同公安机关根据声环境保护的需要，可以划定禁止机动车行驶和使用喇叭等声响装置的路段和时间，向社会公告，并由公安机关交通管理部门依法设置相关标志、标线。"},{"i":50,"n":"第五十条","txt":"在车站、铁路站场、港口等地指挥作业时使用广播喇叭的，应当控制音量，减轻噪声污染。"},{"i":51,"n":"第五十一条","txt":"公路养护管理单位、城市道路养护维修单位应当加强对公路、城市道路的维护和保养，保持减少振动、降低噪声设施正常运行。"},{"i":52,"n":"第五十二条","txt":"民用机场所在地人民政府，应当根据环境影响评价以及监测结果确定的民用航空器噪声对机场周围生活环境产生影响的范围和程度，划定噪声敏感建筑物禁止建设区域和限制建设区域，并实施控制。"},{"i":53,"n":"第五十三条","txt":"民用航空器应当符合国务院民用航空主管部门规定的适航标准中的有关噪声要求。"},{"i":54,"n":"第五十四条","txt":"民用机场管理机构负责机场起降航空器噪声的管理，会同航空运输企业、通用航空企业、空中交通管理部门等单位，采取低噪声飞行程序、起降跑道优化、运行架次和时段控制、高噪声航空器运行限制或者周围噪声敏感建筑物隔声降噪等措施，防止、减轻民用航空器噪声污染。"},{"i":55,"n":"第五十五条","txt":"因公路、城市道路和城市轨道交通运行排放噪声造成严重污染的，设区的市、县级人民政府应当组织有关部门和其他有关单位对噪声污染情况进行调查评估和责任认定，制定噪声污染综合治理方案。"},{"i":56,"n":"第五十六条","txt":"因铁路运行排放噪声造成严重污染的，铁路运输企业和设区的市、县级人民政府应当对噪声污染情况进行调查，制定噪声污染综合治理方案。"},{"i":57,"n":"第五十七条","txt":"因民用航空器起降排放噪声造成严重污染的，民用机场所在地人民政府应当组织有关部门和其他有关单位对噪声污染情况进行调查，综合考虑经济、技术和管理措施，制定噪声污染综合治理方案。"},{"i":58,"n":"第五十八条","txt":"制定噪声污染综合治理方案，应当征求有关专家和公众等的意见。"},{"i":59,"n":"第五十九条","txt":"本法所称社会生活噪声，是指人为活动产生的除工业噪声、建筑施工噪声和交通运输噪声之外的干扰周围生活环境的声音。"},{"i":60,"n":"第六十条","txt":"全社会应当增强噪声污染防治意识，自觉减少社会生活噪声排放，积极开展噪声污染防治活动，形成人人有责、人人参与、人人受益的良好噪声污染防治氛围，共同维护生活环境和谐安宁。"},{"i":61,"n":"第六十一条","txt":"文化娱乐、体育、餐饮等场所的经营管理者应当采取有效措施，防止、减轻噪声污染。"},{"i":62,"n":"第六十二条","txt":"使用空调器、冷却塔、水泵、油烟净化器、风机、发电机、变压器、锅炉、装卸设备等可能产生社会生活噪声污染的设备、设施的企业事业单位和其他经营管理者等，应当采取优化布局、集中排放等措施，防止、减轻噪声污染。"},{"i":63,"n":"第六十三条","txt":"禁止在商业经营活动中使用高音广播喇叭或者采用其他持续反复发出高噪声的方法进行广告宣传。"},{"i":64,"n":"第六十四条","txt":"禁止在噪声敏感建筑物集中区域使用高音广播喇叭，但紧急情况以及地方人民政府规定的特殊情形除外。"},{"i":65,"n":"第六十五条","txt":"家庭及其成员应当培养形成减少噪声产生的良好习惯，乘坐公共交通工具、饲养宠物和其他日常活动尽量避免产生噪声对周围人员造成干扰，互谅互让解决噪声纠纷，共同维护声环境质量。"},{"i":66,"n":"第六十六条","txt":"对已竣工交付使用的住宅楼、商铺、办公楼等建筑物进行室内装修活动，应当按照规定限定作业时间，采取有效措施，防止、减轻噪声污染。"},{"i":67,"n":"第六十七条","txt":"新建居民住房的房地产开发经营者应当在销售场所公示住房可能受到噪声影响的情况以及采取或者拟采取的防治措施，并纳入买卖合同。"},{"i":68,"n":"第六十八条","txt":"居民住宅区安装电梯、水泵、变压器等共用设施设备的，建设单位应当合理设置，采取减少振动、降低噪声的措施，符合民用建筑隔声设计相关标准要求。"},{"i":69,"n":"第六十九条","txt":"基层群众性自治组织指导业主委员会、物业服务人、业主通过制定管理规约或者其他形式，约定本物业管理区域噪声污染防治要求，由业主共同遵守。"},{"i":70,"n":"第七十条","txt":"对噪声敏感建筑物集中区域的社会生活噪声扰民行为，基层群众性自治组织、业主委员会、物业服务人应当及时劝阻、调解；劝阻、调解无效的，可以向负有社会生活噪声污染防治监督管理职责的部门或者地方人民政府指定的部门报告或者投诉，接到报告或者投诉的部门应当依法处理。"},{"i":71,"n":"第七十一条","txt":"违反本法规定，拒绝、阻挠监督检查，或者在接受监督检查时弄虚作假的，由生态环境主管部门或者其他负有噪声污染防治监督管理职责的部门责令改正，处二万元以上二十万元以下的罚款。"},{"i":72,"n":"第七十二条","txt":"违反本法规定，生产、进口、销售超过噪声限值的产品的，由县级以上人民政府市场监督管理部门、海关按照职责责令改正，没收违法所得，并处货值金额一倍以上三倍以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":73,"n":"第七十三条","txt":"违反本法规定，建设单位建设噪声敏感建筑物不符合民用建筑隔声设计相关标准要求的，由县级以上地方人民政府住房和城乡建设主管部门责令改正，处建设工程合同价款百分之二以上百分之四以下的罚款。"},{"i":74,"n":"第七十四条","txt":"违反本法规定，在噪声敏感建筑物集中区域新建排放噪声的工业企业的，由生态环境主管部门责令停止违法行为，处十万元以上五十万元以下的罚款，并报经有批准权的人民政府批准，责令关闭。"},{"i":75,"n":"第七十五条","txt":"违反本法规定，无排污许可证或者超过噪声排放标准排放工业噪声的，由生态环境主管部门责令改正或者限制生产、停产整治，并处二万元以上二十万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":76,"n":"第七十六条","txt":"违反本法规定，有下列行为之一，由生态环境主管部门责令改正，处二万元以上二十万元以下的罚款；拒不改正的，责令限制生产、停产整治："},{"i":77,"n":"第七十七条","txt":"违反本法规定，建设单位、施工单位有下列行为之一，由工程所在地人民政府指定的部门责令改正，处一万元以上十万元以下的罚款；拒不改正的，可以责令暂停施工："},{"i":78,"n":"第七十八条","txt":"违反本法规定，有下列行为之一，由工程所在地人民政府指定的部门责令改正，处五千元以上五万元以下的罚款；拒不改正的，处五万元以上二十万元以下的罚款："},{"i":79,"n":"第七十九条","txt":"违反本法规定，驾驶拆除或者损坏消声器、加装排气管等擅自改装的机动车轰鸣、疾驶，机动车运行时未按照规定使用声响装置，或者违反禁止机动车行驶和使用声响装置的路段和时间规定的，由县级以上地方人民政府公安机关交通管理部门依照有关道路交通安全的法律法规处罚。"},{"i":80,"n":"第八十条","txt":"违反本法规定，有下列行为之一，由交通运输、铁路监督管理、民用航空等部门或者地方人民政府指定的城市道路、城市轨道交通有关部门，按照职责责令改正，处五千元以上五万元以下的罚款；拒不改正的，处五万元以上二十万元以下的罚款："},{"i":81,"n":"第八十一条","txt":"违反本法规定，有下列行为之一，由地方人民政府指定的部门责令改正，处五千元以上五万元以下的罚款；拒不改正的，处五万元以上二十万元以下的罚款，并可以报经有批准权的人民政府批准，责令停业："},{"i":82,"n":"第八十二条","txt":"违反本法规定，有下列行为之一，由地方人民政府指定的部门说服教育，责令改正；拒不改正的，给予警告，对个人可以处二百元以上一千元以下的罚款，对单位可以处二千元以上二万元以下的罚款："},{"i":83,"n":"第八十三条","txt":"违反本法规定，有下列行为之一，由县级以上地方人民政府房产管理部门责令改正，处一万元以上五万元以下的罚款；拒不改正的，责令暂停销售："},{"i":84,"n":"第八十四条","txt":"违反本法规定，有下列行为之一，由地方人民政府指定的部门责令改正，处五千元以上五万元以下的罚款；拒不改正的，处五万元以上二十万元以下的罚款："},{"i":85,"n":"第八十五条","txt":"噪声污染防治监督管理人员滥用职权、玩忽职守、徇私舞弊的，由监察机关或者任免机关、单位依法给予处分。"},{"i":86,"n":"第八十六条","txt":"受到噪声侵害的单位和个人，有权要求侵权人依法承担民事责任。"},{"i":87,"n":"第八十七条","txt":"违反本法规定，产生社会生活噪声，经劝阻、调解和处理未能制止，持续干扰他人正常生活、工作和学习，或者有其他扰乱公共秩序、妨害社会管理等违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":88,"n":"第八十八条","txt":"本法中下列用语的含义："},{"i":89,"n":"第八十九条","txt":"省、自治区、直辖市或者设区的市、自治州根据实际情况，制定本地方噪声污染防治具体办法。"},{"i":90,"n":"第九十条","txt":"本法自2022年6月5日起施行。《中华人民共和国环境噪声污染防治法》同时废止。"}],"zhiyeyishifa":[{"i":1,"n":"第一条","txt":"为了加强医师队伍的建设，提高医师的职业道德和业务素质，保障医师的合法权益，保护人民健康，制定本法。"},{"i":2,"n":"第二条","txt":"依法取得执业医师资格或者执业助理医师资格，经注册在医疗、预防、保健机构中执业的专业医务人员，适用本法。"},{"i":3,"n":"第三条","txt":"医师应当具备良好的职业道德和医疗执业水平，发扬人道主义精神，履行防病治病、救死扶伤、保护人民健康的神圣职责。"},{"i":4,"n":"第四条","txt":"国务院卫生行政部门主管全国的医师工作。"},{"i":5,"n":"第五条","txt":"国家对在医疗、预防、保健工作中作出贡献的医师，给予奖励。"},{"i":6,"n":"第六条","txt":"医师的医学专业技术职称和医学专业技术职务的评定、聘任，按照国家有关规定办理。"},{"i":7,"n":"第七条","txt":"医师可以依法组织和参加医师协会。"},{"i":8,"n":"第八条","txt":"国家实行医师资格考试制度。医师资格考试分为执业医师资格考试和执业助理医师资格考试。"},{"i":9,"n":"第九条","txt":"具有下列条件之一的，可以参加执业医师资格考试："},{"i":10,"n":"第十条","txt":"具有高等学校医学专科学历或者中等专业学校医学专业学历，在执业医师指导下，在医疗、预防、保健机构中试用期满一年的，可以参加执业助理医师资格考试。"},{"i":11,"n":"第十一条","txt":"以师承方式学习传统医学满三年或者经多年实践医术确有专长的，经县级以上人民政府卫生行政部门确定的传统医学专业组织或者医疗、预防、保健机构考核合格并推荐，可以参加执业医师资格或者执业助理医师资格考试。考试的内容和办法由国务院卫生行政部门另行制定。"},{"i":12,"n":"第十二条","txt":"医师资格考试成绩合格，取得执业医师资格或者执业助理医师资格。"},{"i":13,"n":"第十三条","txt":"国家实行医师执业注册制度。"},{"i":14,"n":"第十四条","txt":"医师经注册后，可以在医疗、预防、保健机构中按照注册的执业地点、执业类别、执业范围执业，从事相应的医疗、预防、保健业务。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，不予注册："},{"i":16,"n":"第十六条","txt":"医师注册后有下列情形之一的，其所在的医疗、预防、保健机构应当在三十日内报告准予注册的卫生行政部门，卫生行政部门应当注销注册，收回医师执业证书："},{"i":17,"n":"第十七条","txt":"医师变更执业地点、执业类别、执业范围等注册事项的，应当到准予注册的卫生行政部门依照本法第十三条的规定办理变更注册手续。"},{"i":18,"n":"第十八条","txt":"中止医师执业活动二年以上以及有本法第十五条规定情形消失的，申请重新执业，应当由本法第三十一条规定的机构考核合格，并依照本法第十三条的规定重新注册。"},{"i":19,"n":"第十九条","txt":"申请个体行医的执业医师，须经注册后在医疗、预防、保健机构中执业满五年，并按照国家有关规定办理审批手续；未经批准，不得行医。"},{"i":20,"n":"第二十条","txt":"县级以上地方人民政府卫生行政部门应当将准予注册和注销注册的人员名单予以公告，并由省级人民政府卫生行政部门汇总，报国务院卫生行政部门备案。"},{"i":21,"n":"第二十一条","txt":"医师在执业活动中享有下列权利："},{"i":22,"n":"第二十二条","txt":"医师在执业活动中履行下列义务："},{"i":23,"n":"第二十三条","txt":"医师实施医疗、预防、保健措施，签署有关医学证明文件，必须亲自诊查、调查，并按照规定及时填写医学文书，不得隐匿、伪造或者销毁医学文书及有关资料。"},{"i":24,"n":"第二十四条","txt":"对急危患者，医师应当采取紧急措施进行诊治；不得拒绝急救处置。"},{"i":25,"n":"第二十五条","txt":"医师应当使用经国家有关部门批准使用的药品、消毒药剂和医疗器械。"},{"i":26,"n":"第二十六条","txt":"医师应当如实向患者或者其家属介绍病情，但应注意避免对患者产生不利后果。"},{"i":27,"n":"第二十七条","txt":"医师不得利用职务之便，索取、非法收受患者财物或者牟取其他不正当利益。"},{"i":28,"n":"第二十八条","txt":"遇有自然灾害、传染病流行、突发重大伤亡事故及其他严重威胁人民生命健康的紧急情况时，医师应当服从县级以上人民政府卫生行政部门的调遣。"},{"i":29,"n":"第二十九条","txt":"医师发生医疗事故或者发现传染病疫情时，应当按照有关规定及时向所在机构或者卫生行政部门报告。"},{"i":30,"n":"第三十条","txt":"执业助理医师应当在执业医师的指导下，在医疗、预防、保健机构中按照其执业类别执业。"},{"i":31,"n":"第三十一条","txt":"受县级以上人民政府卫生行政部门委托的机构或者组织应当按照医师执业标准，对医师的业务水平、工作成绩和职业道德状况进行定期考核。"},{"i":32,"n":"第三十二条","txt":"县级以上人民政府卫生行政部门负责指导、检查和监督医师考核工作。"},{"i":33,"n":"第三十三条","txt":"医师有下列情形之一的，县级以上人民政府卫生行政部门应当给予表彰或者奖励："},{"i":34,"n":"第三十四条","txt":"县级以上人民政府卫生行政部门应当制定医师培训计划，对医师进行多种形式的培训，为医师接受继续医学教育提供条件。"},{"i":35,"n":"第三十五条","txt":"医疗、预防、保健机构应当按照规定和计划保证本机构医师的培训和继续医学教育。"},{"i":36,"n":"第三十六条","txt":"以不正当手段取得医师执业证书的，由发给证书的卫生行政部门予以吊销；对负有直接责任的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":37,"n":"第三十七条","txt":"医师在执业活动中，违反本法规定，有下列行为之一的，由县级以上人民政府卫生行政部门给予警告或者责令暂停六个月以上一年以下执业活动；情节严重的，吊销其执业证书；构成犯罪的，依法追究刑事责任："},{"i":38,"n":"第三十八条","txt":"医师在医疗、预防、保健工作中造成事故的，依照法律或者国家有关规定处理。"},{"i":39,"n":"第三十九条","txt":"未经批准擅自开办医疗机构行医或者非医师行医的，由县级以上人民政府卫生行政部门予以取缔，没收其违法所得及其药品、器械，并处十万元以下的罚款；对医师吊销其执业证书；给患者造成损害的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"阻碍医师依法执业，侮辱、诽谤、威胁、殴打医师或者侵犯医师人身自由、干扰医师正常工作、生活的，依照治安管理处罚法的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"医疗、预防、保健机构未依照本法第十六条的规定履行报告职责，导致严重后果的，由县级以上人民政府卫生行政部门给予警告；并对该机构的行政负责人依法给予行政处分。"},{"i":42,"n":"第四十二条","txt":"卫生行政部门工作人员或者医疗、预防、保健机构工作人员违反本法有关规定，弄虚作假、玩忽职守、滥用职权、徇私舞弊，尚不构成犯罪的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"本法颁布之日前按照国家有关规定取得医学专业技术职称和医学专业技术职务的人员，由所在机构报请县级以上人民政府卫生行政部门认定，取得相应的医师资格。其中在医疗、预防、保健机构中从事医疗、预防、保健业务的医务人员，依照本法规定的条件，由所在机构集体核报县级以上人民政府卫生行政部门，予以注册并发给医师执业证书。具体办法由国务院卫生行政部门会同国务院人事行政部门制定。"},{"i":44,"n":"第四十四条","txt":"计划生育技术服务机构中的医师，适用本法。"},{"i":45,"n":"第四十五条","txt":"在乡村医疗卫生机构中向村民提供预防、保健和一般医疗服务的乡村医生，符合本法有关规定的，可以依法取得执业医师资格或者执业助理医师资格；不具备本法规定的执业医师资格或者执业助理医师资格的乡村医生，由国务院另行制定管理办法。"},{"i":46,"n":"第四十六条","txt":"军队医师执行本法的实施办法，由国务院、中央军事委员会依据本法的原则制定。"},{"i":47,"n":"第四十七条","txt":"境外人员在中国境内申请医师考试、注册、执业或者从事临床示教、临床研究等活动的，按照国家有关规定办理。"},{"i":48,"n":"第四十八条","txt":"本法自1999年5月1日起施行。"}],"zhongwaihezijingyingqiyefa":[{"i":1,"n":"第一条","txt":"中华人民共和国为了扩大国际经济合作和技术交流，允许外国公司、企业和其它经济组织或个人（以下简称外国合营者），按照平等互利的原则，经中国政府批准，在中华人民共和国境内，同中国的公司、企业或其它经济组织（以下简称中国合营者）共同举办合营企业。"},{"i":2,"n":"第二条","txt":"中国政府依法保护外国合营者按照经中国政府批准的协议、合同、章程在合营企业的投资、应分得的利润和其它合法权益。"},{"i":3,"n":"第三条","txt":"合营各方签订的合营协议、合同、章程，应报国家对外经济贸易主管部门（以下称审查批准机关）审查批准。审查批准机关应在三个月内决定批准或不批准。合营企业经批准后，向国家工商行政管理主管部门登记，领取营业执照，开始营业。"},{"i":4,"n":"第四条","txt":"合营企业的形式为有限责任公司。"},{"i":5,"n":"第五条","txt":"合营企业各方可以现金、实物、工业产权等进行投资。"},{"i":6,"n":"第六条","txt":"合营企业设董事会，其人数组成由合营各方协商，在合同、章程中确定，并由合营各方委派和撤换。董事长和副董事长由合营各方协商确定或由董事会选举产生。中外合营者的一方担任董事长的，由他方担任副董事长。董事会根据平等互利的原则，决定合营企业的重大问题。"},{"i":7,"n":"第七条","txt":"合营企业的职工依法建立工会组织，开展工会活动，维护职工的合法权益。"},{"i":8,"n":"第八条","txt":"合营企业获得的毛利润，按中华人民共和国税法规定缴纳合营企业所得税后，扣除合营企业章程规定的储备基金、职工奖励及福利基金、企业发展基金，净利润根据合营各方注册资本的比例进行分配。"},{"i":9,"n":"第九条","txt":"合营企业应凭营业执照在国家外汇管理机关允许经营外汇业务的银行或其它金融机构开立外汇帐户。"},{"i":10,"n":"第十条","txt":"合营企业在批准的经营范围内所需的原材料、燃料等物资，按照公平、合理的原则，可以在国内市场或者在国际市场购买。"},{"i":11,"n":"第十一条","txt":"外国合营者在履行法律和协议、合同规定的义务后分得的净利润，在合营企业期满或者中止时所分得的资金以及其它资金，可按合营企业合同规定的货币，按外汇管理条例汇往国外。"},{"i":12,"n":"第十二条","txt":"合营企业的外籍职工的工资收入和其它正当收入，按中华人民共和国税法缴纳个人所得税后，可按外汇管理条例汇往国外。"},{"i":13,"n":"第十三条","txt":"合营企业的合营期限，按不同行业、不同情况，作不同的约定。有的行业的合营企业，应当约定合营期限；有的行业的合营企业，可以约定合营期限，也可以不约定合营期限。约定合营期限的合营企业，合营各方同意延长合营期限的，应在距合营期满六个月前向审查批准机关提出申请。审查批准机关应自接到申请之日起一个月内决定批准或不批准。"},{"i":14,"n":"第十四条","txt":"合营企业如发生严重亏损、一方不履行合同和章程规定的义务、不可抗力等，经合营各方协商同意，报请审查批准机关批准，并向国家工商行政管理主管部门登记，可终止合同。如果因违反合同而造成损失的，应由违反合同的一方承担经济责任。"},{"i":15,"n":"第十五条","txt":"举办合营企业不涉及国家规定实施准入特别管理措施的，对本法第三条、第十三条、第十四条规定的审批事项，适用备案管理。国家规定的准入特别管理措施由国务院发布或者批准发布。"},{"i":16,"n":"第十六条","txt":"合营各方发生纠纷，董事会不能协商解决时，由中国仲裁机构进行调解或仲裁，也可由合营各方协议在其它仲裁机构仲裁。"},{"i":17,"n":"第十七条","txt":"本法自公布之日起生效。"}],"zhongwaihezuojingyingqiyefa":[{"i":1,"n":"第一条","txt":"为了扩大对外经济合作和技术交流，促进外国的企业和其他经济组织或者个人（以下简称外国合作者）按照平等互利的原则，同中华人民共和国的企业或者其他经济组织（以下简称中国合作者）在中国境内共同举办中外合作经营企业（以下简称合作企业），特制定本法。"},{"i":2,"n":"第二条","txt":"中外合作者举办合作企业，应当依照本法的规定，在合作企业合同中约定投资或者合作条件、收益或者产品的分配、风险和亏损的分担、经营管理的方式和合作企业终止时财产的归属等事项。"},{"i":3,"n":"第三条","txt":"国家依法保护合作企业和中外合作者的合法权益。"},{"i":4,"n":"第四条","txt":"国家鼓励举办产品出口的或者技术先进的生产型合作企业。"},{"i":5,"n":"第五条","txt":"申请设立合作企业，应当将中外合作者签订的协议、合同、章程等文件报国务院对外经济贸易主管部门或者国务院授权的部门和地方政府（以下简称审查批准机关）审查批准。审查批准机关应当自接到申请之日起四十五天内决定批准或者不批准。"},{"i":6,"n":"第六条","txt":"设立合作企业的申请经批准后，应当自接到批准证书之日起三十天内向工商行政管理机关申请登记，领取营业执照。合作企业的营业执照签发日期，为该企业的成立日期。"},{"i":7,"n":"第七条","txt":"中外合作者在合作期限内协商同意对合作企业合同作重大变更的，应当报审查批准机关批准；变更内容涉及法定工商登记项目、税务登记项目的，应当向工商行政管理机关、税务机关办理变更登记手续。"},{"i":8,"n":"第八条","txt":"中外合作者的投资或者提供的合作条件可以是现金、实物、土地使用权、工业产权、非专利技术和其他财产权利。"},{"i":9,"n":"第九条","txt":"中外合作者应当依照法律、法规的规定和合作企业合同的约定，如期履行缴足投资、提供合作条件的义务。逾期不履行的，由工商行政管理机关限期履行；限期届满仍未履行的，由审查批准机关和工商行政管理机关依照国家有关规定处理。"},{"i":10,"n":"第十条","txt":"中外合作者的一方转让其在合作企业合同中的全部或者部分权利、义务的，必须经他方同意，并报审查批准机关批准。"},{"i":11,"n":"第十一条","txt":"合作企业依照经批准的合作企业合同、章程进行经营管理活动。合作企业的经营管理自主权不受干涉。"},{"i":12,"n":"第十二条","txt":"合作企业应当设立董事会或者联合管理机构，依照合作企业合同或者章程的规定，决定合作企业的重大问题。中外合作者的一方担任董事会的董事长、联合管理机构的主任的，由他方担任副董事长、副主任。董事会或者联合管理机构可以决定任命或者聘请总经理负责合作企业的日常经营管理工作。总经理对董事会或者联合管理机构负责。"},{"i":13,"n":"第十三条","txt":"合作企业职工的录用、辞退、报酬、福利、劳动保护、劳动保险等事项，应当依法通过订立合同加以规定。"},{"i":14,"n":"第十四条","txt":"合作企业的职工依法建立工会组织，开展工会活动，维护职工的合法权益。"},{"i":15,"n":"第十五条","txt":"合作企业必须在中国境内设置会计帐簿，依照规定报送会计报表，并接受财政税务机关的监督。"},{"i":16,"n":"第十六条","txt":"合作企业应当凭营业执照在国家外汇管理机关允许经营外汇业务的银行或者其他金融机构开立外汇帐户。"},{"i":17,"n":"第十七条","txt":"合作企业可以向中国境内的金融机构借款，也可以在中国境外借款。"},{"i":18,"n":"第十八条","txt":"合作企业的各项保险应当向中国境内的保险机构投保。"},{"i":19,"n":"第十九条","txt":"合作企业可以在经批准的经营范围内，进口本企业需要的物资，出口本企业生产的产品。合作企业在经批准的经营范围内所需的原材料、燃料等物资，按照公平、合理的原则，可以在国内市场或者在国际市场购买。"},{"i":20,"n":"第二十条","txt":"合作企业依照国家有关税收的规定缴纳税款并可以享受减税、免税的优惠待遇。"},{"i":21,"n":"第二十一条","txt":"中外合作者依照合作企业合同的约定，分配收益或者产品，承担风险和亏损。"},{"i":22,"n":"第二十二条","txt":"外国合作者在履行法律规定和合作企业合同约定的义务后分得的利润、其他合法收入和合作企业终止时分得的资金，可以依法汇往国外。"},{"i":23,"n":"第二十三条","txt":"合作企业期满或者提前终止时，应当依照法定程序对资产和债权、债务进行清算。中外合作者应当依照合作企业合同的约定确定合作企业财产的归属。"},{"i":24,"n":"第二十四条","txt":"合作企业的合作期限由中外合作者协商并在合作企业合同中订明。中外合作者同意延长合作期限的，应当在距合作期满一百八十天前向审查批准机关提出申请。审查批准机关应当自接到申请之日起三十天内决定批准或者不批准。"},{"i":25,"n":"第二十五条","txt":"举办合作企业不涉及国家规定实施准入特别管理措施的，对本法第五条、第七条、第十条、第二十四条规定的审批事项，适用备案管理。国家规定的准入特别管理措施由国务院发布或者批准发布。"},{"i":26,"n":"第二十六条","txt":"中外合作者履行合作企业合同、章程发生争议时，应当通过协商或者调解解决。中外合作者不愿通过协商、调解解决的，或者协商、调解不成的，可以依照合作企业合同中的仲裁条款或者事后达成的书面仲裁协议，提交中国仲裁机构或者其他仲裁机构仲裁。"},{"i":27,"n":"第二十七条","txt":"国务院对外经济贸易主管部门根据本法制定实施细则，报国务院批准后施行。"},{"i":28,"n":"第二十八条","txt":"本法自公布之日起施行。"}]};
